def wp_text():
    """Waypoints as short text: 24/60, 79/55 ... (pan/tilt in %)."""
    return ", ".join(f"{w[0]:.0f}/{w[1]:.0f}" for w in WAYPOINTS)


def wp_add():
    p_, t_ = servo_pos()                                         # 2.98.35: where the head really stands (planner 072)
    WAYPOINTS.append([round(float(p_), 1), round(float(t_), 1)])
START = time.time()
LOCK = threading.Lock()
GPIO_PAN, GPIO_TILT, GPIO_RELAY = 17, 27, 22
GPIO_RESERVED = (GPIO_PAN, GPIO_TILT) + ((4,) if os.path.isdir("/sys/bus/w1/devices/w1_bus_master1") else ())   # servo pins / 1-Wire never as relays
MAX_RELAYS = 8
FREE_GPIOS = (23, 24, 25, 5, 6, 12, 13, 16, 26, 4, 22, 18, 19, 20, 21)


def default_relays():
    """Relay 1 = the original alarm relay on GPIO 22 (switches while a person is detected)."""
    return [{"name": "Relay 1", "gpio": GPIO_RELAY, "mode": "auto", "trigger": "person", "hold": 5.0, "active_low": False}]


RELAYS = default_relays()          # edited in the desktop window and on the web page, saved in the settings file
QUICK = {"rec_until": 0.0}          # quick switches on the live page: manual recording until (time), at most 10 minutes


def quick_rec():
    """Quick switch «Record»: manual recording on (max. 10 min) / off. Returns True while recording."""
    if CFG.get("sim_on"):
        log_event("rec", "Simulation: no recordings"); QUICK["rec_until"] = 0.0; return False
    if time.time() < QUICK["rec_until"]:
        QUICK["rec_until"] = 0.0; log_event("rec", "Manual recording stopped"); return False
    QUICK["rec_until"] = time.time() + 600; log_event("rec", "Manual recording started (max. 10 min)"); return True


def quick_photo(frame):
    """Quick switch «Photo»: the current picture into the recordings. Returns the file name (None: no picture yet)."""
    if frame is None or CFG.get("sim_on"):
        return None                                        # simulation: nothing goes into the recordings
    os.makedirs(CFG["record_dir"], exist_ok=True)
    name = f"photo_{datetime.now().strftime('%Y%m%d_%H%M%S')}.jpg"
    cv2.imwrite(os.path.join(CFG["record_dir"], name), frame, [cv2.IMWRITE_JPEG_QUALITY, 90])
    gps_tag_jpg(os.path.join(CFG["record_dir"], name))
    log_event("rec", f"Photo saved: {name}")
    return name


def patrol_status_text(st, lang=None):
    """«moving to waypoint 2/4 (88/82)» -> «fährt zu Wegpunkt 2/4 (88/82)» ..."""
    m = re.fullmatch(r"moving to waypoint (\d+)/(\d+) \((.+)\)", st or "")
    if m:
        return tr("moving to waypoint", lang) + f" {m.group(1)}/{m.group(2)} ({m.group(3)})"
    m = re.fullmatch(r"dwelling at (.+)", st or "")
    if m:
        return tr("waiting at", lang) + " " + m.group(1)
    m = re.fullmatch(r"(.+?) \((.+)\)", st or "")             # 2.98.30: «saving: stays at the most important direction (Zelt)» (162)
    if m and tr(m.group(1), lang) != m.group(1):
        return tr(m.group(1), lang) + " (" + m.group(2) + ")"
    return tr(st or "", lang)


def quick_patrol(source="web"):
    """One patrol button: off -> back and forth -> round trip -> off."""
    if not CFG["patrol"]:
        CFG["patrol"], CFG["patrol_mode"] = True, "pendulum"
    elif CFG["patrol_mode"] == "pendulum":
        CFG["patrol_mode"] = "loop"
    else:
        CFG["patrol"] = False
    save_settings()
    log_event("patrol", ("Patrol ON: " + ("round trip 1-2-3-1" if CFG["patrol_mode"] == "loop" else "back and forth 1-2-3-2-1"))
              if CFG["patrol"] else f"Patrol switched OFF ({source})")
    return CFG["patrol"], CFG["patrol_mode"]
MANUAL = {"until": 0.0}            # manual camera moves pause tracking / patrol until this time


def manual_active():
    return time.time() < MANUAL["until"]


def move_camera(cmd, step=3.0, who="window"):
    """Manual pan/tilt step (direction pad, arrow keys, web page). Pauses tracking/patrol for manual_hold seconds.
    2.98.35: refused while the servos are stopped (Not-Aus, fault - 072); who = the panel that steers (shown everywhere)."""
    if servo_blocked():
        return False
    try:
        step = max(0.5, min(25.0, float(step)))
    except (TypeError, ValueError):
        step = 3.0
    if cmd == "left":
        CFG["pan"] = max(0.0, CFG["pan"] - step)
    elif cmd == "right":
        CFG["pan"] = min(100.0, CFG["pan"] + step)
    elif cmd == "up":
        CFG["tilt"] = min(100.0, CFG["tilt"] + step)
    elif cmd == "down":
        CFG["tilt"] = max(0.0, CFG["tilt"] - step)
    elif cmd == "center":
        CFG["pan"] = 50.0; CFG["tilt"] = 50.0
    else:
        return False
    MANUAL["until"] = time.time() + CFG["manual_hold"]
    servo_driver_note(who, cmd)
    return True


STICK = {"t": 0.0}                 # time of the last joystick sample (0 = stick released)


def stick_camera(x, y, speed=30.0, who="window"):
    """Joystick: x/y = deflection -1..1 (right / up are positive), speed = full-deflection speed in % per second.
    The camera moves by deflection * speed * time since the last sample, so it can never run away: no sample, no movement.
    A small dead zone and a quadratic curve make slow, precise moves easy near the centre."""
    try:
        x, y = float(x), float(y)
        speed = max(5.0, min(100.0, float(speed)))
    except (TypeError, ValueError):
        return False
    if not (math.isfinite(x) and math.isfinite(y)):
        return False
    now = time.time()
    last, STICK["t"] = STICK["t"], now
    mag = math.hypot(x, y)
    if mag < 0.08:
        STICK["t"] = 0.0
        return True
    if servo_blocked():                                          # 2.98.35: Not-Aus / fault (072): the stick does nothing
        return False
    dt = now - last if 0.0 < now - last < 0.5 else 0.1          # first sample after a pause counts as one 100 ms tick
    k = min(1.0, (mag - 0.08) / 0.92) ** 2 * speed * dt / mag
    # 2.98.35: the target runs at most ~0.3 s ahead of the real position (planner 072) - letting go stops the head soon,
    # it does not drive on to a target far ahead
    pp, pt = servo_pos()
    lead_p = max(2.0, srv_axis_limits("pan")[0] * 0.3); lead_t = max(2.0, srv_axis_limits("tilt")[0] * 0.3)
    CFG["pan"] = max(0.0, min(100.0, max(pp - lead_p, min(pp + lead_p, CFG["pan"] + x * k))))
    CFG["tilt"] = max(0.0, min(100.0, max(pt - lead_t, min(pt + lead_t, CFG["tilt"] + y * k))))
    MANUAL["until"] = now + CFG["manual_hold"]
    servo_driver_note(who, "stick")
    return True



ALERTS = {"seq": 0, "items": deque(maxlen=50)}      # live alarms for open web pages (sound in the browser)
ALERTS_COND = threading.Condition()


def push_alert(kind, text="", **extra):
    try:
        protect_on_alert(kind)                         # 2.95.105: escalation (light, then the siren unless disarmed)
        if CFG.get("sim_on"):                          # 2.97.0: simulator code only in the simulation
            rover_on_alarm(kind)                       # 2.96.7: the rover drives to the alarm (simulator, makeover 17)
    except NameError:
        pass
    if not CFG.get("browser_alarm", True):
        return
    if kind in ("person", "prealarm", "warm", "noise") and not is_armed():
        return
    with ALERTS_COND:
        ALERTS["seq"] += 1
        ALERTS["items"].append(dict(seq=ALERTS["seq"], kind=kind, text=text, time=datetime.now().strftime("%H:%M:%S"), ts=time.time(), **extra))
        ALERTS_COND.notify_all()


_LOGDAY = {"d": ""}
# what the overview shows ("important"): alarms, persons, animals, arming, problems, remote access, restarts ...
# everything else (auto-tune, camera moves, status lines, patrol, weather, AI details ...) is only in the full log / archive
_IMP = {
    "person": re.compile(r"^(?!Person counter reset)"),
    "rec": re.compile(r"^(Recording started|Recording failed|Sound recording failed|Diary: [a-z ]+ \()"),
    "sys": re.compile(r"Armed now|Armed in|Disarmed|UNDER-VOLTAGE|CPU hot|Memory card almost full|Battery almost empty|"
                      r"Camera stopped|not available|could not|failed|Camping profile|Operator mode|wrong PIN|paused for|"
                      r"Pause over|Pause ended|Switching to version|Version .* downloaded|Autostart:|Internet not reachable|"
                      r"Internet reachable again|Wi-Fi signal weak|Settings reset|Settings imported|Shutting down|Restarting the Pi|"
                      r"Talking through|Own Wi-Fi .* switched ON|Network automatic: connected|Power cut|Mains power back|UPS HAT found|Battery empty|Automatic update|runs fine \(update|did not start 3 times|SABOTAGE|Motion sensor found|Device .* not reachable|Device added"),
    "web": re.compile(r"Remote access from|Login blocked|Notification failed|Guest access|WARNING|NOT started|Web password|MQTT connected|MQTT: |SMS "),
    "sched": re.compile(r"Schedule started|Schedule ended|Presence"),
}


def log_important(kind, text):
    rx = _IMP.get(kind)
    return bool(rx and rx.search(text or ""))


def log_event(kind, text):
    today = datetime.now().strftime("%Y-%m-%d")
    if _LOGDAY["d"] != today:                             # first line of a new day: archive the old day's log first
        _LOGDAY["d"] = today
        try:
            log_rotate()
        except Exception:
            pass
    try:
        if CFG.get("sim_on"):
            drill_note(kind, text)                       # 2.96.6: what MoveEye does during a drill (141)
    except NameError:
        pass
    with LOCK:
        STATE["events"].insert(0, {"t": datetime.now().strftime("%H:%M:%S"), "kind": kind, "text": text,
                                   "imp": log_important(kind, text)})
        del STATE["events"][300:]
    try:
        with open(LOG_FILE, "a") as f:
            f.write(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}  [{kind}]  {text}\n")
    except OSError:
        pass


# ----------------------------------------------------------------------------
# Zones: polygons on the picture (normalised 0..1). "ignore" = detections whose feet are inside are dropped,
# "only" = when at least one such zone exists, only detections inside it count.
# ----------------------------------------------------------------------------
MAX_ZONES = 12
ZONES = []              # [{"id", "name", "mode": "ignore"|"only"|"privacy", "points": [[x, y], ...], "kinds": "person"|"animal" (optional)}]
# "privacy" = the area is painted black right after the camera, before anything else sees it: live picture, recordings,
# snapshots, timelapse, detection and the zone editor never contain it (neighbour's tent, a path, a window).
# 2.98.7: "sleep" = the sleeping place - a privacy zone that stays on the bed when the head turns: its corners are kept as
# directions (degrees, "ang") and drawn into every picture for the direction the camera has (and had in the last 2 s, the
# picture comes a little later than the servo moves). The wake-up alarm turns the camera to it.
# aufr: "report" = «nur melden»: a person whose feet stand inside is no alarm - one log line / info push now and then (the
# «öffentlicher Weg» of «Platz einrichten» is such a zone since aufr, alarm_gate in 317). Every zone except the black ones
# (they always do) can «stay on its place» ("anchor": the corners are kept as directions and follow the turning head) - a
# switch in the zone editor (520) since aufr; before only the zones of «Platz einrichten» (317) had it.


def _num(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)


def _clean_zone(z, i):
    if not isinstance(z, dict):
        return None
    pts = []
    for p in (z.get("points") or [])[:40] if isinstance(z.get("points"), list) else []:
        if isinstance(p, (list, tuple)) and len(p) == 2 and _num(p[0]) and _num(p[1]):
            pts.append([round(min(1.0, max(0.0, float(p[0]))), 4), round(min(1.0, max(0.0, float(p[1]))), 4)])
    mode = z.get("mode") if z.get("mode") in ("only", "privacy", "line", "loiter", "sleep", "report") else "ignore"
    if mode == "line":
        if len(pts) < 2:
            return None
        pts = pts[:2]
    elif len(pts) < 3:
        return None
    zid = str(z.get("id") or "")
    out = {"id": zid if re.fullmatch(r"[0-9a-f]{8}", zid) else uuid.uuid4().hex[:8],
           "name": str(z.get("name") or "").strip()[:40] or f"Zone {i + 1}", "mode": mode, "points": pts}
    if mode == "line":
        out["dir"] = z.get("dir") if z.get("dir") in ("ab", "ba") else "both"
    if mode in ("ignore", "only") and z.get("kinds") in ("person", "animal"):
        out["kinds"] = z["kinds"]                         # 2.98.13: the zone acts only on persons / only on animals (066)
    if mode == "loiter":
        try:
            out["secs"] = int(max(3, min(600, float(z.get("secs") or 20))))
        except (TypeError, ValueError):
            out["secs"] = 20
    if z.get("anchor") and mode not in FIXED_MODES:
        out["anchor"] = True                              # 2.98.30: «Platz einrichten» (317): stays on its place when the head turns
    if z.get("src") == "place":
        out["src"] = "place"
    if mode in FIXED_MODES or out.get("anchor"):
        ang = z.get("ang")
        if isinstance(ang, list) and len(ang) == len(pts) and all(isinstance(a, (list, tuple)) and len(a) == 2 and _num(a[0]) and _num(a[1]) for a in ang):
            out["ang"] = [[round(float(a[0]), 3), round(float(a[1]), 3)] for a in ang]
    return out


# ---- 2.98.7: the sleeping place stays where the bed is, wherever the camera looks ----
SLEEP_POS = deque(maxlen=60)          # (time, pan %, tilt %) - the picture comes later than the servo: mask every recent direction
SLEEP_MARGIN = 3.0                    # degrees around the bed (the servo and the field of view are not exact)


def _cam_deg(pan, tilt):
    return (float(pan) - 50.0) / 50.0 * servo_half("pan"), (float(tilt) - 50.0) / 50.0 * servo_half("tilt")


def sleep_to_ang(points, pan=None, tilt=None):
    """picture points 0..1 (camera at pan / tilt) -> directions in degrees (right +, up +)"""
    hf, vf = cam_fov()
    a0, e0 = _cam_deg(CFG["pan"] if pan is None else pan, CFG["tilt"] if tilt is None else tilt)
    th, tv = math.tan(math.radians(hf / 2.0)), math.tan(math.radians(vf / 2.0))
    return [[round(a0 + math.degrees(math.atan((x - 0.5) * 2.0 * th)), 3), round(e0 + math.degrees(math.atan((0.5 - y) * 2.0 * tv)), 3)] for x, y in points]


def sleep_project(ang, pan=None, tilt=None, margin=0.0):
    """directions in degrees -> picture points 0..1 for the camera at pan / tilt (may lie outside the picture). The edges are
    cut into small steps, so the straight lines of the bed stay right also near the border of the picture."""
    if not ang:
        return []
    hf, vf = cam_fov()
    a0, e0 = _cam_deg(CFG["pan"] if pan is None else pan, CFG["tilt"] if tilt is None else tilt)
    th, tv = math.tan(math.radians(hf / 2.0)), math.tan(math.radians(vf / 2.0))
    ca = sum(a[0] for a in ang) / len(ang); ce = sum(a[1] for a in ang) / len(ang)
    pts = []
    for a, e in ang:                                     # a little bigger: margin degrees away from the middle
        d = math.hypot(a - ca, e - ce) or 1.0
        pts.append((a + (a - ca) / d * margin, e + (e - ce) / d * margin))
    out = []
    for i in range(len(pts)):
        (a1, e1), (a2, e2) = pts[i], pts[(i + 1) % len(pts)]
        for k in range(8):
            a = a1 + (a2 - a1) * k / 8.0; e = e1 + (e2 - e1) * k / 8.0
            da = a - a0
            if servo_half("pan") >= 179.0:                     # 2.98.30: a 360° head - the shorter way round
                da = (da + 180.0) % 360.0 - 180.0
            da = max(-80.0, min(80.0, da)); de = max(-80.0, min(80.0, e - e0))
            out.append([0.5 + math.tan(math.radians(da)) / (2.0 * th), 0.5 - math.tan(math.radians(de)) / (2.0 * tv)])
    return out


FIXED_MODES = ("privacy", "sleep")    # 2.98.9: privacy zones stay on their place too (before: fixed to the picture - a turning
                                      # head showed the neighbour's tent for a moment)


def fixed_zones():
    return [z for z in ZONES if z["mode"] in FIXED_MODES and z.get("ang")]


def anchored_zones():
    """2.98.30: every zone whose corners are kept as directions - the black ones (FIXED_MODES) and the zones of
    «Platz einrichten» (ignore / line / loiter with "anchor": they follow the place, not the picture)"""
    return [z for z in ZONES if z.get("ang") and (z["mode"] in FIXED_MODES or z.get("anchor"))]


def zone_here(z):
    """False for an anchored zone that lies outside the picture now (the head looks elsewhere)"""
    return not z.get("anchor") or z.get("vis", True)


def sleep_zones():
    return [z for z in ZONES if z["mode"] == "sleep" and z.get("ang")]


def fixed_migrate():
    """2.98.9: privacy zones of older versions have no directions yet - they were drawn at the position the camera has now
    (the start position is saved), so they get their directions from there once"""
    n = 0
    for z in ZONES:
        if z["mode"] in FIXED_MODES and not z.get("ang"):
            try:
                z["ang"] = sleep_to_ang(z["points"]); n += 1
            except Exception:
                pass
    return n


def sleep_update(now=None):
    """remember where the camera looks and move the corners of the sleeping places (for the zone editor and zone_allows)"""
    now = time.time() if now is None else now
    pos = (round(float(CFG["pan"]), 2), round(float(CFG["tilt"]), 2))
    if not SLEEP_POS or SLEEP_POS[-1][1:] != pos:
        SLEEP_POS.append((now,) + pos)
    for z in anchored_zones():
        if z.get("_at") != pos:
            z["_at"] = pos
            pp = sleep_project(z["ang"], *pos)
            corners = pp[::8]                                # the corners (every 8th point)
            if z["mode"] == "line" and len(pp) >= 9:
                corners = [pp[0], pp[8]]                     # a line: its two ends
            z["points"] = [[round(min(1.0, max(0.0, x)), 4), round(min(1.0, max(0.0, y)), 4)] for x, y in corners]
            z["vis"] = any(0.0 <= x <= 1.0 and 0.0 <= y <= 1.0 for x, y in pp)


def sleep_polys(w, h, now=None):
    """pixel polygons of the sleeping places for every direction of the last 2 s"""
    now = time.time() if now is None else now
    zs = fixed_zones()
    if not zs:
        return []
    L = list(SLEEP_POS)
    poss = {(round(float(CFG["pan"]), 2), round(float(CFG["tilt"]), 2))}
    for i, p in enumerate(L):                            # every direction the camera had during the last 2 s
        end = L[i + 1][0] if i + 1 < len(L) else now
        if now - end < 2.0:
            poss.add(p[1:])
    out = []
    for z in zs:
        for pos in poss:
            pp = sleep_project(z["ang"], pos[0], pos[1], SLEEP_MARGIN)
            if pp:
                out.append(np.array([(int(round(x * w)), int(round(y * h))) for x, y in pp], np.int32))
    return out


def _side(a, b, p):
    """> 0: p is on the right-hand side of the line a -> b (screen coordinates, y down)."""
    return (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])


def _segments_cross(p1, p2, a, b):
    d1, d2, d3, d4 = _side(a, b, p1), _side(a, b, p2), _side(p1, p2, a), _side(p1, p2, b)
    return (d1 > 0) != (d2 > 0) and d1 != 0 and d2 != 0 and (d3 > 0) != (d4 > 0)


class ZoneWatch:
    """Lines (crossed, optionally only in one direction) and dwell areas (a person stays longer than N s). Works on the
    person tracks; the point that counts is the feet (bottom middle of the box), like the other zones."""
    def __init__(self):
        self.st = {}

    def update(self, persons, pw, ph, frame, now):
        zs = [z for z in ZONES if z["mode"] in ("line", "loiter") and zone_here(z)]
        if not zs:
            self.st.clear(); return []
        if STATE.get("tracking") or manual_active() or str(STATE.get("patrol_status", "")).startswith("moving"):
            self.st.clear(); return []                        # the camera moves: positions are not comparable
        events, seen = [], set()
        for t in persons:
            x, y, w, h = t.box[:4]
            p = ((x + w / 2.0) / pw, (y + h * 0.95) / ph)
            seen.add(t.id)
            s_ = self.st.setdefault(t.id, {"p": p, "t": now, "in": {}, "done": set(), "last": {}})
            for z in zs:
                if z["mode"] == "line" and z["id"] not in s_["done"]:
                    a, b = z["points"]
                    sd = _side(a, b, p)
                    if abs(sd) < 1e-9:
                        continue                                  # exactly on the line: decide with the next point
                    old = s_["last"].get(z["id"])
                    s_["last"][z["id"]] = (p, sd)
                    if old is None or (old[1] > 0) == (sd > 0):
                        continue
                    q = old[0]                                    # the side changed: did the way pass through the line itself?
                    if _side(q, p, a) * _side(q, p, b) <= 0:
                        if z.get("dir", "both") == "both" or (z["dir"] == "ab") == (sd > 0):
                            s_["done"].add(z["id"]); events.append(("line", z))
                elif z["mode"] == "loiter" and z["id"] not in s_["done"]:
                    if point_in_poly(p[0], p[1], z["points"]):
                        t_in = s_["in"].setdefault(z["id"], now)
                        if now - t_in >= z.get("secs", 20):
                            s_["done"].add(z["id"]); events.append(("loiter", z))
                    else:
                        s_["in"].pop(z["id"], None)
            s_["p"] = p; s_["t"] = now
        for k in [k for k, v in self.st.items() if k not in seen and now - v["t"] > 10]:
            self.st.pop(k, None)
        for kind, z in events:
            zone_event(kind, z, frame)
        return events


def zone_event(kind, z, frame):
    if kind == "line":
        txt = trf("Person crossed the line «{zone}»", zone=z["name"])
        log_event("person", f"Person crossed the line «{z['name']}»")
    else:
        txt = trf("Person stays in «{zone}» for more than {secs} s", zone=z["name"], secs=z.get("secs", 20))
        log_event("person", f"Person stays in «{z['name']}» for more than {z.get('secs', 20)} s")
    STATE["zone_last"] = {"t": time.time(), "text": txt}
    push_alert("person", txt, zone=z["name"])
    w = WATCH_REF.get("w")
    if w is not None and is_armed():
        jpg = None
        try:
            ok, buf = cv2.imencode(".jpg", frame, [cv2.IMWRITE_JPEG_QUALITY, 80])
            jpg = buf.tobytes() if ok else None
        except cv2.error:
            pass
        w.notifier.info(txt, "", title="{name}: " + tr("line" if kind == "line" else "dwell area"), jpg=jpg, fname="zone.jpg")


def apply_privacy(frame):
    """Paint the privacy zones and the sleeping places black (in place). Returns the frame. Both stay where they are when
    the head turns (directions in degrees); a privacy zone without directions (should not happen) is painted as drawn."""
    zs = [z for z in ZONES if z["mode"] == "privacy" and not z.get("ang")]
    if zs and fixed_migrate():                          # older zones: directions once, from where the camera looks now
        zs = [z for z in ZONES if z["mode"] == "privacy" and not z.get("ang")]
        try:
            save_settings(); log_event("sys", "Privacy zones: they now stay on their place when the head turns")
        except Exception:
            pass
    sl = any(z["mode"] in FIXED_MODES and z.get("ang") for z in ZONES)
    if not sl and frame is not None and any(z.get("anchor") for z in ZONES):
        sleep_update()                                   # 2.98.30: the zones of the place follow the head (317)
    if (not zs and not sl) or frame is None:
        return frame
    h, w = frame.shape[:2]
    if not frame.flags.writeable:
        frame = frame.copy()
    polys = [np.array([(int(round(x * w)), int(round(y * h))) for x, y in z["points"]], np.int32) for z in zs]
    if sl:
        sleep_update()
        polys += sleep_polys(w, h)
    if polys:
        cv2.fillPoly(frame, polys, (0, 0, 0))
    return frame


def point_in_poly(x, y, pts):
    inside, j = False, len(pts) - 1
    for i in range(len(pts)):
        xi, yi, xj, yj = pts[i][0], pts[i][1], pts[j][0], pts[j][1]
        if (yi > y) != (yj > y) and x < (xj - xi) * (y - yi) / ((yj - yi) or 1e-9) + xi:
            inside = not inside
        j = i
    return inside


def zone_allows(nx, ny, kind=None):
    """kind: "person" / "animal" / "other" or None (= every zone counts, as before 2.98.13). An ignore / only-here zone
    with «applies to» persons or animals (z["kinds"]) acts only on that kind; the other kinds see it as if it did not exist."""
    zs = ZONES
    if not zs:
        return True
    ap = lambda z: kind is None or z.get("kinds", "all") in ("all", kind)
    for z in zs:
        if z["mode"] in ("ignore", "privacy", "sleep") and (z["mode"] != "ignore" or ap(z)) and zone_here(z) and point_in_poly(nx, ny, z["points"]):
            return False
    only = [z for z in zs if z["mode"] == "only" and ap(z) and zone_here(z)]
    return (not only) or any(point_in_poly(nx, ny, z["points"]) for z in only)


def zone_box_ok(b, pw, ph, kind=None):
    """Box (x, y, w, h, ...) in processing-frame pixels; the point that counts is the middle of the feet region."""
    if not ZONES:
        return True
    return zone_allows((b[0] + b[2] / 2.0) / pw, (b[1] + b[3] * 0.85) / ph, kind)


def zones_set(lst):
    if not isinstance(lst, list):
        return False, "invalid zones"
    out = []
    old = {z["id"]: z for z in ZONES if z["mode"] in FIXED_MODES or z.get("anchor")}
    for z in lst[:MAX_ZONES]:
        c = _clean_zone(z, len(out))
        if c:
            if c["mode"] in FIXED_MODES or c.get("anchor"):     # 2.98.7 / 2.98.9: corners as directions from where the camera looks now
                o = old.get(c["id"])
                same = o and o.get("ang") and len(o.get("points") or []) == len(c["points"]) and all(
                    abs(a[0] - b[0]) < 0.003 and abs(a[1] - b[1]) < 0.003 for a, b in zip(o["points"], c["points"]))
                c["ang"] = o["ang"] if same else (c["ang"] if c.get("ang") and not o else sleep_to_ang(c["points"]))   # new with directions (317): kept
                c.pop("_at", None)
            out.append(c)
    with LOCK:
        ZONES[:] = out
    save_settings(); log_event("sys", f"Zones updated ({len(out)})")
    return True, ""


def presence_home():
    """2.97.0: one answer to «is somebody home?» from both ways: the ping of the devices (presence_hosts) and the phone /
    watch seen in the Wi-Fi or by Bluetooth (presence_macs / presence_bt). True if one of them sees somebody."""
    a = PRESENCE["home"]
    try:
        P = TOOLS["presence"]
        b = P.get("here") if (CFG.get("presence_macs") or CFG.get("presence_bt")) else None
    except (NameError, KeyError):
        b = None
    if a is True or b is True:
        return True
    if a is None and b is None:
        return None
    return False


# ----------------------------------------------------------------------------
# Presence: is somebody home? (ping the phones / devices from the settings)
# ----------------------------------------------------------------------------
PRESENCE = {"home": None, "seen": {}, "start": time.time()}
_HOST_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9.\-:]{0,79}$")


def _ping(host):
    try:
        return subprocess.run(["ping", "-c", "1", "-W", "1", host], capture_output=True, timeout=5).returncode == 0
    except (OSError, subprocess.SubprocessError):
        return False


class PresenceMonitor:
    """Every 20 s: ping the configured devices. 'home' = one of them answered within the last 'away_after' minutes
    (phones sleep their Wi-Fi, so a single missed ping means nothing)."""
    def __init__(self):
        threading.Thread(target=self.loop, daemon=True).start()

    def loop(self):
        while True:
            try:
                self.check()
            except Exception as e:
                log_event("sys", f"Presence error: {e}")
            time.sleep(20.0)

    def check(self):
        hosts = [h for h in CFG["presence_hosts"] if isinstance(h, str) and _HOST_RE.match(h)]
        if not hosts or shutil.which("ping") is None:
            PRESENCE["home"] = None; STATE["presence"] = "unknown"; return
        ts = [threading.Thread(target=lambda h=h: PRESENCE["seen"].__setitem__(h, time.time()) if _ping(h) else None, daemon=True) for h in hosts]
        for t in ts:
            t.start()
        for t in ts:
            t.join(6.0)
        now, grace = time.time(), CFG["away_after"] * 60.0
        seen = [PRESENCE["seen"].get(h, 0.0) for h in hosts]
        if any(now - x < grace for x in seen):
            home = True
        elif not any(seen) and now - PRESENCE["start"] < grace:
            home = None                                    # just started, nothing answered yet -> unknown
        else:
            home = False
        if home != PRESENCE["home"]:
            log_event("sched", "Presence: " + {True: "somebody is home", False: "nobody home", None: "unknown"}[home])
        PRESENCE["home"] = home
        STATE["presence"] = {True: "home", False: "away", None: "unknown"}[home]


