NIGHT_SET = {"detection_on": True, "ai_enabled": True, "record": True, "snapshot_on_person": True, "notify_on": True,
             "notify_prealarm": True, "lowlight_auto": True, "nightvision_auto": True, "report_on": True, "diary_on": True,
             "timelapse_on": False}   # 2.97.0: power saving only on battery (2.98.14: replaces the old mode «night»)


def night_end_ts(now=None):
    """2.98.9: the end of the current / coming night time (report_hour) as a timestamp"""
    now = now or sim_now()                               # the simulated night while connected (285)
    end = now.replace(hour=int(CFG["report_hour"]) % 24, minute=0, second=0, microsecond=0)
    return (end if end > now else end + timedelta(days=1)).timestamp()


def night_guard_tick():
    """2.98.9: «Heute Nacht bewachen» ends with the night time - disarmed in the morning (only if it is still armed and was
    armed by it)"""
    u = float(CFG.get("night_guard_until") or 0)
    if not u:
        return
    if not CFG["armed"]:
        CFG["night_guard_until"] = 0.0; save_settings(); return
    if sim_now().timestamp() >= u:
        CFG["night_guard_until"] = 0.0
        disarm()
        save_settings()
        log_event("sys", "Guard tonight: the night time is over - disarmed")


def night_guard(lang=None):
    """«Guard tonight»: what a night needs on, armed after the countdown; returns what was done and what is missing."""
    L = norm_lang(lang) if lang else cur_lang()
    done = []
    for k, v in NIGHT_SET.items():
        if k in CFG and CFG[k] != v:
            CFG[k] = v; sched_user_changed(k)
    try:
        mains = bool(mode_power()[0])
    except Exception:
        mains = False
    if CFG["eco_on"] != (not mains):
        CFG["eco_on"] = not mains; sched_user_changed("eco_on")
    if (STATE.get("audio") or {}).get("status") == "listening" and not CFG["noise_alarm"]:
        CFG["noise_alarm"] = True; done.append(tr("Noise alarm on", L))
    if STATE.get("thermal") == "connected" and not CFG["thermal_alarm"]:
        CFG["thermal_alarm"] = True; done.append(tr("Thermal alarm on", L))
    if CFG.get("light_ir_out") and CFG.get("light_ir") == "off":     # 2.98.14: from the old mode «night»: infrared by itself
        CFG["light_ir"] = "auto"; done.append(tr("Infrared light by itself in the dark", L))
    save_settings()
    done = [tr("Detection, AI and recordings on", L), tr("Push messages on", L), tr("Night vision and low light automatic", L),
            tr("Night report in the morning", L) + f" ({int(CFG['report_hour']):02d}:00)",
            tr("Power saving on", L) if CFG["eco_on"] else tr("Power saving off (mains power): full attention", L)] + done
    arm()
    CFG["night_guard_until"] = night_end_ts(); save_settings()      # 2.98.9: ends with the night time
    d = int(float(CFG["arm_delay"]))
    done.append(trf("Armed in {s} s - leave the area now", L, s=d) if d else tr("Armed", L))
    done.append(tr("Until the end of the night time", L) + f" ({int(CFG['report_hour']) % 24:02d}:00)")
    h = health_check(L)
    miss = [{"icon": x["icon"], "title": x["title"], "text": x["text"], "tip": x["tip"], "level": x["level"]}
            for x in h["items"] if x["level"] == "bad" or (x["level"] == "warn" and x["id"] in ("servo", "net", "power", "temp", "disk", "batt"))]
    log_event("sys", "Guard tonight: armed" + (f", {len(miss)} problem(s) open" if miss else ""))
    return {"ok": True, "done": done, "missing": miss}


# ---- power mode (2.95.19): the counterpart of power saving - every picture through the AI, bigger processing, best
# stream, the simulator at full speed, the processor at its highest clock. Switching it off restores everything. ----
TURBO_SET = {"eco_on": False, "ai_every": 1, "proc_width": 640, "web_quality": 88, "web_width": 1920, "sim_eco": False, "sim_fps": 15}
_GOV = "/sys/devices/system/cpu/cpu{}/cpufreq/scaling_governor"


def _governor(want=None):
    """read (want=None) or set the governor of all processor cores; returns the old one (or "" if not possible)"""
    old = ""
    try:
        with open(_GOV.format(0)) as f:
            old = f.read().strip()
    except OSError:
        return ""
    if want:
        for i in range(os.cpu_count() or 4):
            try:
                with open(_GOV.format(i), "w") as f:
                    f.write(want)
            except OSError:
                pass
    return old


def _ovl_handover(me, k, v):
    """2.97.0: an overlay (camping, mode, power mode) is switched off while one switched on AFTER it still holds k: that one
    gets the value to give back later - otherwise switching off in another order left e.g. power saving on for good"""
    mine = (CFG.get({"camping": "camping_prev", "mode": "mode_prev", "turbo": "turbo_prev"}[me]) or {})
    seq = float(mine.get("_seq", 0) or 0) if isinstance(mine, dict) else 0.0
    for name, on_key, prev_key in (("camping", "camping", "camping_prev"), ("mode", "mode", "mode_prev"), ("turbo", "turbo_on", "turbo_prev")):
        if name == me or not CFG.get(on_key):
            continue
        p = CFG.get(prev_key)
        if isinstance(p, dict) and k in p and float(p.get("_seq", 0) or 0) > seq:
            p[k] = v
            return True
    return False


def turbo_set(on, who="web"):
    on = bool(on)
    if on and not CFG["turbo_on"]:
        prev = {k: CFG[k] for k in TURBO_SET if k in CFG}
        prev["_governor"] = _governor()
        prev["_seq"] = time.time()
        CFG["turbo_prev"] = prev
        for k, v in TURBO_SET.items():
            if k in CFG:
                CFG[k] = v; sched_user_changed(k)
        g_ = _governor("performance")
        CFG["turbo_on"] = True
        log_event("sys", f"Power mode ON ({who}): every picture through the AI, best quality" + ("" if g_ else " (processor clock: not allowed without root)"))
    elif not on and CFG["turbo_on"]:
        prev = CFG["turbo_prev"] if isinstance(CFG["turbo_prev"], dict) else {}
        for k, v in prev.items():
            if k in CFG and isinstance(v, type(CFG[k])) and not _ovl_handover("turbo", k, v):
                CFG[k] = v
        if prev.get("_governor"):
            _governor(prev["_governor"])
        CFG["turbo_on"] = False; CFG["turbo_prev"] = {}
        log_event("sys", f"Power mode OFF ({who}) - previous settings restored")
    save_settings()
    return True, ""


# ---- modes (2.95.47): one switch sets up the whole device. Camping, campfire games (battery, little power - the
# guard watches on sparingly), gamer (only with mains power - power mode, all games), home, wildlife, transport.
# «Own settings» (no mode) brings back what was set before the first mode.
# 2.98.14 (Konzept): the mode is THE place for behaviour. The mode «night» is gone (= «Heute Nacht bewachen», a one-off for
# tonight); the camping profile IS the mode «Camping» (camping_set() switches the mode). The names are no states any more:
# the state is Aus / Wachsam / Voll (Schutz), the mode says what MoveEye is used for. ----
MODES = [("camping", "⛺", "Camping"), ("fire", "🔥", "Campfire games"), ("gamer", "🎮", "Gamer"), ("home", "🏠", "Home / garden"),
         ("wild", "🦌", "Wildlife watching"), ("transport", "🔕", "Transport / rest")]
MODE_INFO = {
    "": "Your own settings, no mode.",
    "camping": "Full guard: alarms, recordings, own Wi-Fi, armed after the countdown. Power saving while all is quiet.",
    "fire": "The game corner is open for the phones (in the Wi-Fi MoveEye is in). The guard watches on sparingly: few pictures, the AI only at movement - an animal at the tent is still reported. Back to camping at the set time or when the battery gets low.",
    "gamer": "Only with mains power: power mode, all games and the game collection, the best picture. The guard only if you want it. On battery MoveEye goes back to the campfire games by itself.",
    "home": "Guarding house and garden: alarms and recordings on, no own Wi-Fi, no camping profile.",
    "wild": "Animals: no siren, the light does not go on by itself (it would scare them), many pictures, the camera follows what moves.",
    "transport": "Rest while travelling: no detection, no recordings, no alarms - only the battery, GPS theft and tamper protection stay on.",
}
MODE_SETS = {
    "fire": {"eco_on": True, "ai_every": 3, "proc_width": 416, "web_quality": 60, "web_width": 960, "patrol": False, "track_person": False,
             "track_motion": False, "timelapse_on": False, "notify_prealarm": False, "detection_on": True, "notify_on": True, "record": True},
    "home": {"detection_on": True, "record": True, "snapshot_on_person": True, "notify_on": True, "notify_prealarm": False, "eco_on": False},
    # 2.98.14: «no light by itself» = the white light «off» (before: light_white_auto False, not a valid choice)
    "wild": {"detection_on": True, "siren_on": "off", "light_white": "off", "record": True, "snapshot_on_person": True, "notify_prealarm": True,
             "track_motion": True, "track_person": True, "eco_on": False, "lowlight_auto": True},
    "transport": {"detection_on": False, "record": False, "timelapse_on": False, "patrol": False, "track_person": False, "track_motion": False,
                  "eco_on": True, "notify_prealarm": False},
}
MODE_RT = {"msg": "", "gov": "", "party": False, "hotspot": False, "turbo": False, "rest": False, "checked": 0.0}


def mode_power():
    """(mains power?, why not) - the gamer mode needs it. Unknown supply (no UPS HAT, no voltage reading) counts as mains."""
    b = STATE.get("battery") or {}
    sup = STATE.get("supply") or {}
    if b.get("on") and b.get("on_battery"):
        return False, "runs on the battery"
    if sup.get("uv_now"):
        return False, "under-voltage: the power supply is too weak"
    return True, ""


def _mode_keys():
    ks = set()
    for d in MODE_SETS.values():
        ks.update(d)
    return [k for k in ks if k in CFG] + ["armed", "thermal_alarm"]


def _mode_leave(m):
    """undo what the mode switched on (camping profile, power mode, game corner, rest, Wi-Fi, governor)"""
    if m == "camping" and CFG["camping"]:
        _camping_overlay(False)
    if MODE_RT["turbo"] and CFG["turbo_on"]:
        turbo_set(False, "mode")
    MODE_RT["turbo"] = False
    if MODE_RT["rest"] and toolmode_on() and TOOLMODE.get("by") == "gamer mode":
        toolmode_set(0, "gamer mode")
    MODE_RT["rest"] = False
    if MODE_RT["party"] and party_on():
        games_all_close("mode")
    MODE_RT["party"] = False
    if MODE_RT["gov"]:
        _governor(MODE_RT["gov"])
        MODE_RT["gov"] = ""
    if MODE_RT.get("tv"):
        tv_show(False, "mode")
        MODE_RT["tv"] = False


def mode_set(m, who="web"):
    """switch the device to a mode ("" = own settings again)"""
    m = str(m or "")
    if m == "night":                                        # 2.98.14: the old mode «night» = «Heute Nacht bewachen»
        r = night_guard()
        return bool(r.get("ok")), ""
    if m and m not in dict((x[0], x) for x in MODES):
        return False, "unknown mode"
    if m == "gamer":
        ok, why = mode_power()
        if not ok:
            return False, "The gamer mode needs mains power: " + why
    old = CFG.get("mode") or ""
    if old == m:
        return True, ""
    _mode_leave(old)
    prev = CFG["mode_prev"] if isinstance(CFG["mode_prev"], dict) else {}
    if not old:                                             # first mode: keep the own settings
        prev = {k: CFG[k] for k in _mode_keys()}
        prev["hotspot_on"] = bool((STATE.get("hotspot") or {}).get("on"))
        prev["_seq"] = time.time()
        CFG["mode_prev"] = prev
    for k, v in prev.items():                               # every mode starts from the own settings
        if k in CFG and k not in ("armed", "hotspot_on") and isinstance(v, type(CFG[k])) and not (not m and _ovl_handover("mode", k, v)):
            CFG[k] = v
    CFG["mode"] = m
    CFG["mode_since"] = time.time()
    if not m:                                               # own settings again
        if prev.get("armed", CFG["armed"]):
            arm()
        else:
            disarm()
        if not prev.get("hotspot_on", False) and (STATE.get("hotspot") or {}).get("on") and MODE_RT["hotspot"]:
            hotspot_switch_later(False, 2.0)
        MODE_RT["hotspot"] = False
        CFG["mode_prev"] = {}
        log_event("sys", f"Mode off ({who}): own settings again")
        save_settings()
        return True, ""
    for k, v in MODE_SETS.get(m, {}).items():
        if k in CFG:
            CFG[k] = v; sched_user_changed(k)
    hs_on = bool((STATE.get("hotspot") or {}).get("on"))
    if m == "camping":
        _camping_overlay(True)
    elif m in ("fire", "gamer"):
        # 2.95.49: the Wi-Fi is NOT switched here - the own Wi-Fi would cut the phones off the network they are in (the
        # page froze). The game corner works in the network MoveEye is in; the own Wi-Fi is a switch of its own.
        if not party_on():
            games_all_open(float(CFG["mode_fire_hours"]) if m == "fire" else 8.0, "mode"); MODE_RT["party"] = True   # 2.98.7: all games
        if m == "fire":
            g = _governor("powersave")
            if g:
                MODE_RT["gov"] = g
            arm()                                           # the guard watches on, sparingly
        else:
            turbo_set(True, "gamer mode"); MODE_RT["turbo"] = True
            if CFG["mode_gamer_watch"]:
                arm()
            else:
                toolmode_set(720, "gamer mode"); MODE_RT["rest"] = True
    elif m in ("home", "wild"):
        arm()
    elif m == "transport":
        disarm()
        g = _governor("powersave")
        if g:
            MODE_RT["gov"] = g
    if m in ("fire", "gamer") and CFG.get("tv_auto") and _tv_browser():
        tv_show(True, "mode")                               # 2.95.51: the TV view on the HDMI (if a desktop is there)
        MODE_RT["tv"] = True
    MODE_RT["msg"] = ""
    log_event("sys", f"Mode «{dict((x[0], x[2]) for x in MODES)[m]}» on ({who})")
    save_settings()
    return True, ""


def mode_tick():
    """every 10 s: the campfire ends at its time or when the battery gets low; the gamer mode falls back without mains power"""
    m = CFG.get("mode") or ""
    w = WATCH_REF.get("w")
    def push(txt):
        MODE_RT["msg"] = txt
        log_event("sys", txt)
        if w is not None:
            try:
                w.notifier.info(tr(txt), title="{name}: " + tr("Mode"))
            except Exception:
                pass
    if m == "fire":
        b = STATE.get("battery") or {}
        until = str(CFG.get("mode_fire_until") or "")
        late = False
        if re.match(r"^\d{1,2}:\d{2}$", until):
            hh, mm = map(int, until.split(":"))
            now = sim_now(); since = datetime.fromtimestamp(float(CFG.get("mode_since") or 0))   # (285)
            end = now.replace(hour=hh % 24, minute=mm % 60, second=0, microsecond=0)
            late = since < end <= now or (end < since and now.date() > since.date() and now >= end)
        low = b.get("on") and b.get("on_battery") and b.get("pct") is not None and float(b["pct"]) < float(CFG["mode_fire_min_pct"])
        if late or low:
            mode_set("camping", "auto")
            push("Campfire games ended (" + ("battery low" if low else "time") + ") - back to camping")
    elif m == "gamer":
        ok, why = mode_power()
        if not ok:
            mode_set("fire", "auto")
            push("Gamer mode: no mains power any more - campfire games on (" + why + ")")


def mode_state():
    ok, why = mode_power()
    m = CFG.get("mode") or ""
    fit = USE_MODES.get(CFG.get("use_case") or "") if CFG.get("ui_simple") else None    # 2.98.14: «Simple» offers what fits the use case
    return {"id": m, "since": CFG.get("mode_since") or 0, "msg": MODE_RT["msg"], "power_ok": ok, "power_why": why,
            "list": [{"id": i, "icon": ic, "name": n, "info": MODE_INFO[i]} for i, ic, n in MODES if fit is None or i in fit or i == m], "own_info": MODE_INFO[""],
            "fire_until": CFG["mode_fire_until"], "fire_min_pct": CFG["mode_fire_min_pct"], "gamer_watch": bool(CFG["mode_gamer_watch"]), "fire_persons": bool(CFG.get("mode_fire_persons")),
            "camping": bool(CFG["camping"])}


def turbo_state():
    return {"on": bool(CFG["turbo_on"]), "gov": _governor() if CFG["turbo_on"] else "", "temp": STATE.get("cpu_temp"), "cpu": STATE.get("cpu")}


def camping_set(on, hotspot_delay=2.0):
    """2.98.14 (Konzept): the camping profile IS the mode «Camping» - the switch «Camping-Profil» (web, window, older pages)
    switches the mode. Off: back to the own settings (or, an older profile switched on without the mode: only the profile)."""
    if on:
        return mode_set("camping", "camping profile") if (CFG.get("mode") or "") != "camping" else (True, "")
    if (CFG.get("mode") or "") == "camping":
        return mode_set("", "camping profile")
    return _camping_overlay(False, hotspot_delay)


def _camping_overlay(on, hotspot_delay=2.0):
    """what the mode «Camping» switches: own Wi-Fi, alarms, recordings ... (the previous values are kept to give back)"""
    netauto_pause()
    if on and not CFG["camping"]:
        prev = {k: CFG[k] for k in list(CAMPING_SET) + ["thermal_alarm", "armed", "hotspot_on"]}
        prev["_seq"] = time.time()
        CFG["camping_prev"] = prev
        for k, v in CAMPING_SET.items():
            CFG[k] = v; sched_user_changed(k)
        if CFG["thermal_source"]:
            CFG["thermal_alarm"] = True
        CFG["camping"] = True
        log_event("sys", "Camping profile ON")
        arm()
        if wifi_backend() == "nm" and not STATE["hotspot"].get("on"):
            hotspot_switch_later(True, hotspot_delay)
    elif not on and CFG["camping"]:
        prev = CFG["camping_prev"] if isinstance(CFG["camping_prev"], dict) else {}
        for k, v in prev.items():
            if k in CFG and k not in ("armed", "hotspot_on") and isinstance(v, type(CFG[k])) and not _ovl_handover("camping", k, v):
                CFG[k] = v
        CFG["camping"] = False; CFG["camping_prev"] = {}
        log_event("sys", "Camping profile OFF - previous settings restored")
        if prev.get("armed", True):
            CFG["armed"] = True; ARM["at"] = 0.0; ARM["announced"] = True; arm_tick()
        else:
            disarm()
        if not prev.get("hotspot_on", False) and STATE["hotspot"].get("on"):
            hotspot_switch_later(False, hotspot_delay)
    save_settings()
    return True, ""


# ----------------------------------------------------------------------------
# 2.98.14 (Konzept, Wunsch Daniel): EIN Ort entscheidet, was das Gerät tut - der Modus (130). Der Einsatzzweck (use_case)
# entscheidet nur, was angezeigt wird. Der Modus «Nachtwache» ist weg («Heute Nacht bewachen» macht das für eine Nacht),
# das Camping-Profil ist der Modus «Camping». Hier werden Einstellungen älterer Versionen beim Laden umgestellt, ohne dass
# sich am Verhalten des Geräts etwas ändert (Schutz bleibt, wie er ist; nichts wird ein- oder ausgeschaltet):
#  - Modus «night» aktiv -> kein Modus mehr, die jetzigen Werte bleiben die eigenen Einstellungen
#  - Camping-Profil ohne Modus -> Modus «Camping» (Ausschalten gibt wie bisher die alten Werte zurück)
#  - ungültige Licht-Werte aus den alten Modi (True / False statt einer Auswahl) -> gültige Auswahl mit gleicher Wirkung
#  - die Liste der gemerkten eigenen Einstellungen bekommt die neuen Schlüssel der Modi (z. B. das weisse Licht)
# ----------------------------------------------------------------------------
_LIGHT_AUTO_OK = ("alarm_dark", "alarm", "dark")


def _concept_fix_lights(d, live):
    """light_white_auto False (old mode wildlife) meant «never by itself»; light_ir_auto True (old mode night) never worked
    (no valid choice) - both become valid choices with the same effect"""
    if not isinstance(d, dict):
        return
    for n in ("white", "ir"):
        k = f"light_{n}_auto"
        if k in d and d[k] not in _LIGHT_AUTO_OK:
            if d[k] is False and live and d.get("light_" + n) == "auto":
                d["light_" + n] = "off"                       # same effect: the light does not go on by itself
            d[k] = "alarm_dark" if n == "white" else "dark"


def concept_migrate():
    """called after loading / importing the settings (apply_settings in 040 calls it); returns the list of what was changed"""
    did = []
    m = str(CFG.get("mode") or "")
    if m == "night":
        CFG["mode"] = ""; CFG["mode_prev"] = {}; CFG["mode_since"] = 0.0
        did.append("mode night -> own settings (values kept)")
    elif m and m not in dict((x[0], x) for x in MODES):
        CFG["mode"] = ""; CFG["mode_prev"] = {}
        did.append(f"unknown mode {m} -> own settings")
    if CFG.get("camping") and (CFG.get("mode") or "") != "camping" and not CFG.get("mode"):
        cp = CFG.get("camping_prev") if isinstance(CFG.get("camping_prev"), dict) else {}
        CFG["mode"] = "camping"; CFG["mode_since"] = float(cp.get("_seq") or time.time())
        CFG["mode_prev"] = {"armed": bool(cp.get("armed", False)), "hotspot_on": bool(cp.get("hotspot_on", False)),
                            "_seq": float(cp.get("_seq") or time.time()) - 0.001}
        did.append("camping profile -> mode camping")
    _concept_fix_lights(CFG, True)
    for pk in ("mode_prev", "camping_prev", "turbo_prev"):
        _concept_fix_lights(CFG.get(pk), False)
    prev = CFG.get("mode_prev")
    if CFG.get("mode") and isinstance(prev, dict) and prev and CFG["mode"] != "camping":
        for k in _mode_keys():                               # keys the modes switch now, but not when this mode was chosen
            if k not in prev and k in CFG and k not in MODE_SETS.get(CFG["mode"], {}):
                prev[k] = CFG[k]
    if did:
        log_event("sys", "Settings of an older version taken over: " + "; ".join(did))
    return did
# ----------------------------------------------------------------------------
# 2.95.105: one place for everything that protects: a level instead of many switches
#   off   - no alarms
#   watch - «Wachsam»: armed, push messages, sabotage check; no siren
#   full  - «Voller Schutz»: + guarded things (reference scan), GPS theft tracking, siren after a while (escalation)
# Plus: the traffic light (what is missing, with a fix), presence of the owner's phone (armed when it is gone), a PIN
# for disarming (a wrong PIN 3 times = theft alarm); presence (presence_auto, 150) is shown here too, and «Schutz testen» (with the simulator: sabotage, a person).
# ----------------------------------------------------------------------------
PROTECT = {"esc_t": 0.0, "esc_id": 0, "pin_fails": [], "test": {"busy": False, "steps": [], "t": 0.0}}
PROTECT_LEVELS = ("off", "watch", "full")


def protect_level():
    """the level now: off when disarmed, else the chosen one (armed by other means = «watch»)"""
    if not CFG["armed"]:
        return "off"
    lv = CFG.get("protect_level") or "watch"
    return lv if lv in PROTECT_LEVELS and lv != "off" else "watch"


def protect_label(arm_state, left=0, lang=None):
    """2.98.0: one name for the state everywhere (web, window, alarm window): Aus / Wachsam / Voll"""
    lv = tr("Full protection", lang) if (CFG.get("protect_level") == "full") else tr("Watchful", lang)
    if arm_state in ("armed", "arming") and walktest_on():    # 2.98.15: during the walk test no alarms - say so (415)
        return tr("Walk test", lang)
    if arm_state == "armed":
        return lv
    if arm_state == "arming":
        return f"{lv} {tr('in', lang)} {int(left)} s"
    return tr("Off", lang)


def protect_set(level, who="web", answers=None):
    """switch the level; answers of the assistant (what, when, how) adjust what is switched on"""
    if level not in PROTECT_LEVELS:
        return False, "unknown level"
    A = answers or {}
    if level == "off":
        CFG["protect_level"] = "off"
        disarm()
        return True, ""
    CFG["protect_level"] = level
    CFG["notify_on"] = True
    CFG["tamper_on"] = True
    if level == "full" or A.get("device"):
        if CFG.get("gpsmod_on"):
            CFG["gps_theft"] = True
    if level == "full" or A.get("things"):
        CFG["refscan_on_arm"] = True                     # compare with the reference when armed (guarded things)
    react = A.get("react") or ("siren" if level == "full" else "push")
    CFG["escalate_on"] = react == "siren"
    if react in ("light", "siren"):
        CFG["light_white_auto"] = "alarm_dark" if CFG.get("light_white_auto") in ("", "dark") else CFG["light_white_auto"]
    if react == "siren" and CFG.get("siren_on") == "off":
        CFG["siren_on"] = "person"
    for k in ("protect_level", "notify_on", "tamper_on", "gps_theft", "refscan_on_arm", "escalate_on", "siren_on"):
        sched_user_changed(k)
    save_settings()
    when = A.get("when") or "now"
    if when == "night":
        night_guard()
    else:
        arm()
    if (level == "full" or A.get("things")) and not refscan_meta() and not REFSCAN["busy"]:
        refscan_start("scan", "protection assistant")     # no reference yet: take it now (before the countdown ends)
    log_event("sys", f"Protection: {level} ({who})")
    return True, ""


# ---- the traffic light ---------------------------------------------------------------------------------------------------
_PROT_CACHE = {"t": 0.0, "k": "", "v": None}


def protect_status(lang=None, force=False):
    """the state for the page (cached 3 s - the page asks every second)"""
    L = norm_lang(lang) if lang else cur_lang()
    k = L + str(CFG["armed"]) + str(CFG.get("protect_level")) + str(PROTECT["test"]["busy"]) + str(len(PROTECT["test"]["steps"]))
    if not force and _PROT_CACHE["v"] is not None and _PROT_CACHE["k"] == k and time.time() - _PROT_CACHE["t"] < 3.0:
        v = dict(_PROT_CACHE["v"]); v["arm"] = STATE.get("arm_state"); v["left"] = STATE.get("arm_left", 0)
        v["walk"] = walktest_on()
        return v
    v = _protect_status(L)
    _PROT_CACHE.update(t=time.time(), k=k, v=v)
    return dict(v, walk=walktest_on())                     # 2.98.15: walk test running = the state shows «Gehtest»


def _protect_status(L):
    T = lambda x: tr(x, L)
    lv = protect_level()
    items = []                                           # {"id", "ok", "text", "fix"}
    try:
        h = health_check(L)
        for x in h["items"]:
            if x["level"] == "bad":
                items.append({"id": "h_" + str(x["id"]), "ok": False, "text": x["title"] + ": " + x["text"], "fix": ""})
    except Exception:
        pass
    if not CFG.get("notify_on"):
        items.append({"id": "push", "ok": False, "text": T("Push messages are off"), "fix": "push"})
    if lv == "full" or CFG.get("protect_level") == "full":
        if not refscan_meta():
            items.append({"id": "ref", "ok": False, "text": T("No reference scan yet - guarded things cannot be checked"), "fix": "refscan"})
        if CFG.get("gpsmod_on") and GPSMOD.get("status") != "fix":
            items.append({"id": "gps", "ok": False, "text": T("GPS has no position yet"), "fix": ""})
        if CFG.get("escalate_on") and not out_selected():
            items.append({"id": "spk", "ok": False, "text": T("No loudspeaker for the siren"), "fix": "speaker"})
        if not CFG.get("protect_pin"):
            items.append({"id": "pin", "ok": False, "text": T("No PIN for disarming - a thief could switch it off"), "fix": "pin"})
    if CFG.get("backup_type", "off") == "off":
        items.append({"id": "backup", "ok": False, "text": T("Recordings are not copied away (backup off)"), "fix": "backup", "minor": True})
    tam = STATE.get("tamper") or {}
    tl = str(tam.get("last") or "")
    recent = False
    if re.match(r"\d\d:\d\d ", tl):
        try:
            hm = datetime.now().replace(hour=int(tl[:2]), minute=int(tl[3:5]), second=0)
            recent = 0 <= (datetime.now() - hm).total_seconds() < 600
        except ValueError:
            pass
    if recent:
        items.append({"id": "tamper", "ok": False, "text": T("Sabotage") + ": " + str(tam.get("last")), "fix": ""})
    bad = [x for x in items if not x.get("minor")]
    colour = "green" if not bad else ("red" if any(x["id"].startswith("h_") or x["id"] == "tamper" for x in bad) else "orange")
    # device protection in one line
    dev = []
    dev.append(("✓ " if CFG.get("tamper_on") else "– ") + T("sabotage check"))
    if CFG.get("gpsmod_on"):
        dev.append(("✓ " if GPSMOD.get("status") == "fix" else "⚠ ") + "GPS")
    dev.append(("✓ " if CFG.get("backup_type", "off") != "off" else "– ") + T("backup"))
    if CFG.get("protect_pin"):
        dev.append("✓ PIN")
    # the guarded things of the reference scan
    things = []
    meta = refscan_meta()
    if meta:
        miss = set()
        reps = refscan_reports()
        if reps:
            for n in (reps[0].get("gone") or []):
                miss.add(str(n))
        for it in (meta.get("watch") or [])[:12]:
            things.append({"name": it["name"], "pos": it["pos"], "box": [it["x"], it["y"], it["w"], it["h"]], "dir": REFSCAN_KINDS[meta["_kind"]],
                           "missing": it["name"] in miss})
    return {"level": lv, "chosen": CFG.get("protect_level") or "off", "arm": STATE.get("arm_state"), "left": STATE.get("arm_left", 0),
            "colour": colour, "items": items, "device": "  ·  ".join(dev), "things": things, "pin": bool(CFG.get("protect_pin")),
            "presence": {"on": bool(CFG.get("presence_auto")), "back": presence_back_mode(), "devices": len(CFG.get("presence_macs") or []) + len(CFG.get("presence_bt") or []),
                         "here": (TOOLS.get("presence") or {}).get("here")},
            "escalate": {"on": bool(CFG.get("escalate_on")), "s": int(CFG.get("escalate_siren_s", 30)), "pending": max(0, int(PROTECT["esc_t"] - time.time())) if PROTECT["esc_t"] else 0},
            "test": PROTECT["test"], "forecast": arm_forecast_text(L)}      # 2.98.13 (066)


# ---- escalation: light at once, push, the siren after a while unless somebody disarms --------------------------------------
def protect_on_alert(kind):
    if kind != "person" or not is_armed() or not CFG.get("escalate_on"):
        return
    light_alarm()
    if PROTECT["esc_t"] and time.time() < PROTECT["esc_t"]:
        return                                           # already counting
    s = max(0, int(CFG.get("escalate_siren_s", 30)))
    PROTECT["esc_t"] = time.time() + s
    PROTECT["esc_id"] += 1
    my = PROTECT["esc_id"]

    def later():
        time.sleep(s)
        if PROTECT["esc_id"] != my:
            return
        PROTECT["esc_t"] = 0.0
        if CFG.get("siren_on") == "off":                 # 2.97.0: «siren off» (e.g. mode wildlife) counts here too
            log_event("sys", "Escalation: the siren is switched off - only light and push")
            return
        if siren_quiet() and not sim_speaker():
            log_event("sys", "Escalation: siren held back (simulation / game / drill)")
            return                                       # 554: with the simulator connected it plays there (never for real)
        if time.time() - SOUND["last_alarm"] < float(CFG["siren_pause"]):
            return
        if is_armed() and speaker_ok() and not SOUND["playing"]:
            SOUND["last_alarm"] = time.time()
            log_event("sys", f"Escalation: siren after {s} s (nobody disarmed)")
            sound_play(None, None, None, reason="escalation")
    threading.Thread(target=later, daemon=True, name="escalate").start()


def protect_cancel_escalation():
    PROTECT["esc_id"] += 1
    PROTECT["esc_t"] = 0.0


# ---- PIN for disarming ---------------------------------------------------------------------------------------------------
def protect_pin_set(new_pin, old_pin=""):
    new_pin = str(new_pin or "").strip()
    if CFG.get("protect_pin") and not protect_pin_ok(old_pin):
        return False, "wrong PIN"
    if new_pin and not re.fullmatch(r"\d{4,8}", new_pin):
        return False, "the PIN must have 4 to 8 digits"
    CFG["protect_pin"] = _pin_hash(new_pin) if new_pin else ""
    save_settings()
    log_event("sys", "Protection: PIN " + ("set" if new_pin else "removed"))
    return True, ""


def protect_pin_ok(pin):
    h = CFG.get("protect_pin") or ""
    if not h:
        return True
    try:
        return hmac.compare_digest(_pin_hash(str(pin or "").strip(), h.split("$", 1)[0]), h)
    except Exception:
        return False


def protect_disarm(pin, source="web"):
    """disarm with the PIN (if one is set). 3 wrong PINs within 10 minutes: theft alarm (push with picture)"""
    now = time.time()
    PROTECT["pin_fails"] = [t for t in PROTECT["pin_fails"] if now - t < 600]
    if len(PROTECT["pin_fails"]) >= 5:
        return False, "too many wrong PINs - try again in 10 minutes"
    if not protect_pin_ok(pin):
        PROTECT["pin_fails"].append(now)
        log_event("sys", f"Protection: wrong PIN for disarming ({source})")
        if len(PROTECT["pin_fails"]) >= 3:
            w = WATCH_REF.get("w")
            try:
                if w is not None:
                    w.notifier.tamper(tr("Somebody tries to disarm with a wrong PIN"), w.frame_out)
            except Exception:
                pass
            siren_alarm("tamper")
        return False, "wrong PIN"
    PROTECT["pin_fails"] = []
    protect_cancel_escalation()
    protect_set("off", source)
    return True, ""


# ---- «Schutz testen» ---------------------------------------------------------------------------------------------------
def protect_test(lang=None):
    if PROTECT["test"]["busy"]:
        return False, "a test is already running"
    if CFG.get("sim_on") and simtask_busy("protection test"):
        return False, simtask_refuse("protection test")
    L = norm_lang(lang) if lang else cur_lang()
    PROTECT["test"] = {"busy": True, "steps": [], "t": time.time()}
    threading.Thread(target=_protect_test_run, args=(L,), daemon=True, name="protect-test").start()
    return True, ""


def _protect_test_run(L):
    T = lambda x: tr(x, L)
    S = PROTECT["test"]["steps"]

    def step(name, ok, text=""):
        S.append({"name": name, "ok": ok, "text": text})

    sim = bool(CFG.get("sim_on")) and SIM.get("ok") and time.time() - SIM.get("t", 0) < 5
    try:
        w = WATCH_REF.get("w")
        fresh = w is not None and time.time() - float(getattr(w, "last_frame_t", time.time())) < 5
        step(T("Camera picture"), bool(w is not None), "" if fresh else T("no recent picture"))
        step(T("Push messages"), bool(CFG.get("notify_on")), "" if CFG.get("notify_on") else T("off"))
        step(T("Loudspeaker / siren"), bool(out_selected()), "" if out_selected() else T("no loudspeaker"))
        meta = refscan_meta()
        step(T("Reference scan"), bool(meta), (trf("{n} guarded things", L, n=len(meta.get("watch") or [])) if meta else T("not yet")))
        if not sim:
            step(T("Sabotage and person"), None, T("only automatic with the simulator - test by hand: cover the camera, walk past"))
        else:
            t0 = (STATE.get("tamper") or {}).get("last", "")
            sim_control({"action": "sabotage", "cover": True})
            hit = False
            for _ in range(25):
                time.sleep(1)
                if (STATE.get("tamper") or {}).get("last", "") != t0:
                    hit = True
                    break
            sim_control({"action": "sabotage", "cover": False})
            step(T("Sabotage (camera covered)"), hit, "" if hit else T("not noticed within 25 s"))
            time.sleep(4)
            sim_control({"action": "press", "id": "spawn_person"})
            seen = False
            for _ in range(60):
                time.sleep(1)
                if int(STATE.get("persons") or 0) > 0:
                    seen = True
                    break
            step(T("Person walks past"), seen, "" if seen else T("no person detected within 60 s"))
    except Exception as e:
        step(T("Test"), False, str(e)[:120])
    PROTECT["test"]["busy"] = False
    ok = sum(1 for x in S if x["ok"])
    log_event("sys", f"Protection test: {ok} of {len(S)} ok")


