# ----------------------------------------------------------------------------
# Autostart: when switched on, the Pi starts MoveEye when it boots (no screen needed) and switches the own Wi-Fi on.
# When switched off, nothing starts at boot and the Pi joins its known networks as usual (the own Wi-Fi never starts by itself).
#   normal user: systemd USER service  ~/.config/systemd/user/motionwatch.service  (+ "linger" so it starts without login)
#   root (sudo): systemd system service /etc/systemd/system/motionwatch.service
# ----------------------------------------------------------------------------
SERVICE_NAME = "motionwatch.service"
AUTOSTART = {"on": False, "mode": "", "msg": "", "path": ""}


def _is_root():
    return hasattr(os, "geteuid") and os.geteuid() == 0


def _run_user():
    import getpass
    return os.environ.get("SUDO_USER") or os.environ.get("USER") or getpass.getuser()


def _unit_path(mode):
    if mode == "system":
        return "/etc/systemd/system/" + SERVICE_NAME
    return os.path.join(os.path.expanduser("~"), ".config", "systemd", "user", SERVICE_NAME)


def _autostart_mode():
    return "system" if (_is_root() or os.path.isfile(_unit_path("system"))) else "user"


def _systemctl(mode, *args, timeout=30):
    return _run(["systemctl"] + (["--user"] if mode == "user" else []) + list(args), timeout)


INSTANCE = {"fd": None, "stopped": None}


def instance_lock(port):
    """Only one MoveEye per web port (two would fight over camera, servos and port). True = we may run."""
    try:
        import fcntl
    except ImportError:
        return True
    p = os.path.join(tempfile.gettempdir(), f"motionwatch-{int(port)}.lock")
    try:
        fd = os.open(p, os.O_RDWR | os.O_CREAT, 0o666)
    except OSError:
        try:
            fd = os.open(p, os.O_RDONLY)
        except OSError:
            return True
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        os.close(fd); return False
    INSTANCE["fd"] = fd
    try:
        os.chmod(p, 0o666)
    except OSError:
        pass
    return True


def instance_takeover(port, gui):
    """Another MoveEye holds the port. Started by hand with a window while the autostart service runs: ask and take
    over (the service is stopped now and started again when this window closes). Returns True when we may run."""
    url = f"http://127.0.0.1:{int(port)}/"
    mode = _autostart_mode()
    code, out, _e = _systemctl(mode, "is-active", SERVICE_NAME, timeout=10) if shutil.which("systemctl") else (1, "", "")
    service = out.strip() == "active"
    msg = (tr("MoveEye is already running") + (" " + tr("in the background (autostart, without a window).") if service else ".")
           + "\n\n" + tr("Web page") + ": " + url)
    if not (gui and GUI_OK and service):
        print(msg.replace("\n\n", " - ")); return False
    try:
        r = tk.Tk(); r.withdraw()
        yes = messagebox.askyesno("MoveEye", msg + "\n\n" + tr("Open the window here instead? The background service is stopped for "
                                  "that and starts again when you close the window."), parent=r)
        r.destroy()
    except Exception:
        yes = False
    if not yes:
        try:
            import webbrowser
            webbrowser.open(url)
        except Exception:
            pass
        return False
    c2, _o, e2 = _systemctl(mode, "stop", SERVICE_NAME, timeout=40)
    if c2 != 0:
        print(tr("The background service could not be stopped") + ": " + (e2 or "")[:160]); return False
    for _ in range(60):
        if instance_lock(port):
            INSTANCE["stopped"] = mode
            atexit.register(instance_restart_service)
            return True
        time.sleep(0.5)
    return False


def instance_restart_service():
    """The window closes: the autostart service takes over again (not when the Pi is shutting down)."""
    if INSTANCE.get("stopped") and not POWER.get("pending"):
        try:
            subprocess.Popen(["systemctl"] + (["--user"] if INSTANCE["stopped"] == "user" else []) + ["start", "--no-block", SERVICE_NAME],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
        except OSError:
            pass


def autostart_args():
    """The options this program was started with, for the service (without one-time actions), plus --headless --boot."""
    drop = {"--print-service", "--install-service", "--allow-wifi", "--boot", "--headless", "--no-web", "--web"}
    return [x for x in sys.argv[1:] if x not in drop] + ["--headless", "--boot"]


HEART = {"t": time.time()}           # the camera loop is alive (systemd watchdog)
BEATS = {}                            # 2.95.35: name -> [last beat (monotonic), max. age s, label] of background tasks
REC_HEALTH = {"fail_t": 0.0, "fail_n": 0, "msg": ""}   # encoder trouble lately (for the health list)


def beat(name, max_age=120.0, label=""):
    """a background task says «I am alive» - the health list and the guard watch report it when it stops"""
    b = BEATS.get(name)
    if b is None:
        BEATS[name] = [time.monotonic(), float(max_age), label or name]
    else:
        b[0] = time.monotonic(); b[1] = float(max_age)


def _shift_times(obj, d, ref, depth=0):
    """after a jump of the system clock: move time stamps that mean «x seconds ago / in x seconds» along with it,
    so that cool-downs, holds and timers keep their length (2.95.35)"""
    near = lambda v: isinstance(v, float) and abs(v - ref) < 40 * 86400
    if isinstance(obj, dict):
        for k, v in list(obj.items()):
            if near(v):
                obj[k] = v + d
        return
    try:
        items = list(vars(obj).items())
    except TypeError:
        return
    for k, v in items:
        if isinstance(v, bool):
            continue
        if near(v):
            setattr(obj, k, v + d)
        elif isinstance(v, deque) and v and isinstance(v[0], tuple) and v[0] and near(v[0][0]):
            setattr(obj, k, deque(((t[0] + d,) + tuple(t[1:]) for t in list(v)), maxlen=v.maxlen))
        elif depth == 0 and isinstance(v, list) and v and hasattr(v[0], "__dict__"):
            for o in list(v):
                _shift_times(o, d, ref, 1)
        elif depth == 0 and isinstance(v, dict) and v and all(isinstance(x, (int, float, str, type(None))) for x in v.values()):
            _shift_times(v, d, ref, 1)


def clock_guard_loop():
    """The Pi has no clock battery: the time is set later from the internet or the phone and jumps (hours, days).
    Timers measured with the wall clock would then fire at once or never - they are moved by the jump."""
    w0, m0 = time.time(), time.monotonic()
    while True:
        time.sleep(1.0)
        try:
            w, m = time.time(), time.monotonic()
            d = (w - w0) - (m - m0)
            if abs(d) > 5.0:
                ref = w0 + (m - m0)
                wa = WATCH_REF.get("w")
                objs = [ARM, LIGHTS, TEMPA, TOOLMODE, HEART]
                if wa is not None:
                    objs += [wa] + [getattr(wa, a_, None) for a_ in ("notifier", "ai", "patrol", "relays", "zwatch", "tracker", "tuner", "weather")]
                if "DETER" in globals():
                    objs.append(DETER)
                if PARTY.get("until"):
                    PARTY["until"] += d
                for o in objs:
                    if o is not None:
                        try:
                            _shift_times(o, d, ref)
                        except Exception:
                            pass
                log_event("sys", f"System clock jumped {d:+.0f} s - running timers adjusted")
            w0, m0 = w, m
        except Exception:
            w0, m0 = time.time(), time.monotonic()


GUARD_WATCH = {"bad": {}, "last_push": {}}
_GUARD_IDS = ("loop", "cam", "rec", "looprec", "bg", "disk", "push", "temp", "power", "batt", "store")


def guard_watch_loop():
    """every 30 s: something important failed while armed -> one push message (again after 6 h at the earliest);
    fixed again -> a short note"""
    time.sleep(90)
    while True:
        try:
            h = health_check()
            now = time.time(); w = WATCH_REF.get("w")
            bad = {x["id"]: x for x in h["items"] if x["level"] == "bad" and x["id"] in _GUARD_IDS}
            for k, x in bad.items():
                if k not in GUARD_WATCH["bad"]:
                    GUARD_WATCH["bad"][k] = now
                    log_event("sys", f"Health: {x['title']} - {x['text']}"[:200])
                if is_armed() and now - GUARD_WATCH["bad"][k] > 60 and now - GUARD_WATCH["last_push"].get(k, 0) > 6 * 3600 and w is not None:
                    GUARD_WATCH["last_push"][k] = now
                    w.notifier.alert("{name}: " + tr("Problem") + " – " + x["title"], (x["text"] + (" · " + x["tip"] if x.get("tip") else ""))[:300], None)
            for k in [k for k in GUARD_WATCH["bad"] if k not in bad]:
                GUARD_WATCH["bad"].pop(k, None)
                if GUARD_WATCH["last_push"].pop(k, None) and w is not None:
                    w.notifier.info(tr("Fixed again") + ": " + k)
        except Exception as e:
            print(f"guard watch: {e}")
        time.sleep(30)


def sd_notify(msg):
    addr = os.environ.get("NOTIFY_SOCKET")
    if not addr:
        return False
    import socket
    if addr[0] == "@":
        addr = "\0" + addr[1:]
    try:
        with socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM) as sk:
            sk.connect(addr); sk.sendall(msg.encode())
        return True
    except OSError:
        return False


def watchdog_loop():
    """Started by the autostart (systemd, WatchdogSec): "still alive" every 20 s while the camera loop runs. If the program
    hangs (e.g. a camera that blocks forever), systemd restarts it after 2 minutes."""
    if not os.environ.get("NOTIFY_SOCKET"):
        return
    while True:
        if time.time() - HEART["t"] < 60:
            sd_notify("WATCHDOG=1")
        time.sleep(20)


def autostart_unit(mode):
    import shlex
    exe = " ".join(shlex.quote(x) for x in [sys.executable, os.path.abspath(__file__)] + autostart_args())
    # StartLimitIntervalSec=0: never give up (e.g. after a power cut the camera / network may need a while)
    if mode == "system":
        head = ("[Unit]\nDescription=MoveEye (camera surveillance)\nAfter=network.target NetworkManager.service\n"
                "Wants=NetworkManager.service\nStartLimitIntervalSec=0\n\n")
        install = "WantedBy=multi-user.target"
    else:
        head = "[Unit]\nDescription=MoveEye (camera surveillance)\nStartLimitIntervalSec=0\n\n"
        install = "WantedBy=default.target"
    return (head + "[Service]\nType=simple\n" + f"WorkingDirectory={HERE}\nExecStart={exe}\n"
            + f"Environment=PYTHONUNBUFFERED=1\nEnvironment=MOTIONWATCH_HOME={DATA_DIR}\n"
            + "Restart=always\nRestartSec=5\nWatchdogSec=120\nNotifyAccess=main\n\n[Install]\n" + install + "\n")


def desktop_notice(title, text, wait=300):
    """A small message on the desktop of the Pi (notification bubble), also from the background service (often root, before
    anybody is logged in): waits up to `wait` seconds for the desktop session, then sends it as that user. Background thread."""
    def users():
        out = []
        for d in sorted(glob.glob("/run/user/*")):
            try:
                uid = int(os.path.basename(d))
            except ValueError:
                continue
            if (uid >= 1000 or uid == os.getuid()) and os.path.exists(os.path.join(d, "bus")):
                out.append(uid)
        if os.getuid() != 0:
            out = [u for u in out if u == os.getuid()]
        return out

    def send(uid):
        import pwd
        env = dict(os.environ, DBUS_SESSION_BUS_ADDRESS=f"unix:path=/run/user/{uid}/bus", XDG_RUNTIME_DIR=f"/run/user/{uid}")
        kw = {}
        if os.getuid() == 0 and uid != 0:
            try:
                pw_ = pwd.getpwuid(uid); kw = {"user": uid, "group": pw_.pw_gid}; env["HOME"] = pw_.pw_dir; env["USER"] = pw_.pw_name
            except KeyError:
                return False
        gq = lambda x: "'" + str(x).replace("\\", "\\\\").replace("'", "\\'") + "'"     # GVariant text for gdbus
        icon = os.path.join(tempfile.gettempdir(), "motionwatch_icon.png")
        try:
            if not os.path.exists(icon):
                with open(icon, "wb") as f:
                    f.write(app_icon_png(96))
                os.chmod(icon, 0o644)
        except Exception:
            icon = "camera-web"
        if shutil.which("notify-send"):
            cmd = ["notify-send", "-a", "MoveEye", "-i", icon, "-t", "12000", title, text]
        elif shutil.which("gdbus"):
            cmd = ["gdbus", "call", "--session", "--dest", "org.freedesktop.Notifications", "--object-path", "/org/freedesktop/Notifications",
                   "--method", "org.freedesktop.Notifications.Notify", gq("MoveEye"), "0", gq(icon), gq(title), gq(text), "[]", "{}", "12000"]
        else:
            return None                                      # nothing on this system can show a message
        try:
            return subprocess.run(cmd, env=env, capture_output=True, timeout=15, **kw).returncode == 0
        except (OSError, subprocess.SubprocessError, ValueError):
            return False

    def run():
        end = time.time() + wait
        while time.time() < end:
            for uid in users():
                r = send(uid)
                if r:
                    log_event("sys", "Desktop message shown: " + text[:80]); return
                if r is None:
                    return
            time.sleep(10)
    threading.Thread(target=run, daemon=True, name="desktop-notice").start()


def autostart_refresh():
    mode = _autostart_mode()
    path = _unit_path(mode)
    code, out, _e = _systemctl(mode, "is-enabled", SERVICE_NAME, timeout=10)
    AUTOSTART.update(on=out.strip() == "enabled", mode=mode, path=path if os.path.isfile(path) else "")
    STATE["autostart"] = dict(AUTOSTART)
    return STATE["autostart"]


def autostart_set(on):
    if shutil.which("systemctl") is None:
        return False, "autostart needs systemd (Raspberry Pi OS)"
    mode = _autostart_mode()
    path = _unit_path(mode)
    if mode == "system" and not _is_root():
        if on:
            return False, "a system service exists - change it with sudo, or remove it: sudo systemctl disable --now motionwatch"
        code, out, err = _systemctl(mode, "disable", SERVICE_NAME)
        ok = code == 0
        msg = "" if ok else "the system service can only be switched off with sudo: sudo systemctl disable motionwatch"
    elif on:
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w") as f:
                f.write(autostart_unit(mode))
            os.chmod(path, 0o600)                         # the web password may be in the command line
        except OSError as e:
            return False, f"could not write {path}: {e}"
        _systemctl(mode, "daemon-reload")
        code, out, err = _systemctl(mode, "enable", SERVICE_NAME)
        ok, msg = code == 0, "" if code == 0 else (err or "systemctl enable failed")[:200]
        if ok and mode == "user":                         # start at boot even when nobody logs in
            c2, o2, e2 = _run(["loginctl", "enable-linger", _run_user()], 15)
            if c2 != 0:
                msg = ("autostart is on, but it only starts after a login until you run once: "
                       f"sudo loginctl enable-linger {_run_user()}   (or: sudo python3 {os.path.basename(__file__)} --allow-wifi)")
    else:
        code, out, err = _systemctl(mode, "disable", SERVICE_NAME)
        ok, msg = code == 0, "" if code == 0 else (err or "systemctl disable failed")[:200]
    if ok:
        CFG["autostart"] = on; save_settings()
        log_event("sys", "Autostart ON: starts at boot and switches the own Wi-Fi on" if on else
                         "Autostart OFF: nothing starts at boot, the Pi joins its known networks")
    AUTOSTART["msg"] = msg
    autostart_refresh()
    return ok, msg


def autostart_check_boot():
    """Autostart as a user service needs 'linger', otherwise it only starts after somebody logs in (e.g. not after a power
    cut without a desktop login). Checked at every start: switched on when allowed, otherwise a clear hint."""
    if not CFG["autostart"] or _autostart_mode() != "user" or shutil.which("loginctl") is None:
        return
    user = _run_user()
    code, out, _e = _run(["loginctl", "show-user", user, "-p", "Linger"], 10)
    if code == 0 and "Linger=yes" in out:
        return
    c2, _o, _e2 = _run(["loginctl", "enable-linger", user], 15)
    if c2 == 0:
        log_event("sys", "Autostart: start at boot without login switched on (linger)")
        return
    AUTOSTART["msg"] = ("autostart is on, but it only starts after a login until you run once: "
                        f"sudo loginctl enable-linger {user}   (or: sudo python3 {os.path.basename(__file__)} --allow-wifi)")
    log_event("sys", "Autostart: " + AUTOSTART["msg"])


def autostart_follow_version():
    """A new version was started by hand while autostart is on: let the service start this file from now on."""
    if not CFG["autostart"]:
        return
    mode = _autostart_mode()
    path = _unit_path(mode)
    if mode == "system" and not _is_root():
        return
    try:
        with open(path) as f:
            old = f.read()
    except OSError:
        return
    if old != autostart_unit(mode):                 # new file or new unit content (e.g. the watchdog of 1.8.2)
        try:
            with open(path, "w") as f:
                f.write(autostart_unit(mode))
            os.chmod(path, 0o600)
            _systemctl(mode, "daemon-reload")
            log_event("sys", f"Autostart now starts this version: {os.path.basename(__file__)}")
        except OSError:
            pass


def boot_hotspot():
    """Started at boot (--boot): switch the own Wi-Fi on. NetworkManager may still be starting, so try a few times."""
    def work():
        time.sleep(3.0)
        for attempt in range(8):
            ok, err = hotspot_set(True, persist=False)
            if ok:
                return
            WIFI["hs_msg"] = err
            time.sleep(10.0)
        log_event("sys", "Own Wi-Fi could not be switched on at boot")
    threading.Thread(target=work, daemon=True).start()


# ----------------------------------------------------------------------------
# 2.96.6 (Makeover-Punkte 12–15), alles mit dem Simulator:
#  12  Trainings-Nacht: zur eingestellten Stunde mehrere Testläufe in verschiedenen Szenen (Tag- und Nacht-Plan), dann die
#      automatische Optimierung am schwächsten Plan, dann Trainingsbilder (YOLO-Paket auf dem PC des Simulators); am
#      Schluss ein Bericht als Push und unter «Simulator-Zentrale». Nur wenn nicht Schutz eingeschaltet und kein Spiel läuft.
#  13  A/B-Vergleich: zweimal derselbe Testlauf - A mit den jetzigen Einstellungen, B mit einer Änderung. B bleibt nur,
#      wenn es klar besser ist (Punktzahl +3), sonst kommt A zurück.
#  14  Test-Posteingang: im Simulator landen die Meldungen auf Wunsch hier statt auf dem Handy (niemand wird gestört);
#      «Alarm-Kette testen» spielt Push, Licht und Sirene durch und sagt, was ging.
#  15  Störfall-Übungen: Akku leer, WLAN / Internet weg, Hitze, Kälte - MoveEye erlebt es wie echt (nur ohne echtes
#      Herunterfahren) und am Schluss steht, wie es reagiert hat.
# ----------------------------------------------------------------------------
SANDBOX = {"items": [], "force": 0}
DRILL = {"kind": "", "t0": 0.0, "until": 0.0, "seen": [], "busy": False, "last": None, "restore": {}}
TRAIN = {"busy": False, "step": "", "last": None, "stop": False, "day": ""}
ABT = {"busy": False, "step": "", "last": None}
DRILL_KINDS = {"battery": 90, "net": 100, "heat": 70, "cold": 70}
AB_PRESETS = {
    "more_sens": ("More sensitive", {"sensitivity": +10}), "less_sens": ("Less sensitive", {"sensitivity": -10}),
    "ai_strict": ("AI stricter", {"ai_conf": +0.1}), "ai_loose": ("AI more generous", {"ai_conf": -0.1}),
    "small": ("Also small objects", {"min_area": -0.3}), "walk": ("Faster decision", {"walk_frames": -2}),
}


def simtask_busy(except_=""):
    """2.97.0: one lock for everything that uses the simulator to measure or to train: who is busy now ('' = free).
    Every start asks here first, so two of them never mix (a person of the blind spots in a test run, a game round
    in the training night ...). A game round in the simulator counts too."""
    def g(n, d, k="busy"):
        try:
            return n if d.get(k) else ""
        except Exception:
            return ""
    for name, busy in (("test run", TESTOPT.get("busy")), ("training night", TRAIN.get("busy")), ("A/B comparison", ABT.get("busy")),
                       ("drill", DRILL.get("busy"))):
        if busy and name != except_:
            return name
    for name, ref in (("blind spots", "BLIND"), ("false alarm learning", "FALEARN"), ("automatic thresholds", "AUTOTH"), ("demo", "DEMO_RUN"),
                      ("improve assistant", "TUNEA"), ("place setup", "PLACE")):   # 2.98.14: «Erkennung verbessern» (312); 2.98.30: «Platz einrichten» (317)
        d = globals().get(ref)
        if isinstance(d, dict) and d.get("busy") and name != except_:
            return name
    try:
        if PROTECT["test"]["busy"] and except_ != "protection test":
            return "protection test"
    except (NameError, KeyError):
        pass
    if except_ != "game" and sim_game_running():
        return "game"
    try:
        return sim_busy_remote()                           # 2.98.13: started in the simulator window (147_simsperre.py)
    except NameError:
        return ""


def simtask_refuse(me):
    """'' when free, else the reason for the page"""
    b = simtask_busy(me)
    return "" if not b else trf("The simulator is busy: {what}", what=tr(b))


def sim_ready():
    return bool(CFG.get("sim_on")) and SIM.get("ok") and time.time() - SIM.get("t", 0) < 6


# ---- 14: the test inbox ---------------------------------------------------------------------------------------------
def sim_game_running():
    """2.97.0: a round in the simulator (countdown / play) - the players are not burglars"""
    if not CFG.get("sim_on"):
        return False
    try:
        g = sim_game()                                     # fetches it fresh in the background now and then
    except Exception:
        g = SIMGAME.get("g")
    return bool(g) and g.get("round") in ("play", "countdown")


def event_origin():
    """2.97.0: real | sim | game | drill | demo - recordings, the diary and the reports can tell them apart"""
    if not CFG.get("sim_on"):
        return "real"
    if DRILL.get("kind") and time.time() < DRILL.get("until", 0):
        return "drill"
    try:
        if DEMO_RUN.get("busy"):
            return "demo"
    except NameError:
        pass
    return "game" if sim_game_running() else "sim"


def sandbox_active():
    """the test inbox instead of the phone: drills / demo (force), simulation with the switch, and always while a game runs"""
    if SANDBOX["force"] > 0:
        return True
    if not CFG.get("sim_on"):
        return False
    return bool(CFG.get("notify_sandbox")) or sim_game_running()


def sandbox_add(title, text, jpg=None, ev=""):
    it = {"t": datetime.now().strftime("%H:%M:%S"), "title": title, "text": text, "ev": ev, "icon": ev_icon(ev),
          "held": bool(DRILL["kind"] == "net" and time.time() < DRILL["until"])}
    if jpg:
        try:
            d = os.path.join(DATA_DIR, "testinbox")
            os.makedirs(d, exist_ok=True)
            n = "%d.jpg" % int(time.time() * 1000)
            with open(os.path.join(d, n), "wb") as f:
                f.write(jpg)
            it["img"] = n
            fs = sorted(os.listdir(d))
            for x in fs[:-20]:
                os.remove(os.path.join(d, x))
        except OSError:
            pass
    SANDBOX["items"].insert(0, it)
    del SANDBOX["items"][30:]
    if DRILL["kind"] and time.time() < DRILL["until"]:
        DRILL["seen"].append({"t": it["t"], "kind": "push", "text": title + ": " + text})
    log_event("web", f"Test inbox: {title}"[:160])


def alarmchain_test():
    """Push, light, siren - one after the other, into the test inbox (nobody is disturbed)"""
    out = []
    try:
        w = WATCH_REF.get("w")
        n0 = len(SANDBOX["items"])
        if w is not None:
            p = {"event": "person", "persons": 1, "time": datetime.now().isoformat(timespec="seconds"), "snapshot": None, "rain": False,
                 "wind": "", "source": STATE.get("source_label", ""), "link": "", "more": 0, "_test": True}
            jpg = None
            f = getattr(w, "frame_out", None)
            if f is not None:
                ok_, buf = cv2.imencode(".jpg", f, [cv2.IMWRITE_JPEG_QUALITY, 70])
                jpg = buf.tobytes() if ok_ else None
            w.notifier._dispatch(p, jpg, "test.jpg")
        got = len(SANDBOX["items"]) > n0
        out.append({"name": "Push message", "ok": got, "text": SANDBOX["items"][0]["title"] if got else "no message"})
        was = bool((STATE.get("lights") or {}).get("white"))
        light_alarm()
        lit = False
        for _ in range(12):
            time.sleep(0.25)
            if (STATE.get("lights") or {}).get("white"):
                lit = True
                break
        out.append({"name": "Light", "ok": lit or was, "text": "" if lit or was else "the white light is not set to «on alarm» (Light & sound)"})
        ok_s, err_s = sound_play(None, 3, None, reason="test")
        time.sleep(0.6)
        out.append({"name": "Siren", "ok": bool(ok_s and SOUND.get("playing")), "text": err_s or ""})
        time.sleep(2.5)
        try:
            sound_stop()
        except Exception:
            pass
        esc = bool(CFG.get("escalate_on"))
        out.append({"name": "Siren after a while (escalation)", "ok": esc, "text": trf("after {s} s", s=int(CFG.get("escalate_siren_s", 30))) if esc else "off"})
    except Exception as e:
        out.append({"name": "Error", "ok": False, "text": str(e)[:100]})
    log_event("sys", "Alarm chain test: " + ", ".join(f"{x['name']} {'ok' if x['ok'] else 'no'}" for x in out))
    return out


# ---- 15: drills ------------------------------------------------------------------------------------------------------
def drill_active(kind):
    return DRILL["kind"] == kind and time.time() < DRILL["until"]


def drill_note(kind, text):
    """called from log_event: what MoveEye did during a drill"""
    if DRILL["kind"] and time.time() < DRILL["until"] + 3 and len(DRILL["seen"]) < 40:
        DRILL["seen"].append({"t": datetime.now().strftime("%H:%M:%S"), "kind": kind, "text": str(text)[:160]})


def drill_start(kind):
    if kind not in DRILL_KINDS:
        return False, "unknown drill"
    if DRILL["busy"]:
        return False, "a drill is already running"
    if simtask_busy():
        return False, simtask_refuse("drill")
    if not sim_ready():
        return False, "only with the simulator"
    DRILL.update(kind=kind, t0=time.time(), until=time.time() + DRILL_KINDS[kind], seen=[], busy=True, restore={})
    SANDBOX["force"] += 1
    if kind in ("heat", "cold"):
        DRILL["restore"] = {"temp_alarm_on": CFG.get("temp_alarm_on")}
        CFG["temp_alarm_on"] = True                        # for the drill: the temperature alarm listens
        try:
            DRILL["restore"]["ambient"] = float(SIM.get("ambient", 15.0))
            sim_control({"action": "set", "id": "ambient", "value": 38.0 if kind == "heat" else -12.0})
        except Exception:
            pass
    if kind == "battery":
        DRILL["restore"] = {"batt_warned": CFG.get("batt_warned")}
        CFG["batt_warned"] = False
        bm = getattr(WATCH_REF.get("w"), "battmon", None)
        if bm is not None:
            bm._on_batt = False                            # so the first drill tick tells «power cut»
    if kind == "net":
        w = WATCH_REF.get("w")
        try:
            w.netmon.recheck = True
        except Exception:
            pass
    log_event("sys", f"Drill started: {kind}")
    threading.Thread(target=_drill_end_later, daemon=True, name="drill").start()
    return True, ""


def _drill_end_later():
    while time.time() < DRILL["until"]:
        time.sleep(1)
    kind = DRILL["kind"]
    try:
        rs = DRILL.get("restore") or {}
        if "temp_alarm_on" in rs:
            CFG["temp_alarm_on"] = rs["temp_alarm_on"]
        if "ambient" in rs:
            sim_control({"action": "set", "id": "ambient", "value": rs["ambient"]})
        if "batt_warned" in rs:
            CFG["batt_warned"] = bool(rs["batt_warned"])
            bm = getattr(WATCH_REF.get("w"), "battmon", None)
            if bm is not None and getattr(bm, "_on_batt", None):
                bm.ups_events(7.6, 60, None, False, False)  # the «mains power back» of the drill
                bm._on_batt = None
        if kind == "net":
            w = WATCH_REF.get("w")
            try:
                w.netmon.recheck = True
            except Exception:
                pass
            time.sleep(4)
    except Exception as e:
        DRILL["seen"].append({"t": "", "kind": "sys", "text": str(e)[:100]})
    time.sleep(2)
    seen = [x for x in DRILL["seen"] if x.get("kind") not in ("auto", "servo", "patrol", "relay")
            and not str(x["text"]).startswith(("Drill started", "Test inbox"))]
    DRILL["last"] = {"kind": kind, "t": DRILL["t0"], "s": DRILL_KINDS.get(kind, 0), "reactions": seen[:30]}
    DRILL.update(kind="", busy=False)
    SANDBOX["force"] = max(0, SANDBOX["force"] - 1)
    log_event("sys", f"Drill finished: {kind}, {len(seen)} reactions")
    try:
        if seen:
            points_add(50, f"Drill done: {kind}")
    except NameError:
        pass


def drill_battery_tick(bm):
    """BatteryMonitor.tick during the battery drill: the charge falls from 60 to 4 % - like real, but never shuts down"""
    el = time.time() - DRILL["t0"]
    pct = max(4, int(60 - el / DRILL_KINDS["battery"] * 60))
    hours = round(pct / 100.0 * 4.0, 1)
    STATE["battery"] = {"on": True, "src": "drill", "pct": pct, "hours": hours, "on_battery": True, "charging": False, "watts": 4.2,
                        "use_w": 4.2, "volt": round(6.0 + pct / 100.0 * 2.4, 2), "drill": True}
    bm.ups_events(6.0 + pct / 100.0 * 2.4, pct, hours, True, False)   # volt_ok False: never the real shutdown


# ---- 12: the training night ------------------------------------------------------------------------------------------
TRAIN_SCENES = ["camping", "wald", "garten", "parkplatz", "stellplatz"]


def train_run(manual=False):
    if TRAIN["busy"] or simtask_busy():
        return False, simtask_refuse("training night") or "already running"
    if not sim_ready():
        return False, "only with the simulator"
    TRAIN.update(busy=True, stop=False, step="")
    threading.Thread(target=_train_thread, args=(manual,), daemon=True, name="training").start()
    return True, ""


def _train_thread(manual):
    t0 = time.time()
    res, kept, export = [], [], None
    scenes = [s for s in (CFG.get("train_scenes") or TRAIN_SCENES) if isinstance(s, str)][:5] or TRAIN_SCENES
    try:
        TESTOPT["busy"] = "training"
        for sc in scenes:
            for plan in ("quick", "night"):
                if TRAIN["stop"]:
                    break
                TRAIN["step"] = f"{sc} · {plan}"
                try:
                    sim_control({"action": "scenario", "id": sc, "solo": True})   # Simulator-Welten: der alte Ort allein (vergleichbar)
                except Exception:
                    pass
                time.sleep(4)
                run = _run_free(plan)
                if run is not None:
                    rp = run["report"]
                    res.append({"scene": sc, "plan": plan, "score": run["score"], "rate": rp.get("rate"), "fa": rp.get("false_alarms"),
                                "persons": rp.get("persons"), "found": rp.get("persons_detected")})
        TESTOPT["busy"] = ""
        if CFG.get("train_optimize", True) and res and not TRAIN["stop"]:
            worst = min(res, key=lambda x: x["score"] if x["score"] is not None else 999)
            TRAIN["step"] = "optimizing: " + worst["scene"] + " · " + worst["plan"]
            try:
                sim_control({"action": "scenario", "id": worst["scene"], "solo": True})
            except Exception:
                pass
            time.sleep(4)
            _testopt_thread("auto", worst["plan"], 3)
            A = TESTOPT.get("auto") or {}
            kept = list(A.get("kept") or [])
            res.append({"scene": worst["scene"], "plan": "optimized", "score": A.get("best"), "base": A.get("base")})
        if CFG.get("train_pics", True) and not TRAIN["stop"]:
            TRAIN["step"] = "training pictures"
            try:
                export = sim_control({"action": "dataset", "op": "export", "n": 300})
            except Exception:
                export = None
    except Exception as e:
        log_event("sys", f"Training night: {e}"[:150])
    finally:
        TESTOPT["busy"] = ""
    rep = {"t": t0, "min": round((time.time() - t0) / 60.0, 1), "results": res, "kept": kept, "manual": manual, "stopped": TRAIN["stop"],
           "pics": (export or {}).get("n") if isinstance(export, dict) else None, "path": (export or {}).get("zip") if isinstance(export, dict) else None}
    TRAIN.update(busy=False, step="", last=rep)
    try:
        d = os.path.join(DATA_DIR, "training")
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, datetime.now().strftime("%Y%m%d_%H%M") + ".json"), "w", encoding="utf-8") as f:
            json.dump(rep, f)
    except OSError:
        pass
    sc = [r["score"] for r in res if r.get("score") is not None and r["plan"] != "optimized"]
    txt = trf("Training night: {n} test runs, average score {s}, kept changes: {k}", n=len(sc), s=round(sum(sc) / len(sc)) if sc else "–",
              k=", ".join(kept) or tr("none"))
    log_event("sys", txt)
    w = WATCH_REF.get("w")
    if w is not None and not manual:
        w.notifier.info(txt, title="{name}: " + tr("Training night"))


def train_loop():
    while True:
        time.sleep(60)
        try:
            if not CFG.get("train_night_on") or TRAIN["busy"]:
                continue
            now = datetime.now(); day = now.strftime("%Y-%m-%d")
            if now.hour != int(CFG.get("train_hour", 1)) or TRAIN["day"] == day or CFG.get("train_day") == day:
                continue
            if not sim_ready() or is_armed() or simtask_busy():
                continue
            TRAIN["day"] = day
            CFG["train_day"] = day
            save_settings()
            train_run(False)
        except Exception as e:
            log_event("sys", f"Training night: {e}"[:150])


threading.Thread(target=train_loop, daemon=True, name="training-night").start()


# ---- 13: A/B -----------------------------------------------------------------------------------------------------------
def ab_run(preset, plan="quick"):
    if ABT["busy"] or simtask_busy():
        return False, simtask_refuse("A/B comparison") or "already running"
    if preset not in AB_PRESETS:
        return False, "unknown"
    if not sim_ready():
        return False, "only with the simulator"
    ABT.update(busy=True, step="A")
    threading.Thread(target=_ab_thread, args=(preset, plan), daemon=True, name="ab").start()
    return True, ""


def _sim_free(max_s=420):
    """wait until no test run is going on in the simulator (its test bench may have started one by itself)"""
    t_end = time.time() + max_s
    while time.time() < t_end and not TRAIN["stop"]:
        st = _simtest("test_report")
        if not st.get("running"):
            return True
        time.sleep(5)
    return False


def _run_free(plan):
    _sim_free()
    return testopt_run(plan)


def _ab_changes(preset):
    out = []
    for k, d in AB_PRESETS[preset][1].items():
        if k not in CFG:
            continue
        v = CFG[k]
        nv = v * (1 + d) if k == "min_area" else v + d
        out.append([k, v, _clampv(k, nv)])
    return out


def _ab_thread(preset, plan):
    res = {"preset": preset, "title": AB_PRESETS[preset][0], "plan": plan, "a": None, "b": None, "winner": "", "changes": {}}
    try:
        TESTOPT["busy"] = "ab"
        a = _run_free(plan)
        res["a"] = a["score"] if a else None
        ch = _ab_changes(preset)
        res["changes"] = {k: n for k, _o, n in ch}
        if res["a"] is None:
            raise RuntimeError(TESTOPT.get("msg") or "test run A failed")
        ABT["step"] = "B"
        before = opt_apply(ch, "A/B test " + preset)
        b = _run_free(plan)
        res["b"] = b["score"] if b else None
        if res["a"] is not None and res["b"] is not None and res["b"] >= res["a"] + 3.0:
            res["winner"] = "B"
            TESTOPT["undo"] = {"cfg": before, "t": time.time(), "what": "ab"}
            testopt_save()
        else:
            res["winner"] = "A"
            opt_restore(before, "A/B test: A stays")
    except Exception as e:
        res["error"] = str(e)[:100]
    finally:
        TESTOPT["busy"] = ""
        ABT.update(busy=False, step="", last=res)
        log_event("sys", f"A/B test {preset}: A {res['a']} / B {res['b']} -> {res['winner'] or '?'}")


def lab_state():
    return {"sandbox": bool(CFG.get("notify_sandbox")), "inbox": SANDBOX["items"][:12], "drill": {"kind": DRILL["kind"], "busy": DRILL["busy"],
            "left": max(0, int(DRILL["until"] - time.time())) if DRILL["busy"] else 0, "last": DRILL["last"]},
            "train": {"on": bool(CFG.get("train_night_on")), "hour": int(CFG.get("train_hour", 1)), "busy": TRAIN["busy"], "step": TRAIN["step"],
                      "last": TRAIN["last"]}, "ab": {"busy": ABT["busy"], "step": ABT["step"], "last": ABT["last"],
                      "presets": [[k, v[0]] for k, v in AB_PRESETS.items()]}, "ready": bool(sim_ready())}
