FALEARN = {"busy": False, "last": [], "cur": ""}
BLIND = {"busy": False, "kind": "", "last": None, "rehearsal": None}
AUTOTH = {"busy": False, "step": "", "last": None}


# ---- 21 -------------------------------------------------------------------------------------------------------------------
def falearn_start(name, cause):
    if FALEARN["busy"]:
        return False, "already running"
    if simtask_busy():
        return False, simtask_refuse("false alarm learning")
    if not sim_ready():
        return False, "only with the simulator"
    if not rec_path(name):
        return False, "not found"
    FALEARN.update(busy=True, cur=name)
    threading.Thread(target=_falearn_thread, args=(name, str(cause or "other")), daemon=True, name="falearn").start()
    return True, ""


def _falearn_thread(name, cause):
    res = {"name": name, "cause": cause, "t": time.time(), "alarms": 0, "pics": 0, "ok": False}
    try:
        meta = _read_sidecar(name)
        situ = meta.get("situ") or {}
        try:
            dt = datetime.fromisoformat(meta["start"]) if meta.get("start") else (parse_stamp(os.path.basename(name)) or datetime.now())
        except ValueError:
            dt = datetime.now()
        sim_control({"action": "farecreate", "cause": cause, "hour": round(dt.hour + dt.minute / 60.0, 2),
                     "pan_deg": float(situ.get("pan_deg") or 0.0), "rain": bool(situ.get("rain"))})
        d = os.path.join(DATA_DIR, "fa_learn", datetime.now().strftime("%Y%m%d_%H%M%S") + "_" + re.sub(r"[^a-z]", "", cause))
        was = 0
        t_end = time.time() + 60
        w0 = WATCH_REF.get("w")
        if w0 is not None:
            w0.raw_until = t_end + 1                        # the picture without marks, for the training
        last_pic = 0.0
        while time.time() < t_end:
            p = int(STATE.get("persons") or 0)
            if p > 0 and was == 0:
                res["alarms"] += 1
            if p > 0 and time.time() - last_pic > 2.0 and res["pics"] < 10:
                w = WATCH_REF.get("w")
                f = getattr(w, "frame_raw", None) if w is not None else None
                if f is not None:
                    os.makedirs(d, exist_ok=True)
                    cv2.imwrite(os.path.join(d, "%02d.jpg" % res["pics"]), f, [cv2.IMWRITE_JPEG_QUALITY, 85])
                    res["pics"] += 1
                    last_pic = time.time()
            was = p
            time.sleep(0.5)
        res["ok"] = res["alarms"] == 0
        if res["pics"]:
            with open(os.path.join(d, "info.json"), "w") as f_:
                json.dump({"label": "no_person", "cause": cause, "from": name}, f_)
        sim_control({"action": "farecreate", "cause": "end"})
    except Exception as e:
        res["error"] = str(e)[:100]
    FALEARN["last"].insert(0, res)
    del FALEARN["last"][10:]
    FALEARN.update(busy=False, cur="")
    log_event("sys", f"False alarm learning ({cause}): {res['alarms']} alarm(s) in 60 s, {res['pics']} picture(s) kept as «no person»")


# ---- 2.98.2: MoveEye points - one account for the games and the real use -------------------------------------------------
# Games: a blind spot found (+5 a point, at most 100 a day), a false alarm unmasked (+30). Real use: a calm week without a
# false alarm (+100), a drill done (+50), «Entdecker»: the blind spot map shows more recognised places than last time (+50 each).
def points_add(n, why):
    P = CFG.get("me_points") if isinstance(CFG.get("me_points"), dict) else {"total": 0, "log": [], "week": ""}
    P["total"] = int(P.get("total", 0)) + int(n)
    log_ = [x for x in (P.get("log") or []) if isinstance(x, dict)]
    log_.insert(0, {"t": int(time.time()), "n": int(n), "why": str(why)[:80]})
    P["log"] = log_[:40]
    CFG["me_points"] = P
    save_settings()


def points_state():
    P = CFG.get("me_points") if isinstance(CFG.get("me_points"), dict) else {}
    return {"total": int(P.get("total", 0)), "log": (P.get("log") or [])[:12], "badges": BLIND.get("badges") or {}}


def fa_count(days=7):
    """recordings marked «false alarm» in the last days"""
    since = datetime.now() - timedelta(days=days)
    n = 0
    try:
        for f in os.listdir(rec_dir()):
            if f.endswith(".json"):
                dt = parse_stamp(f)
                if dt is not None and dt >= since and _read_sidecar(f[:-5] + ".mp4").get("false"):
                    n += 1
    except OSError:
        pass
    return n


def points_week_loop():
    while True:
        time.sleep(300)
        try:
            now = datetime.now()
            wk = now.strftime("%G-W%V")
            P = CFG.get("me_points") or {}
            if now.weekday() != 0 or P.get("week") == wk or not CFG.get("detection_on", True):
                continue
            P["week"] = wk
            CFG["me_points"] = P
            if fa_count(7) == 0:
                points_add(100, "Calm week: no false alarm")
            else:
                save_settings()
        except Exception as e:
            log_event("sys", f"Points: {e}"[:120])


threading.Thread(target=points_week_loop, daemon=True, name="points").start()


# ---- 2.98.2: false alarms from the games of the simulator ---------------------------------------------------------------
FA_GAME = {"day": "", "n": 0, "z": 0}


def fa_game_box(box, info=None):
    """the simulator says: MoveEye reported a person here, but no player and no visitor was there -> this part of the
    picture (with some margin) goes to fa_learn/ as a «no person» example, like the false alarm learning (21). At most 40 a day.
    2.98.18: «info» = the situation from the game «Fehlalarm-Jäger» (lure, distance, light, weather) - kept next to the picture.
    2.98.38 (falearn): checked once more before (148 fa_box_check): the picture the box came from (not the newest one), no
    person of the simulator near the box, not bigger than a person there - otherwise it goes to fa_learn/zweifel/ (not used)."""
    try:
        x, y, w_, h_ = [float(v) for v in (box or [])[:4]]
    except (TypeError, ValueError):
        return
    day = datetime.now().strftime("%Y%m%d")
    if FA_GAME["day"] != day:
        FA_GAME.update(day=day, n=0, z=0)
    if FA_GAME["n"] >= 40 or FA_GAME.get("z", 0) >= 40 or not CFG.get("fa_learn_auto", True):
        return
    f, how = fa_ring_find([x, y, w_, h_])               # 148: the picture MoveEye saw this box in
    if f is None:
        w = WATCH_REF.get("w")
        f = getattr(w, "frame_raw", None) if w is not None else None
        how = "now"
    if f is None:
        return
    H, W = f.shape[:2]
    mx, my = w_ * 0.25, h_ * 0.25
    x0, y0 = max(0, int((x - mx) * W)), max(0, int((y - my) * H))
    x1, y1 = min(W, int((x + w_ + mx) * W)), min(H, int((y + h_ + my) * H))
    if x1 - x0 < 16 or y1 - y0 < 16:
        return
    ok, why = fa_box_check([x, y, w_, h_], info, how, H)
    d = os.path.join(DATA_DIR, "fa_learn", day + "_spiel") if ok else os.path.join(DATA_DIR, "fa_learn", FA_DOUBT_DIR, day + "_spiel")
    os.makedirs(d, exist_ok=True)
    if ok:
        FA_GAME["n"] += 1
    else:
        FA_GAME["z"] = FA_GAME.get("z", 0) + 1
    n = fa_next_number(d)                               # (before: the count of today - a restart overwrote the pictures)
    cv2.imwrite(os.path.join(d, "%02d.jpg" % n), f[y0:y1, x0:x1], [cv2.IMWRITE_JPEG_QUALITY, 88])
    sit = {}
    if isinstance(info, dict):                          # only short, plain values (it comes over the network)
        for k, v in list(info.items())[:20]:
            if isinstance(k, str) and isinstance(v, (str, int, float, bool)) and len(k) <= 20:
                sit[re.sub(r"[^a-z_]", "", k.lower())[:20]] = v[:40] if isinstance(v, str) else v
    try:
        with open(os.path.join(d, "info.json"), "w") as fo:
            json.dump({"label": "no_person" if ok else "doubtful", "use": ok, "cause": "game", "from": "simulator game", "crop": True, "n": n}, fo)
        with open(os.path.join(d, "%02d.json" % n), "w") as fo:      # one file per case: the situation and the check
            json.dump({"label": "no_person" if ok else "doubtful", "box": [round(x, 3), round(y, 3), round(w_, 3), round(h_, 3)], "situation": sit,
                       "check": dict(fa_check_meta(info, how, H), ok=ok, why=why)}, fo)
    except OSError:
        pass
    if ok:
        log_event("sys", f"False alarm in a game: picture part kept as «no person» ({FA_GAME['n']} today)")
        points_add(30, "False alarm unmasked in a game")
    else:
        log_event("sys", f"False alarm in a game: picture part doubtful ({', '.join(why)[:80]}) - kept apart, not for the training")


# ---- 22 / 23 --------------------------------------------------------------------------------------------------------------
def blind_start(kind="map", hour=None):
    if BLIND["busy"]:
        return False, "already running"
    if simtask_busy():
        return False, simtask_refuse("blind spots")
    if not sim_ready():
        return False, "only with the simulator"
    q = {"action": "blindmap", "do": "start"}
    if kind == "rehearsal":
        q.update(az=[0], dist=[6, 10, 14, 18, 22, 26, 30], hour=hour if hour is not None else 22.5, walk=True)
    else:
        q.update(az=[-60, -40, -20, 0, 20, 40, 60], dist=[5, 10, 15, 20, 25])
    try:
        r = sim_control(q)
    except Exception:
        return False, "simulator not reachable"
    if not r.get("ok"):
        return False, str(r.get("error") or "not supported - update the simulator")
    BLIND.update(busy=True, kind=kind)
    threading.Thread(target=_blind_wait, daemon=True, name="blindmap").start()
    return True, ""


def _blind_wait():
    t_end = time.time() + 900
    res = None
    while time.time() < t_end:
        time.sleep(3)
        try:
            r = sim_control({"action": "blindmap", "do": "info"})
        except Exception:
            continue
        BLIND["prog"] = r.get("prog")
        if not r.get("busy"):
            res = r.get("result")
            break
    kind = BLIND["kind"]
    if res:
        res["tip"] = blind_tip(res)
        if kind == "rehearsal":
            BLIND["rehearsal"] = res
            far = res.get("max_found")
            txt = trf("Night rehearsal: tonight persons are recognised up to {d} m", d=far) if far else tr("Night rehearsal: no person recognised - check the night settings (IR light, night mode)")
            log_event("sys", txt)
            res["text"] = txt
        else:
            prev_ = BLIND.get("last") or {}
            BLIND["last"] = res
            log_event("sys", f"Blind spots: {res.get('found', 0)} of {res.get('inview', 0)} places recognised")
            gain_ = int(res.get("found", 0)) - int(prev_.get("found", res.get("found", 0)))
            if prev_ and gain_ > 0:                         # 2.98.2: «Entdecker» - blind spots of before are recognised now
                points_add(50 * gain_, f"Explorer: {gain_} blind spot(s) fixed")
    BLIND.update(busy=False, kind="")


def blind_tip(res):
    """a short tip from the map: where are the blind spots?"""
    pts = res.get("points") or []
    miss = [p for p in pts if p.get("inview") and not p.get("found")]
    if not pts:
        return ""
    if not any(p.get("inview") for p in pts):
        return tr("The person was never in the picture – check where the head looks (patrol, pan).")
    if not miss:
        return tr("No blind spot in view - well placed.")
    far = [p for p in miss if p["d"] >= 15]
    left = [p for p in miss if p["az"] < -10]
    right = [p for p in miss if p["az"] > 10]
    out = ""
    if len(far) >= len(miss) * 0.6:
        out = tr("Mostly far away: put MoveEye higher or tilt it a little up; at night more IR light helps.")
    elif len(left) > len(right) * 2:
        out = tr("Mostly on the left: turn MoveEye a little to the left or add a patrol point there.")
    elif len(right) > len(left) * 2:
        out = tr("Mostly on the right: turn MoveEye a little to the right or add a patrol point there.")
    else:
        out = tr("Spread over the picture: check the sensitivity (A/B comparison) and the zones.")
    nv = [p for p in pts if not p.get("inview")]
    if len(nv) > len(pts) * 0.3:
        out += " " + tr("Many places are outside the picture: a patrol or a second device covers them.")
    return out


def rehearsal_on_arm():
    """armed in the simulation: the night rehearsal by itself (when switched on)"""
    if CFG.get("rehearsal_on_arm") and sim_ready() and not BLIND["busy"] and not simtask_busy():
        now = datetime.now()
        h = now.hour + now.minute / 60.0
        blind_start("rehearsal", h if (h >= 20 or h < 6) else 22.5)


# ---- 24 --------------------------------------------------------------------------------------------------------------------
def autoth_start():
    if AUTOTH["busy"] or simtask_busy():
        return False, simtask_refuse("automatic thresholds") or "already running"
    if not sim_ready():
        return False, "only with the simulator"
    AUTOTH.update(busy=True, step="day")
    threading.Thread(target=_autoth_thread, daemon=True, name="autoth").start()
    return True, ""


def _autoth_thread():
    res = []
    try:
        for plan in ("quick", "night"):
            AUTOTH["step"] = plan
            _sim_free()
            _testopt_thread("auto", plan, 4)
            A = TESTOPT.get("auto") or {}
            res.append({"plan": plan, "base": A.get("base"), "best": A.get("best"), "kept": list(A.get("kept") or [])})
    finally:
        AUTOTH.update(busy=False, step="", last={"t": time.time(), "res": res})
        log_event("sys", "Automatic thresholds: " + "; ".join(f"{r['plan']} {r['base']} -> {r['best']}" for r in res))


# ---- 25 --------------------------------------------------------------------------------------------------------------------
def weekcheck_loop():
    while True:
        time.sleep(120)
        try:
            if not CFG.get("weekcheck_on"):
                continue
            now = datetime.now()
            wk = now.strftime("%G-W%V")
            if now.weekday() != 6 or now.hour != int(CFG.get("testopt_hour", 3)) or CFG.get("weekcheck_last") == wk:
                continue
            if not sim_ready() or simtask_busy() or is_armed():
                continue
            prev = next((r for r in reversed(TESTOPT["runs"]) if r.get("week")), None)
            TESTOPT["busy"] = "week"
            try:
                _sim_free()
                run = testopt_run("standard")
            finally:
                TESTOPT["busy"] = ""
            if run is None:
                continue                                   # 2.97.0: refused / stopped - try again in 2 min (the week is not lost)
            CFG["weekcheck_last"] = wk
            save_settings()
            run["week"] = True
            testopt_save()
            log_event("sys", f"Weekly recognition check: score {run['score']}")
            if prev and prev.get("score") is not None and run.get("score") is not None and run["score"] <= prev["score"] - 8:
                w = WATCH_REF.get("w")
                if w is not None:
                    w.notifier.info(trf("Weekly check: score {a} instead of {b} – the recognition got worse. Details: tab Simulator.",
                                        a=run["score"], b=prev["score"]), title="{name}: " + tr("Weekly check"))
        except Exception as e:
            log_event("sys", f"Weekly check: {e}"[:150])


threading.Thread(target=weekcheck_loop, daemon=True, name="weekcheck").start()


def blind_game_pts():
    """2.98.0: where players in the simulator games were visible but not reported - a layer of the blind spot map (30 s cache)"""
    if time.time() - BLIND.get("game_t", 0) > 30 and sim_ready():
        BLIND["game_t"] = time.time()
        try:
            r = sim_control({"action": "blindmap", "do": "game"})
            if r.get("ok"):
                old_n = len(BLIND.get("game") or [])
                BLIND["game"] = [p for p in (r.get("pts") or []) if isinstance(p, dict)][-400:]
                BLIND["badges"] = r.get("badges") if isinstance(r.get("badges"), dict) else {}
                new_n = len(BLIND["game"]) - old_n
                if BLIND.get("game_known") and new_n > 0:          # not at the first fetch (those are old)
                    points_add(min(100, 5 * new_n), f"{new_n} blind spot(s) found in games")
                BLIND["game_known"] = True
        except Exception:
            pass
    return BLIND.get("game") or []


def learn_state():
    return {"falearn": {"busy": FALEARN["busy"], "cur": FALEARN["cur"], "last": FALEARN["last"][:5]},
            "blind": {"busy": BLIND["busy"], "kind": BLIND["kind"], "prog": BLIND.get("prog"), "last": BLIND["last"], "rehearsal": BLIND["rehearsal"],
                      "game": blind_game_pts()},
            "autoth": {"busy": AUTOTH["busy"], "step": AUTOTH["step"], "last": AUTOTH["last"]},
            "week": {"on": bool(CFG.get("weekcheck_on")), "runs": [{"t": r["t"], "score": r["score"], "mw": r.get("mw")} for r in TESTOPT["runs"] if r.get("week")][-8:]},
            "rehearsal_on_arm": bool(CFG.get("rehearsal_on_arm")), "fa_learn_auto": bool(CFG.get("fa_learn_auto")),
            "points": points_state(), "facheck": facheck_state()}
# ----------------------------------------------------------------------------
# 2.96.11 (Wunsch Daniel): in der Kopfzeile statt App-Symbol + «MoveEye» der Schriftzug - breit W6 (eine Zeile, «Move» hell,
# «Eye» orange, das «o» ist das Auge, darüber der Sichtfächer mit der erkannten Person), schmal (Handy) W1 (untereinander,
# wie Daniels Skizze). Die Buchstaben sind Pfade (Liberation Sans Bold, SIL OFL) - überall gleich, ohne Schriftart.
# Erzeugt mit werkzeuge/schriftzug_erzeugen.py. Abschaltbar: «header_wordmark».
# ----------------------------------------------------------------------------
WORDMARK_W6 = _zd('144_logo_schriftzug/WORDMARK_W6', "")
WORDMARK_W1 = _zd('144_logo_schriftzug/WORDMARK_W1', "")
LOGO_RED = "#e0242b"          # 2.98.9 (wish of Daniel): the person in the logo is a red silhouette and walks to and fro
PUPIL_X, PUPIL_UP = 4.6, 2.0  # 2.98.52: how far the pupil looks to the side / up (free room in the ring: about 6, so 5 + margin)


def _wm_walk(svg):
    """2.98.9, logo variant C «Kamera folgt»: the red person walks to and fro inside the field of view (steps), the corner
    marks go with it and the field of view swings along - like the head following a person. CSS only (no script)."""
    m = re.search(r'<path d="M([\d.]+) ([\d.]+) L[^"]*" fill="url\(#mwf[^)]*\)"/>', svg)
    f = re.search(r'<g transform="translate\(([\d.]+) ([\d.]+)\) scale\(([\d.]+)\)" fill="#e8590c"[^>]*>.*?</g>', svg)
    b = re.search(r'<g fill="none" stroke="currentColor" stroke-width="[\d.]+" stroke-linecap="round" stroke-linejoin="round"><path d="[^"]*"/></g>', svg)
    if not (m and f and b):
        return svg
    tx, ty, sc = (float(v) for v in f.groups())
    ex, ey = float(m.group(1)), float(m.group(2))
    amp = round(22.0 * sc / 1.6 if sc < 1.3 else 22.0, 1)
    ang = round(math.degrees(math.atan2(amp, max(1.0, ey - ty))), 1)
    R = LOGO_RED
    person = ('<g transform="translate(%.1f %.1f) scale(%.2f)" fill="%s" stroke="%s" stroke-linecap="round" stroke-linejoin="round">'
              '<circle cx="1" cy="-15.5" r="5.2" stroke="none"/><path d="M0.5 -9 L-0.5 3" stroke-width="8"/>'
              '<g class="wl1"><path d="M-0.5 3 L-5 13.5" stroke-width="4.6" fill="none"/></g><g class="wl2"><path d="M-0.5 3 L4.5 13" stroke-width="4.6" fill="none"/></g>'
              '<g class="wa1"><path d="M0.5 -6 L-5.5 0.5" stroke-width="3.6" fill="none"/></g><g class="wa2"><path d="M0.5 -6 L6 -0.5" stroke-width="3.6" fill="none"/></g></g>') % (tx, ty, sc, R, R)
    cone = m.group(0).replace("<path ", '<path class="wmc" style="transform-origin:%.1fpx %.1fpx;--wa:%.1fdeg" ' % (ex, ey, ang), 1)
    out = svg.replace(m.group(0), cone, 1)
    out = out.replace(f.group(0) + b.group(0), '<g class="wmw" style="--wx:%.1fpx">' % amp + person + b.group(0) + "</g>", 1)
    # 2.98.52 (Daniel): the pupil looks at the person (same 7 s curve as the walk: x in proportion to the person's x, a little
    # up because the person walks above the eye; at most 4.6 to the side, always inside the ring) and the eye blinks now and then
    e = re.search(r'(<circle cx="([\d.]+)" cy="([\d.]+)" r="[\d.]+" fill="none" stroke="#ff9f43" stroke-width="[\d.]+"/>)<circle ([^>]*fill="currentColor"/>)', out)
    if e:
        d = tx - float(e.group(2))
        far = max(abs(d - amp), abs(d + amp), 1.0)
        p0, p1 = PUPIL_X * (d - amp) / far, PUPIL_X * (d + amp) / far
        pupil = '<circle class="wmp" style="--p0:%.2fpx;--p1:%.2fpx;--py:%.1fpx" %s' % (p0, p1, -PUPIL_UP, e.group(4))
        out = out.replace(e.group(0), '<g class="wmb">' + e.group(1) + pupil + "</g>", 1)
    return out


WORDMARK_W6 = _wm_walk(WORDMARK_W6)
WORDMARK_W1 = _wm_walk(WORDMARK_W1)
WORDMARK_CSS = ("header h1.wm .wmc,header h1.wm .wmw{transform-box:view-box}header h1.wm .wmw{animation:wmw 7s ease-in-out infinite}"
                "header h1.wm .wmc{animation:wmc 7s ease-in-out infinite}"
                "header h1.wm .wl1,header h1.wm .wl2,header h1.wm .wa1,header h1.wm .wa2{transform-box:fill-box;transform-origin:50% 0}"
                "header h1.wm .wa1,header h1.wm .wa2{transform-origin:100% 0}"
                # 2.98.53: a real gait - leg 1 with arm 2, leg 2 with arm 1 half a step (0.35 s of 0.7 s) later (before: «reverse» on these
                # mirror-like keyframes gave the same angle, all four limbs swung together)
                "header h1.wm .wl1,header h1.wm .wa2{animation:wms .7s ease-in-out infinite}header h1.wm .wl2,header h1.wm .wa1{animation:wms .7s ease-in-out -.35s infinite}"
                "@keyframes wmw{0%,100%{transform:translateX(calc(-1*var(--wx)))}50%{transform:translateX(var(--wx))}}"
                "@keyframes wmc{0%,100%{transform:rotate(calc(-1*var(--wa)))}50%{transform:rotate(var(--wa))}}"
                "@keyframes wms{0%,100%{transform:rotate(18deg)}50%{transform:rotate(-18deg)}}"
                # 2.98.52: pupil follows the person (same 7 s curve), blink twice in 23 s (after 9.2 s and 22.1 s: 13 s / 10 s apart,
                # never in step with the walk), each about 0.2 s
                "header h1.wm .wmp{transform:translate(var(--p0),var(--py));animation:wmp 7s ease-in-out infinite}"
                "header h1.wm .wmb{transform-box:fill-box;transform-origin:50% 50%;animation:wmb 23s linear infinite}"
                "@keyframes wmp{0%,100%{transform:translate(var(--p0),var(--py))}50%{transform:translate(var(--p1),var(--py))}}"
                "@keyframes wmb{0%,39.6%,40.5%,95.6%,96.5%,100%{transform:scaleY(1)}39.85%,40.15%,95.85%,96.15%{transform:scaleY(.1)}}"
                "@media (prefers-reduced-motion:reduce){header h1.wm .wmw,header h1.wm .wmc,header h1.wm .wl1,header h1.wm .wl2,header h1.wm .wa1,header h1.wm .wa2,header h1.wm .wmb{animation:none}"
                "header h1.wm .wmp{animation:none;transform:none}}"
                "header h1.wm{gap:8px}header h1.wm::before{display:none}header h1.wm svg{overflow:visible}"
                "header h1.wm svg{display:block;color:var(--txt,#e8eef5)}header h1.wm .wm6{height:46px;width:auto}"
                "header h1.wm .wm1{height:76px;width:auto;display:none}"
                "@media (max-width:560px){header h1.wm .wm6{display:none}header h1.wm .wm1{display:block}}")


def wordmark_h1(m):
    """the substitution for <h1 ...>MoveEye</h1> (render_page)"""
    tag = m.group(1)
    tag = tag[:-1] + (' class="wm"' if "class=" not in tag else "") + ">"
    return tag + WORDMARK_W6 + WORDMARK_W1
# ----------------------------------------------------------------------------
# Self-healing (Daniel, 29.10.2026). A watchdog thread looks every 15 s:
#  * camera loop: no sign of life (HEART) for 90 s - the loop hangs inside a camera call. Or the source says «connected»,
#    the loop runs, but no new frame came for 150 s. The reconnect of the camera loop (410: read_failures / _good_t) acts
#    after ~6 s; the watchdog only steps in when that did not help for minutes, so the two never fight.
#  * AI: switched on, model loaded, frames come, but the AI has not run for 5 minutes (status stuck) -> the AI is loaded
#    again (only that part); 3 times in an hour -> MoveEye restarts.
#  * web page: http(s)://127.0.0.1:<port>/sw.js does not answer 4 times in a row (2 minutes) -> MoveEye restarts.
# A restart uses the same path as the update / pause (save settings, finish the recording, os.execv, same PID - the
# autostart and the systemd watchdog stay happy). Brake: at least 5 minutes running (doubled after each restart, at most
# 1 hour), at most 2 restarts per hour and 6 per day (kept in <data>/selfheal.json, written only when it restarts). When
# the brake holds, it is logged and one push says so. After a restart the new run logs it and sends one info push.
# Never in tool mode, while paused, during an update or another restart. MOTIONWATCH_NO_SELFHEAL=1 switches it off.
# ----------------------------------------------------------------------------
SELFHEAL = {"on": os.environ.get("MOTIONWATCH_NO_SELFHEAL", "") != "1", "t0": time.time(), "web_fail": 0, "last": [], "ai_fix": deque(maxlen=10),
            "held": {}, "file": None, "started": False, "web_t": 0.0}
SELFHEAL_LOOP_S = 90.0                 # camera loop without a sign of life
SELFHEAL_FRAME_S = 150.0               # «connected», loop alive, but no new frame
SELFHEAL_AI_S = 300.0                  # the AI has not run although it should
SELFHEAL_WEB_FAILS = 4                 # probes in a row without an answer (every 30 s)
SELFHEAL_GRACE_S = 180.0               # after a start: the camera / simulator may take a while
SELFHEAL_PER_HOUR, SELFHEAL_PER_DAY = 2, 6
_SH_TEST = os.environ.get("MOTIONWATCH_SELFHEAL_TEST", "")   # tests only: «web» / «loop» pretend that part hangs
if _SH_TEST:
    SELFHEAL_GRACE_S = float(os.environ.get("MOTIONWATCH_SELFHEAL_GRACE", "20"))


def _sh_file():
    return os.path.join(DATA_DIR, "selfheal.json")


def _sh_load():
    if SELFHEAL["file"] is None:
        try:
            with open(_sh_file()) as f:
                d = json.load(f)
            SELFHEAL["file"] = d if isinstance(d, dict) else {}
        except (OSError, ValueError):
            SELFHEAL["file"] = {}
    return SELFHEAL["file"]


def _sh_save(d):
    SELFHEAL["file"] = d
    try:
        tmp = _sh_file() + ".tmp"
        with open(tmp, "w") as f:
            json.dump(d, f)
        os.replace(tmp, _sh_file())
    except OSError:
        pass


def selfheal_allowed(now=None):
    """(allowed, reason) - the brake: uptime, per hour, per day"""
    now = now or time.time()
    d = _sh_load()
    ts = [float(t) for t in (d.get("restarts") or []) if isinstance(t, (int, float)) and now - float(t) < 86400]
    hour = [t for t in ts if now - t < 3600]
    six = [t for t in ts if now - t < 6 * 3600]
    need = min(3600.0, 300.0 * (2 ** len(six)))          # 5 min, 10, 20, 40, 60 - a hang right after the start waits longer
    if _SH_TEST:
        need = SELFHEAL_GRACE_S
    up = now - SELFHEAL["t0"]
    if len(hour) >= SELFHEAL_PER_HOUR:
        return False, "max. %d restarts per hour" % SELFHEAL_PER_HOUR
    if len(ts) >= SELFHEAL_PER_DAY:
        return False, "max. %d restarts per day" % SELFHEAL_PER_DAY
    if up < need:
        return False, "running only %d s (needs %d s before a restart)" % (up, need)
    return True, ""


def _sh_note(part, what, held=False):
    SELFHEAL["last"].insert(0, {"t": time.time(), "part": part, "what": what, "held": held})
    del SELFHEAL["last"][10:]


def _sh_push(text):
    w = WATCH_REF.get("w")
    if w is None:
        return
    try:
        w.notifier.info(text, title="{name}: " + tr("Self-healing"))
    except Exception:
        pass


def _sh_hold(part, why, reason):
    """a restart was needed but the brake holds: log it, one push per part and day"""
    k = part
    if time.time() - SELFHEAL["held"].get(k, 0) < 86400 and SELFHEAL["held"].get(k + "_r") == reason:
        return
    SELFHEAL["held"][k] = time.time(); SELFHEAL["held"][k + "_r"] = reason
    log_event("sys", f"Self-healing: {why} - no restart now ({reason})")
    _sh_note(part, why + " · " + "no restart now (limit)", True)
    if "per hour" in reason or "per day" in reason:
        _sh_push(tr(why) + " – " + tr("MoveEye did not restart again (limit reached). Please look at it."))


def selfheal_restart(part, why):
    """restart MoveEye (same process, same options) - only when the brake allows it"""
    ok, reason = selfheal_allowed()
    if not ok:
        _sh_hold(part, why, reason)
        return False
    if RESTART.get("pending"):
        return False
    RESTART["pending"] = "selfheal"
    now = time.time()
    d = dict(_sh_load())
    d["restarts"] = [t for t in (d.get("restarts") or []) if isinstance(t, (int, float)) and now - t < 86400] + [now]
    d["pending"] = {"t": now, "part": part, "why": why}
    _sh_save(d)
    log_event("sys", f"Self-healing: {why} - restarting MoveEye")

    def work():
        try:
            w = WATCH_REF.get("w")
            end = time.time() + 8.0
            while w is not None and getattr(w, "writer", None) is not None and time.time() < end and part != "loop":
                time.sleep(0.2)
            try:
                sound_stop(); talk_stop()
            except Exception:
                pass
            save_settings_now()
            _close_fds_on_exec()
            os.execv(sys.executable, [sys.executable, os.path.abspath(__file__)] + _base_args())
        except Exception as e:
            RESTART["pending"] = ""
            log_event("sys", f"Self-healing: restart failed: {e}"[:200])
    threading.Thread(target=work, daemon=True, name="selfheal-restart").start()
    return True


def _sh_after_start():
    """the run after a restart by the watchdog: log it and send one info push (when the messages work again)"""
    d = _sh_load()
    p = d.get("pending")
    if not isinstance(p, dict):
        return
    d = dict(d); d.pop("pending", None); _sh_save(d)
    why = str(p.get("why") or "")
    _sh_note(str(p.get("part") or ""), why + " · " + "restarted")
    log_event("sys", f"Self-healing: started again after «{why}»")
    time.sleep(45)
    _sh_push(tr("MoveEye restarted itself") + ": " + tr(why) + ". " + tr("Everything runs again."))


def _sh_busy():
    """moments in which nothing is judged"""
    try:
        if toolmode_on() or RESTART.get("pending") or PAUSING.get("on") or UPD_PROG.get("phase") or POWER.get("pending"):
            return True
    except NameError:
        pass
    return False


def _sh_web_probe():
    """does the own web page answer? any HTTP answer counts (also 401 / 404)"""
    import http.client
    web = globals().get("WEB")
    if web is None or not getattr(web, "serving", False):
        return None
    host = WEB_OPTS.get("bind") or "127.0.0.1"
    if host in ("0.0.0.0", "", "::"):
        host = "127.0.0.1"
    port = int(CFG["web_port"])
    if _SH_TEST == "web":
        port = 1                                          # tests: nobody answers there
    try:
        if WEB_OPTS.get("https"):
            import ssl
            con = http.client.HTTPSConnection(host, port, timeout=8, context=ssl._create_unverified_context())
        else:
            con = http.client.HTTPConnection(host, port, timeout=8)
        con.request("GET", "/sw.js", headers={"User-Agent": "MoveEye-selfheal"})
        con.getresponse().read(64)
        con.close()
        return True
    except Exception:
        return False


def selfheal_check():
    """one round of the watchdog; returns what it found (for tests)"""
    w = WATCH_REF.get("w")
    now = time.time()
    if w is None or not SELFHEAL["on"] or now - SELFHEAL["t0"] < SELFHEAL_GRACE_S or _sh_busy():
        SELFHEAL["web_fail"] = 0
        return ""
    # --- the camera loop
    hb = now - HEART["t"] + (1000 if _SH_TEST == "loop" else 0)
    if hb > SELFHEAL_LOOP_S:
        selfheal_restart("loop", "The camera loop hung")
        return "loop"
    src = str(STATE.get("source_status") or "")
    good = float(getattr(w, "_good_t", 0.0) or 0.0)
    if src == "connected" and w.cap is not None and good and now - good > SELFHEAL_FRAME_S:
        selfheal_restart("frames", "No new pictures although the camera is connected")
        return "frames"
    # --- the AI (only the part)
    ai = getattr(w, "ai", None)
    if (ai is not None and getattr(ai, "net", None) is not None and CFG.get("ai_enabled") and CFG.get("detection_on", True)
            and not DEMO.get("on") and not helper_ready() and good and now - good < 10):
        last = float(getattr(ai, "_last_run", 0.0) or 0.0)
        since = SELFHEAL.get("ai_since") or now
        SELFHEAL["ai_since"] = since
        if now - max(last, since) > SELFHEAL_AI_S:
            recent = [t for t in SELFHEAL["ai_fix"] if now - t < 3600]
            if len(recent) >= 3:
                selfheal_restart("ai", "The AI got stuck again and again")
                return "ai_restart"
            SELFHEAL["ai_fix"].append(now); SELFHEAL["ai_since"] = now
            log_event("ai", "Self-healing: the AI was stuck - loading it again")
            _sh_note("ai", "The AI was stuck · loaded again")
            try:
                w.ai = AIDetector()
            except Exception as e:
                log_event("ai", f"Self-healing: AI could not be loaded again: {e}"[:200])
            if len(recent) == 0:
                _sh_push(tr("The AI was stuck and was loaded again."))
            return "ai"
    else:
        SELFHEAL["ai_since"] = None
    # --- the web page (every 30 s)
    if now - SELFHEAL["web_t"] >= 30:
        SELFHEAL["web_t"] = now
        ok = _sh_web_probe()
        if ok is False:
            SELFHEAL["web_fail"] += 1
            if SELFHEAL["web_fail"] >= SELFHEAL_WEB_FAILS:
                SELFHEAL["web_fail"] = 0
                selfheal_restart("web", "The web page did not answer")
                return "web"
        else:
            SELFHEAL["web_fail"] = 0
    return ""


def selfheal_loop():
    threading.Thread(target=_sh_after_start, daemon=True, name="selfheal-note").start()
    while True:
        time.sleep(15 if not _SH_TEST else 5)
        try:
            sdcard_tick()
            selfheal_check()
        except Exception as e:
            print(f"self-healing: {e}")


def selfheal_start():
    """started once the camera loop object exists (from the health wrapper or the first look)"""
    if SELFHEAL["started"]:
        return
    SELFHEAL["started"] = True
    threading.Thread(target=selfheal_loop, daemon=True, name="selfheal").start()


def _selfheal_waiter():
    """the program starts its parts in 640; this waits until the camera loop object exists (never in the self-test)"""
    for _ in range(600):
        time.sleep(1.0)
        if WATCH_REF.get("w") is not None:
            selfheal_start()
            return


threading.Thread(target=_selfheal_waiter, daemon=True, name="selfheal-wait").start()


def selfheal_health_item(L):
    T = lambda x: tr(x, L)
    if not SELFHEAL["on"]:
        return {"id": "selfheal", "icon": "🩹", "title": T("Self-healing"), "level": "off", "text": T("off"), "tip": ""}
    day = [x for x in SELFHEAL["last"] if time.time() - x["t"] < 86400]
    if not day:
        return {"id": "selfheal", "icon": "🩹", "title": T("Self-healing"), "level": "ok", "text": T("watching camera, AI and web page"), "tip": ""}
    x = day[0]
    held = bool(x.get("held"))
    return {"id": "selfheal", "icon": "🩹", "title": T("Self-healing"), "level": "bad" if held else "warn",
            "text": datetime.fromtimestamp(x["t"]).strftime("%H:%M") + " " + " · ".join(T(p) for p in x["what"].split(" · ")) + (f" (+{len(day) - 1})" if len(day) > 1 else ""),
            "tip": T("If it happens again: send the diagnosis package (Settings → Help).")}


# ---- the self-check shows the two traffic lights above: health_check (120) calls sdcard_health_item and selfheal_health_item
# ----------------------------------------------------------------------------
# The simulator (3D-3.94, realism.gd) makes its pictures look like the real ones of THIS MoveEye: brightness, contrast,
# saturation, colour cast (red / blue to green), sharpness and grain - day and night separately. The real pictures are the
# diary pictures and the alarm pictures (never taken in the simulation). Measured the same way as realism.gd.stats():
# 160 x 90 bilinear, luminance 0.299 / 0.587 / 0.114. Only picture data leaves MoveEye (no map data, no picture itself).
# ----------------------------------------------------------------------------
REAL_LOOK = {"t": 0.0, "v": None, "busy": False}


def real_look_stats(img):
    s = cv2.resize(img, (160, 90), interpolation=cv2.INTER_LINEAR).astype(np.float32) / 255.0
    b, g, r = s[:, :, 0], s[:, :, 1], s[:, :, 2]
    L = 0.299 * r + 0.587 * g + 0.114 * b
    mean = float(L.mean())
    sat = float((s.max(axis=2) - s.min(axis=2)).mean())
    inner = L[1:89, 1:159]
    sharp = float(np.abs(inner - L[1:89, 0:158]).mean())
    noise = float(np.abs(inner - (L[1:89, 0:158] + L[1:89, 2:160] + L[0:88, 1:159] + L[2:90, 1:159]) * 0.25).mean())
    gm = max(0.001, float(g.mean()))
    return {"mean": mean, "std": float(L.std()), "sat": sat, "r": float(r.mean()) / gm, "b": float(b.mean()) / gm, "sharp": sharp, "noise": noise}


def _real_look_files():
    out = []
    for d, pat in ((diary_dir(), None), (rec_dir(), "person_")):
        try:
            for f in os.listdir(d):
                if f.lower().endswith(".jpg") and (pat is None or f.startswith(pat)):
                    p = os.path.join(d, f)
                    out.append((os.path.getmtime(p), p))
        except OSError:
            pass
    out.sort(reverse=True)
    return [p for _t, p in out[:80]]


def real_look_build():
    acc = {"day": [], "night": []}
    for p in _real_look_files():
        img = cv2.imread(p)
        if img is None or img.shape[0] < 90:
            continue
        st = real_look_stats(img)
        acc["night" if st["mean"] < 0.18 or st["sat"] < 0.03 else "day"].append(st)
    res = {}
    for k, lst in acc.items():
        if lst:
            res[k] = {key: round(float(np.median([x[key] for x in lst])), 4) for key in lst[0]}
            res[k]["n"] = len(lst)
    return res


def real_look():
    """for the simulator state: the look of the real pictures (computed in the background, at most every 6 h)"""
    if not REAL_LOOK["busy"] and time.time() - REAL_LOOK["t"] > 6 * 3600:
        REAL_LOOK["busy"] = True

        def run():
            try:
                REAL_LOOK["v"] = real_look_build()
                log_event("sys", "Real look for the simulator: " + ", ".join(f"{k} {v['n']} picture(s)" for k, v in (REAL_LOOK["v"] or {}).items()))
            except Exception as e:
                log_event("sys", f"Real look: {e}"[:120])
            REAL_LOOK["t"] = time.time()
            REAL_LOOK["busy"] = False
        threading.Thread(target=run, daemon=True, name="reallook").start()
    return REAL_LOOK["v"] or None
# ----------------------------------------------------------------------------
# 2.98.13 (Daniel, 29.10.2026): MoveEye had simtask_busy (141), the simulator busy_with (main.gd). Now they know each other:
#  * MoveEye asks the simulator every 3 s ({"action": "busy"} -> busy_with("")). A test run, the test bench, training
#    pictures, blind spots … started in the simulator window lock MoveEye's own starts with the same message
#    «The simulator is busy: …» (simtask_busy in 141 asks sim_busy_remote()).
#  * MoveEye tells the simulator what it does itself (sim_state: "simtask_de" - Aufräumen 2: «simtask» in English is no longer sent); the simulator refuses its own
#    starts then (busy_with in main.gd: «Störfall-Übung (von MoveEye)»).
#  * Blind spots started in the simulator («Testen» card): MoveEye follows them like its own (BLIND / _blind_wait in 143),
#    so the map in MoveEye shows the result, whoever started it. Older simulators without «busy»: blindmap info is asked.
# ----------------------------------------------------------------------------
SIMBUSY = {"w": "", "t": 0.0, "ok": None, "seen_blind": 0, "poll_t": 0.0, "started": False}
SIM_BUSY_NAMES = {"Testlauf": "test run", "Prüfstand": "test bench", "Trainingsbilder": "training pictures", "Blinde Flecken": "blind spots",
                  "Fehlalarm nachstellen": "false alarm learning", "Wiedergabe": "playback of a recording"}


def simtask_local():
    """what MoveEye itself does with the simulator right now ('' = nothing) - without asking the simulator"""
    for name, busy in (("test run", TESTOPT.get("busy")), ("training night", TRAIN.get("busy")), ("A/B comparison", ABT.get("busy")),
                       ("drill", DRILL.get("busy"))):
        if busy:
            return name
    for name, ref in (("blind spots", "BLIND"), ("false alarm learning", "FALEARN"), ("automatic thresholds", "AUTOTH"), ("demo", "DEMO_RUN"),
                      ("place setup", "PLACE")):
        d = globals().get(ref)
        if isinstance(d, dict) and d.get("busy") and not (ref == "BLIND" and d.get("ext")):
            return name
    try:
        if PROTECT["test"]["busy"]:
            return "protection test"
    except (NameError, KeyError, TypeError):
        pass
    return ""


def sim_busy_remote():
    """'' or the name of what the simulator does that MoveEye did not start (for simtask_busy). While MoveEye runs a task
    itself, the simulator being busy is that task - not counted."""
    if not CFG.get("sim_on") or simtask_local():
        return ""
    if time.time() - SIMBUSY["t"] > 30:
        return ""
    w = str(SIMBUSY["w"] or "")
    if not w or w == "Spielrunde" or "MoveEye" in w:          # the game round: sim_game_running() in 141
        return ""
    if w == "Blinde Flecken" and BLIND.get("busy"):
        return "blind spots"
    return tr(SIM_BUSY_NAMES.get(w, w)) + " (" + tr("started in the simulator") + ")"


def _simbusy_adopt_blind():
    """blind spots run in the simulator, MoveEye does not follow them yet -> follow them (result in BLIND['last'])"""
    if BLIND.get("busy"):
        SIMBUSY["seen_blind"] = 0
        return
    SIMBUSY["seen_blind"] += 1
    if SIMBUSY["seen_blind"] < 2:                              # twice in a row: not a start of MoveEye that is just coming
        return
    SIMBUSY["seen_blind"] = 0
    BLIND.update(busy=True, kind="map", ext=True)
    log_event("sys", "Blind spots started in the simulator - MoveEye draws the map")

    def run():
        try:
            _blind_wait()
        finally:
            BLIND["ext"] = False
    threading.Thread(target=run, daemon=True, name="blindmap-ext").start()


def _sim_reachable():
    """looser than sim_ready(): a slow simulator PC may miss a few frames - the lock still counts (30 s)"""
    return bool(CFG.get("sim_on")) and SIM.get("ok") and time.time() - SIM.get("t", 0) < 30


def simbusy_poll():
    if not _sim_reachable():
        SIMBUSY["seen_blind"] = 0
        return
    if SIMBUSY["ok"] is not False:
        try:
            r = sim_control({"action": "busy"})
        except Exception:
            return
        if r.get("ok") and "busy" in r:
            SIMBUSY.update(w=str(r.get("busy") or ""), t=time.time(), ok=True)
        elif r.get("error") == "unknown action":
            SIMBUSY.update(ok=False, poll_t=time.time())
            return
        blind = SIMBUSY["w"] == "Blinde Flecken"
    else:                                                      # an older simulator: only the blind spots
        if time.time() - SIMBUSY["poll_t"] > 600:
            SIMBUSY["ok"] = None                               # updated meanwhile? ask again
        try:
            r = sim_control({"action": "blindmap", "do": "info"})
        except Exception:
            return
        blind = bool(r.get("busy"))
    if blind:
        _simbusy_adopt_blind()
    else:
        SIMBUSY["seen_blind"] = 0


def simbusy_loop():
    while True:
        time.sleep(3.0)
        try:
            simbusy_poll()
            simupd_sync()
        except Exception as e:
            print(f"simulator lock: {e}")


def _simbusy_waiter():
    for _ in range(600):
        time.sleep(1.0)
        if WATCH_REF.get("w") is not None:
            threading.Thread(target=simbusy_loop, daemon=True, name="simbusy").start()
            return


threading.Thread(target=_simbusy_waiter, daemon=True, name="simbusy-wait").start()

# ----------------------------------------------------------------------------
# 2.98.38: In jeder Spielrunde meldete der Simulator (gamelearn.gd) rund 20 «Fehlalarme» pro Minute – auch Rahmen um Spieler,
# weil er MoveEyes Rahmen (aus einem Bild von vor 1–3 s) mit den Spielern von JETZT verglich. Diese Ausschnitte kamen als
# «keine Person» nach fa_learn/ und hätten der KI Falsches beigebracht. Darum hier ein Sicherheitsnetz:
#  - das richtige Bild: MoveEye merkt sich während einer Spielrunde die letzten Bilder mit ihren Personen-Rahmen
#    (fa_ring_note, aus 410) und schneidet den Ausschnitt aus dem Bild, in dem es den Rahmen wirklich gesehen hat
#  - die Wahrheit vom Simulator (ab 3D-4.13, «info.v» 2): keine Person / kein Spieler in der Nähe des Rahmens, der Rahmen
#    nicht viel grösser als eine stehende Person an dieser Stelle («pmax»), der Kopf hat sich nicht gedreht
#  - sonst kommt der Ausschnitt nach fa_learn/zweifel/ (label «doubtful», use false – nicht fürs Training)
#  - «Lernbilder prüfen» (Web: Simulator → Lernen → Fehlalarm-Lernen; Fenster: Simulator): prüft die vorhandenen
#    Spiel-Bilder in fa_learn/ nochmals mit den gespeicherten Angaben; alte Spiel-Bilder ohne diese Angaben gehen nach zweifel/.
# ----------------------------------------------------------------------------
FA_DOUBT_DIR = "zweifel"
FA_RING = {"q": deque(maxlen=48)}          # (time, picture, [[x, y, w, h] 0..1, …]) of the last seconds
FACHECK = {"last": None, "count": None, "count_t": 0.0}


def fa_ring_note(frame, boxes):
    """410: a picture with persons during a game round (frame_raw is a fresh copy per picture - only the reference is kept)"""
    try:
        q = FA_RING["q"]
        now = time.time()
        q.append((now, frame, [list(b) for b in boxes]))
        while q and now - q[0][0] > 5.0:
            q.popleft()
    except Exception:
        pass


def fa_ring_find(box):
    """(picture, "ring") in which MoveEye reported exactly this box, newest first - or (None, "")"""
    try:
        for t_, f_, bs in reversed(list(FA_RING["q"])):
            if time.time() - t_ > 5.0:
                break
            for b in bs:
                if all(abs(float(b[i]) - float(box[i])) <= 0.0015 for i in range(4)):
                    return f_, "ring"
    except Exception:
        pass
    return None, ""


def fa_near(m, t):
    """a box and a truth box mean the same thing (like gamelearn.gd «near»): the truth box grows by a margin; a quarter
    of the box in it, or the centre of one in the other"""
    try:
        m = [float(v) for v in m[:4]]
        t = [float(v) for v in t[:4]]
    except (TypeError, ValueError, IndexError):
        return False
    mx, my = 0.04 + 0.25 * t[2], 0.04 + 0.15 * t[3]
    e = [t[0] - mx, t[1] - my, t[2] + 2 * mx, t[3] + 2 * my]
    ix = max(0.0, min(m[0] + m[2], e[0] + e[2]) - max(m[0], e[0]))
    iy = max(0.0, min(m[1] + m[3], e[1] + e[3]) - max(m[1], e[1]))
    if m[2] * m[3] > 0 and ix * iy / (m[2] * m[3]) >= 0.25:
        return True
    cx, cy = m[0] + m[2] / 2, m[1] + m[3] / 2
    if e[0] <= cx <= e[0] + e[2] and e[1] <= cy <= e[1] + e[3]:
        return True
    tx, ty = t[0] + t[2] / 2, t[1] + t[3] / 2
    return m[0] <= tx <= m[0] + m[2] and m[1] <= ty <= m[1] + m[3]


def fa_box_check(box, info, how, H=0):
    """(ok, [reasons]) - may this box be kept as «no person»? Every doubt is a reason."""
    why = []
    try:
        x, y, w_, h_ = [float(v) for v in (box or [])[:4]]
    except (TypeError, ValueError):
        return False, ["no box"]
    if w_ * h_ > 0.2 or w_ > 0.6 or h_ > 0.8:
        why.append("very big")
    if not isinstance(info, dict) or int(info.get("v") or 0) < 2:
        why.append("no truth from the simulator")
    else:
        tru = info.get("truth") if isinstance(info.get("truth"), list) else []
        if any(isinstance(t, (list, tuple)) and len(t) >= 4 and fa_near([x, y, w_, h_], t) for t in tru[:32]):
            why.append("person near")
        try:
            pm = float(info.get("pmax") or -1)
        except (TypeError, ValueError):
            pm = -1.0
        if pm > 0.005 and (h_ > 1.3 * pm or w_ > 1.0 * pm):     # a person is about a third as wide as high
            why.append("bigger than a person there")
        if info.get("steady") is False:
            why.append("head turned")
    if how != "ring":
        why.append("picture not found")
    try:
        e = size_expected([x, y, w_, h_], 1.0)             # 417: how big a person is at this place (learned by MoveEye)
        if e and h_ > 2.5 * e and "bigger than a person there" not in why:
            why.append("bigger than a person there")
    except Exception:
        pass
    return not why, why


def fa_check_meta(info, how, H=0):
    """what is kept next to the picture so «Lernbilder prüfen» can check it again later"""
    m = {"v": 2 if isinstance(info, dict) and int(info.get("v") or 0) >= 2 else 1, "frame": how, "h": int(H or 0)}
    if isinstance(info, dict):
        tru = []
        for t in (info.get("truth") if isinstance(info.get("truth"), list) else [])[:16]:
            try:
                tru.append([round(float(v), 3) for v in t[:4]])
            except (TypeError, ValueError, IndexError):
                pass
        m["truth"] = tru
        try:
            m["pmax"] = round(float(info.get("pmax")), 3)
        except (TypeError, ValueError):
            m["pmax"] = -1
        if isinstance(info.get("steady"), bool):
            m["steady"] = info["steady"]
    return m


def fa_next_number(d):
    n = 0
    try:
        for fn in os.listdir(d):
            m_ = re.match(r"^(\d+)\.jpg$", fn)
            if m_:
                n = max(n, int(m_.group(1)))
    except OSError:
        pass
    return n + 1


def _fa_is_game_dir(dn, d):
    if dn.endswith("_spiel"):
        return True
    try:
        with open(os.path.join(d, "info.json")) as f:
            i = json.load(f)
        return i.get("cause") == "game" or i.get("from") == "simulator game"
    except (OSError, ValueError, AttributeError):
        return False


def fa_counts():
    """(game pictures for the training, doubtful pictures) - cached for 30 s"""
    if FACHECK["count"] is not None and time.time() - FACHECK["count_t"] < 30:
        return FACHECK["count"]
    base = os.path.join(DATA_DIR, "fa_learn")
    g = z = 0
    try:
        for dn in os.listdir(base):
            d = os.path.join(base, dn)
            if not os.path.isdir(d):
                continue
            if dn == FA_DOUBT_DIR:
                for r_, _ds, fs in os.walk(d):
                    z += sum(1 for f in fs if f.endswith(".jpg"))
            elif _fa_is_game_dir(dn, d):
                g += sum(1 for f in os.listdir(d) if f.endswith(".jpg"))
    except OSError:
        pass
    FACHECK.update(count=(g, z), count_t=time.time())
    return g, z


def fa_review():
    """«Lernbilder prüfen»: every game picture in fa_learn/ again - with the saved truth if there is one; game pictures
    without it (before 2.98.38) go to fa_learn/zweifel/. The pictures of real false alarms (👎) are not touched."""
    base = os.path.join(DATA_DIR, "fa_learn")
    res = {"t": time.time(), "checked": 0, "kept": 0, "moved": 0}
    try:
        names = sorted(os.listdir(base))
    except OSError:
        names = []
    for dn in names:
        d = os.path.join(base, dn)
        if dn == FA_DOUBT_DIR or not os.path.isdir(d) or not _fa_is_game_dir(dn, d):
            continue
        zd = os.path.join(base, FA_DOUBT_DIR, dn)
        for fn in sorted(os.listdir(d)):
            if not fn.endswith(".jpg"):
                continue
            res["checked"] += 1
            jp = os.path.join(d, fn[:-4] + ".json")
            meta = {}
            try:
                with open(jp) as f:
                    meta = json.load(f)
            except (OSError, ValueError):
                meta = {}
            chk = meta.get("check") if isinstance(meta, dict) else None
            if isinstance(chk, dict) and int(chk.get("v") or 0) >= 2:
                ok, why = fa_box_check(meta.get("box"), dict(chk, v=2), chk.get("frame"), chk.get("h") or 0)
            else:
                ok, why = False, ["old game picture without truth"]
            if ok:
                res["kept"] += 1
                continue
            try:
                os.makedirs(zd, exist_ok=True)
                n = fa_next_number(zd)
                shutil.move(os.path.join(d, fn), os.path.join(zd, "%02d.jpg" % n))
                meta = meta if isinstance(meta, dict) else {}
                meta.update(label="doubtful", moved_from=dn + "/" + fn, check=dict(chk if isinstance(chk, dict) else {}, ok=False, why=why))
                with open(os.path.join(zd, "%02d.json" % n), "w") as f:
                    json.dump(meta, f)
                if os.path.isfile(jp):
                    os.remove(jp)
                res["moved"] += 1
            except OSError as e:
                log_event("sys", f"Check learning pictures: {e}"[:120])
        try:                                            # nothing left but info.json: the folder goes too
            rest = [f for f in os.listdir(d) if f != "info.json"]
            if not rest:
                if os.path.isdir(zd) and not os.path.exists(os.path.join(zd, "info.json")) and os.path.isfile(os.path.join(d, "info.json")):
                    shutil.copy(os.path.join(d, "info.json"), os.path.join(zd, "info.json"))
                shutil.rmtree(d, ignore_errors=True)
        except OSError:
            pass
    if res["moved"]:                                    # the doubtful folders say so themselves (a training tool walking fa_learn/)
        for r_, ds, _fs in os.walk(os.path.join(base, FA_DOUBT_DIR)):
            for x in ds + [""]:
                p_ = os.path.join(r_, x, "info.json")
                try:
                    with open(p_, "w") as f:
                        json.dump({"label": "doubtful", "use": False, "from": "simulator game", "note": "not for the training"}, f)
                except OSError:
                    pass
            break
    FACHECK["last"] = res
    FACHECK["count"] = None
    log_event("sys", f"Learning pictures checked: {res['checked']} checked, {res['kept']} kept, {res['moved']} moved to «doubtful»")
    return res


def facheck_state():
    g, z = fa_counts()
    return {"last": FACHECK["last"], "game": g, "doubt": z}


def falearn_tk_build(app, sbody):
    """the window (section Simulator): «Lernbilder prüfen» - like the web (139, sheet «Fehlalarm-Lernen»)"""
    from tkinter import ttk
    def run():
        def go():
            r = fa_review()
            g, z = fa_counts()
            app._status("Simulator", "✓ " + tr("Learning pictures checked") + f": {r['checked']} · {tr('kept')} {r['kept']} · "
                        + f"{tr('moved to «doubtful»')} {r['moved']} · {tr('Game pictures for the training')} {g} · {tr('doubtful (not used)')} {z}")
        threading.Thread(target=go, daemon=True, name="facheck").start()
    ttk.Button(sbody, text="🔍 " + tr("Check learning pictures"), command=run).pack(fill="x", pady=(4, 0))
# ----------------------------------------------------------------------------
# Second Wi-Fi adapter (USB stick): one adapter makes the own Wi-Fi, the other one joins a known network (campsite, phone)
# -> repeater: the devices in the own Wi-Fi have internet (NetworkManager "shared" does the routing). Also: automatic change
# to another known network when the internet is gone, devices in the own Wi-Fi without internet (cameras), and a guard
# that listens for Wi-Fi jamming (deauthentication attacks) when the stick can listen ("monitor mode").
# ----------------------------------------------------------------------------
DUAL = {"on": False, "ap": "", "up": "", "adapters": [], "t": 0.0, "msg": "", "log": [], "sig": [], "drops": [], "unstable": False,
        "switch_t": 0.0, "offline_since": None, "iso": "", "iso_msg": ""}
WGUARD = {"state": "off", "iface": "", "phy": "", "msg": "", "deauth_min": [], "deauth_now": 0, "all_now": 0, "frames": 0,
          "last_alarm": 0.0, "alarms": [], "count_on": False, "count_now": None, "count_hist": [], "chan": None}
WIFI_CHIPS = {"brcmfmac": ("Broadcom (built in)", ""),
              "mt76x2u": ("MediaTek MT7612U", "very good: own Wi-Fi, 5 GHz and listening (monitor) work"),
              "mt7921u": ("MediaTek MT7921AU (Wi-Fi 6)", "very good: own Wi-Fi, 5 GHz and listening (monitor) work"),
              "mt76x0u": ("MediaTek MT7610U", "good: 5 GHz and listening (monitor) work"),
              "mt7601u": ("MediaTek MT7601U", "simple stick: only 2.4 GHz"),
              "rt2800usb": ("Ralink RT5370 / RT3070", "only 2.4 GHz, listening (monitor) works"),
              "ath9k_htc": ("Atheros AR9271", "only 2.4 GHz, listening (monitor) works"),
              "rtl8xxxu": ("Realtek (rtl8xxxu)", "simple driver: no own Wi-Fi, no listening"),
              "r8188eu": ("Realtek RTL8188EU", "simple driver: no listening"),
              "rtw88_8821cu": ("Realtek RTL8811CU / RTL8821CU", "listening (monitor) mostly not possible"),
              "rtw88_8822bu": ("Realtek RTL8812BU / RTL8822BU", "listening (monitor) mostly not possible"),
              "rtw88_8723du": ("Realtek RTL8723DU", "only 2.4 GHz"),
              "rtl88xxau": ("Realtek RTL8812AU / RTL8821AU (extra driver)", "extra driver needed"),
              "8812au": ("Realtek RTL8812AU (extra driver)", "extra driver needed"),
              "88XXau": ("Realtek RTL8812AU / RTL8821AU (extra driver)", "extra driver needed")}


def _rd(p):
    try:
        with open(p) as f:
            return f.read().strip()
    except OSError:
        return ""


def _iw_phy(phy):
    """What the radio can do: kinds of use (AP = own Wi-Fi, monitor = listening), 5 GHz."""
    if not phy or shutil.which("iw") is None:
        return [], False, ""
    code, out, _e = _run(["iw", "phy", phy, "info"], 6)
    if code != 0:
        return [], False, ""
    modes, in_modes = [], False
    for ln in out.splitlines():
        s = ln.strip()
        if s.startswith("Supported interface modes"):
            in_modes = True; continue
        if in_modes:
            if s.startswith("* "):
                modes.append(s[2:].strip())
            else:
                in_modes = False
    five = bool(re.search(r"\b5[1-8]\d\d(\.\d+)? MHz \[\d+\](?![^\n]*disabled)", out))
    comb = ""
    m = re.search(r"valid interface combinations:(.*?)(?:\n\t[A-Z]|\Z)", out, re.S)
    if m:
        comb = " ".join(m.group(1).split())[:200]
    return modes, five, comb


def wifi_adapters():
    out = []
    for i in _wifi_ifaces():
        if i.startswith("mwmon"):
            continue
        base = f"/sys/class/net/{i}"
        dev = os.path.realpath(base + "/device") if os.path.exists(base + "/device") else ""
        usb = "/usb" in dev
        drv = os.path.basename(os.path.realpath(base + "/device/driver")) if os.path.exists(base + "/device/driver") else ""
        phy = _rd(base + "/phy80211/name")
        prod, vid = "", ""
        if usb:
            p = os.path.dirname(dev)
            vid = (_rd(p + "/idVendor") + ":" + _rd(p + "/idProduct")).strip(":")
            prod = (_rd(p + "/manufacturer") + " " + _rd(p + "/product")).strip()
        modes, five, comb = _iw_phy(phy)
        chip, note = WIFI_CHIPS.get(drv, (prod or drv or "?", ""))
        out.append({"iface": i, "usb": usb, "driver": drv, "chip": chip, "product": prod[:60], "usb_id": vid, "phy": phy,
                    "mac": _rd(base + "/address"), "ap": ("AP" in modes) if modes else None, "monitor": ("monitor" in modes) if modes else None,
                    "five": five, "note": note, "comb": comb, "up": _rd(base + "/operstate") == "up"})
    return out


def _nm_dev_autoconnect(iface, on):
    if iface and shutil.which("nmcli"):
        _run(["nmcli", "device", "set", iface, "autoconnect", "yes" if on else "no"], 10)


def dual_roles():
    """Which adapter does what. Default: the built-in one makes the own Wi-Fi (devices are near), the USB stick joins the
    campsite / phone network (it often has a better antenna and may hang higher on a cable)."""
    ads = wifi_adapters()
    DUAL["adapters"] = ads; DUAL["t"] = time.time()
    was = (DUAL["on"], DUAL["ap"], DUAL["up"])
    if len(ads) < 2 or not CFG.get("wifi_repeater") or wifi_backend() != "nm":
        DUAL.update(on=False, ap="", up="",
                    msg="" if len(ads) >= 2 or not ads else "only one Wi-Fi adapter")
        if len(ads) >= 2 and wifi_backend() != "nm":
            DUAL["msg"] = "needs NetworkManager"
        if was[0]:
            WIFI["iface"] = ads[0]["iface"] if ads else "wlan0"; WIFI.pop("ap_iface", None)
            for a in ads:
                _nm_dev_autoconnect(a["iface"], True)
            dual_log(tr("Second Wi-Fi adapter: off - back to one adapter"))
        DUAL["choice"] = None
        return DUAL
    names = [a["iface"] for a in ads]
    ch = DUAL.get("choice")
    if ch and ch[0] in names and ch[1] in names and ch[2] == bool(CFG.get("wifi_swap")):
        ap = next(a for a in ads if a["iface"] == ch[0]); up = next(a for a in ads if a["iface"] == ch[1])   # keep the roles once chosen
    else:
        # the adapter that is connected to a network now keeps that connection (the Pi must stay reachable);
        # only when none is connected the USB stick is used for the internet (often the better antenna)
        conn = [a for a in ads if (_iw_link(a["iface"]) or {}).get("connected")]
        intern = next((a for a in ads if not a["usb"]), ads[0])
        stick = next((a for a in ads if a is not intern), ads[1])
        if CFG.get("wifi_swap"):                         # «internet over the USB stick (better antenna)»
            up = stick
        else:
            up = conn[0] if conn else stick
        ap = next(a for a in ads if a is not up)
        if ap["ap"] is False and up["ap"]:
            ap, up = up, ap                                  # this adapter cannot make an own Wi-Fi
        DUAL["choice"] = (ap["iface"], up["iface"], bool(CFG.get("wifi_swap")))
    DUAL.update(on=True, ap=ap["iface"], up=up["iface"], msg="")
    WIFI["iface"] = up["iface"]; WIFI["ap_iface"] = ap["iface"]
    if was != (True, ap["iface"], up["iface"]):
        _nm_unbind(ap["iface"])                              # known networks bound to the own-Wi-Fi adapter may use the other one
        _nm_dev_autoconnect(ap["iface"], False)              # the own Wi-Fi adapter does not join networks by itself
        _nm_dev_autoconnect(up["iface"], True)
        DUAL["since"] = time.time(); DUAL["had_conn"] = bool((STATE.get("wifi") or {}).get("connected"))
        dual_log(trf("Second Wi-Fi adapter: own Wi-Fi on {ap} ({a}), internet over {up} ({b})", ap=ap["iface"], a=ap["chip"], up=up["iface"], b=up["chip"]))
        if STATE["hotspot"].get("on") and was[1] and was[1] != ap["iface"]:
            hotspot_switch_later(True, 0.5)                  # the own Wi-Fi moves to the other adapter
        WIFI["refresh"] = True
    return DUAL


def _nm_unbind(iface):
    """Saved networks that only work on one adapter (connection.interface-name, e.g. made by the Raspberry Pi Imager) may
    then be used by the other adapter too - otherwise the stick cannot join the home Wi-Fi."""
    if not iface or not shutil.which("nmcli"):
        return
    code, out, _e = _run(["nmcli", "-t", "-f", "UUID,TYPE", "connection", "show"], 10)
    if code != 0:
        return
    for ln in out.splitlines():
        f = _nm_split(ln)
        if len(f) < 2 or f[1] not in ("802-11-wireless", "wifi"):
            continue
        c2, o2, _e = _run(["nmcli", "-t", "-g", "connection.interface-name,802-11-wireless.mode,connection.id", "connection", "show", "uuid", f[0]], 10)
        g = o2.splitlines() if c2 == 0 else []
        if len(g) >= 2 and g[0].strip() == iface and g[1].strip() != "ap":
            if _run(["nmcli", "connection", "modify", "uuid", f[0], "connection.interface-name", ""], 10)[0] == 0:
                log_event("sys", f"Wi-Fi «{g[2] if len(g) > 2 else f[0]}» may now be used by every adapter")


def dual_safety():
    """Safety net: the repeater was switched on, but the Pi has had no connection to a network for 2.5 minutes since then
    -> switch it off again by itself, so the Pi becomes reachable again the old way."""
    if not DUAL["on"] or not DUAL.get("had_conn"):
        return
    since = DUAL.get("since") or 0
    if time.time() - since < 150 or time.time() - since > 600:
        return
    w = STATE.get("wifi") or {}
    if w.get("connected") or (STATE.get("net") or {}).get("online"):
        DUAL["had_conn"] = False                             # it works - the safety net is no longer needed
        return
    CFG["wifi_repeater"] = False; save_settings()
    DUAL["choice"] = None
    dual_roles()
    if not CFG.get("hotspot_on"):
        hotspot_set(False, persist=False)
    DUAL["msg"] = "repeater switched off again: no connection to a network"
    dual_log(tr("Repeater switched off again by itself: the Pi had no connection to a network any more"), push=True)


def dual_log(text, push=False):
    DUAL["log"] = ([{"t": time.time(), "text": text}] + DUAL["log"])[:30]
    log_event("sys", text)
    if push and CFG.get("net_inet_notify", True):
        w = WATCH_REF.get("w")
        if w is not None:
            threading.Thread(target=w.notifier.info, args=(text,), kwargs={"title": "{name}: " + tr("Network")}, daemon=True).start()


def _visible_saved(iface):
    """Known networks that can be seen now with this adapter, strongest first."""
    code, out, _e = _run(["nmcli", "-t", "-f", "SSID,SIGNAL", "device", "wifi", "list", "ifname", iface, "--rescan", "auto"], 30)
    if code != 0:
        return []
    sig = {}
    for ln in out.splitlines():
        f = _nm_split(ln)
        if len(f) >= 2 and f[0]:
            try:
                sig[f[0]] = max(sig.get(f[0], 0), int(f[1]))
            except ValueError:
                pass
    saved = [s for s in _nm_saved() if s["ssid"] in sig]
    for s in saved:
        s["signal"] = sig[s["ssid"]]
    return sorted(saved, key=lambda s: (-s["prio"], -s["signal"]))


# ---- USB tethering (2.95.51): a phone on the USB cable gives its internet (Android «USB tethering», iPhone «Personal
# hotspot» + cable). NetworkManager prefers the cable to the Wi-Fi, so the own Wi-Fi (game network) gets the internet of
# the phone too - without a second Wi-Fi adapter. MoveEye finds the phone, connects it and shows it. ----
TETHER_DRV = {"rndis_host": "Android", "cdc_ether": "Android", "cdc_ncm": "Android", "ipheth": "iPhone"}
TETHER = {"t_try": 0.0, "was": ""}


def tether_scan():
    out = []
    for d in glob.glob("/sys/class/net/*"):
        try:
            drv = os.path.basename(os.readlink(os.path.join(d, "device", "driver")))
        except OSError:
            continue
        if drv in TETHER_DRV:
            out.append({"iface": os.path.basename(d), "kind": TETHER_DRV[drv], "drv": drv})
    return out


def tether_tick():
    found = tether_scan()
    if not found:
        if TETHER["was"]:
            log_event("sys", f"Phone on the USB cable gone ({TETHER['was']}) - internet over Wi-Fi again")
            TETHER["was"] = ""
        STATE["tether"] = {"on": False}
        return
    t = found[0]
    rc, txt, _e = _run(["ip", "-4", "-o", "addr", "show", "dev", t["iface"]], 5)
    m = re.search(r"inet (\d+\.\d+\.\d+\.\d+)", txt or "")
    ip = m.group(1) if m else ""
    if not ip and wifi_backend() == "nm" and time.time() - TETHER["t_try"] > 60:
        TETHER["t_try"] = time.time()
        _run(["nmcli", "device", "set", t["iface"], "managed", "yes"], 10)
        _run(["nmcli", "device", "connect", t["iface"]], 30)
    if ip and TETHER["was"] != t["iface"]:
        TETHER["was"] = t["iface"]
        log_event("sys", f"Phone on the USB cable ({t['kind']}, {t['iface']} {ip}): internet over the phone - also for the own Wi-Fi")
    STATE["tether"] = {"on": True, "iface": t["iface"], "kind": t["kind"], "ip": ip, "ready": bool(ip)}


# ---- TV view (2.95.51): a big page for a television - on the HDMI of the Pi (browser in kiosk mode, starts by itself in
# the campfire / gamer mode) or any screen with the link. Left the simulator window (or the camera), right the game:
# the wizard while it is set up, the QR code to join, the time, the players, the ranking; or the game corner of the Pi. ----
TV_PAGE = _zd('150_zweites_wlan_tv_netzcheck/TV_PAGE', ZD_PAGE)
TV = {"proc": None, "msg": "", "sim": False}


def tv_sim(on, who="web"):
    """2.95.53: the TV mode of the 3D simulator (on the PC at the television) - smoother than the browser"""
    iu = (page_address().rstrip("/") + "/info/") if CFG.get("info_page") and page_address() else ""
    try:
        r = sim_control({"action": "tv", "on": bool(on), "info_url": iu})
    except Exception as e:
        return False, "simulator not reachable"
    if not isinstance(r, dict) or not r.get("ok"):
        return False, "not supported - update the simulator"
    TV["sim"] = bool(on)
    log_event("sys", f"TV mode of the simulator {'on' if on else 'off'} ({who})")
    return True, ""


def tv_key():
    if not CFG.get("tv_key"):
        CFG["tv_key"] = secrets.token_urlsafe(9); save_settings()
    return CFG["tv_key"]


def tv_url(local=True):
    return f"{'https' if WEB_OPTS.get('https') else 'http'}://127.0.0.1:{CFG.get('web_port') or 5000}/tv/{tv_key()}/" if local else "/tv/" + tv_key() + "/"


def _tv_browser():
    for b in ("chromium-browser", "chromium", "firefox"):
        p_ = shutil.which(b)
        if p_:
            return p_
    return ""


def tv_show(on, who="web"):
    """the TV view on the HDMI of the Pi: a browser in kiosk mode on the desktop of the Pi"""
    if not on:
        pr = TV["proc"]
        if pr is not None and pr.poll() is None:
            try:
                pr.terminate()
            except Exception:
                pass
        TV["proc"] = None; TV["msg"] = "off"
        return True, ""
    if TV["proc"] is not None and TV["proc"].poll() is None:
        return True, ""
    br = _tv_browser()
    if not br:
        TV["msg"] = "no browser on this device (Chromium)"
        return False, TV["msg"]
    env = dict(os.environ)
    uid = os.getuid() if hasattr(os, "getuid") else 1000
    rt = env.get("XDG_RUNTIME_DIR") or f"/run/user/{uid}"
    if not env.get("WAYLAND_DISPLAY") and not env.get("DISPLAY"):
        way = next((os.path.basename(x) for x in sorted(glob.glob(os.path.join(rt, "wayland-*"))) if not x.endswith(".lock")), "")
        if way:
            env["WAYLAND_DISPLAY"] = way; env["XDG_RUNTIME_DIR"] = rt
        elif os.path.exists("/tmp/.X11-unix/X0"):
            env["DISPLAY"] = ":0"
        else:
            TV["msg"] = "no desktop on the HDMI (Raspberry Pi OS with desktop needed)"
            return False, TV["msg"]
    args = [br, "--kiosk", tv_url(True)] if "firefox" in br else [br, "--kiosk", "--noerrdialogs", "--disable-infobars", "--incognito",
            "--password-store=basic", "--ignore-certificate-errors", "--autoplay-policy=no-user-gesture-required", "--check-for-update-interval=31536000", tv_url(True)]
    try:
        TV["proc"] = subprocess.Popen(args, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
    except Exception as e:
        TV["msg"] = "browser: " + str(e)[:80]
        return False, TV["msg"]
    TV["msg"] = "on"
    log_event("sys", f"TV view on the HDMI ({who})")
    return True, ""


def tv_state():
    on = TV["proc"] is not None and TV["proc"].poll() is None
    return {"on": on, "msg": TV["msg"], "browser": bool(_tv_browser()),
            "url": tv_url(False), "auto": bool(CFG["tv_auto"]), "sim": TV["sim"], "sim_ok": bool(CFG.get("sim_on") and time.time() - SIM.get("t", 0) < 15)}


GAME_STATE_WORDS = {"goal": "at the goal", "out": "caught", "jail": "in jail", "play": "on the way", "lobby": "ready"}


def game_live_tv(g, T):
    """Aufräumen 2: «game_live» of the simulator -> the game part of the TV page (the same words as tv.gd and the SmallTV)"""
    url = str(g.get("url") or "")
    def ps_(p):
        k, pt = int(p.get("k", 0) or 0), p.get("pt")
        return {"n": p.get("n"), "c": p.get("c") or "#3b8cff",
                "s": " · ".join(x for x in (T(GAME_STATE_WORDS.get(str(p.get("s")), str(p.get("s") or ""))), f"{k}×" if k else "",
                                            f"{int(pt)} {T('points')}" if pt is not None else "") if x)}
    return {"open": True, "round": g.get("round"), "cd": g.get("cd"), "left": g.get("left"), "last_minute": g.get("lm"),
            "title": T("Game in the 3D simulator") + (" · " + str(g.get("goal")) if g.get("goal") else ""), "url": url, "qr": qr_svg(url) if url else "",
            "players": [ps_(p) for p in g.get("players") or []], "feed": [str(x)[:80] for x in (g.get("feed") or [])][:4],
            "board": [{"n": b.get("n"), "c": b.get("c"), "score": b.get("score")} for b in (g.get("board") or [])],
            "win": g.get("win"), "next": g.get("next") or "", "mw": g.get("mw")}


def tv_data():
    """what the TV page shows"""
    L = norm_lang(CFG.get("lang")) or "de"
    T = lambda x: tr(x, L)
    m = CFG.get("mode") or ""
    md = dict((x[0], x) for x in MODES).get(m)
    d = {"mode": (md[1] + " " + T(md[2])) if md else "",
         "state": T({"armed": "Armed", "arming": "Arming …", "disarmed": "Not armed"}.get(STATE.get("arm_state"), "")),
         "t_setup": T("The game is being set up"), "t_join": T("Join: scan the QR code with the phone (same Wi-Fi) or open"),
         "t_ready": T("Get ready"), "t_play": T("Round running"), "t_end": T("Round over"), "t_waiting": T("Waiting for players"),
         "t_board": T("Ranking of the evening"), "t_mw": T("MoveEye caught {n}"), "t_corner": T("Game corner"), "t_idle": T("Nothing is going on at the moment - MoveEye keeps watch."),
         "events": [], "game": {}, "wiz": {}, "party": {}}
    try:
        d["events"] = [str(e.get("text") or e.get("msg") or "")[:90] for e in list(EVENTS)[-5:]][::-1] if "EVENTS" in globals() else []
    except Exception:
        d["events"] = []
    if CFG.get("sim_on"):
        d["view_label"] = T("Simulator")
        try:
            wz = sim_control({"action": "gamewiz", "op": "get"})
            if isinstance(wz, dict) and wz.get("ok"):
                d["wiz"] = {k: wz.get(k) for k in ("shown", "step", "steps", "title", "cards", "pics")}
            # Aufräumen 2: ONE source for all game displays - «game_live» of the simulator (in every answer, 552 keeps it in
            # STV «game»), the same as the SmallTV and the TV mode of the simulator (tv.gd); older simulators: «game_info»
            gl = STV["game"] if "STV" in globals() and STV.get("game") and time.time() - STV.get("game_t", 0.0) < 10 else None
            if gl is not None:
                d["game"] = game_live_tv(gl, T)
            else:
                gi = sim_control({"action": "game_info"})
                if isinstance(gi, dict) and gi.get("open"):
                    url = ((wz or {}).get("game") or {}).get("url") or ""
                    d["game"] = game_live_tv({"round": gi.get("round"), "cd": gi.get("cd"), "left": gi.get("left"), "lm": gi.get("last_minute"),
                                              "goal": gi.get("goal"), "url": url, "players": gi.get("players") or [],
                                              "feed": [str(x.get("x")) for x in (gi.get("feed") or [])][::-1][:4], "board": gi.get("board") or []}, T)
        except Exception:
            pass
    else:
        d["view_label"] = T("Camera")
    try:
        d["tip"] = almanac_tip(); d["t_tip"] = T("Tip of the evening")
    except Exception:
        pass
    if CFG.get("info_page") and page_address():
        iu = page_address().rstrip("/") + "/info/"
        d["info"] = {"url": iu, "qr": qr_svg(iu)}; d["t_info"] = T("More about MoveEye")
    if party_on():
        url = page_address().rstrip("/") + "/p/" + PARTY["key"] + "/"
        d["party"] = {"on": True, "url": url, "qr": qr_svg(url), "game": str(PARTY.get("game") or ""),
                      "players": [{"n": v["name"], "c": "#3b8cff", "s": str(v.get("score", 0))} for k, v in PARTY["players"].items() if time.time() - v["t"] < 25]}
    return d


# ---- network check of the players (2.95.52): every phone measures its connection to MoveEye - ping (reaction time),
# jitter, losses, download and upload - and MoveEye adds what only it sees: the signal of each phone at its own Wi-Fi.
# Open only while a check runs (a few minutes); limited data per phone, so nobody can use it to load the Pi. ----
NETTEST = {"round": 0, "until": 0.0, "res": {}, "bytes": {}, "t0": 0.0}
NT_DOWN_MAX = 8 << 20          # one phone: at most this much down and up per check
NT_UP_MAX = 4 << 20
NT_BLOB = os.urandom(1 << 16)


def nettest_open():
    return time.time() < NETTEST["until"]


def nettest_start(minutes=3):
    NETTEST.update(round=NETTEST["round"] + 1, until=time.time() + 60 * max(1, min(15, minutes)), res={}, bytes={}, t0=time.time())
    try:
        party_bump()                                    # the phones in the game corner start their measurement by themselves
    except Exception:
        pass
    log_event("sys", "Network check of the players started")


def nettest_stop():
    NETTEST["until"] = 0.0


def _wifi_stations():
    """the phones at the own Wi-Fi of MoveEye: MAC -> signal, speeds (only when MoveEye is the access point)"""
    out = {}
    hs = STATE.get("hotspot") or {}
    if not hs.get("on") or shutil.which("iw") is None:
        return out
    ap_if = WIFI.get("ap_iface") or WIFI["iface"]
    code, txt, _e = _run(["iw", "dev", ap_if, "station", "dump"], 5)
    if code != 0:
        return out
    cur = None
    for line in txt.splitlines():
        m = re.match(r"Station\s+([0-9a-f:]{17})", line.strip(), re.I)
        if m:
            cur = out.setdefault(m.group(1).lower(), {}); continue
        if cur is None:
            continue
        k, _, v = line.strip().partition(":")
        v = v.strip()
        if k == "signal":
            mm = re.match(r"(-?\d+)", v); cur["dbm"] = int(mm.group(1)) if mm else None
        elif k == "tx bitrate":
            mm = re.match(r"([\d.]+)", v); cur["tx"] = float(mm.group(1)) if mm else None
        elif k == "rx bitrate":
            mm = re.match(r"([\d.]+)", v); cur["rx"] = float(mm.group(1)) if mm else None
        elif k == "connected time":
            mm = re.match(r"(\d+)", v); cur["conn_s"] = int(mm.group(1)) if mm else None
    return out


def _nt_grade(r):
    """good / fair / weak with the main reason (shown to the player and in the list)"""
    why = []
    rtt, jit, loss, dn, up, dbm = r.get("rtt"), r.get("jitter"), r.get("loss", 0), r.get("down"), r.get("up"), r.get("dbm")
    bad = 0
    if loss and loss >= 2:
        bad = 2; why.append("lost packets")
    if rtt is not None and rtt > 150:
        bad = 2; why.append("slow reaction")
    elif rtt is not None and rtt > 60:
        bad = max(bad, 1); why.append("reaction a bit slow")
    if jit is not None and jit > 40:
        bad = max(bad, 1); why.append("unsteady")
    if dn is not None and dn < 2:
        bad = 2; why.append("little speed")
    elif dn is not None and dn < 8:
        bad = max(bad, 1); why.append("medium speed")
    if dbm is not None and dbm < -75:
        bad = 2; why.append("weak signal")
    elif dbm is not None and dbm < -67:
        bad = max(bad, 1); why.append("signal could be better")
    return ["good", "fair", "weak"][bad], why


def nettest_report(ip, d):
    name = re.sub(r"[\x00-\x1f<>]", "", str(d.get("name") or "")).strip()[:20] or ip
    def num(k, lo, hi):
        try:
            v = float(d.get(k))
            return round(max(lo, min(hi, v)), 1)
        except (TypeError, ValueError):
            return None
    r = {"name": name, "ip": ip, "t": time.time(), "rtt": num("rtt", 0, 10000), "jitter": num("jitter", 0, 10000), "loss": int(num("loss", 0, 50) or 0),
         "down": num("down", 0, 10000), "up": num("up", 0, 10000), "dev": re.sub(r"[\x00-\x1f<>]", "", str(d.get("dev") or ""))[:30],
         "src": str(d.get("src") or "page")[:10]}
    mac = _arp_table().get(ip, "")
    r["mac"] = mac
    try:
        r["maker"] = oui_vendor(mac) if mac else ""
    except Exception:
        r["maker"] = ""
    st_ = _wifi_stations().get(mac) if mac else None
    if st_:
        r.update(dbm=st_.get("dbm"), link_tx=st_.get("tx"), link_rx=st_.get("rx"), via="own Wi-Fi")
    else:
        r["via"] = "this computer" if ip in ("127.0.0.1", "::1") else "network"
    r["grade"], r["why"] = _nt_grade(r)
    NETTEST["res"][ip] = r
    return r


NETWALK = deque(maxlen=200)          # 2.95.53: Empfangs-Rundgang: measured spots round MoveEye (metres; z = where the camera looks)


def netwalk_add(ip, d):
    def num(k, lo, hi):
        try:
            return round(max(lo, min(hi, float(d.get(k)))), 1)
        except (TypeError, ValueError):
            return None
    x, z = num("x", -60, 60), num("z", -60, 60)
    if x is None or z is None:
        return None
    pt = {"x": x, "z": z, "rtt": num("rtt", 0, 10000), "down": num("down", 0, 10000), "loss": int(num("loss", 0, 50) or 0), "t": time.time(),
          "name": re.sub(r"[\x00-\x1f<>]", "", str(d.get("name") or ""))[:20]}
    mac = _arp_table().get(ip, "")
    st_ = _wifi_stations().get(mac) if mac else None
    pt["dbm"] = st_.get("dbm") if st_ else None
    # 0 (bad) .. 1 (good): signal if known, else reaction time and speed
    q = []
    if pt["dbm"] is not None:
        q.append(max(0.0, min(1.0, (pt["dbm"] + 85) / 30.0)))
    if pt["rtt"] is not None:
        q.append(max(0.0, min(1.0, 1.0 - (pt["rtt"] - 10) / 140.0)))
    if pt["down"] is not None:
        q.append(max(0.0, min(1.0, pt["down"] / 20.0)))
    if pt["loss"]:
        q.append(0.0)
    pt["q"] = round(sum(q) / len(q), 2) if q else 0.0
    NETWALK.append(pt)
    return pt


def nettest_state():
    now = time.time()
    hs = STATE.get("hotspot") or {}
    w = STATE.get("wifi") or {}
    res = sorted(NETTEST["res"].values(), key=lambda r: (["weak", "fair", "good"].index(r["grade"]), r["name"].lower()))
    st_ = _wifi_stations()
    known = {r.get("mac") for r in res}
    others = [{"mac": m, "maker": oui_vendor(m), "dbm": v.get("dbm"), "tx": v.get("tx")} for m, v in st_.items() if m not in known]
    players = [v["name"] for k, v in PARTY["players"].items() if now - v["t"] < 25] if party_on() else []
    return {"open": nettest_open(), "left": max(0, int(NETTEST["until"] - now)), "round": NETTEST["round"], "res": res, "others": others,
            "hotspot": bool(hs.get("on")), "pi_link": {"ssid": w.get("ssid"), "dbm": w.get("dbm"), "rate": w.get("rate")} if w and w.get("connected") else None,
            "party": party_on(), "party_players": players, "url": "/nt/",
            "pending": [n for n in players if n not in {r["name"] for r in res}], "walk": list(NETWALK)}


NT_JS = r"""
// network check (2.95.52): reaction time, jitter, losses, download, upload - to MoveEye, not to the internet
async function ntMeasure(name, step, src) {
  const now = () => performance.now(), rtts = []; let loss = 0;
  step("ping", 0);
  for (let i = 0; i < 15; i++) {
    const c = new AbortController(), to = setTimeout(() => c.abort(), 1500), t0 = now();
    try { const r = await fetch("/nt/ping?r=" + Math.random(), {cache: "no-store", signal: c.signal}); await r.text(); if (i > 0) rtts.push(now() - t0); } catch (e) { loss++; }
    clearTimeout(to); step("ping", (i + 1) / 15);
  }
  rtts.sort((a, b) => a - b);
  const med = rtts.length ? rtts[Math.floor(rtts.length / 2)] : null;
  const jit = rtts.length > 2 ? rtts.slice(1).reduce((s, v, i) => s + Math.abs(v - rtts[i]), 0) / (rtts.length - 1) : null;
  const down = async (kb) => { const t0 = now(); const r = await fetch("/nt/down?kb=" + kb + "&r=" + Math.random(), {cache: "no-store"}); const b = await r.arrayBuffer(); return {mb: b.byteLength * 8 / 1e6, s: (now() - t0) / 1000}; };
  let dn = null, up = null;
  try {
    step("down", 0); const w = await down(256);
    const kb = w.s < 0.15 ? 4096 : w.s < 0.6 ? 2048 : 768;          // a slow phone does not wait forever
    const m = await down(kb); dn = m.mb / Math.max(0.01, m.s); step("down", 1);
  } catch (e) {}
  try {
    step("up", 0); const kb = dn && dn > 20 ? 2048 : 512, buf = new Uint8Array(kb * 1024); for (let i = 0; i < buf.length; i += 4096) buf[i] = (Math.random() * 255) | 0;
    const t0 = now(); const r = await fetch("/nt/up", {method: "POST", body: buf}); await r.text(); up = buf.length * 8 / 1e6 / Math.max(0.01, (now() - t0) / 1000); step("up", 1);
  } catch (e) {}
  const dev = (navigator.userAgentData && navigator.userAgentData.platform) || (/iPhone|iPad|Android|Windows|Mac OS|Linux/.exec(navigator.userAgent) || [""])[0];
  const res = {name: name, rtt: med, jitter: jit, loss: loss, down: dn, up: up, dev: dev, src: src || "page"};
  try { const r = await fetch("/nt/report", {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify(res)}); return await r.json(); } catch (e) { return Object.assign(res, {grade: "?"}); }
}
"""


