# Wunsch Daniel (29.10.2026, «KI-Daten aufräumen»):
#   * «Trainingspaket für ein eigenes KI-Modell (YOLO)» (Reiter Simulator und Fenster) hat dieselbe Wahl wie der Simulator:
#     «Vielfalt: normal / hoch» (dataset.gd / kitrain.gd, Name «vielfalt» wie dort).
#   * Die Pakete (Ordner user://trainingsbilder/<Zeit> + ZIP «MoveEye-Trainingsbilder_….zip», bis 3D-4.21 «MW-…», auf dem Schreibtisch) liegen auf dem
#     Rechner des Simulators (PC oder Pi). Der Simulator räumt nach jedem neuen Paket selbst auf (kidaten.gd): die neuesten 3
#     bleiben, nichts älter als 30 Tage; das neueste Paket bleibt immer. Der Knopf «Alte KI-Daten löschen» löscht alle
#     ausser dem neuesten. Das KI-Modell (models/moveeye_model.*, frozen_inference_graph.pb) wird nie angefasst.
# ----------------------------------------------------------------------------
KIDATA_VF = ("normal", "hoch")
KIDATA_SIZES = (200, 500, 1000, 2000)


def kidata_export(n, vielfalt=None):
    """a training pack in the simulator; vielfalt "normal" / "hoch" (else the choice of the simulator)"""
    try:
        n = int(n or 500)
    except (TypeError, ValueError):
        n = 500
    q = {"action": "dataset", "op": "export", "n": max(10, min(5000, n))}
    if str(vielfalt or "") in KIDATA_VF:
        q["vielfalt"] = str(vielfalt)
    return sim_control(q)


def kidata_packs(clean=False, lang=None):
    """the packs on the PC of the simulator; clean=True: delete all except the newest. ValueError for an old simulator."""
    r = sim_control({"action": "dataset", "op": "clean" if clean else "packs"})
    if not isinstance(r, dict) or "packs" not in r:
        raise ValueError("not supported - update the simulator")
    if not r.get("ok", True):
        raise ValueError(str(r.get("error") or "busy"))
    if clean:
        log_event("ai", f"Old AI data deleted: {int(r.get('deleted') or 0)} packs, {float(r.get('freed_mb') or 0):.0f} MB")
    r["text"] = kidata_text(r, lang)
    return r


def kidata_text(r, lang=None):
    ps = r.get("packs") or []
    t = (f"📦 {len(ps)} " + tr("training packs", lang) + f" · {float(r.get('total_mb') or 0):.0f} MB") if ps else "📦 " + tr("no training packs", lang)
    if r.get("deleted"):
        t += " · 🧹 " + trf("{n} deleted ({mb} MB)", lang, n=int(r["deleted"]), mb=f"{float(r.get('freed_mb') or 0):.0f}")
    return t


def kidata_tk_build(app, parent):
    """the window (section Simulator): size, «Vielfalt», «Trainingspaket», «Alte KI-Daten löschen» + one status line"""
    ttk.Label(parent, text="📦 " + tr("Training set for an own AI model (YOLO)"), style="Mut.TLabel").pack(anchor="w", pady=(8, 0))
    fr = ttk.Frame(parent); fr.pack(fill="x", pady=(2, 0))
    n_var = tk.StringVar(value="500")
    ttk.Combobox(fr, textvariable=n_var, values=[str(x) for x in KIDATA_SIZES], width=6, state="readonly").pack(side="left", padx=(0, 4))
    vf_names = {"hoch": tr("Variety: high (recommended)"), "normal": tr("Variety: normal")}
    vf_var = tk.StringVar(value=vf_names["hoch"])
    ttk.Combobox(fr, textvariable=vf_var, values=[vf_names["hoch"], vf_names["normal"]], state="readonly", width=24).pack(side="left", fill="x", expand=True)
    lbl = ttk.Label(parent, text="", style="Mut.TLabel", wraplength=330, justify="left")

    def run(fn):
        def work():
            try:
                txt = fn()
            except ValueError as e:
                txt = "⚠ " + tr_err(str(e))
            except Exception:
                txt = "⚠ " + tr_err("simulator not reachable")
            try:
                app.root.after(0, lambda: lbl.config(text=txt))
            except Exception:
                pass
        threading.Thread(target=work, daemon=True, name="kidata").start()

    def export():
        vf = "normal" if vf_var.get() == vf_names["normal"] else "hoch"
        r = kidata_export(n_var.get(), vf)
        return tr("The simulator makes the pictures and saves a ZIP on the desktop of its PC (about 2 s per picture).") + " " + str((r or {}).get("msg") or "")

    def clean():
        if not messagebox.askyesno("MoveEye", tr("Delete all training packs on the PC of the simulator except the newest one? The AI model stays.")):
            return
        run(lambda: kidata_packs(True)["text"])
    bf = ttk.Frame(parent); bf.pack(fill="x", pady=(4, 0))
    ttk.Button(bf, text="📦 " + tr("Make the training pack"), command=lambda: run(export)).pack(side="left", expand=True, fill="x", padx=(0, 4))
    ttk.Button(bf, text="🧹 " + tr("Delete old AI data"), command=clean).pack(side="left", expand=True, fill="x")
    lbl.pack(anchor="w", pady=(4, 0))
    ttk.Label(parent, text=tr("Cleaned up by itself: after every new pack the newest 3 stay, nothing older than 30 days (the newest always stays). The AI model is never deleted."), style="Mut.TLabel", wraplength=330, justify="left").pack(anchor="w")
    run(lambda: kidata_packs(False)["text"])
# ----------------------------------------------------------------------------
# Main detector
# ----------------------------------------------------------------------------
# ----------------------------------------------------------------------------
# Video sources
#   usb:<n>   USB / V4L2 webcams (/dev/video<n>)        pi:<n>   Raspberry Pi CSI cameras (picamera2)
#   url:<id>  network cameras: RTSP / HTTP-MJPEG (IP cams, Wi-Fi cams) saved in the settings
#   auto      first working USB camera (the behaviour of the older versions)
# Every source object offers read() -> (ok, BGR frame) and release(), so the main loop does not care where the picture comes from.
# ----------------------------------------------------------------------------
SRC_RE = re.compile(r"^(auto|demo|usb:\d{1,2}|pi:\d{1,2}|url:[0-9a-f]{8}|senxor:0|sim:\d|sim:thermal)$")
MAX_IP_SOURCES = 16
V4L_SKIP = ("bcm2835-codec", "bcm2835-isp", "rpivid", "pispbe", "rp1-cfe", "hevc", "-decoder", "-encoder")   # Pi internal nodes, no cameras
SOURCES = {"items": [], "time": 0.0, "scanning": False, "hints": []}      # result of the last scan
_SCAN_LOCK = threading.Lock()


def _url_ok(u):
    return isinstance(u, str) and len(u) <= 500 and re.match(r"^(rtsp|rtsps|http|https)://[^\s]+$", u, re.I) is not None


def mask_url(u):
    """rtsp://user:secret@host/x -> rtsp://user:***@host/x  (passwords are never shown or sent to the browser)."""
    return re.sub(r"(://[^/@:\s]+):[^/@\s]*@", r"\1:***@", u or "")


def _clean_ip_sources(lst):
    out, seen = [], set()
    for s in (lst if isinstance(lst, list) else [])[:MAX_IP_SOURCES]:
        if not isinstance(s, dict):
            continue
        sid, url = str(s.get("id", "")), str(s.get("url", "")).strip()
        if not re.fullmatch(r"[0-9a-f]{8}", sid) or sid in seen or not _url_ok(url):
            continue
        seen.add(sid)
        out.append({"id": sid, "name": str(s.get("name") or "").strip()[:40] or "Network camera", "url": url})
    return out


def find_ip_source(sid):
    for s in CFG["ip_sources"]:
        if s["id"] == sid:
            return s
    return None


_ROT = {"90": cv2.ROTATE_90_CLOCKWISE, "180": cv2.ROTATE_180, "270": cv2.ROTATE_90_COUNTERCLOCKWISE}


def cam_orient(frame):
    """Turn / mirror the camera picture as set (camera mounted sideways or upside down). Everything after sees it upright."""
    r = _ROT.get(str(CFG.get("cam_rotate", "0")))
    if r is not None:
        frame = cv2.rotate(frame, r)
    if CFG.get("cam_mirror"):
        frame = cv2.flip(frame, 1)
    return frame


class CvSource:
    """A camera read through OpenCV (USB webcam or network stream)."""
    def __init__(self, cap, size=None):
        self.cap = cap; self.size = size; self.full_fps = None

    def read(self):
        return self.cap.read()

    def set_fps(self, fps):
        """fps=None: full speed again. Many USB cameras can go slower; if not, nothing happens."""
        try:
            if self.full_fps is None:
                self.full_fps = float(self.cap.get(cv2.CAP_PROP_FPS) or 0) or 30.0
            self.cap.set(cv2.CAP_PROP_FPS, float(fps or self.full_fps))
        except Exception:
            pass

    def release(self):
        try:
            self.cap.release()
        except Exception:
            pass


class PiCamSource:
    """Raspberry Pi camera (CSI) through picamera2 / libcamera."""
    def __init__(self, index):
        from picamera2 import Picamera2                     # ImportError -> "not installed" message
        self.cam = Picamera2(index)
        self.cam.configure(self.cam.create_video_configuration(main={"size": (1280, 720), "format": "RGB888"}))
        self.cam.start()
        self.size = (1280, 720)

    def read(self):
        try:
            return True, self.cam.capture_array("main")     # "RGB888" is delivered in B,G,R order = what OpenCV expects
        except Exception:
            return False, None

    def set_fps(self, fps):
        try:
            self.cam.set_controls({"FrameRate": float(fps or 30.0)})
        except Exception:
            pass

    def release(self):
        for fn in ("stop", "close"):
            try:
                getattr(self.cam, fn)()
            except Exception:
                pass


def _v4l_internal(idx):
    """2.98.24: /dev/video<idx> is an internal node of the Raspberry Pi (on a Pi 5 the CSI camera itself shows up as rp1-cfe
    nodes video0 … video7): no USB camera - opening it with OpenCV hangs or blocks the Pi camera."""
    try:
        name = _v4l_name(idx).lower()
    except NameError:
        return False
    return any(b in name for b in V4L_SKIP)


def _pi_cams():
    """numbers of the Raspberry Pi cameras (CSI) that libcamera sees, [] without picamera2"""
    try:
        from picamera2 import Picamera2
        return [int(i.get("Num", n)) for n, i in enumerate(Picamera2.global_camera_info()) if "usb" not in str(i.get("Id", "")).lower()]
    except Exception:
        return []


def _open_usb(idx, raw=False):
    """raw=True for thermal cameras: they have their own small resolution and formats, so nothing is forced on them."""
    if _v4l_internal(idx):
        return None
    for backend, name in ((cv2.CAP_V4L2, "V4L2"), (cv2.CAP_ANY, "default")):
        cap = cv2.VideoCapture(idx, backend)
        if cap.isOpened():
            if not raw:
                cap.set(cv2.CAP_PROP_FOURCC, cv2.VideoWriter_fourcc(*"MJPG"))
                cap.set(cv2.CAP_PROP_FRAME_WIDTH, 1280); cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 720)
            cap.set(cv2.CAP_PROP_BUFFERSIZE, 1)
            ok, frame = cap.read()
            if ok:
                return CvSource(cap, (frame.shape[1], frame.shape[0]))
        cap.release()
    return None


def _open_url(url):
    if url.lower().startswith("rtsp"):
        os.environ.setdefault("OPENCV_FFMPEG_CAPTURE_OPTIONS", "rtsp_transport;tcp")     # TCP is far more reliable over Wi-Fi
    cap = None
    try:                                                    # connect / read time-outs (OpenCV >= 4.5.2)
        cap = cv2.VideoCapture(url, cv2.CAP_FFMPEG, [cv2.CAP_PROP_OPEN_TIMEOUT_MSEC, 8000, cv2.CAP_PROP_READ_TIMEOUT_MSEC, 8000])
    except Exception:
        cap = cv2.VideoCapture(url, cv2.CAP_FFMPEG)
    try:
        cap.set(cv2.CAP_PROP_BUFFERSIZE, 1)
    except Exception:
        pass
    ok, frame = cap.read() if cap.isOpened() else (False, None)
    if not ok:
        cap.release()
        return None
    return CvSource(cap, (frame.shape[1], frame.shape[0]))


def source_label(spec):
    kind, _, arg = spec.partition(":")
    if kind == "usb":
        return f"USB camera {arg}"
    if kind == "pi":
        return f"Pi camera {arg}"
    if kind == "url":
        s = find_ip_source(arg)
        return s["name"] if s else "Network camera"
    if kind == "senxor":
        return "Waveshare Thermal-90 (SPI)"
    if kind == "sim":
        return "Simulator thermal camera" if arg == "thermal" else f"Simulator camera {arg}"
    if spec == "demo":
        return "Demo"
    return "Automatic"


# ----------------------------------------------------------------------------
# Demo mode (--demo): a drawn camping scene where now and then a person, a dog or a bear walks by - the whole program reacts
#   as with a real camera (alarm, recording, diary, deterrence, header). Own settings folder, nothing is changed on the
#   computer: shutting down, Wi-Fi, updates, passwords and the like are switched off. For trying it out / an online demo.
# ----------------------------------------------------------------------------
DEMO = {"on": False, "objs": [], "size": (960, 540)}
DEMO_BLOCK = ("/api/power", "/api/wifi", "/api/hotspot", "/api/password", "/api/settings/import", "/api/pause", "/api/autostart",
              "/api/backup", "/api/fleet", "/api/time", "/api/gps", "/api/bt", "/api/lock", "/api/ai_model", "/api/ext")


class DemoSource:
    def __init__(self):
        W, H = DEMO["size"]
        self.t0 = time.time(); self.fps = 15.0; self.last = 0.0
        bg = np.zeros((H, W, 3), np.float32)
        for y in range(H):                                            # sky
            k = y / (H * 0.55)
            bg[y] = (235 - 60 * k, 200 - 50 * k, 150 - 40 * k)
        hz = int(H * 0.55)
        pts = np.array([[0, hz], [120, hz - 90], [260, hz - 30], [420, hz - 140], [600, hz - 40], [760, hz - 110], [960, hz - 20], [960, hz], [0, hz]], np.int32)
        cv2.fillPoly(bg, [pts], (120, 110, 100))                       # mountains
        bg[hz:] = (60, 120, 70)                                        # meadow
        rng = np.random.default_rng(3)
        for i in range(600):
            x, y = int(rng.integers(0, W)), int(rng.integers(hz, H))
            cv2.line(bg, (x, y), (x + int(rng.integers(-2, 3)), y - int(rng.integers(3, 9))), (40, 100 + int(rng.integers(0, 50)), 50), 1)
        for x in (70, 150, 840, 900):                                  # trees
            cv2.rectangle(bg, (x - 5, hz - 10), (x + 5, hz + 40), (40, 60, 80), -1)
            cv2.fillPoly(bg, [np.array([[x - 40, hz + 5], [x, hz - 110], [x + 40, hz + 5]], np.int32)], (40, 90, 50))
        tent = np.array([[560, hz + 120], [660, hz + 10], [760, hz + 120]], np.int32)   # tent
        cv2.fillPoly(bg, [tent], (60, 140, 230)); cv2.fillPoly(bg, [np.array([[640, hz + 120], [660, hz + 50], [680, hz + 120]], np.int32)], (40, 70, 120))
        self.bg = bg; self.hz = hz

    def set_fps(self, fps):
        self.fps = float(fps) if fps else 15.0

    def _person(self, img, x, y, ph):
        s_ = ph / 100.0; leg = math.sin(ph * 0 + time.time() * 7) * 12 * s_
        c = (60, 50, 60)
        cv2.circle(img, (int(x), int(y - 88 * s_)), int(9 * s_), (170, 190, 220), -1)
        cv2.rectangle(img, (int(x - 10 * s_), int(y - 78 * s_)), (int(x + 10 * s_), int(y - 38 * s_)), (50, 60, 160), -1)
        cv2.line(img, (int(x), int(y - 40 * s_)), (int(x + leg), int(y)), c, max(2, int(7 * s_)))
        cv2.line(img, (int(x), int(y - 40 * s_)), (int(x - leg), int(y)), c, max(2, int(7 * s_)))

    def _animal(self, img, x, y, size, col):
        leg = math.sin(time.time() * 9) * 6 * size
        cv2.ellipse(img, (int(x), int(y - 22 * size)), (int(28 * size), int(13 * size)), 0, 0, 360, col, -1)
        cv2.circle(img, (int(x + 30 * size), int(y - 30 * size)), int(10 * size), col, -1)
        for dx in (-18, 16):
            cv2.line(img, (int(x + dx * size), int(y - 15 * size)), (int(x + dx * size + leg), int(y)), col, max(2, int(4 * size)))

    def read(self):
        wait = 1.0 / max(1.0, self.fps) - (time.time() - self.last)
        if wait > 0:
            time.sleep(wait)
        self.last = time.time()
        t = time.time() - self.t0; W, H = DEMO["size"]
        img = self.bg.copy()
        for i, (cx, cy) in enumerate(((120, 60), (420, 90), (760, 50))):    # clouds drift
            x = int((cx + t * (6 + i * 2)) % (W + 200)) - 100
            cv2.ellipse(img, (x, cy), (70, 22), 0, 0, 360, (245, 245, 245), -1)
        objs = []
        cyc = t % 90.0
        if 12 < cyc < 26:                                               # a person walks past the tent
            k = (cyc - 12) / 14.0; x = -40 + k * (W + 80); y = self.hz + 150
            self._person(img, x, y, 110); objs.append(("person", int(x - 16), int(y - 110), 32, 112))
        if 55 < cyc < 66:                                               # an animal crosses the meadow
            k = (cyc - 55) / 11.0; big = int(t // 90) % 3 == 2
            x = W + 60 - k * (W + 120); y = self.hz + 210
            sz = 2.2 if big else 1.1
            self._animal(img, x, y, sz, (40, 50, 70) if big else (40, 110, 200))
            objs.append(("bear" if big else "dog", int(x - 30 * sz), int(y - 40 * sz), int(72 * sz), int(42 * sz)))
        night = max(0.0, math.sin(t / 600.0 * math.pi)) * 0.0               # (kept bright: a demo should be seen)
        img = np.clip(img * (1 - night) + np.random.default_rng(int(t * 15)).normal(0, 2.0, img.shape), 0, 255).astype(np.uint8)
        DEMO["objs"] = objs
        return True, img

    def release(self):
        pass


def demo_ai(frame):
    """AI results in the demo: what the scene has drawn (in the coordinates of the processing picture)."""
    H, W = frame.shape[:2]; sx, sy = W / DEMO["size"][0], H / DEMO["size"][1]
    ids = {v: k for k, v in COCO_LABELS.items()}
    boxes, objs = [], []
    for lab, x, y, w, h in DEMO["objs"]:
        b = (int(x * sx), int(y * sy), max(2, int(w * sx)), max(2, int(h * sy)))
        if lab == "person":
            boxes.append(b + (0.91,))
        else:
            objs.append(b + (0.86, ids.get(lab, 18)))
    return boxes, objs


def open_source(spec, thermal=False):
    """Open a source (may block for seconds - always call from a background thread). thermal=True opens USB cameras unforced.
    Returns (source or None, resolved id, label, error text)."""
    label = source_label(spec)
    try:
        kind, _, arg = spec.partition(":")
        if spec == "demo" or DEMO["on"]:
            return DemoSource(), "demo", "Demo", ""
        if kind == "sim":                                  # the separate simulation program (simulator connection)
            if arg == "thermal":
                src = SimThermalSource()
                return (src, spec, label, "") if src.ok() else (None, spec, label, "simulator not reachable")
            src = _open_url(sim_base() + f"/cam/{arg}/video.mjpg" + (f"?fps={sim_cam_fps(arg)}" if sim_eco_now() else ""))
            return (src, spec, label, "") if src else (None, spec, label, "simulator not reachable - is it running?")
        if spec == "auto":
            for idx in range(10):
                src = _open_usb(idx)
                if src:
                    return src, f"usb:{idx}", f"USB camera {idx}", ""
            pis = _pi_cams()                                     # 2.98.24: no USB camera -> the Pi camera
            if pis:
                sp_ = f"pi:{pis[0]}"
                if sp_ in CFG.get("extra_cams", []):              # 2.98.31: the main camera has priority (was: both fought)
                    CFG["extra_cams"] = [x for x in CFG["extra_cams"] if x != sp_]; save_settings()
                    log_event("sys", f"{source_label(sp_)}: removed from the extra cameras - it is the main camera")
                    cams_apply(); time.sleep(2.0)
                return PiCamSource(pis[0]), sp_, source_label(sp_), ""
            return None, spec, label, "no working camera found (ls /dev/video*)"
        if kind == "usb" and not thermal and _v4l_internal(int(arg)):
            pis = [n for n in _pi_cams() if f"pi:{n}" not in {c.spec for c in CAMS}]     # 2.98.24: an internal node was chosen
            if pis:
                log_event("sys", f"/dev/video{arg} is not a camera (internal node of the Raspberry Pi) - using the Pi camera {pis[0]}")
                return PiCamSource(pis[0]), f"pi:{pis[0]}", source_label(f"pi:{pis[0]}"), ""
            return None, spec, label, f"/dev/video{arg} is no camera (internal node of the Raspberry Pi) - choose «Raspberry Pi camera»"
        if kind == "usb":
            src = (_open_usb(int(arg), raw=True) or _open_usb(int(arg))) if thermal else _open_usb(int(arg))
            return (src, spec, label, "") if src else (None, spec, label, f"no picture from /dev/video{arg}")
        if kind == "pi":
            if not thermal and spec in CFG.get("extra_cams", []) and CFG.get("source") in (spec, "auto"):
                # 2.98.26: the Pi camera can be open only once - the main camera has priority over an extra camera
                CFG["extra_cams"] = [x for x in CFG["extra_cams"] if x != spec]; save_settings()
                log_event("sys", f"{label}: removed from the extra cameras - it is the main camera now")
                cams_apply(); time.sleep(2.0)
            try:
                return PiCamSource(int(arg)), spec, label, ""
            except Exception as e:
                if any(k in str(e).lower() for k in ("busy", "acquire", "sequence did not complete", "in use")):
                    if any(c.spec == spec for c in CAMS):        # 2.98.27: an extra camera holds it - close that one first
                        cams_apply()
                    time.sleep(3.0)                              # the old picture of the camera is still being closed: once more
                    return PiCamSource(int(arg)), spec, label, ""
                raise
        if kind == "senxor":
            if not thermal:
                return None, spec, label, "the Thermal-90 can only be used as thermal camera"
            return SenxorSource(), spec, label, ""
        if kind == "url":
            s = find_ip_source(arg)
            if not s:
                return None, spec, label, "unknown network camera"
            src = _open_url(s["url"])
            return (src, spec, label, "") if src else (None, spec, label, "no picture from " + mask_url(s["url"]))
        return None, spec, label, "unknown source"
    except ImportError:
        return None, spec, label, "picamera2 not installed (sudo apt install python3-picamera2)"
    except Exception as e:
        return None, spec, label, str(e)[:160]


def _v4l_name(idx):
    try:
        with open(f"/sys/class/video4linux/video{idx}/name") as f:
            return f.read().strip()
    except OSError:
        return ""


def _is_pi():
    try:
        with open("/proc/device-tree/model") as f:
            return "raspberry" in f.read().lower()
    except OSError:
        return False


def scan_sources(active_id=""):
    """Look for every camera that is connected right now (a few seconds). The camera that is in use cannot be opened a
    second time, so it is listed without probing."""
    if not _SCAN_LOCK.acquire(blocking=False):
        return SOURCES["items"]                             # a scan is already running
    SOURCES["scanning"] = True
    try:
        items, hints = [], []
        idxs = sorted({int(re.sub(r"\D", "", p)) for p in glob.glob("/dev/video*") if re.sub(r"\D", "", p)})
        if not idxs and not sys.platform.startswith("linux"):
            idxs = [0, 1, 2, 3]
        for idx in idxs:
            name = _v4l_name(idx)
            if any(b in name.lower() for b in V4L_SKIP):
                continue
            sid = f"usb:{idx}"
            entry = {"id": sid, "kind": "usb", "name": "USB camera: " + (name or f"video{idx}"),
                     "detail": f"/dev/video{idx}", "available": True}
            if sid == active_id:
                entry["detail"] += " · in use"
            else:
                src = _open_usb(idx) or _open_usb(idx, raw=True)     # thermal cameras do not like the forced format
                if src is None:
                    continue                                # metadata node or camera that is busy / not working
                entry["detail"] += f" · {src.size[0]}x{src.size[1]}"; src.release()
            items.append(entry)
        try:
            from picamera2 import Picamera2
            for n, info in enumerate(Picamera2.global_camera_info()):
                if "usb" in str(info.get("Id", "")).lower():
                    continue                                # USB cameras were found above
                num = int(info.get("Num", n))
                items.append({"id": f"pi:{num}", "kind": "pi", "name": "Raspberry Pi camera: " + str(info.get("Model", "camera")),
                              "detail": f"CSI port {num}", "available": True})
        except ImportError:
            if _is_pi():
                hints.append("Raspberry Pi cameras need picamera2:  sudo apt install python3-picamera2  "
                             "(in a virtual environment create it with --system-site-packages)")
        except Exception as e:
            hints.append(f"Pi camera scan failed: {e}")
        SOURCES.update(items=items, hints=hints, time=time.time())
        log_event("sys", f"Camera scan: {len(items)} camera(s) found")
        return items
    finally:
        SOURCES["scanning"] = False
        _SCAN_LOCK.release()


def list_sources():
    """Everything the user can pick: automatic + scanned cameras + saved network cameras."""
    items = [{"id": "auto", "kind": "auto", "name": "Automatic (first working USB camera)", "detail": "", "available": None}]
    items += [dict(i) for i in SOURCES["items"] if i["kind"] != "url"]
    items += [{"id": "url:" + s["id"], "kind": "url", "name": s["name"], "detail": mask_url(s["url"]), "available": None}
              for s in CFG["ip_sources"]]
    ids = {i["id"] for i in items}
    act = STATE["source_id"]
    if act and act not in ids:                              # the running camera is always in the list
        items.insert(1, {"id": act, "kind": act.split(":")[0], "name": STATE["source_label"], "detail": "in use", "available": True})
    return items


def source_info():
    return {"items": list_sources(), "selected": CFG["source"], "active": STATE["source_id"], "label": STATE["source_label"],
            "status": STATE["source_status"], "res": STATE["source_res"], "scanning": SOURCES["scanning"],
            "scanned": SOURCES["time"], "hints": list(SOURCES["hints"])}


def source_select(watch, sid):
    if not isinstance(sid, str) or not SRC_RE.match(sid):
        return False, "unknown source"
    if sid.startswith("url:") and not find_ip_source(sid[4:]):
        return False, "unknown network camera"
    watch.request_source(sid)
    return True, ""


def source_add(name, url):
    """Save a network camera. Returns (ok, error, new id)."""
    url = str(url or "").strip()
    if not _url_ok(url):
        return False, "invalid URL (rtsp:// or http:// expected)", ""
    if len(CFG["ip_sources"]) >= MAX_IP_SOURCES:
        return False, "too many network cameras", ""
    sid = uuid.uuid4().hex[:8]
    name = str(name or "").strip()[:40] or "Network camera"
    CFG["ip_sources"] = CFG["ip_sources"] + [{"id": sid, "name": name, "url": url}]     # re-assign, never mutate (DEFAULTS share the list)
    save_settings(); log_event("sys", f"Network camera added: {name} ({mask_url(url)})")
    return True, "", sid


def source_remove(watch, sid):
    s = find_ip_source(sid) if isinstance(sid, str) else None
    if not s:
        return False, "unknown network camera"
    CFG["ip_sources"] = [x for x in CFG["ip_sources"] if x["id"] != sid]
    save_settings(); log_event("sys", f"Network camera removed: {s['name']}")
    if CFG["source"] == "url:" + sid:
        watch.request_source("auto")
    return True, ""


# ----------------------------------------------------------------------------
# Timelapse: every N minutes the camera drives to a chosen position, waits until the picture is calm and saves a photo.
# An alarm (person seen, recording running, tracking) always has priority: then nothing moves, and the photo is taken
# only after the alarm is over. Photos: <recordings>/timelapse/tl_YYYYmmdd_HHMMSS.jpg   videos: tlv_*.mp4 in the same folder.
# ----------------------------------------------------------------------------
TL_HOLD = {"on": False}                          # True while the camera is parked for a photo: the patrol must not move it
TL_PHOTO_RE = re.compile(r"^tl_(\d{8})_(\d{6})\.jpg$")
TL_VIDEO_RE = re.compile(r"^tlv_[0-9A-Za-z_\-]{1,40}\.mp4$")
_TL_RENDER_LOCK = threading.Lock()


def servo_hold():
    """Something other than tracking is holding the servos (hand control, timelapse position)."""
    return manual_active() or TL_HOLD["on"] or wake_hold() or bool(servo_blocked())      # 2.98.35: Not-Aus / fault (072)


def tl_dir():
    return os.path.join(os.path.abspath(CFG["record_dir"]), "timelapse")


def tl_photos(day=""):
    try:
        names = sorted(n for n in os.listdir(tl_dir()) if TL_PHOTO_RE.match(n) and (not day or n[3:11] == day))
    except OSError:
        names = []
    return names


def tl_overview():
    photos = tl_photos(); days = {}
    for n in photos:
        days[n[3:11]] = days.get(n[3:11], 0) + 1
    videos = []
    try:
        for n in sorted(os.listdir(tl_dir()), reverse=True):
            if TL_VIDEO_RE.match(n):
                st = os.stat(os.path.join(tl_dir(), n))
                videos.append({"name": n, "size": st.st_size, "time": int(st.st_mtime)})
    except OSError:
        pass
    return {"count": len(photos), "latest": photos[-1] if photos else "", "videos": videos[:30],
            "days": [{"day": d, "count": c} for d, c in sorted(days.items(), reverse=True)[:60]],
            "status": STATE["timelapse"], "render": STATE["timelapse_render"], "on": bool(CFG["timelapse_on"])}


def tl_path(name):
    """Absolute path of a timelapse photo / video (guards against path tricks), or None."""
    if not isinstance(name, str) or not (TL_PHOTO_RE.match(name) or TL_VIDEO_RE.match(name)):
        return None
    p = os.path.join(tl_dir(), name)
    return p if os.path.isfile(p) else None


def tl_cleanup():
    limit = CFG["timelapse_max_gb"] * 1024 ** 3
    try:
        files = [(n, os.path.getsize(os.path.join(tl_dir(), n))) for n in os.listdir(tl_dir()) if TL_PHOTO_RE.match(n)
                 and not _read_sidecar("timelapse/" + n).get("fav")]          # starred photos stay
    except OSError:
        return
    files.sort()
    total = sum(sz for _n, sz in files); removed = 0
    while total > limit and len(files) > 1:
        n, sz = files.pop(0)
        try:
            os.remove(os.path.join(tl_dir(), n)); total -= sz; removed += 1
        except OSError:
            break
    if removed:
        log_event("servo", f"Cleanup: {removed} old photo(s) deleted")


class Timelapse:
    """State machine, called once per camera frame with the untouched picture.
       idle -> (interval over, no alarm) -> moving (camera driven to the position, settle time) -> photo -> idle."""
    def __init__(self):
        self.state = "idle"; self.t = 0.0; self.last_shot = 0.0; self.saved = None; self.target = None; self.pending_now = False

    def request_now(self):
        self.pending_now = True

    def _back(self):
        """Drive back to where the camera was - but only if nobody (tracking, hand control) has moved it since."""
        if CFG["timelapse_return"] and self.saved and self.target and abs(CFG["pan"] - self.target[0]) < 1 and abs(CFG["tilt"] - self.target[1]) < 1:
            CFG["pan"], CFG["tilt"] = self.saved

    def _abort(self, why):
        self._back()
        TL_HOLD["on"] = False; self.state = "idle"
        log_event("servo", f"Photo postponed: {why}")

    def update(self, frame, alarm):
        now = time.time()
        if not CFG["timelapse_on"] and not self.pending_now:
            if self.state != "idle":
                self._back(); TL_HOLD["on"] = False; self.state = "idle"
            STATE["timelapse"] = "off"
            return
        busy = alarm or manual_active() or wake_hold()
        if self.state == "idle":
            due = self.pending_now or now - self.last_shot >= CFG["timelapse_interval"] * 60.0
            if not due:
                STATE["timelapse"] = f"next photo in {int(max(1, (self.last_shot + CFG['timelapse_interval'] * 60.0 - now) / 60.0 + 0.5))} min"
                return
            if busy:
                STATE["timelapse"] = "waiting: alarm has priority" if alarm else "waiting: manual control"
                return
            tp = float(max(0.0, min(100.0, CFG["timelapse_pan"]))); tt = float(max(0.0, min(100.0, CFG["timelapse_tilt"])))
            self.saved = (CFG["pan"], CFG["tilt"]); self.target = (tp, tt)
            TL_HOLD["on"] = True
            CFG["pan"], CFG["tilt"] = tp, tt
            self.state = "moving"; self.t = now
            log_event("servo", f"Driving to the photo position (pan {tp:.0f}%, tilt {tt:.0f}%)")
            STATE["timelapse"] = "moving to the photo position"
            return
        # state == "moving": the alarm may start at any time and wins immediately
        if busy:
            self._abort("alarm" if alarm else "manual control")
            STATE["timelapse"] = "waiting: alarm has priority" if alarm else "waiting: manual control"
            return
        if not servo_arrived() or now - max(self.t, SRV["arrive_t"]) < CFG["timelapse_settle"]:     # 2.98.35: ramps (072)
            STATE["timelapse"] = "moving to the photo position"
            return
        self._shoot(frame, now)

    def _shoot(self, frame, now):
        try:
            os.makedirs(tl_dir(), exist_ok=True)
            name = datetime.now().strftime("tl_%Y%m%d_%H%M%S.jpg")
            ok = cv2.imwrite(os.path.join(tl_dir(), name), frame, [cv2.IMWRITE_JPEG_QUALITY, 90])
            if ok:
                gps_tag_jpg(os.path.join(tl_dir(), name))
        except (OSError, cv2.error) as e:
            ok, name = False, ""
            log_event("servo", f"Photo could not be saved: {e}")
        self.last_shot = now; self.pending_now = False
        if ok:
            STATE["timelapse_last"] = name
            log_event("servo", f"Photo saved: {name}")
            tl_cleanup()
        self._back()
        TL_HOLD["on"] = False; self.state = "idle"
        STATE["timelapse"] = "photo saved"


def timelapse_render(day="", fps=None):
    """Make a video from the photos of one day (or all). Runs in the background; progress is in STATE['timelapse_render']."""
    day = day if isinstance(day, str) and re.fullmatch(r"\d{8}", day) else ""
    try:
        fps = max(5.0, min(60.0, float(fps if fps is not None else CFG["timelapse_fps"])))
    except (TypeError, ValueError):
        fps = 25.0
    files = tl_photos(day)[-20000:]
    if len(files) < 2:
        return False, "need at least 2 photos"
    if not _TL_RENDER_LOCK.acquire(blocking=False):
        return False, "a video is already being made"

    def work():
        enc_before = STATE["recording_enc"]
        try:
            first = cv2.imread(os.path.join(tl_dir(), files[0]))
            if first is None:
                STATE["timelapse_render"] = "error: first photo unreadable"; return
            h, w = first.shape[:2]
            name = f"tlv_{day or 'all'}_{datetime.now().strftime('%H%M%S')}.mp4"
            path = os.path.join(tl_dir(), name)
            writer, _codec = open_writer(path, fps, (w, h))
            if writer is None:
                STATE["timelapse_render"] = "error: no video encoder available"; return
            for i, n in enumerate(files):
                img = cv2.imread(os.path.join(tl_dir(), n))
                if img is None:
                    continue
                if img.shape[:2] != (h, w):
                    img = cv2.resize(img, (w, h))
                writer.write(img)
                if hasattr(writer, "q"):
                    while writer.q.qsize() > 30:                 # the ffmpeg pipe drops frames when it is full: wait for it
                        time.sleep(0.01)
                STATE["timelapse_render"] = f"making video {i + 1}/{len(files)}"
            writer.release()
            STATE["timelapse_render"] = "video ready: " + name
            log_event("servo", f"Video made: {name} ({len(files)} photos, {fps:.0f} fps)")
        except Exception as e:
            STATE["timelapse_render"] = "error: " + str(e)[:100]
        finally:
            STATE["recording_enc"] = enc_before
            _TL_RENDER_LOCK.release()
    STATE["timelapse_render"] = "making video 0/" + str(len(files))
    threading.Thread(target=work, daemon=True).start()
    return True, ""


# ----------------------------------------------------------------------------
# Thermal camera: a second camera with the same view. Its picture is coloured and laid over the normal picture
# (blend, or "hot mode": only the warmest areas are shown). Detection always works on the normal picture.
# ----------------------------------------------------------------------------
class ThermalCam:
    """Keeps the chosen thermal source open in the background and always holds its newest picture."""
    def __init__(self):
        self.src = None; self.spec = ""; self.frame = None; self.t = 0.0; self.fails = 0
        self.retry_at = 0.0; self.opening = False; self.cache = (None, None)
        self.bgsub = None; self.bg_shape = None; self.hits = deque(maxlen=5); self.det_t = 0.0; self.boxes = []; self.lo = self.hi = None
        threading.Thread(target=self.loop, daemon=True).start()

    def wanted(self):
        spec = CFG["thermal_source"] if (CFG["thermal_on"] or CFG["thermal_alarm"] or CFG["nightvision"] or CFG["nightvision_auto"]
                                         or thermal_person_active()) else ""
        if spec and spec == STATE["source_id"]:
            return ""                                          # that camera is the main camera already
        return spec

    def _close(self):
        src, self.src, self.frame = self.src, None, None
        if src is not None:
            src.release()

    def _open(self, spec):
        self.opening = True
        try:
            res = open_source(spec, thermal=True)
            if res[0] is None:
                STATE["thermal"] = "no picture: " + res[3]
                log_event("sys", f"Thermal camera '{res[2]}' not available: {res[3]}")
                self.retry_at = time.time() + 5.0
            elif self.wanted() != spec:
                res[0].release()
            else:
                self.src = res[0]; self.spec = spec; self.fails = 0
                size = getattr(res[0], "size", None)
                STATE["thermal_res"] = f"{size[0]}x{size[1]}" if size else ""
                log_event("sys", f"Thermal camera: {res[2]}" + (f" ({STATE['thermal_res']})" if size else ""))
        finally:
            self.opening = False

    def loop(self):
        while True:
            try:
                want = self.wanted()
                if self.src is not None and (want != self.spec):
                    self._close()
                if self.src is None:
                    if not want:
                        STATE["thermal"] = "off" if not (CFG["thermal_on"] or CFG["thermal_alarm"]) else ("same camera as the main picture" if CFG["thermal_source"] else "no thermal camera selected")
                        time.sleep(0.5); continue
                    if time.time() >= self.retry_at and not self.opening:
                        STATE["thermal"] = "connecting…"
                        self._open(want)
                    else:
                        time.sleep(0.3)
                    continue
                ok, fr = self.src.read()
                w_ = WATCH_REF["w"]
                if w_ is not None and w_.eco_slow:
                    time.sleep(max(0.0, 1.0 / max(1.0, float(CFG["eco_fps"])) - 0.05))     # power saving
                if ok and fr is not None:
                    self.frame = fr; self.t = time.time(); self.fails = 0
                    STATE["thermal"] = "connected"
                else:
                    self.fails += 1
                    if self.fails >= 30:
                        STATE["thermal"] = "connection lost - reconnecting"
                        self._close(); self.retry_at = time.time() + 3.0
                    time.sleep(0.05)
            except Exception as e:
                STATE["thermal"] = "error: " + str(e)[:80]
                self._close(); self.retry_at = time.time() + 5.0; time.sleep(1.0)

    main_aspect = 9 / 16.0                           # height / width of the camera picture (set by the overlay)

    @classmethod
    def crop(cls, fr):
        """The part of the (wider) thermal picture that the normal camera sees: zoom + shift (thermal camera settings)."""
        g = cls.sim_geom()
        if g is not None:                            # 2.95.88: simulator - fit by the field of view of both cameras
            return cls.fit(fr, *g)
        z = max(0.3, min(1.0, float(CFG["thermal_zoom"]) / 100.0))
        dx, dy = float(CFG["thermal_dx"]) / 100.0, float(CFG["thermal_dy"]) / 100.0
        if z >= 0.999 and not dx and not dy:
            return fr
        H, W = fr.shape[:2]
        w = W * z; h = min(float(H), w * cls.main_aspect)
        x0 = max(0.0, min(W - w, W * (0.5 + dx) - w / 2)); y0 = max(0.0, min(H - h, H * (0.5 - dy) - h / 2))
        out = fr[int(round(y0)):int(round(y0 + h)), int(round(x0)):int(round(x0 + w))]
        return out if out.size else fr

    @staticmethod
    def sim_geom():
        """In the simulation the field of view of the head camera and of the thermal camera is known (/info): which part
        of the main picture the thermal picture covers (fx, fy; < 1 = it covers less, it is put in the middle). None outside."""
        try:
            if not (CFG.get("sim_on") and str(CFG["thermal_source"]) == "sim:thermal" and str(CFG["source"]).startswith("sim:")):
                return None
            info = SIM.get("info") or {}
            th = info.get("thermal") or {}
            cam = next((c for c in info.get("cameras") or [] if str(c.get("id")) == str(CFG["source"])[4:]), None)
            if not th or not cam or not (th.get("on_head") and cam.get("on_head")):
                return None
            if CFG.get("thermal_align_own"):
                return None                              # 557: the assistant «Wärmebild ausrichten» measured it (zoom / shift)
            fx = math.tan(math.radians(float(th["fov_h"])) / 2) / math.tan(math.radians(float(cam["fov_h"])) / 2)
            fy = fx * (float(th["h"]) / float(th["w"])) / (float(cam["h"]) / float(cam["w"]))
            if th.get("fov_v") and cam.get("fov_v"):     # 557: Thermal-90 has 90° × 67° (the pixels are not square)
                fy = math.tan(math.radians(float(th["fov_v"])) / 2) / math.tan(math.radians(float(cam["fov_v"])) / 2)
            return fx, fy
        except (KeyError, ValueError, TypeError, ZeroDivisionError):
            return None

    @staticmethod
    def fit(fr, fx, fy):
        """The thermal picture as the field of the main picture: bigger field = cut out the middle, smaller = put it in the middle
        and fill the rest with the median (no picture there, so no warm edges)."""
        H, W = fr.shape[:2]
        oW, oH = max(2, int(round(W / fx))), max(2, int(round(H / fy)))
        x0, y0 = (oW - W) // 2, (oH - H) // 2
        fill = np.median(fr.reshape(H * W, -1), axis=0).astype(fr.dtype)
        out = np.empty((oH, oW) + fr.shape[2:], fr.dtype); out[...] = fill
        sx0, sy0 = max(0, -x0), max(0, -y0)
        dx0, dy0 = max(0, x0), max(0, y0)
        w, h = min(W - sx0, oW - dx0), min(H - sy0, oH - dy0)
        out[dy0:dy0 + h, dx0:dx0 + w] = fr[sy0:sy0 + h, sx0:sx0 + w]
        return out

    @staticmethod
    def to_gray8(fr):
        """Any thermal frame -> 8 bit intensity (hot = bright) with the contrast stretched to what is in the picture."""
        if fr.ndim == 3:
            if fr.shape[2] == 1:
                fr = fr[:, :, 0]
            else:
                fr = cv2.cvtColor(fr, cv2.COLOR_BGR2GRAY) if fr.dtype == np.uint8 else fr.mean(axis=2)
        f = fr.astype(np.float32)
        small = f[::max(1, f.shape[0] // 60), ::max(1, f.shape[1] // 80)]
        lo, hi = np.percentile(small, (1, 99))
        if hi - lo < 1e-3:
            return np.zeros(f.shape, np.uint8)
        return np.clip((f - lo) * (255.0 / (hi - lo)), 0, 255).astype(np.uint8)

    @staticmethod
    def is_plain_gray(fr):
        if fr.ndim == 2 or fr.shape[2] == 1:
            return True
        if fr.dtype != np.uint8:
            return True
        s = fr[::8, ::8].astype(np.int16)
        return int(np.abs(s[:, :, 0] - s[:, :, 1]).max()) < 6 and int(np.abs(s[:, :, 1] - s[:, :, 2]).max()) < 6

    def color(self, fr):
        """-> (colour picture, intensity). A camera that already delivers false colours keeps its own colours."""
        gray = self.to_gray8(fr)
        cmap = THERMAL_MAPS.get(CFG["thermal_map"], cv2.COLORMAP_INFERNO)
        if self.is_plain_gray(fr):
            col = cv2.applyColorMap(gray, cmap) if cmap is not None else cv2.cvtColor(gray, cv2.COLOR_GRAY2BGR)
        else:
            col = fr if fr.dtype == np.uint8 and fr.ndim == 3 and fr.shape[2] == 3 else cv2.cvtColor(gray, cv2.COLOR_GRAY2BGR)
        return col, gray

    def detect(self):
        """Warm bodies in the thermal picture: clearly warmer than the scene (thermal_delta), moving (unless switched off,
        so sun-warmed stones or an engine do not alarm), big enough, inside the zones, seen in 3 of the last 5 pictures."""
        fr, t = self.frame, self.t
        if fr is None or time.time() - t > 3.0:
            self.hits.clear(); self.boxes = []; return []
        if t == self.det_t:
            return self.boxes
        self.det_t = t
        f = self.crop(fr).astype(np.float32)
        if f.ndim == 3:
            f = f.mean(axis=2)
        if f.shape[1] > 160:
            f = cv2.resize(f, (160, max(1, int(f.shape[0] * 160 / f.shape[1]))), interpolation=cv2.INTER_AREA)
        lo, hi = np.percentile(f, (2, 99.5))
        if self.lo is None:
            self.lo, self.hi = float(lo), float(hi)
        else:                                            # slow: an animal walking in must not re-scale the whole picture
            self.lo += 0.05 * (lo - self.lo); self.hi += 0.05 * (max(hi, self.lo + 1e-3) - self.hi)
        g = np.clip((f - self.lo) * 255.0 / max(1e-3, self.hi - self.lo), 0, 255).astype(np.uint8)
        med = float(np.median(g))
        # 2.98.x (Prüfstand: clear nights 0 thermal persons): the clear night sky is very cold (-20 °C and colder) and sets
        # the bottom of the scale - the ground then sits at ~210 of 255 and «median + 30 %» was above 255: nothing could
        # ever be warm. The step is now measured on the warm side only (twice the room above the median, at most the old
        # full scale), with a camera in °C at least 10 °C, else at least a quarter of the scale.
        span = min(255.0, 2.0 * (255.0 - med))
        if fr.dtype != np.uint8:
            span = max(span, min(255.0, 10.0 * 255.0 / max(1e-3, self.hi - self.lo)))
        else:
            span = max(span, 64.0)
        warm = ((g.astype(np.float32) > med + CFG["thermal_delta"] / 100.0 * span).astype(np.uint8)) * 255
        if CFG["thermal_need_motion"]:
            if self.bgsub is None or self.bg_shape != g.shape:
                self.bgsub = cv2.createBackgroundSubtractorMOG2(history=300, varThreshold=12, detectShadows=False); self.bg_shape = g.shape
            mov = cv2.dilate(self.bgsub.apply(g), np.ones((3, 3), np.uint8), iterations=2)
            warm = cv2.bitwise_and(warm, mov)
        warm = cv2.morphologyEx(warm, cv2.MORPH_OPEN, np.ones((2, 2), np.uint8))
        cnts, _ = cv2.findContours(warm, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        H, W = g.shape
        min_a = max(2.0, CFG["thermal_min_area"] / 100.0 * W * H)
        boxes = []
        for c in cnts:
            if cv2.contourArea(c) < min_a:
                continue
            x, y, w, h = cv2.boundingRect(c)
            nb = (x / W, y / H, w / W, h / H)
            if zone_allows(nb[0] + nb[2] / 2.0, nb[1] + nb[3] * 0.85):
                boxes.append(nb)
        self.hits.append(bool(boxes))
        self.boxes = boxes if sum(self.hits) >= 3 else []
        return self.boxes

    def overlay(self, frame):
        fr = self.frame
        if fr is None or time.time() - self.t > 3.0:
            return frame
        try:
            H, W = frame.shape[:2]
            ThermalCam.main_aspect = H / float(W)
            col, gray = self.color(self.crop(fr))
            col = cv2.resize(col, (W, H), interpolation=cv2.INTER_CUBIC)
            a = float(max(0.05, min(1.0, CFG["thermal_alpha"])))
            if CFG["thermal_hot"]:
                gray = cv2.resize(gray, (W, H), interpolation=cv2.INTER_LINEAR)
                thr = float(np.percentile(gray[::4, ::4], CFG["thermal_hot_pct"]))
                m = cv2.GaussianBlur((gray > thr).astype(np.float32), (0, 0), max(2.0, W / 200.0))[:, :, None] * a
                return (frame * (1.0 - m) + col * m).astype(np.uint8)
            return cv2.addWeighted(frame, 1.0 - a, col, a, 0)
        except cv2.error:
            return frame


THERMAL = None            # created together with the camera loop


_BELLY = "25:fe87bfc14c106eb2ebb75df5dba6aaec172507faaafe006700ce29179083c51cf8728e897041b1972f895c703f641812f524ff98ff0049463f8eab9055117ba9afa5d29fbee9fec505c09efe89178"     # a little pattern for the marmot (easter egg)


def belly_matrix():
    n, hx = _BELLY.split(":"); n = int(n)
    bits = bin(int(hx, 16))[2:].zfill(len(hx) * 4)
    return [[bits[r * n + c] == "1" for c in range(n)] for r in range(n)]


def _rdp(P, eps):
    """Ramer-Douglas-Peucker: the corners of a drawn line."""
    if len(P) < 3:
        return list(P)
    (ax, ay), (bx, by) = P[0], P[-1]; L = math.hypot(bx - ax, by - ay) or 1e-9
    dmax, idx = -1.0, 0
    for i in range(1, len(P) - 1):
        d = abs((bx - ax) * (ay - P[i][1]) - (ax - P[i][0]) * (by - ay)) / L if L > 1e-6 else math.hypot(P[i][0] - ax, P[i][1] - ay)
        if d > dmax:
            dmax, idx = d, i
    if dmax <= eps:
        return [P[0], P[-1]]
    return _rdp(P[:idx + 1], eps)[:-1] + _rdp(P[idx:], eps)


def cw_triangle(P):
    """True when the points (screen coordinates, y down) are a closed triangle drawn clockwise."""
    if len(P) < 8:
        return False
    xs = [p[0] for p in P]; ys = [p[1] for p in P]
    w, h = max(xs) - min(xs), max(ys) - min(ys); size = max(w, h)
    if size < 40 or min(w, h) < size * 0.3 or math.hypot(P[0][0] - P[-1][0], P[0][1] - P[-1][1]) > size * 0.35:
        return False
    area = sum(P[i][0] * P[(i + 1) % len(P)][1] - P[(i + 1) % len(P)][0] * P[i][1] for i in range(len(P))) / 2
    if area <= 0 or not (0.25 <= area / (w * h) <= 0.68):          # y down: positive = clockwise; a triangle fills about half
        return False
    V = _rdp(list(P) + [P[0]], size * 0.12)[:-1]
    changed = True
    while changed and len(V) > 3:                                      # drop corners that are nearly straight
        changed = False
        for i in range(len(V)):
            a, b, c = V[i - 1], V[i], V[(i + 1) % len(V)]
            u, v = (a[0] - b[0], a[1] - b[1]), (c[0] - b[0], c[1] - b[1])
            nu, nv = math.hypot(*u), math.hypot(*v)
            if nu < size * 0.12 or nv < size * 0.12 or (u[0] * v[0] + u[1] * v[1]) / (nu * nv) < -0.88:
                del V[i]; changed = True; break
    return len(V) == 3


def ccw_heart(P, min_size=90):
    """2.95.61: True when the points (screen coordinates, y down) are a big closed heart drawn counter-clockwise:
    two round lobes at the top, a dip in the middle between them, a point at the bottom."""
    if len(P) < 12:
        return False
    xs = [p[0] for p in P]; ys = [p[1] for p in P]
    left, right, top, bot = min(xs), max(xs), min(ys), max(ys)
    w, h = right - left, bot - top; size = max(w, h)
    if size < min_size or not (0.6 <= w / max(h, 1e-6) <= 1.6) or math.hypot(P[0][0] - P[-1][0], P[0][1] - P[-1][1]) > size * 0.3:
        return False
    area = sum(P[i][0] * P[(i + 1) % len(P)][1] - P[(i + 1) % len(P)][0] * P[i][1] for i in range(len(P))) / 2
    if area >= 0 or not (0.4 <= -area / (w * h) <= 0.88):          # y down: negative = counter-clockwise on the screen
        return False
    cx = (left + right) / 2
    D = []                                                           # more points on long, fast strokes
    for i in range(len(P)):
        a_, b_ = P[i], P[(i + 1) % len(P)]; k_ = max(1, int(math.hypot(b_[0] - a_[0], b_[1] - a_[1]) / (size / 80)))
        D += [(a_[0] + (b_[0] - a_[0]) * j / k_, a_[1] + (b_[1] - a_[1]) * j / k_) for j in range(k_)]
    P = D
    tip = max(P, key=lambda p: p[1])
    if abs(tip[0] - cx) > 0.22 * w:                                  # the point at the bottom, in the middle
        return False
    low = [p[0] for p in P if p[1] > top + 0.8 * h]
    if low and max(low) - min(low) > 0.55 * w:                       # it gets narrow towards the point
        return False
    mid = [p[1] for p in P if abs(p[0] - cx) < 0.07 * w and p[1] < top + 0.6 * h]
    if not mid or min(mid) < top + 0.07 * h:                         # the dip between the lobes
        return False
    lt = [p[1] for p in P if p[0] < cx - 0.15 * w]; rt = [p[1] for p in P if p[0] > cx + 0.15 * w]
    return bool(lt and rt and min(lt) <= top + 0.15 * h and min(rt) <= top + 0.15 * h)     # two lobes up high


def heart_points(cx, cy, s, n=48, scale_x=1.0):
    """the outline of a heart around (cx, cy), s = half the width (screen: y down)"""
    out = []
    for i in range(n):
        t = 2 * math.pi * i / n
        x = 16 * math.sin(t) ** 3; y = -(13 * math.cos(t) - 5 * math.cos(2 * t) - 2 * math.cos(3 * t) - math.cos(4 * t))
        out.append((cx + x / 16 * s * scale_x, cy + (y + 2.5) / 16 * s))
    return out


class NightVision:
    """Night vision look: the picture brightened and tinted green like an image intensifier (a little grain, dark
    corners); a thermal camera adds glowing outlines of warm bodies and - with the Thermal-90 - their temperature."""
    def __init__(self):
        self.vig = None; self.vig_size = None; self.clahe = cv2.createCLAHE(clipLimit=3.0, tileGridSize=(8, 8))
        self.rng = np.random.default_rng(3)

    def active(self):
        return bool(CFG["nightvision"] or (CFG["nightvision_auto"] and LIGHTS.get("dark")))

    def apply(self, frame):
        try:
            H, W = frame.shape[:2]
            g = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            g = self.clahe.apply(g)
            m = float(g.mean())
            if m < 110:                                        # lift dark scenes (gamma)
                gm = max(0.35, math.log(120.0 / 255.0) / math.log(max(m, 2.0) / 255.0))
                g = (255.0 * (g / 255.0) ** gm).astype(np.uint8)
            if self.vig_size != (W, H):
                yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
                r = np.sqrt(((xx - W / 2) / (W / 2)) ** 2 + ((yy - H / 2) / (H / 2)) ** 2)
                self.vig = np.clip(1.15 - 0.55 * r ** 2, 0.25, 1.0).astype(np.float32); self.vig_size = (W, H)
            noise = self.rng.normal(0, 9, (H // 2 + 1, W // 2 + 1)).astype(np.float32)
            noise = cv2.resize(noise, (W, H), interpolation=cv2.INTER_NEAREST)
            v = np.clip((g.astype(np.float32) + noise) * self.vig, 0, 255)
            out = np.dstack([v * 0.22, v, v * 0.38]).astype(np.uint8)          # B, G, R: phosphor green
            th = THERMAL
            if th is not None and th.frame is not None and time.time() - th.t < 3.0:
                self._thermal(out, th, W, H)
            cv2.putText(out, "NV", (W - 42, 24), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (120, 255, 150), 2, cv2.LINE_AA)
            return out
        except (cv2.error, ValueError):
            return frame

    def _thermal(self, out, th, W, H):
        fr = ThermalCam.crop(th.frame)
        celsius = fr.ndim == 2 and fr.dtype.kind == "f"
        f = fr.astype(np.float32) if celsius else ThermalCam.to_gray8(fr).astype(np.float32)
        f = cv2.resize(f, (W, H), interpolation=cv2.INTER_LINEAR)
        thr = float(np.percentile(f[::4, ::4], 96))
        if celsius:
            thr = max(thr, float(np.median(f[::4, ::4])) + 4.0)          # at least 4 °C warmer than the surroundings
        mask = (f > thr).astype(np.uint8) * 255
        mask = cv2.morphologyEx(mask, cv2.MORPH_OPEN, np.ones((5, 5), np.uint8))
        cnts, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        cnts = sorted((c for c in cnts if cv2.contourArea(c) > W * H * 0.002), key=cv2.contourArea, reverse=True)[:4]
        glow = np.zeros_like(out)
        cv2.drawContours(glow, cnts, -1, (170, 255, 200), 3)
        glow = cv2.GaussianBlur(glow, (0, 0), 3)
        np.maximum(out, glow, out=out)
        cv2.drawContours(out, cnts, -1, (210, 255, 225), 1, cv2.LINE_AA)
        if celsius:
            for c in cnts:
                x, y, w, h = cv2.boundingRect(c)
                t = float(f[y:y + h, x:x + w].max())
                num, F, col = f"{t:.0f}", cv2.FONT_HERSHEY_SIMPLEX, (190, 255, 205)
                (nw, th_), _ = cv2.getTextSize(num, F, 0.55, 2); (cw, _h), _ = cv2.getTextSize("C", F, 0.55, 2)
                tw = nw + 7 + cw
                tx, ty = int(min(max(2, x + w / 2 - tw / 2), W - tw - 4)), int(max(th_ + 4, y - 6))
                cv2.rectangle(out, (tx - 4, ty - th_ - 4), (tx + tw + 4, ty + 4), (20, 60, 25), -1)
                cv2.putText(out, num, (tx, ty), F, 0.55, col, 2, cv2.LINE_AA)
                cv2.circle(out, (tx + nw + 3, ty - th_ + 2), 2, col, 1, cv2.LINE_AA)          # degree sign
                cv2.putText(out, "C", (tx + nw + 7, ty), F, 0.55, col, 2, cv2.LINE_AA)


NIGHTVISION = NightVision()


# ----------------------------------------------------------------------------
# 2.98.13 (Wunsch Daniel): at night the normal camera often sees nobody (too dark, too far for the IR light). The thermal
# camera still sees the warm body. A warm body (ThermalCam.detect: warmer than the scene by thermal_delta, moving unless
# thermal_need_motion is off, in the zones, seen in 3 of 5 pictures) counts as a PERSON when it also
#   - stands upright (taller than wide, as a person),
#   - has the size of a person at its distance (1.7 m tall, 0.2 … 1.3 m wide - from the field of view of the camera),
#   - is warmer than the background but not hot like a fire or an engine (only with a camera that gives °C).
# It then goes into the same person / alarm logic (push, recording, siren, zones of the recording) as «Person (Wärmebild)».
# Option thermal_person (default on) - only at night (or by day too: thermal_person_day). Needs a thermal camera.
# 2.98.22 (Wunsch Daniel: «das Wärmebild soll mitlaufen»): by day too is now the default, so the thermal camera always
# runs along as soon as one is chosen - also with the overlay and the warm alarm off. Older settings are switched once
# (thermal_migrate, called by 040); who switches «… by day too» off again keeps it off.
# real-reh-fusspunkt (31.10.2026, Fehlalarm Daniel): a roe deer or a fox coming straight at the camera at night is narrow and
# looks «upright» in the thermal picture; with the 1.7 m of a person it seemed far away and so of person size -> push «Person».
# Now the distance is estimated a second time from the FOOT POINT (lower edge of the box, flat ground): the camera height
# (simulator: its pole «mast» from the twin info, else FOOT_CAM_H_M) and the tilt of the head (servo; simulator: the real
# head angle head_deg minus its fixed 6° down, main.gd want_tilt) give the distance of the feet, and with it the real height
# of the thing. First round (replaced, see «third round» below): do both distances disagree strongly (FOOT_RATIO_MIN) and is
# the thing clearly lower than a standing person (FOOT_ANIMAL_MAX_H_M), it was an animal. Since the third round this only
# applies to a FLAT warm body - frontal / upright stays a person. Feet near the horizon or cut off at the picture edge: no
# foot estimate, everything as before. Self-test: 417 (foot_selftest, thermal_maybe_selftest).
# Decision Daniel (31.10.2026, third round): «animal» ONLY for a really FLAT warm body, everything upright stays as before:
#   - upright boxes (h/w >= 1.3, thermal_person_check) are persons exactly as before - also a roe deer straight from the
#     front, a child, a crouching person («im Zweifel Person»),
#   - a flat warm body (failed the upright check, before only «warm») becomes «animal» when: it is night / low light, the
#     foot point works (FOOT_RATIO_MIN, FOOT_ANIMAL_MAX_H_M), real height / real width <= FLAT_MAX_ASP, it did not stand
#     up in the last FOOT_HIST_S seconds, and 3 such pictures over >= 1 s (until then «warm» only),
#   - «Person?» (weak_person_feed): a flat box at the ground (w/h > WEAK_FLAT) that the AI of MoveEye calls a person with at
#     least WEAK_AI_MIN (the normal AI threshold stays) AND a movement track or a warm body confirms it -> a person (alarm,
#     «PERSON?»). It wins over «animal»: a warm body under a «Person?» never becomes an animal.
# Code-Prüfung M3 (Daniel 31.10.2026, «im Zweifel Person?»): «animal» only when the AI of MoveEye really looked for weak
# persons in the last WEAK_OK_S seconds (AIDetector.weak_ok_t: own run on the Pi, or the PC helper with the standard model).
# AI off, still loading, or a PC helper that gives no weak boxes: a flat warm body that would be an «animal» becomes
# «PERSON? (THERMAL)» (a person, alarm) - never «no person». Upright warm bodies are persons as before.
# Camera height: CFG «cam_height» («Höhe der Kamera (m)» in «Platz einrichten», 537 / 582, default 1.6 m). Connected to the
# simulator, its pole («Höhe der Kamera», 3D-4.x) has priority (the simulated camera really is that high); the field is for
# the real device.
# ----------------------------------------------------------------------------
for _k, _v in {"thermal_person": True, "thermal_person_day": True, "thermal_mig22": False}.items():
    CFG.setdefault(_k, _v)
    DEFAULTS.setdefault(_k, _v)
TPERS = {"t": 0.0, "seen": 0.0, "n": 0, "animal_seen": 0.0, "animals": 0, "last": None}
# ---- foot point (real-reh-fusspunkt) - the limits and why ----------------------------------------------------------------
FOOT_CAM_H_M = 1.6          # camera height when nothing is known: the simulator's head (main.gd HEAD_H 1.6 m); a camping tripod
                            # is about 1.2 … 1.8 m. Too high a guess makes things look taller (= the safe side, more «person»).
FOOT_MIN_DEP_DEG = 4.0      # the feet must be at least 4° below the horizon. Thermal-90 (MI0802, 80 x 62 px, 90° x 67°,
                            # datasheet Waveshare / Meridian) = about 1.1° per pixel; with ±1° servo play the foot distance is
                            # then good to about ±30 %, enough to tell 1.7 m from 0.9 m (factor 1.9). Above it: as before.
FOOT_RATIO_MIN = 1.5        # «strongly different»: the 1.7 m estimate is at least 1.5 x the foot distance (a person stays near
                            # 1.0; ±30 % error of height / tilt keeps a real person below 1.5)
FOOT_ANIMAL_MAX_H_M = 1.1   # «clearly lower than a person»: roe deer shoulder height 0.6 … 0.9 m (head up to about 1.1 m), fox
                            # 0.35 … 0.4 m (about 0.5 m with the head) - Wildtier Schweiz / Hespeler «Rehwild heute»; standing
                            # adults are 1.45 m and taller. Small children and a crouching person are lower too - they stay
                            # persons: upright (thermal_person_check) or not flat (FLAT_MAX_ASP).
FLAT_MAX_ASP = 0.8          # «really flat» (Daniel: wider than high): real height / real width from the side. Roe deer: shoulder
                            # 0.6 … 0.9 m, head-body 0.95 … 1.35 m (Wildtier Schweiz) -> 0.5 … 0.8 (head held high up to ~0.9:
                            # then «warm», not animal); fox: shoulder 0.35 … 0.4 m, head-body 0.6 … 0.9 m (+ tail 0.35 … 0.45)
                            # -> 0.3 … 0.6. A crouching person (1.0 / 0.55 m = 1.8) and any child standing (> 3) are far above.
WEAK_AI_MIN = 0.15          # «Person?»: the raw person score of the AI (crawling figures of the simulator reach 0.18 at most,
                            # REAL_KRIECHENDE.md; the normal threshold ai_conf stays for everything else)
WEAK_FLAT = 1.5             # «flat box at the ground»: AI box width / height above 1.5 (crawling / lying, a standing person ~0.4)
WEAK_AGE_S = 2.5            # the AI runs only now and then: its weak boxes count for 2.5 s
WEAK_OK_S = 6.0             # M3: the AI looked for weak persons in the last 6 s (it runs every 0.3 … ~5 s: hot Pi, battery saver)
FOOT_HIST_S = 4.0           # «does not stand up over the last pictures»: what was seen of it in the last 4 s
FOOT_NEED_N, FOOT_NEED_S = 3, 1.0   # an animal needs 3 animal-like pictures over at least 1 s (the thermal camera: 3 of 5 anyway)
FOOT = {"h": None, "t": 0.0, "busy": False, "hist": deque(maxlen=200)}
# ---- real-erk-e1 (Erkennungstest: a car on 20 m gave a push «Person (Wärmebild)» by day) - the limits and why --------------
# A moving car in the thermal picture: the movement mask cuts its hot parts (bonnet, grille, tyres, exhaust) into narrow
# pieces that look «upright». Now a warm body is NO thermal person when
#   - it is followed over the thermal pictures (TVEH chains) and as a 1.7 m person it would run faster than TV_PERSON_MAX_MS, or
#   - it is a wide (real width / height >= TV_WIDE), very warm body that drives faster than TV_CAR_MS (as a 1.5 m high car),
#     and the pieces near it (same height band) for TV_HOLD_S,
#   - the normal camera / the AI sees a vehicle or an animal on it (418 fixp_veto: vehicle track, car / truck …, animal of
#     the AI or an animal track = «Tier vor Person»).
# Only while the head stands still (a turning head makes everything «drive»).
TV_PERSON_MAX_MS = 10.0     # m/s: a sprinter reaches 9 - 10, a person running away 4 - 6; a half hidden person (only the upper
                            # half warm: 2 x too far as 1.7 m) running 5 m/s stays below. A car piece at 20 m (0.6 m tyre seen as
                            # 1.7 m = 57 m away) at 30 km/h is about 23 m/s.
TV_WIDE = 1.6               # «breit»: a car from the side 4.5 x 1.5 m = 3; a person, also two side by side walking, is below
TV_CAR_MS = 4.0             # m/s (14 km/h) for a wide body seen as 1.5 m high: faster than walking / jogging persons in a group
TV_HOT_C = 8.0              # «sehr warm» with a camera in °C: at least 8 °C over the scene (a body 3 - 6 °C through clothes);
                            # without °C (8-bit picture) only the shape and the speed count
TV_HOLD_S = 2.0
TVEH = {"chains": [], "veh": [], "ts": 0.0}
for _k, _v in {"cam_height": FOOT_CAM_H_M}.items():
    CFG.setdefault(_k, _v)
    DEFAULTS.setdefault(_k, _v)


def thermal_migrate(cfg_in):
    """once per settings file: the thermal camera runs along by day too (2.98.22)"""
    if not isinstance(cfg_in, dict) or cfg_in.get("thermal_mig22"):
        return []
    CFG["thermal_mig22"] = True
    if cfg_in.get("thermal_person_day") is False:
        CFG["thermal_person_day"] = True
        return ["thermal camera runs along by day too"]
    return []


def thermal_person_active():
    """thermal persons are looked for now: the option is on, a thermal camera is chosen, and it is night (or by day too)"""
    if not CFG.get("thermal_person") or not CFG.get("thermal_source") or not CFG.get("detection_on"):
        return False
    if CFG.get("thermal_person_day") or STATE.get("fog"):
        return True                                       # 411: in fog the camera sees little - the thermal camera by day too
    try:
        return bool(is_dark() or STATE.get("lowlight"))
    except Exception:
        return bool(STATE.get("lowlight"))


def _thermal_temps(box):
    """(warm body, background) in °C when the thermal camera gives temperatures (float picture), else None"""
    th = THERMAL
    fr = th.frame if th is not None else None
    if fr is None or fr.dtype == np.uint8:
        return None
    try:
        f = th.crop(fr).astype(np.float32)
        if f.ndim == 3:
            f = f.mean(axis=2)
        H, W = f.shape[:2]
        x, y, w, h = box
        x0, y0 = max(0, int(x * W)), max(0, int(y * H))
        x1, y1 = min(W, int(math.ceil((x + w) * W))), min(H, int(math.ceil((y + h) * H)))
        reg = f[y0:y1, x0:x1]
        if reg.size < 2:
            return None
        return float(np.percentile(reg, 80)), float(np.median(f))
    except (ValueError, TypeError, cv2.error):
        return None


def cam_height_cfg():
    """the field «Höhe der Kamera (m)» of «Platz einrichten» (0.2 … 10 m, else the default 1.6 m)"""
    try:
        v = float(CFG.get("cam_height") or FOOT_CAM_H_M)
    except (TypeError, ValueError):
        return FOOT_CAM_H_M
    return v if 0.2 <= v <= 10.0 else FOOT_CAM_H_M


def cam_height_info():
    """for the pages: {"m": field, "sim": pole of the simulator or None, "used": what the foot point uses}"""
    h = _foot_cam_h()
    sim = FOOT["h"] if bool(CFG.get("sim_on")) and str(CFG.get("source") or "").startswith("sim:") else None
    return {"m": round(cam_height_cfg(), 2), "sim": round(sim, 2) if sim else None, "used": round(h, 2)}


def _foot_cam_h():
    """height of the camera above the ground in m: connected to the simulator its pole (twin info «mast», fetched in the
    background at most every 60 s - never in the camera loop) has priority, else the field «Höhe der Kamera» (cam_height)"""
    sim = bool(CFG.get("sim_on")) and str(CFG.get("source") or "").startswith("sim:")
    if not sim:
        return cam_height_cfg()
    now = time.time()
    if now - FOOT["t"] > 60.0 and not FOOT["busy"]:
        FOOT["t"] = now; FOOT["busy"] = True

        def _get():
            try:
                m = (sim_twin_info() or {}).get("mast")
                FOOT["h"] = float(m) if m is not None and 0.2 <= float(m) <= 10.0 else None
            except Exception:
                pass
            finally:
                FOOT["busy"] = False
        threading.Thread(target=_get, daemon=True).start()
    return FOOT["h"] or cam_height_cfg()


def _foot_pitch_deg():
    """where the main camera looks up (+) / down (-) in degrees: the wide camera of the simulator its mount (tilt_deg, + the
    head with tilt_follow), the head camera the servo; in the simulator the real head (head_deg) and its fixed 6° down"""
    src = str(CFG.get("source") or "")
    sim = bool(CFG.get("sim_on")) and src.startswith("sim:")
    head = servo_pos_deg()[1]
    if sim and isinstance(SIM.get("head"), list) and len(SIM["head"]) >= 2:
        try:
            head = float(SIM["head"][1])
        except (TypeError, ValueError):
            pass
    if sim and src != "sim:0":
        cam = next((c for c in (SIM.get("info") or {}).get("cameras") or [] if str(c.get("id")) == src[4:]), None)
        if cam and cam.get("tilt_deg") is not None:
            return float(cam["tilt_deg"]) + ((head - 6.0) if cam.get("tilt_follow") else 0.0)
    return head - 6.0 if sim else head


def foot_estimate(box, cam_h=None, pitch=None, vf=None):
    """(distance of the feet in m, real height in m) of a thing standing on flat ground, from the lower / upper edge of its
    box (x, y, w, h 0..1 of the main picture) - or None when the feet are cut off or too near the horizon"""
    x, y, w, h = box
    if h <= 0 or y + h > 0.985 or y < 0.01:
        return None                                           # cut off at the picture edge: feet / head unknown
    cam_h = _foot_cam_h() if cam_h is None else float(cam_h)
    pitch = _foot_pitch_deg() if pitch is None else float(pitch)
    vf = erk_vfov() if vf is None else float(vf)
    k = math.tan(math.radians(vf) / 2.0)
    dep_b = math.atan((y + h - 0.5) * 2.0 * k) - math.radians(pitch)   # how far below the horizon the feet are
    if dep_b < math.radians(FOOT_MIN_DEP_DEG):
        return None
    dist = cam_h / math.tan(dep_b)
    dep_t = math.atan((y - 0.5) * 2.0 * k) - math.radians(pitch)
    return dist, cam_h - dist * math.tan(dep_t)


def _foot_night():
    try:
        return bool(is_dark() or STATE.get("lowlight"))
    except Exception:
        return bool(STATE.get("lowlight"))


def foot_shape(box, fe):
    """real height / real width of a box (both from the foot distance) - small = flat like an animal from the side"""
    hf = cam_fov()[0]
    width_m = box[2] * 2.0 * fe[0] * math.tan(math.radians(hf) / 2.0)
    return max(0.0, fe[1]) / max(0.05, width_m)


def foot_decide(box, d, fe, night, t0, hist, maybe=False, vf=None):
    """the decision of thermal_classify, without the camera (self-test 417): -> ("person", d) / ("animal", foot m, height m,
    distance at 1.7 m) / ("wait", None) / None (only warm, as before). d = thermal_person_check (upright person) or None;
    maybe = a «Person?» of the AI lies on it. hist = deque of the last observations {t, cx, fy, low, person}."""
    x, y, w, h = box
    cx, fy = x + w / 2.0, y + h
    same = [o for o in hist if t0 - o["t"] <= FOOT_HIST_S and abs(o["cx"] - cx) < 0.12 and abs(o["fy"] - fy) < 0.15]
    if d is not None:                                           # upright: a person, as before
        hist.append({"t": t0, "cx": cx, "fy": fy, "low": False, "person": True})
        return ("person", d)
    low = False
    if fe is not None and night and not maybe:
        vf = erk_vfov() if vf is None else vf
        d_size = PERSON_H_M / (2.0 * max(1e-3, h) * math.tan(math.radians(vf) / 2.0))
        low = (d_size / max(0.1, fe[0]) >= FOOT_RATIO_MIN and fe[1] <= FOOT_ANIMAL_MAX_H_M and foot_shape(box, fe) <= FLAT_MAX_ASP)
    stood = any(o["person"] for o in same)                     # it stood up in the last seconds: no animal
    hist.append({"t": t0, "cx": cx, "fy": fy, "low": low, "person": False})
    if not low or stood:
        return None
    lows = [o for o in same if o["low"]] + [hist[-1]]
    if len(lows) >= FOOT_NEED_N and t0 - min(o["t"] for o in lows) >= FOOT_NEED_S:
        vf = erk_vfov() if vf is None else vf
        return ("animal", fe[0], max(0.0, fe[1]), PERSON_H_M / (2.0 * max(1e-3, h) * math.tan(math.radians(vf) / 2.0)))
    return ("wait", None)


def thermal_classify(box, t0=None, maybe=False):
    """-> ("person", distance m) / ("animal", …) / ("wait", None) / None for a warm body (x, y, w, h 0..1 of the main picture):
    upright as before (thermal_person_check), flat at night with the foot point = animal (real-reh-fusspunkt)"""
    d = thermal_person_check(box)
    fe = None
    if d is None:
        try:
            fe = foot_estimate(box)
        except Exception:
            fe = None
    TPERS["last"] = {"d_size": round(d, 2) if d else None, "d_foot": round(fe[0], 2) if fe else None, "h_foot": round(fe[1], 2) if fe else None}
    return foot_decide(box, d, fe, _foot_night(), time.time() if t0 is None else t0, FOOT["hist"], maybe)


def _ov(a, b):
    """two boxes (x, y, w, h, same units) overlap: intersection / smaller area"""
    ix = max(0.0, min(a[0] + a[2], b[0] + b[2]) - max(a[0], b[0])); iy = max(0.0, min(a[1] + a[3], b[1] + b[3]) - max(a[1], b[1]))
    return ix * iy / max(1e-9, min(a[2] * a[3], b[2] * b[3]))


def weak_person_check(ab, tracks_n, warm_n, fe):
    """«Person?» for one weak AI box ab = (x, y, w, h, conf) 0..1: flat, at the ground, confirmed by movement or warmth"""
    x, y, w, h, cf = ab
    if cf < WEAK_AI_MIN or h <= 0 or (w / h) * (1.0 / max(1e-3, float(ThermalCam.main_aspect))) <= WEAK_FLAT:
        return False                                            # (w / h in real pixels of the picture)
    if fe is not None and fe[1] > FOOT_ANIMAL_MAX_H_M + 0.3:
        return False                                            # not at the ground (a flat thing high up)
    return any(_ov(ab[:4], b) > 0.3 for b in list(tracks_n) + list(warm_n))


def weak_person_feed(ai, tracks, warm_boxes, person_boxes, present, frame, pw, ph, W, H, t0, veto=()):
    """410, when nobody was found: the weak person boxes of the AI (180, below ai_conf) that are flat at the ground and confirmed
    by a movement track or the thermal picture become «PERSON?» (person boxes = the normal person / alarm logic).
    Returns the «Person?» boxes 0..1 (a warm body under one never becomes an animal).
    real-erk-e1: not where the AI sees an animal (or an animal track is) - «Tier vor Person» (418 fixp_veto)."""
    wk = getattr(ai, "weak", None) or []
    STATE["person_maybe"] = 0                                   # /api/state: how many «Person?» in this picture
    if not wk or t0 - float(getattr(ai, "weak_t", 0.0)) > WEAK_AGE_S:
        return []
    ThermalCam.main_aspect = H / float(W)
    tn = [(t.box[0] / pw, t.box[1] / ph, t.box[2] / pw, t.box[3] / ph) for t in tracks if getattr(t, "box", None)]
    out = []
    for ab in wk:
        if not zone_box_ok((ab[0] * pw, ab[1] * ph, ab[2] * pw, ab[3] * ph), pw, ph, "person"):
            continue                                            # Code-Prüfung K1: zones by kind, like the normal AI boxes (410)
        try:
            fe = foot_estimate(ab[:4])
        except Exception:
            fe = None
        if weak_person_check(ab, tn, warm_boxes or [], fe) and not any(_ov(ab[:4], v[:4]) > 0.3 for v in veto if v[4] == "animal"):
            out.append(ab)
    for bx, by, bw, bh, cf in out:
        person_boxes.append((int(bx * pw), int(by * ph), max(1, int(bw * pw)), max(1, int(bh * ph))))
        p1 = (int(bx * W), int(by * H)); p2 = (int((bx + bw) * W), int((by + bh) * H))
        cv2.rectangle(frame, p1, p2, (60, 0, 255), 3)
        cv2.putText(frame, f"PERSON? (AI {cf:.2f})", (p1[0], max(18, p1[1] - 6)), cv2.FONT_HERSHEY_SIMPLEX, 0.55, (60, 0, 255), 2)
    STATE["person_maybe"] = len(out)
    if out:
        present.add("person")
        if t0 - TPERS.get("weak_seen", 0.0) > 10.0:
            TPERS["weak_n"] = TPERS.get("weak_n", 0) + 1
            log_event("person", f"Person? lying / crawling - AI {max(o[4] for o in out):.2f} (below the normal threshold) + "
                                f"movement / warmth at the same place")
        TPERS["weak_seen"] = t0
    return [o[:4] for o in out]


def thermal_person_check(box):
    """-> distance in m when the warm body (x, y, w, h 0..1 of the main picture) looks like a person by shape, size at 1.7 m and
    temperature, else None (the foot point comes after it: thermal_classify)"""
    x, y, w, h = box
    if w <= 0 or h <= 0:
        return None
    asp = (h / w) * float(ThermalCam.main_aspect)             # height / width in real pixels of the main picture
    if not (1.3 <= asp <= 5.5):
        return None                                           # lying, round or a long thin thing: no standing person
    hf, vf = cam_fov()
    vf = erk_vfov()
    d = PERSON_H_M / (2.0 * h * math.tan(math.radians(vf) / 2.0))
    if not (1.0 <= d <= 80.0):
        return None
    width_m = w * 2.0 * d * math.tan(math.radians(hf) / 2.0)
    if not (0.2 <= width_m <= 1.3):
        return None                                           # too broad for a person at that distance (cow, car bonnet)
    tt = _thermal_temps(box)
    if tt is not None:
        body, bg = tt
        if body - bg < 3.0 or body > 45.0:
            return None                                       # hardly warmer than the ground / hot like a fire or an engine
    return d


def _tv_speed(ch, now):
    """(picture widths per second, mean height, mean width) of a chain over its last 2 s - or None (too short)"""
    pts = [p for p in ch["pts"] if now - p[0] <= 2.0]
    if len(pts) < 3 or pts[-1][0] - pts[0][0] < 0.4:
        return None
    return ((pts[-1][1] - pts[0][1]) / (pts[-1][0] - pts[0][0]), sum(p[4] for p in pts) / len(pts), sum(p[3] for p in pts) / len(pts))


def thermal_vehicle_step(boxes, ts, hf, vf, asp, temps=None):
    """follow the warm bodies over the thermal pictures (ts = time of the thermal picture) -> the boxes that are a vehicle.
    asp = picture height / width (main picture), temps(box) -> (body, scene) °C or None. Without the camera (self-test)."""
    if ts != TVEH["ts"]:
        TVEH["ts"] = ts
        for b in boxes:
            cx, cy = b[0] + b[2] / 2.0, b[1] + b[3] / 2.0
            near = [c for c in TVEH["chains"] if ts - c["pts"][-1][0] <= 1.0 and abs(c["pts"][-1][2] - cy) < 0.15
                    and abs(c["pts"][-1][1] - cx) < 0.25 + b[2]]
            ch = min(near, key=lambda c: abs(c["pts"][-1][1] - cx), default=None) if near else None
            if ch is None or ch["pts"][-1][0] == ts:
                ch = {"pts": deque(maxlen=20), "veh": 0.0}; TVEH["chains"].append(ch)
            ch["pts"].append((ts, cx, cy, b[2], b[3]))
            sp = _tv_speed(ch, ts)
            if sp is None:
                continue
            vx, mh, mw = sp
            k = 2.0 * math.tan(math.radians(hf) / 2.0)
            v_person = abs(vx) * k * PERSON_H_M / (2.0 * max(1e-3, mh) * math.tan(math.radians(vf) / 2.0))
            v_car = abs(vx) * k * 1.5 / (2.0 * max(1e-3, mh) * math.tan(math.radians(vf) / 2.0))
            wide = (mw / max(1e-3, mh)) / max(1e-3, asp) >= TV_WIDE
            tt = temps(b) if temps else None
            hot = tt is None or tt[0] - tt[1] >= TV_HOT_C
            if (mh / max(1e-3, mw)) * asp >= 1.0 and v_person >= TV_PERSON_MAX_MS:
                ch["veh"] = ts                                  # upright piece far too fast for a person
            elif wide and hot and v_car >= TV_CAR_MS:
                ch["veh"] = ts; TVEH["veh"].append((ts, cx, cy))    # a wide hot body that drives: the pieces near it too
        TVEH["chains"] = [c for c in TVEH["chains"] if ts - c["pts"][-1][0] <= 1.5][-8:]
        TVEH["veh"] = [v for v in TVEH["veh"] if ts - v[0] <= TV_HOLD_S]
    out = []
    for b in boxes:
        cx, cy = b[0] + b[2] / 2.0, b[1] + b[3] / 2.0
        ch = next((c for c in TVEH["chains"] if c["pts"][-1][0] == TVEH["ts"] and abs(c["pts"][-1][1] - cx) < 1e-6 and abs(c["pts"][-1][2] - cy) < 1e-6), None)
        if (ch and TVEH["ts"] - ch["veh"] <= TV_HOLD_S) or any(abs(v[2] - cy) < 0.15 and abs(v[1] - cx) < 0.25 for v in TVEH["veh"]):
            out.append(b)
    return out


def thermal_ai_checked(t0, ai=None):
    """M3: the AI looked for weak («Person?») persons in the last WEAK_OK_S seconds - only then a flat warm body may be an animal"""
    if ai is None:
        w = WATCH_REF.get("w")
        ai = getattr(w, "ai", None) if w is not None else None
    if ai is None or not CFG.get("ai_enabled") or DEMO.get("on"):
        return False
    return 0.0 <= t0 - float(getattr(ai, "weak_ok_t", 0.0) or 0.0) <= WEAK_OK_S


def thermal_person_feed(warm_boxes, person_boxes, present, frame, pw, ph, W, H, t0, maybe_boxes=(), veto=(), ai=None):
    """called by the camera loop (410) when the normal camera found nobody: the warm bodies that are persons become person
    boxes (in the working picture), drawn as «PERSON (THERMAL)». Returns the warm bodies that stay «warm».
    real-erk-e1: a vehicle (fast / wide and hot in the thermal picture, or the camera / AI sees one there) or an animal of the
    AI on it is no person (veto from 418 fixp_veto)."""
    rest = []
    found = []
    ThermalCam.main_aspect = H / float(W)                      # (the overlay sets it too - only when the thermal picture is shown)
    animals = []
    vehicles = []
    try:
        if fixp_head_still(t0) >= 1.5:
            hf, vf = cam_fov()
            vehicles = thermal_vehicle_step(warm_boxes, float(getattr(THERMAL, "t", t0) or t0), hf, erk_vfov(), ThermalCam.main_aspect, _thermal_temps)
        else:
            TVEH["chains"] = []; TVEH["veh"] = []
    except Exception:
        vehicles = []
    unsure = []
    for b in warm_boxes:
        if b in vehicles or any(_ov(b, v[:4]) > 0.3 for v in veto if v[4] == "vehicle"):
            rest.append(b)                                    # a vehicle: only warm (the warm alarm, if on, as before)
            p1 = (int(b[0] * W), int(b[1] * H)); p2 = (int((b[0] + b[2]) * W), int((b[1] + b[3]) * H))
            cv2.rectangle(frame, p1, p2, (200, 200, 200), 2)
            cv2.putText(frame, "VEHICLE (THERMAL)", (p1[0], max(18, p1[1] - 6)), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (200, 200, 200), 2)
            if t0 - TPERS.get("veh_seen", 0.0) > 10.0:
                log_event("ai", "Vehicle in the thermal picture (fast / wide and hot, or the camera sees one) - no person")
            TPERS["veh_seen"] = t0
            continue
        if any(_ov(b, v[:4]) > 0.3 for v in veto if v[4] == "animal"):
            rest.append(b); present.add("animal"); continue   # Tier vor Person: the AI sees an animal there
        c = thermal_classify(b, t0, any(_ov(b, m) > 0.3 for m in maybe_boxes))
        if c is None or c[0] == "wait":
            rest.append(b); continue                          # «wait»: maybe an animal - a few more pictures (only warm meanwhile)
        if c[0] == "animal":
            if not thermal_ai_checked(t0, ai):                # M3: nobody checked for a crawling person: «Person?», not «animal»
                unsure.append((b, c[1])); continue
            animals.append((b, c[1], c[2], c[3])); rest.append(b); continue   # still a warm body (the warm alarm, if on, as for any animal)
        found.append((b, c[1]))
    if unsure:
        for (bx, by, bw, bh), d_ in unsure:
            person_boxes.append((int(bx * pw), int(by * ph), max(1, int(bw * pw)), max(1, int(bh * ph))))
            p1 = (int(bx * W), int(by * H)); p2 = (int((bx + bw) * W), int((by + bh) * H))
            cv2.rectangle(frame, p1, p2, (60, 0, 255), 3)
            cv2.putText(frame, f"PERSON? (THERMAL) ~{dist_round(d_)}m", (p1[0], max(18, p1[1] - 6)), cv2.FONT_HERSHEY_SIMPLEX, 0.55, (60, 0, 255), 2)
        present.add("person")
        STATE["person_maybe"] = int(STATE.get("person_maybe") or 0) + len(unsure)
        if t0 - TPERS.get("weak_seen", 0.0) > 10.0:
            TPERS["weak_n"] = TPERS.get("weak_n", 0) + 1
            log_event("person", f"Person? in the thermal picture: flat warm body, about {dist_round(min(u[1] for u in unsure))} m - "
                                "the AI could not check it (AI off / PC helper) - in doubt a person")
        TPERS["weak_seen"] = t0
    if animals:
        for (bx, by, bw, bh), d_, h_, _ds in animals:
            p1 = (int(bx * W), int(by * H)); p2 = (int((bx + bw) * W), int((by + bh) * H))
            cv2.rectangle(frame, p1, p2, (0, 200, 255), 2)
            cv2.putText(frame, f"ANIMAL (THERMAL) ~{dist_round(d_)}m {h_:.1f}m high", (p1[0], max(18, p1[1] - 6)), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0, 200, 255), 2)
        present.add("animal")
        if t0 - TPERS["animal_seen"] > 10.0:                  # a new appearance (not every picture)
            TPERS["animals"] += 1
            a_ = min(animals, key=lambda a: a[1])
            try:                                              # for tuning FLAT_MAX_ASP with real nights (shape, box)
                shp = f", shape h/w {foot_shape(a_[0], (a_[1], a_[2])):.2f}, box {tuple(round(float(q), 3) for q in a_[0])}"
            except Exception:
                shp = ""
            log_event("ai", f"Animal in the thermal picture, about {dist_round(a_[1])} m, about {a_[2]:.1f} m high - no person "
                            f"(foot point; as a 1.7 m person it would be {dist_round(a_[3])} m away{shp})")
        TPERS["animal_seen"] = t0
    if not found:
        return rest
    for (bx, by, bw, bh), d in found:
        pb = (int(bx * pw), int(by * ph), max(1, int(bw * pw)), max(1, int(bh * ph)))
        person_boxes.append(pb)
        p1 = (int(bx * W), int(by * H)); p2 = (int((bx + bw) * W), int((by + bh) * H))
        cv2.rectangle(frame, p1, p2, (60, 0, 255), 3)
        cv2.putText(frame, f"PERSON (THERMAL) ~{dist_round(d)}m", (p1[0], max(18, p1[1] - 6)), cv2.FONT_HERSHEY_SIMPLEX, 0.55, (60, 0, 255), 2)
        try:
            walktest_hit(bx + bw / 2.0, by + bh, d, "thermal", "th", t0)
        except Exception:
            pass
    present.add("person")
    best = min(found, key=lambda x: x[1])
    erk_note_thermal(best[1], t0)
    if t0 - TPERS["seen"] > 10.0:                             # a new appearance (not every picture)
        STATE["detections_total"] = STATE.get("detections_total", 0) + 1
        log_event("person", f"Person in the thermal picture, about {dist_round(best[1])} m (the normal camera sees nobody)")
    TPERS["seen"] = t0; TPERS["n"] = len(found)
    return rest
# ----------------------------------------------------------------------------
# Audio: microphone (noise alarm, live listening in the browser, sound in the recordings) + loudspeaker of the Pi (siren)
#   One "arecord" process reads the microphone (16 kHz mono) and feeds everything else: a USB microphone can only be
#   opened by one program at a time. The loudspeaker plays generated sounds (siren, two-tone, beeps, horn) or own sound
#   files from <settings folder>/sounds via "aplay". While the Pi plays a sound, the noise alarm does not listen.
# ----------------------------------------------------------------------------
AUDIO_RATE = 16000                     # microphone: 16 kHz mono 16 bit = 32 kB/s (fine over a phone hotspot)
AUDIO_CHUNK = AUDIO_RATE // 10         # 0.1 s
OUT_RATE = 22050                       # loudspeaker
AUDIO_DEV_RE = re.compile(r"^(default|(plug)?hw:CARD=[A-Za-z0-9_\-]{1,40},DEV=\d{1,2})$")
AUDIO_DEVS = {"in": [], "out": [], "time": 0.0, "err": ""}
SOUND_KINDS = ("siren", "two-tone", "beeps", "horn", "whistle", "bangs")
SIREN_ON = ("off", "person", "alarm", "all")
SOUND_EXT = (".wav", ".mp3", ".ogg", ".flac", ".m4a")
SOUND_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9 _.\-()]{0,80}$")
_ALSA_RE = re.compile(r"^card (\d+): (\S+) \[(.*?)\], device (\d+): (.*?) \[(.*?)\]")
AUDIO = None                           # AudioMonitor, created together with the camera loop


def sounds_dir():
    return os.path.join(DATA_DIR, "sounds")


def own_sounds():
    try:
        return sorted(f for f in os.listdir(sounds_dir()) if f.lower().endswith(SOUND_EXT) and SOUND_NAME_RE.match(f))[:40]
    except OSError:
        return []


def _alsa_scan(cmd):
    """Sound cards from "arecord -l" / "aplay -l". The id uses the card NAME (plughw:CARD=Device,DEV=0): the number of a USB
    card can change after a reboot, the name stays. plughw converts the sample rate (many USB microphones only do 48 kHz)."""
    if not shutil.which(cmd):
        return [], f"{cmd} is missing (sudo apt install alsa-utils)"
    rc, out, err = _run([cmd, "-l"], timeout=10)
    items = []
    for line in (out or "").splitlines():
        m = _ALSA_RE.match(line.strip())
        if not m:
            continue
        _n, cid, cname, dev, _dn, dname = m.groups()
        dev_id = f"plughw:CARD={cid},DEV={dev}"
        if not AUDIO_DEV_RE.match(dev_id) or any(i["id"] == dev_id for i in items):
            continue
        label = cname if (not dname or dname == cname or dname.startswith("USB Audio")) else f"{cname} - {dname}"
        items.append({"id": dev_id, "name": label})
    return items, ("" if rc == 0 or items else (err or "")[:200])


def audio_scan():
    """Look for microphones and loudspeakers (also called from the page: "Search devices")."""
    ins, e1 = _alsa_scan("arecord")
    outs, e2 = _alsa_scan("aplay")
    AUDIO_DEVS.update({"in": ins, "out": outs, "time": time.time(), "err": e1 or e2})
    return ins, outs


def audio_choice_pairs(kind):
    """[(value, label)] for the microphone / loudspeaker selection. A saved device that is not plugged in stays selectable."""
    pairs = [("", "– " + tr("none") + " –"), ("default", tr("System default"))]
    pairs += [(d["id"], d["name"]) for d in AUDIO_DEVS[kind]]
    if kind == "out":
        pairs += [("bt:" + d["mac"], "Bluetooth: " + d["name"]) for d in BT["devices"] if d["paired"] and d["audio"]]
    cur = CFG["audio_in" if kind == "in" else "audio_out"]
    if cur and cur not in [p[0] for p in pairs]:
        pairs.append((cur, ("Bluetooth " + cur[3:]) if cur.startswith("bt:") else cur.replace("plughw:CARD=", "").split(",")[0] + " (" + tr("not connected") + ")"))
    return pairs


def sound_choice_pairs():
    names = {"siren": "Siren (rising and falling)", "two-tone": "Two-tone horn", "beeps": "Fast beeps", "horn": "Horn",
             "whistle": "High whistle (animals)", "bangs": "Bangs / claps (animals)"}
    return [(k, tr(names[k])) for k in SOUND_KINDS] + [("file:" + f, "♪ " + f) for f in own_sounds()]


def _db(rms):
    return round(20.0 * math.log10(max(rms, 1.0) / 32768.0), 1)


# ----------------------------------------------------------------------------
# Clap switch and «Bless you!»: listens to the microphone (the same stream as the noise alarm).
#   Clap switch: 2 / 3 / 4 claps in a row (¼ to ¾ s apart) -> an action (relay, light, photo, recording, arm / disarm).
#     A clap = the level jumps up within 20 ms and is down again after 150 ms (speech, music, doors last longer).
#   Bless you: after a loud sound, a small sound recognition model (YAMNet, Google, about 4 MB, ~500 kinds of sounds)
#     checks whether it was a sneeze; then the loudspeaker says «Gesundheit!» (or plays an own recording).
# ----------------------------------------------------------------------------
SOUNDEV = {"claps": [], "last_clap": 0.0, "seq_n": 0, "last_n": 0, "last_n_t": 0.0, "last_act": "", "last_act_t": 0.0,
           "sneeze_t": 0.0, "sneeze_score": None, "sneeze_last": 0.0, "model": "off", "model_msg": "", "install": "", "checks": 0}
YAMNET_URLS = ("https://storage.googleapis.com/download.tensorflow.org/models/tflite/task_library/audio_classification/android/"
               "lite-model_yamnet_classification_tflite_1.tflite",
               "https://tfhub.dev/google/lite-model/yamnet/classification/tflite/1?lite-format=tflite")
YAMNET_SNEEZE = 44                       # index of «Sneeze» in the 521 YAMNet classes (when the label list is missing)
_SNEEZE_DAYS = {"loaded": False, "days": {}}


def clap_act_pairs():
    out = [("none", tr("nothing"))]
    for i, r in enumerate(RELAYS):
        out.append((f"relay:{i}", trf("{name} on / off", name=r.get("name") or f"Relay {i + 1}")))
    out += [("light_white", tr("White light on / off")), ("light_ir", tr("Infrared light on / off")), ("photo", tr("Take a photo")),
            ("rec", tr("Record (10 min) / stop")), ("arm", tr("Arm / disarm (with a beep)"))]
    return out


def sneeze_reply_pairs():
    return [("tts", tr("Speak the words below"))] + [("file:" + f, "🎵 " + f) for f in own_sounds()]


def sev_beep(n=1, ok=True):
    """Short beep(s) as an answer: n beeps rising (done) or one low beep (only counted / not allowed)."""
    if not CFG.get("clap_beep") or not out_selected():
        return
    sound_play("beep%d" % max(1, min(4, n)) if ok else "beeplow", 0.18 * max(1, n) + 0.1, CFG.get("clap_volume", 60), reason="test")


def clap_action(n):
    """n claps in a row: what was chosen for it."""
    act = str(CFG.get(f"clap_{n}") or "none")
    SOUNDEV.update(last_n=n, last_n_t=time.time())
    if wake_clap_listens():                              # 2.98.9: the wake-up alarm rings - clapping = snooze
        SOUNDEV.update(last_act=tr("Snooze"), last_act_t=time.time()); wake_snooze(f"{n}× clapped"); return
    if act == "none":
        SOUNDEV["last_act"] = ""; return
    label = dict(clap_act_pairs()).get(act, act)
    if CFG.get("clap_practice"):
        SOUNDEV.update(last_act=tr("practice") + ": " + label, last_act_t=time.time()); sev_beep(n); return
    if CFG.get("clap_disarmed") and CFG["armed"] and act != "arm":
        SOUNDEV.update(last_act=tr("not while armed"), last_act_t=time.time()); sev_beep(1, ok=False); return
    w = WATCH_REF.get("w")
    done = ""
    try:
        if act.startswith("relay:"):
            i = int(act[6:])
            if 0 <= i < len(RELAYS):
                new = "off" if RELAYS[i].get("mode") == "on" else "on"
                ok, _e = relay_update(i, "mode", new)
                if ok:
                    save_settings(); done = f"{RELAYS[i].get('name') or 'Relay %d' % (i + 1)} → {tr(new)}"
        elif act in ("light_white", "light_ir"):
            nm = act[6:]; new = "off" if CFG["light_" + nm] == "on" else "on"
            ok, _e = light_set(nm, new)
            if ok:
                done = f"{tr('White light') if nm == 'white' else tr('Infrared light')} → {tr(new)}"
        elif act == "photo":
            nm = quick_photo(getattr(w, "frame_out", None)) if w is not None else None
            done = tr("Photo") + f" {nm}" if nm else ""
        elif act == "rec":
            done = tr("Recording") + " → " + tr("on" if quick_rec() else "off")
        elif act == "arm":
            if is_armed() or CFG["armed"]:
                if CFG.get("protect_pin"):                  # 2.97.0: with a PIN, clapping only arms (anyone can clap)
                    done = ""; log_event("sys", "Clap switch: disarming needs the PIN")
                else:
                    disarm(); done = tr("disarmed")
            else:
                arm(); done = tr("armed (countdown)")
    except Exception as e:
        done = ""; log_event("sys", f"Clap switch: {e}"[:160])
    SOUNDEV.update(last_act=done or tr("not possible"), last_act_t=time.time())
    if done:
        log_event("sys", f"Clap switch ({n}×): {done}")
        sev_beep(n)
    else:
        sev_beep(1, ok=False)


class SoundEvents:
    """Fed with every 0.1 s piece of the microphone (16 kHz, 16 bit). Looks at 10 ms steps."""
    FR = AUDIO_RATE // 100                                  # 10 ms

    def __init__(self):
        self.hist = deque(maxlen=60)                         # (t, dB) of the last 0.6 s in 10 ms steps
        self.bg = None
        self.pending = []                                    # onsets waiting for the check «short?» (t, peak dB)
        self.pcm = deque(maxlen=30)                          # the last 3 s as float pieces (for the sneeze model)
        self.q = queue.Queue(maxsize=2)
        self.loud_t = 0.0
        threading.Thread(target=self._model_loop, daemon=True, name="sneeze").start()

    def feed(self, a, now):
        if not (CFG.get("clap_on") or CFG.get("sneeze_on") or wake_clap_listens()):
            self.pending.clear(); SOUNDEV["claps"] = []; return
        muted = (AUDIO is not None and now < AUDIO.mute_until) or SOUND["playing"] or now - SERVO_MOVE["t"] < 1.0
        x = a / 32768.0
        self.pcm.append((now, x.astype(np.float32)))
        n = x.size // self.FR
        if n <= 0:
            return
        fr = x[:n * self.FR].reshape(n, self.FR)
        dbs = 10.0 * np.log10(np.mean(fr * fr, axis=1) + 1e-10)
        t0 = now - n * 0.01
        for i, db in enumerate(dbs):
            t = t0 + (i + 1) * 0.01
            self._step(t, float(db), muted)

    def _step(self, t, db, muted):
        prev = [d for (tt, d) in self.hist if t - tt <= 0.04]
        before = min(prev) if prev else db
        self.hist.append((t, db))
        if self.bg is None:
            self.bg = db
        quiet = db < self.bg + 6
        self.bg += (db - self.bg) * (0.02 if quiet else 0.002)          # background follows slowly (not the claps)
        sens = float(CFG.get("clap_sens", 5))
        rise = 26.0 - 1.6 * sens                                          # sensitivity 1 = +24 dB ... 10 = +10 dB
        loud = db > max(self.bg + rise, -42.0)
        if CFG.get("sneeze_on") and db > max(self.bg + 14.0, -45.0) and t - self.loud_t > 0.7 and not muted:
            self.loud_t = t                                              # something loud: look at it with the model in 0.6 s
            threading.Timer(0.6, self._ask_model, args=(t,)).start()
        if (CFG.get("clap_on") or wake_clap_listens()) and not muted and loud and before < db - 12.0 and not any(abs(t - p[0]) < 0.12 for p in self.pending):
            self.pending.append((t, db))
        for p in list(self.pending):
            if t - p[0] >= 0.16:                                          # 160 ms later: was it short (a clap)?
                self.pending.remove(p)
                after = [d for (tt, d) in self.hist if 0.11 <= tt - p[0] <= 0.16]
                if after and max(after) < p[1] - 10.0:
                    self._clap(p[0])
        c = SOUNDEV["claps"]
        if c and t - c[-1] > 1.0:                                         # the row is over
            n = len(c); SOUNDEV["claps"] = []
            if 2 <= n <= 4:
                clap_action(n)
            elif n > 4:
                SOUNDEV.update(last_n=n, last_n_t=time.time(), last_act=tr("too many claps"))

    def _clap(self, t):
        c = SOUNDEV["claps"]
        if c and t - c[-1] < 0.15:
            return
        if c and t - c[-1] > 0.9:
            c.clear()
        c.append(t); SOUNDEV["last_clap"] = time.time(); SOUNDEV["seq_n"] = len(c)

    # ---- sneeze ----
    def _ask_model(self, t):
        if not CFG.get("sneeze_on"):
            return
        pieces = [x for (tt, x) in list(self.pcm) if t - 0.45 <= tt <= t + 0.6]
        if not pieces:
            return
        w = np.concatenate(pieces)[-15600:]
        if w.size < 15600:
            w = np.concatenate([np.zeros(15600 - w.size, np.float32), w])
        try:
            self.q.put_nowait((t, w))
        except queue.Full:
            pass

    def _model_loop(self):
        it = None
        while True:
            t, w = self.q.get()
            if it is None:
                it = yamnet_interpreter()
                if it is None:
                    continue
            try:
                sc = yamnet_scores(it, w)
            except Exception as e:
                SOUNDEV.update(model="error", model_msg=str(e)[:120]); it = None; continue
            SOUNDEV["checks"] += 1
            idx = YAMNET_INFO.get("sneeze", YAMNET_SNEEZE)
            s = float(sc[idx]) if idx < sc.size else 0.0
            top3 = np.argsort(sc)[-3:]
            SOUNDEV.update(sneeze_score=round(s, 2), sneeze_t=time.time())
            thr = 0.55 - 0.04 * (float(CFG.get("sneeze_sens", 5)) - 5)
            if s >= thr and idx in top3:
                sneeze_reply()


YAMNET_INFO = {}
_SIM_SND = {"seen": 0}


def sim_sound_events(evs, last, fresh=False):
    """2.98.11: the short sounds of the 3D simulator (no real microphone): claps go to the clap switch (and snooze the
    wake-up alarm), a sneeze to «Bless you». Each id once; after a (re)connect the old ones are skipped. Loudness at the
    microphone must reach the same threshold as with a real microphone."""
    if AUDIO is None or AUDIO.proc is not None:
        return
    if fresh or last < _SIM_SND["seen"]:
        _SIM_SND["seen"] = last; return
    bg = AUDIO.bg if AUDIO.bg is not None else -60.0
    for e in sorted(evs or [], key=lambda x: int(x.get("id") or 0)):
        i = int(e.get("id") or 0)
        if i <= _SIM_SND["seen"]:
            continue
        _SIM_SND["seen"] = i
        kind, n, db = str(e.get("kind") or ""), int(e.get("n") or 1), float(e.get("db") or -90.0)
        if kind in ("clap", "sneeze") and own_sound_now():
            own_sound_ignored(kind); continue            # 554: MoveEye plays a sound itself (siren …) - like the real microphone
        if kind == "clap" and (CFG.get("clap_on") or wake_clap_listens()):
            rise = 26.0 - 1.6 * float(CFG.get("clap_sens", 5))
            if db < max(bg + rise, -42.0):
                SOUNDEV.update(last_n=n, last_n_t=time.time(), last_act=tr("too quiet")); continue
            SOUNDEV.update(last_clap=time.time(), seq_n=n)
            if 2 <= n <= 4:
                clap_action(n)
            elif n > 4:
                SOUNDEV.update(last_n=n, last_n_t=time.time(), last_act=tr("too many claps"))
        elif kind == "sneeze" and CFG.get("sneeze_on"):
            SOUNDEV["checks"] += 1
            if db >= max(bg + 14.0, -45.0):
                SOUNDEV.update(sneeze_score=0.9, sneeze_t=time.time())
                sneeze_reply()


def yamnet_runtime():
    for mod in ("ai_edge_litert.interpreter", "tflite_runtime.interpreter"):
        try:
            import importlib
            return importlib.import_module(mod).Interpreter
        except Exception:
            continue
    try:
        import tensorflow as tf
        return tf.lite.Interpreter
    except Exception:
        return None


def yamnet_path():
    return os.path.join(DATA_DIR, "models", "yamnet.tflite")


def yamnet_fetch():
    """Fetch the sound recognition model once (about 4 MB, from Google)."""
    p = yamnet_path()
    if os.path.isfile(p) and os.path.getsize(p) > 1000000:
        return True
    os.makedirs(os.path.dirname(p), exist_ok=True)
    SOUNDEV.update(model="downloading", model_msg="")
    for u in YAMNET_URLS:
        try:
            req = urllib.request.Request(u, headers={"User-Agent": "MotionWatch/" + APP_VERSION})
            with urllib.request.urlopen(req, timeout=60) as r:
                data = r.read(20 * 1024 * 1024)
            if len(data) < 1000000 or data[4:8] != b"TFL3":
                raise ValueError("not a model file")
            with open(p + ".part", "wb") as f:
                f.write(data)
            os.replace(p + ".part", p)
            log_event("sys", f"Sound recognition model loaded ({len(data) // 1024} kB)")
            return True
        except Exception as e:
            SOUNDEV["model_msg"] = str(e)[:120]
    SOUNDEV["model"] = "download failed"; SOUNDEV["fail_t"] = time.time()
    return False


def yamnet_interpreter():
    if time.time() - SOUNDEV.get("fail_t", 0.0) < 600:
        return None                                           # it did not work a moment ago: try again in 10 minutes
    Interp = yamnet_runtime()
    if Interp is None:
        SOUNDEV.update(model="no runtime", model_msg="pip install ai-edge-litert"); return None
    if not yamnet_fetch():
        return None
    try:
        it = Interp(model_path=yamnet_path())
        it.allocate_tensors()
        inp = it.get_input_details()[0]
        YAMNET_INFO["in"] = inp; YAMNET_INFO["out"] = it.get_output_details()[0]
        try:                                                  # the class names travel inside the model file (zip part)
            with zipfile.ZipFile(yamnet_path()) as z:
                names = [n for n in z.namelist() if n.endswith(".txt")]
                labels = z.read(names[0]).decode("utf-8", "replace").splitlines() if names else []
            if "Sneeze" in labels:
                YAMNET_INFO["sneeze"] = labels.index("Sneeze")
        except (zipfile.BadZipFile, OSError, IndexError):
            pass
        SOUNDEV.update(model="ready", model_msg="")
        return it
    except Exception as e:
        SOUNDEV.update(model="error", model_msg=str(e)[:120], fail_t=time.time()); return None


def yamnet_scores(it, w):
    inp, out = YAMNET_INFO["in"], YAMNET_INFO["out"]
    x = w.astype(np.float32)
    if len(inp["shape"]) == 2:
        x = x.reshape(1, -1)
    if tuple(inp["shape"]) != tuple(x.shape):
        it.resize_tensor_input(inp["index"], list(x.shape)); it.allocate_tensors()
    it.set_tensor(inp["index"], x)
    it.invoke()
    sc = np.asarray(it.get_tensor(out["index"]), dtype=np.float32)
    return sc.reshape(-1, sc.shape[-1]).mean(axis=0) if sc.ndim > 1 else sc


def sneeze_count(add=False):
    d = datetime.now().strftime("%Y-%m-%d"); p = os.path.join(DATA_DIR, "sneezes.json")
    if not _SNEEZE_DAYS["loaded"]:
        _SNEEZE_DAYS["loaded"] = True
        try:
            with open(p) as f:
                _SNEEZE_DAYS["days"] = {k: int(v) for k, v in json.load(f).items()}
        except (OSError, ValueError, AttributeError):
            pass
    if add:
        D = _SNEEZE_DAYS["days"]; D[d] = D.get(d, 0) + 1
        for k in sorted(D)[:-120]:
            D.pop(k, None)
        try:
            with open(p, "w") as f:
                json.dump(D, f)
        except OSError:
            pass
    return _SNEEZE_DAYS["days"].get(d, 0)


def sneeze_reply():
    now = time.time()
    if now - SOUNDEV["sneeze_last"] < 5.0:                     # «hatschi - hatschi»: one answer
        return
    SOUNDEV["sneeze_last"] = now
    n = sneeze_count(add=True)
    h = sim_now().hour                                         # the simulated night while connected (285)
    quiet = CFG.get("sneeze_night") and (h >= 22 or h < 7)
    log_event("sys", f"Sneeze recognised (today {n}×)" + (" - quiet at night" if quiet else ""))
    if quiet or not out_selected() or SOUND["playing"]:
        return
    rep = str(CFG.get("sneeze_reply") or "tts")
    vol = CFG.get("sneeze_volume", 70)
    if rep.startswith("file:") and rep[5:] in own_sounds():
        sec = 3.0
        try:
            r = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0",
                                os.path.join(sounds_dir(), rep[5:])], capture_output=True, text=True, timeout=10)
            sec = max(0.5, min(10.0, float(r.stdout.strip() or 3)))
        except (OSError, ValueError, subprocess.SubprocessError):
            pass
        sound_play(rep, sec, vol, reason="test"); return
    words = [x.strip() for x in str(CFG.get("sneeze_texts") or "").split("|") if x.strip()] or [tr("Bless you!")]
    text = tr("Again? Get well soon!") if n >= 3 and n % 3 == 0 else words[(n - 1) % len(words)]
    ok, err = tts_make(text, CFG["lang"], TTS["file"])
    if not ok:                                                # no speech program: a small friendly melody
        sound_play("beep3", 0.7, vol, reason="test"); SOUNDEV["model_msg"] = err; return
    try:
        import wave
        with wave.open(TTS["file"]) as w_:
            dur = w_.getnframes() / float(w_.getframerate() or 1)
    except Exception:
        dur = 2.0
    sound_play("tts", dur + 0.3, vol, reason="test")


def sneeze_upload(data):
    """An own answer (e.g. «Gesundheit!» recorded on a phone): converted to a short .wav in the own sounds and chosen at once."""
    if not data or len(data) > 8 * 1024 * 1024:
        return False, "the file is too large (max. 8 MB)", ""
    if not shutil.which("ffmpeg"):
        return False, "ffmpeg is missing (sudo apt install ffmpeg)", ""
    os.makedirs(sounds_dir(), exist_ok=True)
    i = 1
    while os.path.exists(os.path.join(sounds_dir(), f"Gesundheit {i}.wav")):
        i += 1
    name = f"Gesundheit {i}.wav"
    tmp = os.path.join(tempfile.gettempdir(), "mw_sneeze_upload.bin")
    with open(tmp, "wb") as f:
        f.write(data)
    try:
        r = subprocess.run(["ffmpeg", "-loglevel", "error", "-y", "-i", tmp, "-t", "8", "-ac", "1", "-ar", "22050", os.path.join(sounds_dir(), name)],
                           capture_output=True, timeout=60)
        if r.returncode != 0 or not os.path.isfile(os.path.join(sounds_dir(), name)):
            return False, "the file could not be read (a sound file like .m4a, .mp3 or .wav is needed)", ""
    finally:
        try:
            os.remove(tmp)
        except OSError:
            pass
    CFG["sneeze_reply"] = "file:" + name; save_settings()
    log_event("sys", f"Own answer for «Bless you!» saved: {name}")
    return True, "", name


def sneeze_install():
    """Install the runtime for the sound recognition model (pip, a few minutes; in the background)."""
    if SOUNDEV["install"] == "running":
        return False, "already running"
    SOUNDEV["install"] = "running"

    def work():
        try:
            r = subprocess.run([sys.executable, "-m", "pip", "install", "--break-system-packages", "ai-edge-litert"],
                               capture_output=True, text=True, timeout=1200)
            ok = r.returncode == 0
            SOUNDEV["fail_t"] = 0.0
            SOUNDEV["install"] = "done" if ok else "failed: " + ((r.stderr or r.stdout).strip().splitlines() or ["?"])[-1][:140]
            log_event("sys", "Sound recognition: runtime installed" if ok else "Sound recognition: " + SOUNDEV["install"])
            if ok:
                SOUNDEV.update(model="off", model_msg="")
        except Exception as e:
            SOUNDEV["install"] = "failed: " + str(e)[:120]
    threading.Thread(target=work, daemon=True, name="sneeze-install").start()
    return True, ""


def soundev_state():
    now = time.time()
    return {"clap_on": bool(CFG.get("clap_on")), "sneeze_on": bool(CFG.get("sneeze_on")), "counting": len(SOUNDEV["claps"]),
            "last_n": SOUNDEV["last_n"] if now - SOUNDEV["last_n_t"] < 30 else 0, "last_act": SOUNDEV["last_act"] if now - SOUNDEV["last_act_t"] < 30 else "",
            "model": SOUNDEV["model"], "model_msg": SOUNDEV["model_msg"], "install": SOUNDEV["install"], "runtime": yamnet_runtime() is not None,
            "sneeze_score": SOUNDEV["sneeze_score"] if now - SOUNDEV["sneeze_t"] < 20 else None, "sneezes_today": sneeze_count(),
            "mic": bool(CFG["audio_in"]), "spk": out_selected(), "tts": tts_engine() is not None}


def soundev_text(which, lang=None):
    s = soundev_state()
    if not s["mic"]:
        return tr("no microphone selected (Microphone)", lang)
    if which == "clap":
        if not s["clap_on"]:
            return tr("off", lang)
        t = tr("listening", lang) + (" · " + tr("counting", lang) + f": {s['counting']}×" if s["counting"] else "")
        if s["last_n"]:
            t += f" · {tr('last', lang)}: {s['last_n']}× → " + (tr(s["last_act"], lang) if s["last_act"] else "–")
        return t + ("" if s["spk"] else " · " + tr("no loudspeaker for the beep", lang))
    if not s["sneeze_on"]:
        return tr("off", lang) + (f" · {tr('today', lang)}: {s['sneezes_today']}× {tr('sneezed', lang)}" if s["sneezes_today"] else "")
    m = s["model"]
    t = {"ready": tr("listening", lang), "downloading": tr("loading the sound recognition …", lang), "off": tr("waiting for the first loud sound", lang),
         "no runtime": tr("needs the sound recognition program - button «Install»", lang), "download failed": tr("model could not be loaded", lang),
         "error": tr("error", lang)}.get(m, m)
    if s["install"] == "running":
        t = tr("installing … (a few minutes)", lang)
    elif s["install"].startswith("failed"):
        t += " · ⚠ " + s["install"]
    if s["sneeze_score"] is not None:
        t += f" · {tr('last check', lang)}: {round(100 * s['sneeze_score'])} %"
    t += f" · {tr('today', lang)}: {s['sneezes_today']}× {tr('sneezed', lang)}"
    if not s["tts"] and str(CFG.get("sneeze_reply") or "tts") == "tts":
        t += " · " + tr("no speech program (sudo apt install libttspico-utils)", lang)
    return t


SOUNDEV_OBJ = {"o": None}


class AudioMonitor:
    """Reads the microphone (arecord), measures the level, raises the noise alarm, feeds the live listeners and the
    sound file of a running recording."""
    def __init__(self):
        self.proc = None; self.dev = ""; self.err = ""; self.restart_at = 0.0
        self.lk = threading.Lock()
        self.ring = deque()                  # (end time, pcm bytes) of the last seconds: the pre-roll of a recording
        self.listeners = set()               # queues of open "listen" connections
        self.rec = None                      # {"wave", "path", "video", "frames"}
        self.level = None; self.bg = None; self.peak = -90.0; self.peak_t = 0.0
        self.loud_since = 0.0; self.last_loud = 0.0; self.noisy_until = 0.0
        self.noise_alerted = False; self.last_noise = 0.0
        self.sim_t = 0.0                     # the 3D simulator sends the sound of its world (no real microphone)
        self.mute_until = 0.0                # the Pi plays a sound itself: the noise alarm does not listen
        self.mux_threads = []
        self._status("off")
        threading.Thread(target=self.run, daemon=True, name="audio").start()

    # ---- status for the page / window ----
    def _status(self, status):
        lv, bg = self.level, self.bg
        STATE["audio"] = {"status": status, "dev": self.dev if self.proc else "", "level": lv, "bg": None if bg is None else round(bg, 1),
                          "thr": None if bg is None else round(max(bg + CFG["noise_threshold"], -70.0), 1),
                          "peak": self.peak if time.time() - self.peak_t < 3 else lv, "loud": time.time() < self.noisy_until,
                          "listeners": len(self.listeners), "playing": SOUND["playing"], "sound_msg": SOUND["msg"],
                          "rec": self.rec is not None, "mic": bool(CFG["audio_in"]) or status == "simulated", "spk": out_selected(),
                          "bt": {"avail": bt_available(), "scanning": BT["scanning"], "busy": BT["busy"], "msg": BT["msg"]},
                          "talk": TALK["proc"] is not None, "https_port": STATE.get("https_port")}

    def noisy(self):
        return (self.proc is not None or time.time() - self.sim_t < 1.5) and time.time() < self.noisy_until

    def feed_sim(self, lvl, mic=None):
        """the sound level (dB) of the simulated world - only when no real microphone runs: noise alarm like with a microphone.
        mic (3D simulator, real-pir-ton): background and the loudest sources - «listen» then gets a made-up sound of this
        loudness (558p sim_mic_pcm), so listening in works in the simulation too"""
        if self.proc is not None:
            return
        now = time.time()
        if now - self.sim_t > 5.0:
            self._started = now; self.bg = None          # a new start: learn the background again
            self._sim_pcm_t = now
        if self.listeners and isinstance(mic, dict):
            secs = min(0.5, max(0.0, now - getattr(self, "_sim_pcm_t", now)))
            n = int(secs * AUDIO_RATE) // AUDIO_CHUNK * AUDIO_CHUNK
            if n > 0:
                self._sim_pcm_t = getattr(self, "_sim_pcm_t", now) + n / AUDIO_RATE
                try:
                    data = sim_mic_pcm(mic, n)
                except Exception:
                    data = bytes(n * 2)
                with self.lk:
                    for i in range(0, len(data), AUDIO_CHUNK * 2):
                        for q in list(self.listeners):
                            try:
                                q.put_nowait(data[i:i + AUDIO_CHUNK * 2])
                            except queue.Full:
                                pass
        else:
            self._sim_pcm_t = now
        self.sim_t = now
        self.level = float(lvl)
        if self.level >= self.peak or now - self.peak_t > 3:
            self.peak, self.peak_t = self.level, now
        self._noise(now, self.level)
        self._status("simulated")

    # ---- microphone process ----
    def _stop(self):
        p, self.proc = self.proc, None
        if p is not None:
            try:
                p.kill(); p.wait(timeout=3)
            except Exception:
                pass
        self.level = None; self.bg = None

    def run(self):
        try:
            audio_scan()
        except Exception:
            pass
        while True:
            try:
                self._loop_once()
            except Exception as e:                       # never let the audio thread die
                self.err = str(e)[:200]; self._stop(); self.restart_at = time.time() + 5.0
                self._status("error: " + self.err); time.sleep(1.0)

    def _loop_once(self):
        want = CFG["audio_in"]
        if not want or not AUDIO_DEV_RE.match(want):
            if time.time() - self.sim_t < 1.5:           # the simulator supplies the sound
                time.sleep(0.5); return
            if self.proc is not None:
                self._stop(); log_event("sys", "Microphone off")
            self.rec_abort(); self._status("off"); time.sleep(0.5); return
        if self.proc is None or self.dev != want:
            self._stop()
            if time.time() < self.restart_at:
                self._status("error: " + self.err if self.err else "starting"); time.sleep(0.3); return
            if not shutil.which("arecord"):
                self.err = "arecord is missing (sudo apt install alsa-utils)"; self.restart_at = time.time() + 30.0
                return
            self.dev = want
            self.proc = subprocess.Popen(["arecord", "-q", "-D", want, "-f", "S16_LE", "-r", str(AUDIO_RATE), "-c", "1", "-t", "raw"],
                                         stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            self._started = time.time(); self.err = ""
        data = self.proc.stdout.read(AUDIO_CHUNK * 2)
        if not data or len(data) < 2:
            p = self.proc
            try:
                p.wait(timeout=2); err = (p.stderr.read() or b"").decode(errors="replace").strip()
            except Exception:
                err = ""
            self.err = (err.splitlines()[-1] if err else f"arecord stopped (exit {p.poll()})")[:200]
            log_event("sys", f"Microphone: {self.err}")
            self._stop(); self.restart_at = time.time() + 10.0; self._status("error: " + self.err)
            return
        self._chunk(data[:len(data) // 2 * 2])

    def _chunk(self, data):
        now = time.time()
        a = np.frombuffer(data, dtype="<i2").astype(np.float32)
        gain = 10.0 ** (float(CFG["audio_gain"]) / 20.0)
        if abs(gain - 1.0) > 1e-3:
            a = np.clip(a * gain, -32768, 32767)
            data = a.astype("<i2").tobytes()
        lvl = _db(float(np.sqrt(np.mean(a * a))) if a.size else 0.0)
        self.level = lvl
        if lvl >= self.peak or now - self.peak_t > 3:
            self.peak, self.peak_t = lvl, now
        with self.lk:
            self.ring.append((now, data))
            keep = max(3.0, float(CFG["pre_roll"]) + 2.0)
            while self.ring and now - self.ring[0][0] > keep:
                self.ring.popleft()
            if self.rec is not None:
                try:
                    self.rec["wave"].writeframes(data)
                except Exception:
                    self.rec = None
            for q in list(self.listeners):
                try:
                    q.put_nowait(data)
                except queue.Full:
                    pass                                 # slow phone: drop instead of waiting
        self._noise(now, lvl)
        if SOUNDEV_OBJ["o"] is not None:
            try:
                SOUNDEV_OBJ["o"].feed(a, now)
            except Exception as e:
                SOUNDEV["model_msg"] = str(e)[:120]
        self._status("listening")

    # ---- noise alarm ----
    def _noise(self, now, lvl):
        if now - getattr(self, "_started", 0) < 1.5:
            return                                       # the first moments of a microphone are often a click
        muted = now < self.mute_until or SOUND["playing"] or now - SERVO_MOVE["t"] < 1.0    # servo motors are loud
        if self.bg is None:
            self.bg = lvl
        thr = max(self.bg + float(CFG["noise_threshold"]), -70.0)       # never below -70 dB: microphone hiss is no noise
        loud = lvl > thr and not muted
        # background level: follows quiet phases fast, loud ones very slowly (a running generator becomes "normal" after ~1 min)
        k = 0.1 if lvl < self.bg else (0.003 if loud else 0.02)
        if not muted:
            self.bg += k * (lvl - self.bg)
        if loud:
            self.last_loud = now
            if not self.loud_since:
                self.loud_since = now
            if now - self.loud_since >= float(CFG["noise_min"]) - 0.05:
                self.noisy_until = now + 2.0
                if CFG["noise_alarm"] and is_armed():
                    self.last_noise = now                # keeps a recording running (like a person in the picture)
                if CFG["noise_alarm"] and not self.noise_alerted:
                    self.noise_alerted = True
                    self._alarm(lvl)
        else:
            self.loud_since = 0.0
            if self.noise_alerted and now - self.last_loud > 5.0:
                self.noise_alerted = False

    def _alarm(self, lvl):
        txt = f"Noise: {lvl:.0f} dB (background {self.bg:.0f} dB)"
        if not is_armed():
            log_event("person", txt + " (disarmed - no alarm)"); return
        w = WATCH_REF["w"]
        push_alert("noise", "noise", db=round(lvl), source=STATE["source_label"])
        sent = w is not None and w.notifier.prealarm(w.frame_out, "noise")
        log_event("person", "Noise alarm: " + txt + (" - push message sent" if sent else ""))
        siren_alarm("noise")

    # ---- live listening ----
    def listen(self):
        q = queue.Queue(maxsize=25)
        with self.lk:
            self.listeners.add(q)
        return q

    def unlisten(self, q):
        with self.lk:
            self.listeners.discard(q)

    # ---- sound of a recording: a WAV file next to the video, joined with it when the recording ends ----
    def rec_start(self, video_path, t0):
        if not (CFG["audio_record"] and self.proc is not None) or self.rec is not None:
            return False
        import wave
        tdir = os.path.join(os.path.dirname(os.path.abspath(video_path)), ".tmp")
        try:
            os.makedirs(tdir, exist_ok=True)
            path = os.path.join(tdir, os.path.basename(video_path) + ".wav")
            wf = wave.open(path, "wb"); wf.setnchannels(1); wf.setsampwidth(2); wf.setframerate(AUDIO_RATE)
        except Exception as e:
            log_event("rec", f"Sound recording failed: {e}"[:200]); return False
        with self.lk:
            for t, data in self.ring:                    # the seconds before the detection (pre-roll), like the video
                if t > t0:
                    wf.writeframes(data)
            self.rec = {"wave": wf, "path": path, "video": video_path}
        return True

    def rec_abort(self):
        with self.lk:
            r, self.rec = self.rec, None
        if r:
            try:
                r["wave"].close(); os.remove(r["path"])
            except Exception:
                pass

    def rec_stop(self, video_path, frames, fps):
        with self.lk:
            r = self.rec
            if r is None or r["video"] != video_path:
                return
            self.rec = None
        try:
            r["wave"].close()
        except Exception:
            return
        th = threading.Thread(target=audio_mux, args=(video_path, r["path"], frames, fps), daemon=True)
        th.start()
        self.mux_threads = [t for t in self.mux_threads if t.is_alive()] + [th]

    def wait_mux(self, timeout=30.0):
        end = time.time() + timeout
        for t in list(self.mux_threads):
            t.join(max(0.1, end - time.time()))


def audio_mux(video, wav, frames, fps):
    """Put the sound into the finished video (ffmpeg, the picture is copied, not encoded again). The video runs at the
    measured frame rate; if that was a bit off, the picture timing is stretched to the real length of the sound."""
    import wave
    name = os.path.basename(video)
    LIVE_RECS.add(name)                                  # not playable / deletable while it is replaced
    tmp = os.path.join(os.path.dirname(wav), "mux_" + name)
    try:
        with wave.open(wav, "rb") as w:
            adur = w.getnframes() / float(w.getframerate() or AUDIO_RATE)
        vdur = frames / fps if fps else 0.0
        if adur < 0.3 or not shutil.which("ffmpeg") or not os.path.isfile(video):
            return
        ratio = adur / vdur if vdur > 0.2 else 1.0
        scale = ratio if 0.25 <= ratio <= 4.0 else 1.0
        cmd = (["nice", "-n", "10"] if shutil.which("nice") else []) + [
            "ffmpeg", "-y", "-loglevel", "error", "-itsscale", f"{scale:.5f}", "-i", video, "-i", wav,
            "-map", "0:v:0", "-map", "1:a:0", "-c:v", "copy", "-c:a", "aac", "-b:a", "64k"] + (
            ["-metadata", "location=" + gps_iso6709(gps_now()), "-metadata", "location-eng=" + gps_iso6709(gps_now())] if CFG["gps_tag"] and gps_now() else []) + [
            "-movflags", "+faststart", tmp]
        r = subprocess.run(cmd, capture_output=True, timeout=900)
        if r.returncode != 0 or not os.path.isfile(tmp) or os.path.getsize(tmp) < 1000:
            log_event("rec", "Sound could not be added: " + (r.stderr.decode(errors="replace").strip()[-160:] or f"ffmpeg exit {r.returncode}"))
            return
        os.replace(tmp, video)
        side = os.path.splitext(video)[0] + ".json"
        try:
            with open(side) as f:
                meta = json.load(f)
            meta.update(audio=True, duration=round(vdur * scale, 1))
            with open(side, "w") as f:
                json.dump(meta, f)
        except (OSError, ValueError):
            pass
        stem = os.path.splitext(name)[0]
        for p in (os.path.join(os.path.dirname(video), ".cache", stem + ".h264.mp4"),):
            try:
                os.remove(p)
            except OSError:
                pass
        _REC_META.pop(name, None)
    except Exception as e:
        log_event("rec", f"Sound could not be added: {e}"[:200])
    finally:
        LIVE_RECS.discard(name)
        for p in (wav, tmp):
            try:
                os.remove(p)
            except OSError:
                pass


# ---- Bluetooth loudspeaker (bluetoothctl + PipeWire / PulseAudio of Raspberry Pi OS) -----------------------------------
#   Search, pair, trust, connect from the page / the window. The sound goes through the sound server of the user session
#   (paplay or pw-cat). Bluetooth speakers often switch themselves off when idle: the Pi reconnects as soon as it is back.
BT_MAC_RE = re.compile(r"^([0-9A-F]{2}:){5}[0-9A-F]{2}$")
BT = {"devices": [], "scanning": False, "busy": "", "msg": "", "time": 0.0}
_BT_LOCK = threading.Lock()


def bt_available():
    return shutil.which("bluetoothctl") is not None


def _btctl(*args, timeout=15):
    return _run(["bluetoothctl"] + list(args), timeout=timeout)


def bt_info(mac):
    rc, out, _e = _btctl("info", mac, timeout=8)
    d = {"mac": mac, "name": mac, "paired": False, "connected": False, "trusted": False, "audio": False}
    for line in (out or "").splitlines():
        line = line.strip()
        if line.startswith("Name:"):
            d["name"] = line[5:].strip()[:60] or mac
        elif line.startswith("Alias:") and d["name"] == mac:
            d["name"] = line[6:].strip()[:60] or mac
        elif line.startswith("Paired:"):
            d["paired"] = line.endswith("yes")
        elif line.startswith("Connected:"):
            d["connected"] = line.endswith("yes")
        elif line.startswith("Trusted:"):
            d["trusted"] = line.endswith("yes")
        elif line.startswith("Icon:") and "audio" in line:
            d["audio"] = True
        elif "Audio Sink" in line or "Headset" in line or "Handsfree" in line:
            d["audio"] = True
    return d


def bt_list():
    rc, out, _e = _btctl("devices", timeout=8)
    macs = []
    for line in (out or "").splitlines():
        m = re.match(r"^Device\s+(([0-9A-F]{2}:){5}[0-9A-F]{2})\b", line.strip())
        if m and m.group(1) not in macs:
            macs.append(m.group(1))
    devs = [bt_info(m) for m in macs[:30]]
    devs.sort(key=lambda d: (not d["connected"], not d["paired"], not d["audio"], d["name"].lower()))
    BT["devices"] = devs; BT["time"] = time.time()
    return devs


def bt_scan(seconds=12):
    """Look for Bluetooth devices (the loudspeaker must be in pairing mode). Runs in the background."""
    if not bt_available():
        return False, "bluetoothctl is missing (sudo apt install bluez)"
    if BT["scanning"]:
        return True, ""
    BT["scanning"] = True; BT["msg"] = ""

    def work():
        try:
            _btctl("power", "on", timeout=8)
            t0 = time.time()
            rc, _o, _e = _btctl("--timeout", str(int(seconds)), "scan", "on", timeout=seconds + 8)   # 2.95.54: newer bluez
            if time.time() - t0 < seconds / 2:                      # old bluez without --timeout: keep it open by hand
                p = subprocess.Popen(["bluetoothctl", "scan", "on"], stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                time.sleep(seconds)
                try:
                    p.terminate(); p.wait(timeout=3)
                except Exception:
                    p.kill()
            _btctl("scan", "off", timeout=5)
            bt_list()
        except Exception as e:
            BT["msg"] = str(e)[:200]
        finally:
            BT["scanning"] = False
    threading.Thread(target=work, daemon=True, name="bt-scan").start()
    return True, ""


def bt_connected(mac):
    return bt_info(mac)["connected"]


def bt_connect(mac, select=True):
    """Pair (if needed), trust and connect a loudspeaker, then use it for the siren / talking."""
    mac = str(mac or "").upper()
    if not BT_MAC_RE.match(mac):
        return False, "invalid Bluetooth address"
    if not bt_available():
        return False, "bluetoothctl is missing (sudo apt install bluez)"
    with _BT_LOCK:
        BT["busy"] = mac
        try:
            _btctl("power", "on", timeout=8)
            info = bt_info(mac)
            if not info["paired"]:
                rc, out, err = _btctl("--agent", "NoInputNoOutput", "pair", mac, timeout=30)   # 2.95.54: a speaker has no keyboard
                if not bt_info(mac)["paired"]:
                    rc, out, err = _btctl("pair", mac, timeout=30)
                if not bt_info(mac)["paired"]:
                    return False, "pairing failed - is the loudspeaker in pairing mode (blue light blinking)?"
            _btctl("trust", mac, timeout=8)
            rc, out, err = _btctl("connect", mac, timeout=25)
            info = bt_info(mac)
            if not info["connected"]:
                return False, "could not connect - switch the loudspeaker on and bring it closer"
            if select and CFG["audio_out"] != "bt:" + mac:
                CFG["audio_out"] = "bt:" + mac; save_settings()
            log_event("sys", f"Bluetooth loudspeaker connected: {info['name']}")
            return True, ""
        finally:
            BT["busy"] = ""
            try:
                bt_list()
            except Exception:
                pass


def bt_disconnect(mac, remove=False):
    mac = str(mac or "").upper()
    if not BT_MAC_RE.match(mac):
        return False, "invalid Bluetooth address"
    _btctl("disconnect", mac, timeout=10)
    if remove:
        _btctl("remove", mac, timeout=10)
        if CFG["audio_out"] == "bt:" + mac:
            CFG["audio_out"] = ""; save_settings()
    log_event("sys", f"Bluetooth loudspeaker {'removed' if remove else 'disconnected'}: {mac}")
    bt_list()
    return True, ""


def bt_keeper():
    """While a Bluetooth loudspeaker is chosen: reconnect it when it was switched off and on again (every 60 s)."""
    warned = False
    while True:
        time.sleep(60)
        out = CFG["audio_out"]
        if not out.startswith("bt:") or not bt_available() or BT["busy"] or SOUND["playing"] or TALK["proc"] is not None:
            continue
        mac = out[3:]
        try:
            if not bt_connected(mac):
                ok, _m = bt_connect(mac, select=False)
                if not ok and not warned:
                    warned = True; log_event("sys", "Bluetooth loudspeaker not reachable - trying again every minute")
                elif ok:
                    warned = False
        except Exception:
            pass


def _bt_sink(mac):
    rc, out, _e = _run(["pactl", "list", "short", "sinks"], timeout=5) if shutil.which("pactl") else (1, "", "")
    key = mac.replace(":", "_")
    for line in (out or "").splitlines():
        parts = line.split("\t")
        if len(parts) > 1 and key in parts[1]:
            return parts[1]
    return None


def out_cmd(rate, connect=True):
    """Command that plays raw 16 bit mono at `rate` on the chosen loudspeaker -> (argv, error)."""
    dev = CFG["audio_out"]
    if dev.startswith("bt:") and BT_MAC_RE.match(dev[3:]):
        if _is_root():
            return None, "Bluetooth sound needs the program as normal user (not with sudo / not as system service)"
        mac = dev[3:]
        if not bt_connected(mac):
            if not connect:                              # talking: do not block, connect in the background
                if not BT["busy"]:
                    threading.Thread(target=bt_connect, args=(mac, False), daemon=True).start()
                return None, "the Bluetooth loudspeaker is being connected - try again in a few seconds"
            ok, err = bt_connect(mac, select=False)
            if not ok:
                return None, err
        sink = _bt_sink(mac)
        if shutil.which("paplay"):
            return ["paplay", "--raw", "--format=s16le", f"--rate={rate}", "--channels=1"] + (["-d", sink] if sink else []), ""
        if shutil.which("pw-cat"):
            return ["pw-cat", "--playback", "--format", "s16", "--rate", str(rate), "--channels", "1"] + (["--target", sink] if sink else []) + ["-"], ""
        return None, "paplay is missing (sudo apt install pulseaudio-utils)"
    if not dev or not AUDIO_DEV_RE.match(dev):
        return None, "no loudspeaker selected"
    if not shutil.which("aplay"):
        return None, "aplay is missing (sudo apt install alsa-utils)"
    return ["aplay", "-q", "-D", dev, "-t", "raw", "-f", "S16_LE", "-r", str(rate), "-c", "1"], ""


def out_selected():
    dev = CFG["audio_out"]
    return bool(dev) and (AUDIO_DEV_RE.match(dev) is not None or (dev.startswith("bt:") and BT_MAC_RE.match(dev[3:]) is not None))


# ---- loudspeaker: siren / test sound -------------------------------------------------------------
SOUND = {"proc": None, "playing": False, "msg": "", "last_alarm": 0.0, "gen": 0}
_SOUND_LOCK = threading.Lock()


def _smooth(env, rate):
    k = max(1, int(rate * 0.006))                        # 6 ms edges: no clicks when a beep starts / stops
    return np.convolve(env.astype(np.float32), np.ones(k, np.float32) / k, mode="same")


def sound_samples(kind, seconds, rate=OUT_RATE):
    """Float samples -1..1 of a generated alarm sound or an own file (looped to the length)."""
    n = max(1, int(seconds * rate)); t = np.arange(n, dtype=np.float64) / rate
    if kind.startswith("beep"):                          # short answer beeps (clap switch): 1-4 rising, or one low
        y = np.zeros(n, np.float32)
        segs = [(0.0, 0.16, 440.0)] if kind == "beeplow" else [(i * 0.18, 0.12, 880.0 * (1.19 ** i)) for i in range(int(kind[4:] or 1))]
        for st_, du, f in segs:
            i0, i1 = int(st_ * rate), min(n, int((st_ + du) * rate))
            if i1 > i0:
                y[i0:i1] = (np.sin(2 * np.pi * f * (t[i0:i1] - st_)) * _smooth(np.ones(i1 - i0), rate) * 0.8).astype(np.float32)
        return y
    if kind in ("chime", "birds"):                       # 2.98.7: wake-up sounds - a soft bell melody / bird song
        y = np.zeros(n, np.float32)
        rng_ = np.random.default_rng(3)
        if kind == "chime":
            notes = [523.25, 659.25, 783.99, 1046.5, 783.99, 659.25]
            pos = 0.0
            while pos < seconds:
                for k, f in enumerate(notes):
                    st_ = pos + k * 0.32
                    i0 = int(st_ * rate)
                    if i0 >= n:
                        break
                    L = min(n - i0, int(1.6 * rate)); tt = np.arange(L) / rate
                    env = np.exp(-tt * 2.6) * np.minimum(1.0, tt / 0.004)
                    y[i0:i0 + L] += (np.sin(2 * np.pi * f * tt) + 0.3 * np.sin(2 * np.pi * 2.0 * f * tt) + 0.12 * np.sin(2 * np.pi * 3.01 * f * tt)) * env * 0.5
                pos += 3.2
        else:
            pos = 0.2
            while pos < seconds:
                i0 = int(pos * rate)
                if i0 >= n:
                    break
                for k in range(int(rng_.integers(2, 6))):          # a short phrase of chirps
                    L = int(rng_.uniform(0.06, 0.14) * rate); j0 = i0 + k * int(0.16 * rate)
                    if j0 + L >= n:
                        break
                    tt = np.arange(L) / rate; f0 = rng_.uniform(2800, 4200); f1 = f0 * rng_.uniform(0.7, 1.35)
                    ph = 2 * np.pi * np.cumsum(f0 + (f1 - f0) * tt / tt[-1]) / rate
                    y[j0:j0 + L] += np.sin(ph) * np.sin(np.pi * tt / tt[-1]) * 0.7
                pos += float(rng_.uniform(0.8, 2.2))
        return (y / max(1e-6, float(np.max(np.abs(y))))).astype(np.float32)
    if kind == "marmot":                                 # two short whistles
        y = np.zeros(n, np.float32)
        for st in (0.05, 0.55):
            i0, L = int(st * rate), int(0.26 * rate)
            if i0 + L > n:
                break
            tt = np.arange(L) / rate
            f = 3000.0 - 900.0 * (tt / 0.26) ** 1.5
            ph = 2 * np.pi * np.cumsum(f) / rate
            env = np.minimum(1.0, tt / 0.015) * np.minimum(1.0, (0.26 - tt) / 0.06)
            y[i0:i0 + L] = (np.sin(ph) + 0.25 * np.sin(2 * ph)) * env
        return (y / max(1e-6, float(np.max(np.abs(y))))).astype(np.float32)
    if kind.startswith("file:") or kind == "tts":
        name = kind[5:]
        path = TTS["file"] if kind == "tts" else os.path.join(sounds_dir(), name)
        if not ((kind == "tts" or SOUND_NAME_RE.match(name)) and os.path.isfile(path)):
            raise ValueError("sound file not found")
        r = subprocess.run(["ffmpeg", "-loglevel", "error", "-i", path, "-t", "300", "-f", "s16le", "-ac", "1", "-ar", str(rate), "-"],
                           capture_output=True, timeout=60)
        y = np.frombuffer(r.stdout[:len(r.stdout) // 2 * 2], dtype="<i2").astype(np.float32) / 32768.0
        if not y.size:
            raise ValueError("the sound file could not be read")
        return np.tile(y, int(math.ceil(n / y.size)))[:n] if y.size < n else y[:n]
    if kind == "two-tone":
        f = np.where((t % 1.2) < 0.6, 960.0, 770.0)
        env = np.ones(n)
    elif kind == "beeps":
        f = np.full(n, 2400.0); env = _smooth((t % 0.25) < 0.12, rate)
    elif kind == "horn":
        f = np.full(n, 330.0); env = _smooth((t % 1.5) < 1.0, rate)
    elif kind == "whistle":                              # high, fast sweeps (many animals react strongly; small speakers manage)
        f = 6500.0 + 3500.0 * np.abs(((t * 3.0) % 2.0) - 1.0)
        env = _smooth((t % 0.6) < 0.45, rate)
    elif kind == "bangs":                                # short loud noise bursts at irregular times, like claps / banging
        rng_ = np.random.default_rng(7)
        y = np.zeros(n, np.float32); pos = 0.0
        while pos < seconds:
            i = int(pos * rate); L = int(0.06 * rate)
            if i >= n:
                break
            burst = rng_.uniform(-1, 1, min(L, n - i)).astype(np.float32) * np.exp(-np.arange(min(L, n - i)) / (0.012 * rate)).astype(np.float32)
            y[i:i + burst.size] += burst
            pos += float(rng_.uniform(0.18, 0.7))
        return (y / max(1e-6, float(np.max(np.abs(y))))).astype(np.float32)
    else:                                                # siren: rising and falling
        f = 950.0 + 550.0 * np.sin(2 * np.pi * t / 1.8)
        env = np.ones(n)
    ph = 2 * np.pi * np.cumsum(f) / rate
    y = np.sin(ph) + 0.35 * np.sin(2 * ph) + 0.2 * np.sin(3 * ph)          # some harmonics: louder on small speakers
    if kind == "horn":
        y = y + 0.25 * np.sin(4 * ph) + 0.15 * np.sin(5 * ph)
    y = y / np.max(np.abs(y)) * env
    fade = min(n // 4, int(rate * 0.02))
    if fade:
        y[:fade] *= np.linspace(0, 1, fade); y[-fade:] *= np.linspace(1, 0, fade)
    return y.astype(np.float32)


def sound_play(kind=None, seconds=None, volume=None, reason="test"):
    """Play a sound on the loudspeaker of the Pi. Returns (ok, error). Runs in the background."""
    if sim_speaker_only(reason):                         # 554: test inbox / no loudspeaker - only the simulator plays it
        return sim_sound_play(kind, seconds, volume, reason)
    dev = CFG["audio_out"]
    if not out_selected():
        return False, "no loudspeaker selected"
    if not dev.startswith("bt:") and not shutil.which("aplay"):
        return False, "aplay is missing (sudo apt install alsa-utils)"
    kind = kind or CFG["siren_sound"]
    if kind not in SOUND_KINDS + ("marmot", "chime", "birds", "tts", "beep1", "beep2", "beep3", "beep4", "beeplow") and not (kind.startswith("file:") and kind[5:] in own_sounds()):
        kind = "siren"
    seconds = max(0.5, min(120.0, float(seconds if seconds is not None else CFG["siren_seconds"])))
    vol = max(0.0, min(100.0, float(volume if volume is not None else CFG["siren_volume"]))) / 100.0
    sound_stop(); talk_stop()
    with _SOUND_LOCK:
        SOUND["gen"] += 1; gen = SOUND["gen"]
        SOUND["playing"] = True; SOUND["msg"] = ""
        SOUND.update(kind=kind, virt=False, vol=vol * 100.0)          # 554: what plays (for the simulator)

    def work():
        p = None
        try:
            y = sound_samples(kind, seconds)
            data = (np.clip(y * (vol ** 2), -1, 1) * 32767).astype("<i2").tobytes()     # volume: squared feels linear to the ear
            cmd, err = out_cmd(OUT_RATE)                  # Bluetooth: connects first if needed (a few seconds)
            if cmd is None:
                raise RuntimeError(err)
            with _SOUND_LOCK:
                if gen != SOUND["gen"]:
                    return
                p = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
                SOUND["proc"] = p
            if AUDIO is not None:
                AUDIO.mute_until = time.time() + seconds + 2.0
            try:
                p.stdin.write(data); p.stdin.close()
            except (BrokenPipeError, OSError):
                pass
            try:
                p.wait(timeout=seconds + 30)
            except subprocess.TimeoutExpired:           # 2.95.34: hangs (Bluetooth) - free the sound device
                p.kill(); p.wait(timeout=5)
            err = (p.stderr.read() or b"").decode(errors="replace").strip()
            if p.returncode not in (0, -9, -15) and gen == SOUND["gen"]:
                SOUND["msg"] = (err.splitlines()[-1] if err else f"{cmd[0]} exit {p.returncode}")[:200]
                log_event("sys", f"Loudspeaker: {SOUND['msg']}")
        except Exception as e:
            SOUND["msg"] = str(e)[:200]
            log_event("sys", f"Loudspeaker: {SOUND['msg']}")
        finally:
            with _SOUND_LOCK:
                if gen == SOUND["gen"]:
                    SOUND["playing"] = False; SOUND["proc"] = None
            if AUDIO is not None:
                AUDIO.mute_until = time.time() + 2.0      # the echo of the room must not trigger the noise alarm
    threading.Thread(target=work, daemon=True, name="sound").start()
    if reason != "test":
        log_event("sys", f"Loudspeaker: {kind} for {seconds:.0f} s ({reason})")
    return True, ""


# ---- spoken announcement from text (offline): pico2wave (nicer voice) or espeak-ng ----
TTS = {"file": os.path.join(tempfile.gettempdir(), "motionwatch_tts.wav")}
_TTS_VOICES = {"de": ("de-DE", "de"), "fr": ("fr-FR", "fr"), "it": ("it-IT", "it"), "rm": ("de-DE", "de"), "en": ("en-GB", "en")}


def tts_engine():
    for e in ("pico2wave", "espeak-ng", "espeak"):
        if shutil.which(e):
            return e
    return None


def tts_make(text, lang, path):
    eng = tts_engine()
    if eng is None:
        return False, "no speech program (sudo apt install espeak-ng - or libttspico-utils for a nicer voice)"
    pico, esp = _TTS_VOICES.get(norm_lang(lang), ("de-DE", "de"))
    cmd = (["pico2wave", "-l", pico, "-w", path, text] if eng == "pico2wave"
           else [eng, "-v", esp, "-s", "145", "-a", "200", "-w", path, text])
    try:
        r = subprocess.run(cmd, capture_output=True, timeout=30)
    except (OSError, subprocess.SubprocessError) as e:
        return False, str(e)[:120]
    if r.returncode != 0 or not os.path.isfile(path) or os.path.getsize(path) < 100:
        return False, (r.stderr or b"").decode(errors="replace").strip()[:120] or "speech failed"
    return True, ""


def tts_say(text, lang=None, save=False):
    """Speak a text on the loudspeaker; save=True also keeps it as an own sound («Announcement ….wav»)."""
    text = re.sub(r"[\x00-\x1f]", " ", str(text or "")).strip()[:200]
    if not text:
        return False, "empty text"
    lang = norm_lang(lang or CFG["lang"])
    if save:
        import unicodedata
        tx = text
        for x, y in (("ä", "ae"), ("ö", "oe"), ("ü", "ue"), ("Ä", "Ae"), ("Ö", "Oe"), ("Ü", "Ue"), ("ß", "ss")):
            tx = tx.replace(x, y)
        tx = unicodedata.normalize("NFKD", tx).encode("ascii", "ignore").decode()
        nm = re.sub(r"[^A-Za-z0-9 _\-]", "", tx)[:40].strip() or "text"
        path = os.path.join(sounds_dir(), f"{tr('Announcement', lang)} {nm}.wav")
        path = path.encode("ascii", "ignore").decode()
        os.makedirs(sounds_dir(), exist_ok=True)
        ok, err = tts_make(text, lang, path)
        if not ok:
            return False, err
        log_event("sys", f"Announcement saved as sound: {os.path.basename(path)}")
        return True, os.path.basename(path)
    ok, err = tts_make(text, lang, TTS["file"])
    if not ok:
        return False, err
    try:
        import wave
        with wave.open(TTS["file"]) as w_:
            dur = w_.getnframes() / float(w_.getframerate() or 1)
    except Exception:
        dur = 5.0
    log_event("sys", f"Announcement: «{text[:60]}»")
    return sound_play("tts", dur + 0.3, None, reason="test")


def sound_stop():
    with _SOUND_LOCK:
        SOUND["gen"] += 1
        p = SOUND["proc"]; SOUND["proc"] = None; SOUND["playing"] = False
    if p is not None:
        try:
            p.kill()
        except Exception:
            pass


def siren_quiet():
    """2.97.0: no real siren while the test inbox takes the messages (simulation, game round, drill, demo)"""
    try:
        return sandbox_active()
    except Exception:
        return False


def siren_alarm(kind):
    """Siren on the Pi at an alarm (only when armed). siren_on: off | person | alarm (person, thermal, noise) | all (+ pre-alarm)."""
    mode = CFG["siren_on"]
    if mode == "off" or not speaker_ok() or not is_armed() or SOUND["playing"] or TALK["proc"] is not None:
        return                                           # somebody talks through the loudspeaker: no siren over the voice
    if siren_quiet() and not sim_speaker():
        log_event("sys", f"Siren held back ({kind}): simulation / game / drill - into the test inbox")
        return                                           # 554: with the simulator it plays there (sound_play), never for real
    if kind == "person" and CFG.get("escalate_on"):
        return                                           # 2.97.0: the escalation decides (light now, siren after the wait)
    if kind == "prealarm" and mode != "all":
        return
    if kind in ("warm", "noise") and mode not in ("alarm", "all"):
        return
    now = time.time()
    if now - SOUND["last_alarm"] < float(CFG["siren_pause"]):
        return
    SOUND["last_alarm"] = now
    sound_play(None, None, None, reason={"person": "person alarm", "warm": "thermal alarm", "noise": "noise alarm",
                                         "prealarm": "pre-alarm", "tamper": "sabotage alarm", "sensor": "sensor alarm"}.get(kind, kind))


# ----------------------------------------------------------------------------
# Idea of Daniel's daughter: MoveEye stands somewhere in the room. While you sleep the camera looks away (a set direction,
# e.g. the door). When the alarm rings it turns to the sleeping place and understands two gestures:
#   wave (hand to and fro)  -> snooze (again after N minutes)
#   sit up / get up         -> alarm off
# The sleeping place is a zone of the kind "sleep" (zone editor): it is covered in black in every picture, in every direction
# of the camera (030: sleep_polys). Only the gesture detection here gets the picture of the bed - small, grey, in memory,
# only while the alarm rings, never stored or sent.
# ----------------------------------------------------------------------------
WAKE = {"state": "off", "due": 0.0, "until": 0.0, "t0": 0.0, "snoozes": 0, "done": 0.0, "msg": "", "gest": "", "gest_t": 0.0,
        "test": False, "light_prev": None, "light_t": 0.0, "snd_t": 0.0, "level": 0.0, "last": "", "pos_t": 0.0}
WAKE_LOCK = threading.Lock()
WAKE_DAYS = {"all": (0, 1, 2, 3, 4, 5, 6), "mon-fri": (0, 1, 2, 3, 4), "sat-sun": (5, 6), "sun-thu": (6, 0, 1, 2, 3), "once": (0, 1, 2, 3, 4, 5, 6)}
_HM_RE = re.compile(r"^([01]?\d|2[0-3]):([0-5]\d)$")


def _hm(s):
    m = _HM_RE.match(str(s or "").strip())
    return (int(m.group(1)), int(m.group(2))) if m else None


def wake_next(now=None):
    """the next moment the alarm rings (timestamp) or 0"""
    if not CFG.get("wake_on"):
        return 0.0
    hm = _hm(CFG.get("wake_time"))
    if hm is None:
        return 0.0
    now = time.time() if now is None else now
    days = WAKE_DAYS.get(CFG.get("wake_days"), WAKE_DAYS["all"])
    d0 = datetime.fromtimestamp(now)
    for k in range(0, 9):
        d = (d0 + timedelta(days=k)).replace(hour=hm[0], minute=hm[1], second=0, microsecond=0)
        if d.weekday() in days and d.timestamp() > now:
            return d.timestamp()
    return 0.0


def wake_sleep_from(due):
    """when the night before the alarm `due` starts (the camera looks away from then on) - 0 = not wanted.
    2.98.9: the ONE night time of MoveEye (report_from, Einstellungen → Nachtbericht) - also for the night report and
    «Heute Nacht bewachen»."""
    if not CFG.get("wake_away_night", True) or not due:
        return 0.0
    d = datetime.fromtimestamp(due)
    s = d.replace(hour=int(CFG.get("report_from", 22)) % 24, minute=0, second=0, microsecond=0)
    if s >= d:
        s -= timedelta(days=1)
    return s.timestamp()


def bed_zone():
    zs = sleep_zones()
    return zs[0] if zs else None


def _pct(deg, axis):
    return max(0.0, min(100.0, 50.0 + deg / servo_half(axis) * 50.0))


def bed_view():
    """(pan %, tilt %) that looks at the middle of the sleeping place, or None"""
    z = bed_zone()
    if not z:
        return None
    a = sum(p[0] for p in z["ang"]) / len(z["ang"]); e = sum(p[1] for p in z["ang"]) / len(z["ang"])
    return round(_pct(a, "pan"), 2), round(_pct(e, "tilt"), 2)


def away_view():
    p, t = float(CFG.get("wake_away_pan", -1)), float(CFG.get("wake_away_tilt", -1))
    return (p, t) if 0 <= p <= 100 and 0 <= t <= 100 else None


def wake_clap_listens():
    """2.98.9: while the alarm rings, clapping 2 times = snooze (the melody pauses 8 s of every 20 s so the microphone hears it)"""
    sim_ear = AUDIO is not None and time.time() - AUDIO.sim_t < 3.0        # 2.98.11: the simulator supplies the sound
    return WAKE["state"] == "ring" and bool(CFG.get("wake_clap", True)) and (bool(CFG.get("audio_in")) or sim_ear)


def wake_hold():
    """the wake-up alarm holds the head (sleeping: looks away, ringing: looks at the bed) - tracking, patrol and the
    timelapse leave it alone"""
    return WAKE["state"] in ("sleep", "ring", "snooze")


def _look(pos):
    if pos and not manual_active() and (abs(CFG["pan"] - pos[0]) > 0.3 or abs(CFG["tilt"] - pos[1]) > 0.3):
        CFG["pan"], CFG["tilt"] = float(pos[0]), float(pos[1])
        WAKE["pos_t"] = time.time()


def _light(on):
    if not CFG.get("wake_light"):
        return
    try:
        if on:
            if WAKE["light_prev"] is None:
                WAKE["light_prev"] = CFG.get("light_white") or "auto"
            light_set("white", "on")
        elif WAKE["light_prev"] is not None:
            light_set("white", WAKE["light_prev"])
            WAKE["light_prev"] = None
        WAKE["light_t"] = time.time()
    except Exception as e:
        log_event("sys", f"Wake-up light: {e}")


def _ring_sound(now):
    """the melody again every 20 s, a little louder each time (from 40 % up to the set volume in about 2 minutes)"""
    if now - WAKE["snd_t"] < 20.0:
        return
    WAKE["snd_t"] = now
    full = float(CFG.get("wake_volume", 60))
    WAKE["level"] = min(full, max(full * 0.4, WAKE["level"] + full * 0.1)) if WAKE["level"] else full * 0.4
    kind = CFG.get("wake_sound") or "chime"
    ok, err = sound_play(kind, 12.0 if wake_clap_listens() else 19.0, WAKE["level"], reason="wake-up alarm")
    if not ok:
        WAKE["msg"] = err


def wake_ring(test=False, who="time"):
    with WAKE_LOCK:
        WAKE.update(state="ring", t0=time.time(), test=bool(test), snd_t=0.0, level=0.0, gest="", until=0.0)
    WAKEG.reset()
    MANUAL["until"] = 0.0                                  # the alarm wins over a hand-moved camera
    _look(bed_view())
    _light(True)
    log_event("sys", "Wake-up alarm rings" + (" (test)" if test else "") + f" ({who})")


def wake_snooze(who="web"):
    if WAKE["state"] != "ring":
        return False, "the alarm does not ring"
    sound_stop()
    _light(False)
    mins = float(CFG.get("wake_snooze", 9))
    with WAKE_LOCK:
        WAKE.update(state="snooze", until=time.time() + mins * 60.0, snoozes=WAKE["snoozes"] + 1, last=f"snooze ({who})")
    MANUAL["until"] = 0.0
    _look(away_view())
    log_event("sys", f"Wake-up alarm: snooze {mins:g} min ({who})")
    return True, ""


def wake_stop(who="web"):
    if WAKE["state"] not in ("ring", "snooze", "sleep"):
        return False, "the alarm is not on"
    was = WAKE["state"]
    sound_stop()
    _light(False)
    with WAKE_LOCK:
        if was in ("ring", "snooze"):
            WAKE["done"] = WAKE["due"] or time.time()
        WAKE.update(state="off", until=0.0, test=False, last=f"off ({who})", snoozes=0)
    if was in ("ring", "snooze") and CFG.get("wake_days") == "once" and not WAKE.get("test"):
        CFG["wake_on"] = False; save_settings()
    log_event("sys", f"Wake-up alarm off ({who})")
    return True, ""


def wake_sleep_now(who="web"):
    """«Gute Nacht»: look away now (until the alarm)"""
    if not WAKE["due"]:
        return False, "no alarm set"
    WAKE["state"] = "sleep"; WAKE["sleep_now"] = WAKE["due"]
    _look(away_view())
    log_event("sys", f"Wake-up alarm: good night - the camera looks away ({who})")
    return True, ""


def wake_tick():
    """once a second (Scheduler thread)"""
    now = time.time()
    st = WAKE["state"]
    if st in ("off", "sleep"):
        due = wake_next(now - 90.0)                          # an alarm of the last 90 s still rings (a busy second is not lost)
        if due and due <= WAKE["done"] + 1.0:
            due = wake_next(max(now, WAKE["done"] + 1.0))
        WAKE["due"] = due
        if due and now >= due and due > WAKE["done"]:
            wake_ring(False, "time")
            return
        sf = wake_sleep_from(due)
        night = bool(due) and ((sf and sf <= now < due) or WAKE.get("sleep_now") == due)
        if night and away_view() is not None:
            if st != "sleep":
                log_event("sys", "Wake-up alarm: night - the camera looks away from the sleeping place")
            WAKE["state"] = "sleep"
            _look(away_view())
        elif st == "sleep":
            WAKE["state"] = "off"
        return
    if st == "snooze":
        _look(away_view())
        if now >= WAKE["until"]:
            wake_ring(WAKE["test"], "snooze over")
        return
    if st == "ring":
        _look(bed_view())
        _ring_sound(now)
        g = WAKE.get("gest") if now - WAKE.get("gest_t", 0.0) < 3.0 else ""
        if g == "wave":
            WAKE["gest"] = ""; wake_snooze("gesture: waving")
        elif g == "up":
            WAKE["gest"] = ""; wake_stop("gesture: got up")
        elif now - WAKE["t0"] > float(CFG.get("wake_ring_max", 15)) * 60.0:
            wake_stop("nobody reacted")
            try:
                w_ = WATCH_REF.get("w")
                if w_ is not None:
                    w_.notifier.alert("{name}: " + tr("Wake-up alarm"), tr("The alarm rang without a reaction and stopped by itself."), None)
            except Exception:
                pass


def wake_state(lang=None):
    z = bed_zone()
    return {"on": bool(CFG.get("wake_on")), "state": WAKE["state"], "due": int(WAKE["due"] or wake_next()), "until": int(WAKE["until"]),
            "snoozes": WAKE["snoozes"], "bed": bool(z), "bed_name": (z or {}).get("name", ""), "away": away_view() is not None,
            "gest": WAKE.get("gest_show", ""), "last": WAKE["last"], "msg": WAKE["msg"], "spk": bool(out_selected()),
            "sleep_from": int(wake_sleep_from(WAKE["due"] or wake_next())), "gestures": bool(CFG.get("wake_gestures", True))}


class WakeGestures:
    """2.98.7: two gestures in the picture of the sleeping place while the alarm rings - without any AI model, also in the
    dark (infrared): the difference between two pictures shows what moves.
      waving  = a small moving area whose middle goes to and fro (3 turns in 3 s; at a low frame rate: moving most of
                the time over 2 s with a clear sideways range)
      getting up = a big part of the bed and of the area above it moves for more than ~1.5 s
    The first 2 s after the head turned or the light went on are ignored (everything changes then)."""
    W = 320

    def __init__(self):
        self.reset()

    def reset(self):
        self.prev = None; self.hist = deque(); self.t0 = time.time(); self.roi = None
        self.base = None; self.changed_t = 0.0                  # the picture of the bed when it started to ring (sitting up = differs)

    def _roi(self, w, h):
        z = bed_zone()
        if not z:
            return None
        pp = sleep_project(z["ang"], CFG["pan"], CFG["tilt"])
        if not pp:
            return None
        xs = [p[0] for p in pp]; ys = [p[1] for p in pp]
        x0, x1, y0, y1 = min(xs), max(xs), min(ys), max(ys)
        bw, bh = x1 - x0, y1 - y0
        x0 -= bw * 0.15; x1 += bw * 0.15; y0 -= bh * 0.8          # above the bed: sitting up, a raised hand
        x0, x1 = max(0.0, x0), min(1.0, x1); y0, y1 = max(0.0, y0), min(1.0, y1)
        if x1 - x0 < 0.05 or y1 - y0 < 0.05:
            return None
        return int(x0 * w), int(y0 * h), int(x1 * w), int(y1 * h)

    def feed(self, frame, now=None):
        """frame: BGR picture before the privacy mask. Returns "wave", "up" or ""."""
        if not CFG.get("wake_gestures", True) or frame is None:
            return ""
        now = time.time() if now is None else now
        H, W = frame.shape[:2]
        h = int(H * self.W / W)
        g = cv2.cvtColor(cv2.resize(frame, (self.W, h), interpolation=cv2.INTER_AREA), cv2.COLOR_BGR2GRAY)
        roi = self._roi(self.W, h)
        if roi is None:
            self.prev = None
            return ""
        x0, y0, x1, y1 = roi
        r = cv2.GaussianBlur(g[y0:y1, x0:x1], (5, 5), 0).astype(np.float32)
        if self.prev is not None and self.prev.shape == r.shape and float(cv2.absdiff(r, self.prev).max()) < 1.5:
            return ""                                          # the same picture again (the camera is slower than the loop)
        prev, self.prev = self.prev, r
        quiet = max(WAKE.get("pos_t", 0.0), WAKE.get("light_t", 0.0), float(SERVO_MOVE.get("t", 0.0)), self.t0)
        if prev is None or prev.shape != r.shape or now - quiet < 2.0:
            self.hist.clear(); self.base = None; self.changed_t = 0.0
            return ""
        if self.base is None or self.base.shape != r.shape:
            self.base = r.copy()
        thr = max(6.0, 0.035 * float(prev.mean()))            # little contrast (infrared, a washed-out bright room): a low threshold
        m = (cv2.absdiff(r, prev) > thr).astype(np.uint8)
        m = cv2.dilate(cv2.erode(m, np.ones((2, 2), np.uint8)), np.ones((3, 3), np.uint8))   # no single grains, thin arms stay
        frac = float(m.mean())
        if frac > 0.85:                                        # everything changed (light, a jolt): not a gesture
            self.hist.clear()
            return ""
        cx = None
        if frac > 0.0012:                                      # the biggest moving thing (not the moths at the lamp, not the grain)
            nl, lab, st, cen = cv2.connectedComponentsWithStats(m, connectivity=8)
            if nl > 1:
                j = 1 + int(np.argmax(st[1:, cv2.CC_STAT_AREA]))
                frac = float(st[j, cv2.CC_STAT_AREA]) / float(m.size)
                cx = float(cen[j][0]) / max(1, m.shape[1])
            if frac <= 0.0012:
                cx = None
        self.hist.append((now, cx, frac))
        while self.hist and now - self.hist[0][0] > 4.0:
            self.hist.popleft()
        # sitting up / out of bed: the picture stays different from the one when it began to ring (and nothing moves now)
        bd = (cv2.absdiff(r - float(r.mean()), self.base - float(self.base.mean())) > thr * 1.5).astype(np.uint8)   # brightness drift (exposure) does not count
        bfrac = float(cv2.morphologyEx(bd, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8)).mean())
        self.bfrac = bfrac
        if bfrac > 0.03 and frac < 0.01:
            if not self.changed_t:
                self.changed_t = now
            elif now - self.changed_t >= 2.5:
                return "up"
        elif bfrac <= 0.03:
            self.changed_t = 0.0
        return self._judge(now)

    @staticmethod
    def _turns(cs, step=0.03):
        turns, d, ref = 0, 0, cs[0]
        for c in cs[1:]:
            if abs(c - ref) >= step:
                s = 1 if c > ref else -1
                if d and s != d:
                    turns += 1
                d, ref = s, c
        return turns

    def _judge(self, now):
        """2.98.9: measured in the 3D simulator (bedroom scene, 2-3 pictures per second, 4 m away): the arm is small in the
        picture, getting up is a path across the picture rather than a big area"""
        H_ = list(self.hist)
        n_all = max(1, len(H_))
        pts = [(t, c, f) for t, c, f in H_ if c is not None]
        if not pts:
            return ""
        cs = [c for _t, c, _f in pts]
        span = pts[-1][0] - pts[0][0]
        rng = max(cs) - min(cs)
        moving = len(pts) / n_all
        meanf = sum(f for _t, _c, f in pts) / len(pts)
        turns = self._turns(cs)
        # getting up: a big moving area for 1.2 s, or something big enough travels across (out of the bed)
        big = [(t, f) for t, _c, f in pts if now - t <= 2.5 and f > 0.12]
        if len(big) >= 3 and big[-1][0] - big[0][0] >= 1.2:
            return "up"
        if span >= 2.0 and moving >= 0.6 and meanf >= 0.008 and abs(cs[-1] - cs[0]) >= 0.3 and turns <= 1:
            return "up"
        # waving: a small area going to and fro in one place - and the bed looks as before (sitting up changes it a lot)
        if len(pts) >= 4 and meanf < 0.025 and rng < 0.5 and getattr(self, "bfrac", 0.0) < 0.03:
            if turns >= 3:
                return "wave"
            if span >= 2.0 and moving >= 0.6 and meanf < 0.025 and rng < 0.35 and abs(cs[-1] - cs[0]) < 0.2 and len(pts) <= 14:
                return "wave"                                   # few pictures per second: the hand moves on and on in one place
        return ""


WAKEG = WakeGestures()


def wake_feed(frame):
    """from the main loop, before the privacy mask - only while the alarm rings"""
    if WAKE["state"] != "ring":
        return
    try:
        g = WAKEG.feed(frame)
    except Exception as e:
        log_event("sys", f"Wake-up gestures: {e}")
        return
    if g:
        WAKE["gest"] = g; WAKE["gest_t"] = time.time()
        WAKE["gest_show"] = g
        WAKEG.hist.clear()


def wake_text(lang=None):
    """one status line (window and web page)"""
    lang = norm_lang(lang or CFG["lang"])
    st = WAKE["state"]
    hm = lambda ts: datetime.fromtimestamp(ts).strftime("%H:%M")
    if st == "ring":
        return "🔔 " + tr("rings", lang) + (" – " + tr("wave = snooze, sit up = off", lang) if CFG.get("wake_gestures", True) else "")
    if st == "snooze":
        return "😴 " + tr("snoozing until", lang) + " " + hm(WAKE["until"])
    if st == "sleep":
        return "🌙 " + tr("night: the camera looks away until", lang) + " " + hm(WAKE["due"])
    if not CFG.get("wake_on"):
        return tr("off", lang)
    due = WAKE["due"] or wake_next()
    days = {"de": "Mo Di Mi Do Fr Sa So", "rm": "Gli Ma Me Gie Ve So Du", "fr": "lu ma me je ve sa di", "it": "lu ma me gi ve sa do"}.get(lang, "Mon Tue Wed Thu Fri Sat Sun").split()
    txt = (tr("next alarm", lang) + ": " + days[datetime.fromtimestamp(due).weekday()] + " " + hm(due)) if due else tr("no time set", lang)
    warn = []
    if not bed_zone():
        warn.append(tr("no sleeping place yet (Zones → + Sleeping place)", lang))
    if away_view() is None and CFG.get("wake_away_night", True):
        warn.append(tr("no direction for the night yet (button «Look here at night»)", lang))
    if not out_selected():
        warn.append(tr("no loudspeaker selected", lang))
    return txt + ("".join(" · ⚠ " + w for w in warn))


def wake_away_here(who="web"):
    CFG["wake_away_pan"] = round(float(CFG["pan"]), 2); CFG["wake_away_tilt"] = round(float(CFG["tilt"]), 2)
    save_settings()
    log_event("sys", f"Wake-up alarm: direction for the night = pan {CFG['pan']:.0f} %, tilt {CFG['tilt']:.0f} % ({who})")
    return True, ""


def wake_action(a, who="web"):
    """web / window / MQTT: test | snooze | stop | away_here | sleep_now"""
    if a == "test":
        if not bed_zone():
            return False, "no sleeping place yet (Zones → + Sleeping place)"
        wake_ring(True, who); return True, ""
    if a == "snooze":
        return wake_snooze(who)
    if a == "stop":
        return wake_stop(who)
    if a == "away_here":
        return wake_away_here(who)
    if a == "sleep_now":
        return wake_sleep_now(who)
    return False, "unknown action"
# ----------------------------------------------------------------------------
# A small area only for the developer (Daniel). It is HIDDEN until it is switched on, and protected with its own PIN.
# What it shows is only about THIS device and is read-only - never the traffic of other people:
#   - the device's own open network connections (to where, which program, how much data) with a reverse-DNS name
#   - the names the device itself looked up (its own DNS questions, from the connections it holds)
#   - the data volume per network card (how much came in and went out since the start)
#   - the programs that listen on a port on this device
# No «sniffer» of foreign packets, no promiscuous / monitor mode, no password cracking, no scan of other devices.
# That keeps it on the right side of the law (Art. 143bis / 179novies StGB, data-protection act): the developer looks at
# his own machine, like `ss`, `netstat` or a router page do. Every time the area is opened and every look is written to the
# log (kind «dev»). Short-lived snapshots (the lists below) are kept at most 24 h in memory, never on disk.
# ----------------------------------------------------------------------------
import socket

DEV = {"token": "", "token_t": 0.0, "fails": [], "snaps": deque(maxlen=48)}   # snaps: (t, kind) - for the 24 h note only
DEV_TTL = 900.0                       # an unlock lasts 15 minutes
_DEV_IFACE_BASE = {}


def dev_available():
    """the area exists only when it was switched on (CFG.dev_area) - otherwise it is invisible everywhere"""
    return bool(CFG.get("dev_area"))


def dev_pin_ok(pin):
    h = CFG.get("dev_pin") or ""
    if not h or "$" not in h or not isinstance(pin, str):
        return False
    try:
        return hmac.compare_digest(_pin_hash(pin.strip(), h.split("$", 1)[0]), h)
    except Exception:
        return False


def dev_pin_set(new_pin, old_pin=""):
    new_pin = str(new_pin or "").strip()
    if CFG.get("dev_pin") and not dev_pin_ok(old_pin):
        return False, "wrong PIN"
    if new_pin and not re.fullmatch(r"\d{4,10}", new_pin):
        return False, "the PIN must have 4 to 10 digits"
    CFG["dev_pin"] = _pin_hash(new_pin) if new_pin else ""
    save_settings()
    log_event("dev", "Developer PIN " + ("set" if new_pin else "removed"))
    return True, ""


def dev_unlocked():
    return bool(DEV["token"]) and time.time() - DEV["token_t"] < DEV_TTL


def dev_unlock(pin, source="web"):
    now = time.time()
    DEV["fails"] = [t for t in DEV["fails"] if now - t < 600]
    if len(DEV["fails"]) >= 5:
        return False, "too many wrong PINs - try again in 10 minutes", ""
    if CFG.get("dev_pin") and not dev_pin_ok(pin):
        DEV["fails"].append(now)
        log_event("dev", f"Developer area: wrong PIN ({source})")
        return False, "wrong PIN", ""
    DEV["token"] = secrets.token_urlsafe(18); DEV["token_t"] = now
    log_event("dev", f"Developer area opened ({source})")
    return True, "", DEV["token"]


def dev_token_ok(tok):
    return dev_unlocked() and isinstance(tok, str) and tok and hmac.compare_digest(tok, DEV["token"])


def dev_lock():
    DEV["token"] = ""; DEV["token_t"] = 0.0


def _dev_note(kind):
    DEV["snaps"].append((time.time(), kind))


def _rev_dns(ip):
    try:
        return socket.gethostbyaddr(ip)[0]
    except Exception:
        return ""


_DEV_PROC_CACHE = {"t": 0.0, "map": {}}


def _dev_proc_map():
    """inode -> (pid, program) for the own sockets (from /proc), so a connection can show which program it belongs to.
    Only this device's own processes - the same a task manager shows."""
    now = time.time()
    if now - _DEV_PROC_CACHE["t"] < 2.0:
        return _DEV_PROC_CACHE["map"]
    m = {}
    try:
        for pid in os.listdir("/proc"):
            if not pid.isdigit():
                continue
            fd = "/proc/%s/fd" % pid
            try:
                names = os.listdir(fd)
            except OSError:
                continue
            name = ""
            for f in names:
                try:
                    link = os.readlink(os.path.join(fd, f))
                except OSError:
                    continue
                if link.startswith("socket:["):
                    if not name:
                        try:
                            with open("/proc/%s/comm" % pid) as c:
                                name = c.read().strip()
                        except OSError:
                            name = "?"
                    m[link[8:-1]] = (pid, name)
    except OSError:
        pass
    _DEV_PROC_CACHE.update(t=now, map=m)
    return m


def _hx_ip(hx):
    """the little-endian hex address of /proc/net/tcp -> a readable IP"""
    if len(hx) == 8:
        b = bytes.fromhex(hx)
        return ".".join(str(x) for x in b[::-1])
    try:
        parts = [hx[i:i + 8] for i in range(0, 32, 8)]
        segs = []
        for p in parts:
            b = bytes.fromhex(p)[::-1]
            segs.append("%02x%02x" % (b[0], b[1])); segs.append("%02x%02x" % (b[2], b[3]))
        ip = ":".join(segs)
        import ipaddress as _ipa
        return str(_ipa.ip_address(int(_ipa.IPv6Address(ip))))
    except Exception:
        return hx


_TCP_STATES = {"01": "aktiv", "02": "SYN", "06": "wartet", "08": "wartet", "0A": "lauscht"}


def dev_connections():
    """the device's own TCP connections to the outside (established or listening), with program and reverse-DNS name.
    Read from /proc/net - the same data `ss` or `netstat` show. Only this machine."""
    _dev_note("connections")
    pm = _dev_proc_map()
    seen_names = {}
    out = []
    for fn in ("/proc/net/tcp", "/proc/net/tcp6"):
        try:
            with open(fn) as f:
                rows = f.read().splitlines()[1:]
        except OSError:
            continue
        for ln in rows[:4000]:
            p = ln.split()
            if len(p) < 10:
                continue
            la, lp = p[1].split(":"); ra, rp = p[2].split(":")
            st = p[3].upper(); rip = _hx_ip(ra); lport = int(lp, 16); rport = int(rp, 16)
            if st not in _TCP_STATES or (st != "0A" and rport == 0):
                continue
            pid, prog = pm.get(p[9], ("", ""))
            local = st == "0A" or rip in ("0.0.0.0", "::", "127.0.0.1", "::1")
            name = ""
            if not local and rip:
                name = seen_names.get(rip)
                if name is None:
                    name = _rev_dns(rip); seen_names[rip] = name
            out.append({"state": _TCP_STATES.get(st, st), "lport": lport, "rip": "" if st == "0A" else rip, "rport": rport,
                        "host": name, "prog": prog, "pid": pid, "listen": st == "0A", "local": local})
    out.sort(key=lambda x: (x["listen"], x["local"], x["host"] or x["rip"]))
    return out[:400]


def dev_dns():
    """the names the device itself reached (from its own open connections) - a reverse-DNS of the outside addresses,
    grouped. This is the device's own activity, not anybody else's."""
    _dev_note("dns")
    hosts = {}
    for c in dev_connections():
        if c["listen"] or c["local"] or not c["rip"]:
            continue
        key = c["host"] or c["rip"]
        e = hosts.setdefault(key, {"host": c["host"], "ip": c["rip"], "ports": set(), "progs": set()})
        e["ports"].add(c["rport"])
        if c["prog"]:
            e["progs"].add(c["prog"])
    res = [{"host": v["host"], "ip": v["ip"], "ports": sorted(v["ports"])[:8], "progs": sorted(v["progs"])} for v in hosts.values()]
    res.sort(key=lambda x: x["host"] or x["ip"])
    return res


def dev_ifaces():
    """data volume per network card since the start of the system (/proc/net/dev) - how much came in and went out.
    Only this device's own cards."""
    _dev_note("ifaces")
    out = []
    try:
        with open("/proc/net/dev") as f:
            rows = f.read().splitlines()[2:]
    except OSError:
        return out
    now = time.time()
    for ln in rows:
        if ":" not in ln:
            continue
        name, rest = ln.split(":", 1)
        name = name.strip()
        if name == "lo":
            continue
        v = rest.split()
        if len(v) < 16:
            continue
        rx, tx = int(v[0]), int(v[8])
        base = _DEV_IFACE_BASE.get(name)
        rate_rx = rate_tx = None
        if base and now - base[0] > 0.5:
            rate_rx = max(0, rx - base[1]) / (now - base[0])
            rate_tx = max(0, tx - base[2]) / (now - base[0])
        _DEV_IFACE_BASE[name] = (now, rx, tx)
        out.append({"name": name, "rx": rx, "tx": tx, "rx_rate": rate_rx, "tx_rate": rate_tx,
                    "up": int(v[3]) >= 0 and (rx > 0 or tx > 0)})
    out.sort(key=lambda x: -(x["rx"] + x["tx"]))
    return out


def dev_state(lang=None):
    """everything for the developer page (only if unlocked)"""
    cutoff = time.time() - 86400
    recent = sum(1 for t, _k in DEV["snaps"] if t > cutoff)
    return {"on": dev_available(), "has_pin": bool(CFG.get("dev_pin")), "unlocked": dev_unlocked(),
            "left": int(max(0, DEV_TTL - (time.time() - DEV["token_t"]))) if dev_unlocked() else 0,
            "looks_24h": recent, "host": socket.gethostname(), "uid": device_uid()}


DEV_PAGE = _zd('258_entwickler/DEV_PAGE', ZD_PAGE)

DEV_DE = {"Developer": "Entwickler", "Lock": "Sperren", "Connections": "Verbindungen", "Reached names": "Erreichte Namen",
          "Data volume": "Datenmenge", "open for": "offen noch", "Set a PIN for the developer area (4 to 10 digits).": "Lege eine PIN für den Entwickler-Bereich fest (4 bis 10 Ziffern).",
          "Enter the developer PIN.": "Entwickler-PIN eingeben.", "Set PIN": "PIN festlegen", "Open": "Öffnen",
          "The two PINs are different.": "Die beiden PINs sind verschieden.", "The developer area is switched off.": "Der Entwickler-Bereich ist ausgeschaltet.",
          "State": "Zustand", "Program": "Programm", "To": "Ziel", "Port": "Port", "listening": "lauscht", "local": "lokal",
          "no connections": "keine Verbindungen", "Name": "Name", "Address": "Adresse", "Ports": "Ports", "nothing reached": "nichts erreicht",
          "Card": "Netzwerkkarte", "Received": "Empfangen", "Sent": "Gesendet", "Now": "Jetzt",
          "Only this device, read-only.": "Nur dieses Gerät, nur lesen.", "Looks in the last 24 h": "Abfragen in den letzten 24 h",
          "dev-law": "Nur dieses Gerät, nur lesen: eigene Verbindungen, erreichte Namen und die Datenmenge der eigenen Netzwerkkarten – wie «netstat» oder eine Router-Seite. MoveEye liest keine fremden Pakete mit und durchsucht keine fremden Geräte. Jede Nutzung wird ins Protokoll geschrieben. Bitte nur im eigenen Netz und auf eigenen Geräten verwenden."}


def dev_page():
    js = "Object.assign(I18N.de, " + json.dumps(DEV_DE, ensure_ascii=False) + ");" \
         + "I18N.en=I18N.en||{};Object.assign(I18N.en,{\"dev-law\":\"Only this device, read-only: its own connections, the names it reached and the data volume of its own network cards – like netstat or a router page. MoveEye does not capture other people's packets and does not scan other devices. Every use is written to the log. Please use it only in your own network and on your own devices.\"});"
    return render_page(DEV_PAGE, "dev").replace("/*DEVDE*/", js, 1)
# ----------------------------------------------------------------------------
# Several devices: one MoveEye shows the others (Cameras page): picture, armed / alarm, battery, last event; arm or
#   disarm one or all. The other devices are reached over the network (home network or Tailscale) with their own password.
#   Passwords are only ever sent to the address of that device.
# ----------------------------------------------------------------------------
FLEET = {"state": {}, "seen": 0.0, "snaps": {}, "lock": threading.Lock()}
_FLEET_URL = re.compile(r"^https?://[A-Za-z0-9.\-\[\]:]{1,120}(:\d{1,5})?/?$")


def device_uid():
    """Short id of this Pi (from /etc/machine-id): the same device over two addresses is shown once."""
    if not FLEET.get("uid"):
        try:
            with open("/etc/machine-id") as f:
                raw = f.read().strip()
        except OSError:
            raw = str(uuid.getnode())
        FLEET["uid"] = hashlib.sha256(("motionwatch|" + raw).encode()).hexdigest()[:12]
    return FLEET["uid"]


def fleet_hello():
    """Small status of this device for the overview of another one."""
    imp = [e for e in STATE["events"] if e.get("imp")][:1]
    b = STATE.get("battery") or {}
    return {"app": "Motion Watch", "uid": device_uid(), "name": CFG["device_name"] or "MoveEye", "version": APP_VERSION, "arm": STATE["arm_state"],
            "persons": STATE["persons"], "recording": bool(STATE.get("recording")), "fps": STATE.get("fps"),
            "battery": b.get("pct"), "mains": (not b.get("on_battery")) if b.get("src") == "ups" else None,
            "temp": STATE.get("cpu_temp"), "last": (imp[0].get("t", "")[:5] + " " + imp[0].get("text", ""))[:120] if imp else "",
            "tamper": (STATE.get("tamper") or {}).get("last", ""), "time": datetime.now().strftime("%H:%M:%S")}


def _fleet_https(dev, path, data, h, timeout):
    """2.98.x («Anmelden nur verschlüsselt», 574): the password goes to the other device over its secure page (https, port + 1).
    Its certificate is self-made: it is remembered at the first contact (fingerprint in the device entry) and must stay
    the same afterwards. None = that device has no secure page (older MoveEye) - then plain http as before."""
    import http.client, ssl
    from urllib.parse import urlsplit
    u = urlsplit(dev["url"])
    if u.scheme != "http" or not u.port or time.time() < FLEET.setdefault("no_tls", {}).get(dev.get("id") or dev["url"], 0):
        return None
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT); ctx.check_hostname = False; ctx.verify_mode = ssl.CERT_NONE
    con = http.client.HTTPSConnection(u.hostname, u.port + 1, timeout=timeout, context=ctx)
    try:
        try:
            con.connect()
        except (OSError, ssl.SSLError):
            FLEET["no_tls"][dev.get("id") or dev["url"]] = time.time() + 600     # try https again in 10 minutes
            return None
        fp = hashlib.sha256(con.sock.getpeercert(True) or b"").hexdigest()
        if dev.get("fp") and dev["fp"] != fp:
            raise urllib.error.HTTPError(dev["url"], 495, "certificate of the device changed", {}, None)
        if not dev.get("fp") and dev in CFG["fleet"]:
            dev["fp"] = fp; save_settings()
        con.request("POST" if data is not None else "GET", path, body=json.dumps(data).encode() if data is not None else None, headers=h)
        r = con.getresponse()
        body = r.read(4 * 1024 * 1024)
        if r.status >= 400:
            raise urllib.error.HTTPError(dev["url"] + path, r.status, r.reason, r.headers, None)
        return body, r.getheader("Content-Type", "")
    finally:
        con.close()


def _fleet_req(dev, path, data=None, timeout=4.0):
    import base64
    url = dev["url"].rstrip("/") + path
    h = {"Content-Type": "application/json"} if data is not None else {}
    if dev.get("pw"):
        h["Authorization"] = "Basic " + base64.b64encode(("mw:" + dev["pw"]).encode()).decode()
        res = _fleet_https(dev, path, data, dict(h, **{"User-Agent": "MotionWatch/" + APP_VERSION}), timeout)
        if res is not None:
            return res
    req = urllib.request.Request(url, data=json.dumps(data).encode() if data is not None else None, headers=h, method="POST" if data is not None else "GET")
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))      # devices are in the own network: no proxy
    with opener.open(req, timeout=timeout) as r:
        return r.read(4 * 1024 * 1024), r.headers.get("Content-Type", "")


def fleet_poll_one(dev):
    try:
        raw, _ct = _fleet_req(dev, "/api/fleet_state")
        st = json.loads(raw.decode()); st["ok"] = True; st["err"] = ""
        if not dev.get("name") and st.get("name") and dev in CFG["fleet"]:
            dev["name"] = str(st["name"])[:40]; save_settings()
    except urllib.error.HTTPError as e:
        st = {"ok": False, "err": "password wrong" if e.code == 401 else f"HTTP {e.code}"}
    except Exception as e:
        st = {"ok": False, "err": "not reachable"}
    st["checked"] = time.time()
    try:
        fleet_handover(dev, st)                          # 2.96.7 (makeover 16): a person goes from one device to the next
    except Exception:
        pass
    with FLEET["lock"]:
        old = FLEET["state"].get(dev["id"], {})
        if old.get("ok") and not st["ok"] and is_armed():
            log_event("sys", f"Device {dev.get('name') or dev['url']} not reachable any more")
        FLEET["state"][dev["id"]] = st
    return st


def fleet_loop():
    while True:
        time.sleep(1.0)
        devs = list(CFG["fleet"])
        if not devs:
            continue
        busy = time.time() - FLEET["seen"] < 60 or is_armed()     # 2.96.7: armed - often, for the handover
        for d in devs:
            last = FLEET["state"].get(d["id"], {}).get("checked", 0)
            if time.time() - last > (4 if busy else 60):
                fleet_poll_one(d)


def fleet_add(url, name="", pw=""):
    url = str(url or "").strip()
    if not url.startswith("http"):
        url = "http://" + url
    if re.match(r"^https?://[^/:]+$", url):
        url += f":{CFG['web_port']}"
    if not _FLEET_URL.match(url):
        return False, "invalid address (e.g. http://192.168.1.20:5000)", None
    if any(d["url"].rstrip("/") == url.rstrip("/") for d in CFG["fleet"]):
        return False, "this device is in the list already", None
    if len(CFG["fleet"]) >= 12:
        return False, "at most 12 devices", None
    dev = {"id": uuid.uuid4().hex[:8], "url": url.rstrip("/"), "name": str(name or "")[:40], "pw": str(pw or "")[:64]}
    st = fleet_poll_one(dev)
    if st.get("uid") == device_uid():
        FLEET["state"].pop(dev["id"], None)
        return False, "this is this device itself", None
    if st.get("ok") and not dev["name"]:
        dev["name"] = str(st.get("name") or "")[:40]
    CFG["fleet"] = CFG["fleet"] + [dev]; save_settings()
    log_event("sys", f"Device added to the overview: {dev['name'] or url}")
    return True, "", dev["id"]


def fleet_scan():
    """Look for other MoveEye devices: own network (x.y.z.1-254, same port) + Tailscale devices."""
    from concurrent.futures import ThreadPoolExecutor
    ips = set()
    ip = wifi_ip()
    if ip and ip.count(".") == 3:
        pre = ip.rsplit(".", 1)[0]
        ips |= {f"{pre}.{i}" for i in range(1, 255)} - {ip}
    try:
        ips |= set((tailscale_status().get("peers") or {}).keys())
    except Exception:
        pass
    known = {d["url"] for d in CFG["fleet"]}
    found = []

    def probe(a):
        if ":" in a:
            return None
        url = f"http://{a}:{CFG['web_port']}"
        if url in known:
            return None
        try:
            raw, _ = _fleet_req({"url": url}, "/api/fleet_state", timeout=0.8)
            j = json.loads(raw.decode())
            return {"url": url, "name": j.get("name", ""), "needs_pw": False, "uid": j.get("uid", "")} if j.get("app") in ("Motion Watch", "MoveEye") else None
        except urllib.error.HTTPError as e:
            if e.code == 401 and ("Motion Watch" in str(e.headers.get("WWW-Authenticate", "")) or "MoveEye" in str(e.headers.get("WWW-Authenticate", ""))):
                return {"url": url, "name": "", "needs_pw": True}
            if e.code == 403:                            # 574: a MoveEye that takes the password only over https
                try:
                    if json.loads(e.read(4096).decode()).get("https"):
                        return {"url": url, "name": "", "needs_pw": True}
                except Exception:
                    pass
        except Exception:
            pass
        return None
    have = {device_uid()} | {st.get("uid") for st in FLEET["state"].values() if st.get("uid")}
    with ThreadPoolExecutor(64) as ex:
        for r in ex.map(probe, sorted(ips)):
            if r and (not r.get("uid") or r["uid"] not in have):
                found.append(r)
                if r.get("uid"):
                    have.add(r["uid"])
    return found


def fleet_snap(dev_id):
    dev = next((d for d in CFG["fleet"] if d["id"] == dev_id), None)
    if dev is None:
        return None
    c = FLEET["snaps"].get(dev_id)
    if c and time.time() - c[0] < 2.0:
        return c[1]
    try:
        raw, _ct = _fleet_req(dev, "/snapshot.jpg", timeout=5)
        img = cv2.imdecode(np.frombuffer(raw, np.uint8), cv2.IMREAD_COLOR)
        if img is None:
            return None
        h, w = img.shape[:2]
        if w > 640:
            img = cv2.resize(img, (640, int(h * 640 / w)), interpolation=cv2.INTER_AREA)
        ok, buf = cv2.imencode(".jpg", img, [cv2.IMWRITE_JPEG_QUALITY, 70])
        data = buf.tobytes() if ok else None
    except Exception:
        data = None
    FLEET["snaps"][dev_id] = (time.time(), data)
    return data



# ---- 2.96.7 (Makeover-Punkt 16): Übergabe zwischen Geräten - eine Person verschwindet bei einem Gerät und taucht innert
# 40 s beim nächsten auf: «Übergabe A → B» im Protokoll (wichtig) und in der Liste FLEET["handover"] (Kameras-Seite / Zentrale).
FLEET.setdefault("seen_p", {})        # device -> time persons were last > 0 ("" = this device)
FLEET.setdefault("handover", [])


def fleet_handover(dev, st):
    now = time.time()
    me = CFG.get("device_name") or "MoveEye"
    if int(STATE.get("persons") or 0) > 0:
        if now - FLEET["seen_p"].get("", 0.0) > 15:       # new here: did another device see the person just before?
            for k, t in FLEET["seen_p"].items():
                if k and 2 < now - t < 40:
                    src = next((d.get("name") or d.get("url") for d in CFG["fleet"] if d["id"] == k), k)
                    log_event("person", f"Handover: person from {src} to {me}")
                    FLEET["handover"].insert(0, {"t": datetime.now().strftime("%H:%M:%S"), "from": src, "to": me})
                    del FLEET["handover"][20:]
                    break
        FLEET["seen_p"][""] = now
    name = dev.get("name") or dev.get("url", "?")
    had = FLEET["seen_p"].get(dev["id"], 0.0)
    if st.get("ok") and int(st.get("persons") or 0) > 0:
        if now - had > 15:                                  # new at this device: where was the person before?
            src = None
            for k, t in FLEET["seen_p"].items():
                if k != dev["id"] and 2 < now - t < 40:
                    src = me if k == "" else next((d.get("name") or d.get("url") for d in CFG["fleet"] if d["id"] == k), k)
            if src:
                txt = f"Handover: person from {src} to {name}"
                log_event("person", txt)
                FLEET["handover"].insert(0, {"t": datetime.now().strftime("%H:%M:%S"), "from": src, "to": name})
                del FLEET["handover"][20:]
        FLEET["seen_p"][dev["id"]] = now
# ----------------------------------------------------------------------------
# MQTT / Home Assistant: state (armed, person, motion, animal, recording, battery, temperature), events and the alarm picture
#   go to an MQTT broker (e.g. the Mosquitto add-on of Home Assistant); commands come back (arm / disarm, lights).
#   Home Assistant finds MoveEye by itself (MQTT discovery): alarm panel, sensors, camera picture.
#   Own small MQTT 3.1.1 client (no extra package), optional TLS.
# ----------------------------------------------------------------------------
class MiniMQTT:
    def __init__(self, host, port, client_id, user="", pw="", tls=False, will=None):
        self.host, self.port, self.cid, self.user, self.pw, self.tls, self.will = host, int(port), client_id, user, pw, tls, will
        self.sock = None; self.lock = threading.Lock(); self.pid = 1; self.on_message = None; self.last_tx = 0.0

    @staticmethod
    def _len(n):
        out = bytearray()
        while True:
            b = n % 128; n //= 128
            out.append(b | (0x80 if n else 0))
            if not n:
                return bytes(out)

    @staticmethod
    def _str(x):
        b = x.encode() if isinstance(x, str) else x
        return len(b).to_bytes(2, "big") + b

    def _send(self, ptype, body):
        with self.lock:
            self.sock.sendall(bytes([ptype]) + self._len(len(body)) + body)
            self.last_tx = time.time()

    def _recv_exact(self, n):
        b = b""
        while len(b) < n:
            c = self.sock.recv(n - len(b))
            if not c:
                raise ConnectionError("broker closed the connection")
            b += c
        return b

    def _read_packet(self):
        h = self._recv_exact(1)[0]                       # may time out (nothing there) - the rest of a packet may not
        old = self.sock.gettimeout()
        try:
            self.sock.settimeout(20.0)
            mult, n = 1, 0
            for _i in range(4):
                d = self._recv_exact(1)[0]
                n += (d & 0x7F) * mult; mult *= 128
                if not d & 0x80:
                    break
            else:
                raise ConnectionError("invalid packet from the broker")
            if n > 256 * 1024:
                raise ConnectionError("packet from the broker too big")
            body = self._recv_exact(n) if n else b""
        finally:
            self.sock.settimeout(old)
        self.last_rx = time.time()
        return h, body

    def connect(self):
        import socket, ssl
        s_ = socket.create_connection((self.host, self.port), timeout=10)
        if self.tls:
            s_ = ssl.create_default_context().wrap_socket(s_, server_hostname=self.host)
        self.sock = s_
        flags = 0x02
        payload = self._str(self.cid)
        if self.will:
            flags |= 0x04 | 0x20; payload += self._str(self.will[0]) + self._str(self.will[1])
        if self.user:
            flags |= 0x80; payload += self._str(self.user)
            if self.pw:
                flags |= 0x40; payload += self._str(self.pw)
        self._send(0x10, self._str("MQTT") + bytes([4, flags]) + (60).to_bytes(2, "big") + payload)
        h, body = self._read_packet()
        if h >> 4 != 2 or len(body) < 2:
            raise ConnectionError("no answer from the broker")
        if body[1] != 0:
            raise ConnectionError({4: "user name / password wrong", 5: "not allowed (user / password?)"}.get(body[1], f"refused ({body[1]})"))
        self.sock.settimeout(1.0); self.last_rx = time.time()

    def publish(self, topic, payload, retain=False):
        if isinstance(payload, str):
            payload = payload.encode()
        self._send(0x30 | (1 if retain else 0), self._str(topic) + payload)

    def subscribe(self, topic):
        self.pid = self.pid % 65000 + 1
        self._send(0x82, self.pid.to_bytes(2, "big") + self._str(topic) + b"\x00")

    def poll(self):
        """Read what the broker sends (1 s at most). Keeps the connection alive."""
        import socket
        if time.time() - self.last_tx > 30:
            self._send(0xC0, b"")
        if time.time() - getattr(self, "last_rx", time.time()) > 95:
            raise ConnectionError("no answer from the broker for 95 s")
        try:
            h, body = self._read_packet()
        except socket.timeout:
            return
        if h >> 4 == 3:
            tl = int.from_bytes(body[:2], "big"); topic = body[2:2 + tl].decode(errors="replace")
            off = 2 + tl + (2 if (h >> 1) & 3 else 0)
            if self.on_message:
                self.on_message(topic, body[off:])

    def close(self):
        try:
            self._send(0xE0, b"")
        except Exception:
            pass
        try:
            self.sock.close()
        except Exception:
            pass


MQTT = {"status": "off", "client": None}


class MqttBridge:
    def __init__(self):
        self.last = None; self.last_t = 0.0; self.prev_ev = None
        threading.Thread(target=self.loop, daemon=True, name="mqtt").start()

    def base(self):
        return (CFG["mqtt_prefix"].strip().strip("/") or "motionwatch") + "/" + device_uid()

    def loop(self):
        backoff = 5
        while True:
            if not (CFG["mqtt_on"] and CFG["mqtt_host"].strip()):
                MQTT["status"] = "off"; time.sleep(2); continue
            b = self.base()
            c = MiniMQTT(CFG["mqtt_host"].strip(), int(CFG["mqtt_port"] or 1883), "motionwatch-" + device_uid(), CFG["mqtt_user"], CFG["mqtt_password"],
                         CFG["mqtt_tls"], will=(b + "/availability", "offline"))
            try:
                c.connect()
                c.on_message = self.command
                c.publish(b + "/availability", "online", retain=True)
                c.subscribe(b + "/cmd/#")
                zb = CFG["sens_on"] and CFG["zigbee_on"]
                if zb:
                    c.subscribe("zigbee2mqtt/+")                   # Zigbee sensors (Zigbee2MQTT) for the extra sensors
                MQTT["client"] = c; MQTT["status"] = "connected"; backoff = 5
                log_event("web", f"MQTT connected to {CFG['mqtt_host']}:{CFG['mqtt_port']}")
                if CFG["mqtt_discovery"]:
                    self.discovery(c)
                self.last = None
                key = (CFG["mqtt_host"], CFG["mqtt_port"], CFG["mqtt_user"], CFG["mqtt_password"], CFG["mqtt_tls"], CFG["mqtt_prefix"], CFG["mqtt_on"], zb)
                while (CFG["mqtt_host"], CFG["mqtt_port"], CFG["mqtt_user"], CFG["mqtt_password"], CFG["mqtt_tls"], CFG["mqtt_prefix"], CFG["mqtt_on"],
                       CFG["sens_on"] and CFG["zigbee_on"]) == key:
                    c.poll()
                    self.push_state(c)
                c.publish(b + "/availability", "offline", retain=True)
                MQTT["status"] = "off" if not CFG["mqtt_on"] else "reconnecting"; backoff = 1
            except Exception as e:
                msg = str(e) or e.__class__.__name__
                if len(CFG["mqtt_password"]) >= 6:
                    msg = msg.replace(CFG["mqtt_password"], "***")
                if MQTT["status"] != "error: " + msg[:120]:
                    log_event("web", f"MQTT: {msg}"[:200])
                MQTT["status"] = "error: " + msg[:120]
            finally:
                MQTT["client"] = None
                c.close()
            time.sleep(backoff); backoff = min(120, backoff * 2)

    def state(self):
        b = STATE.get("battery") or {}
        present = set(STATE.get("present") or [])
        arm = STATE["arm_state"]
        ha = "triggered" if arm == "armed" and STATE["persons"] else {"armed": "armed_away", "arming": "arming"}.get(arm, "disarmed")
        return {"arm": arm, "alarm_panel": ha, "person": "ON" if STATE["persons"] else "OFF", "motion": "ON" if "motion" in present else "OFF",
                "animal": "ON" if "animal" in present else "OFF", "recording": "ON" if STATE.get("recording") else "OFF",
                "persons": STATE["persons"], "battery": b.get("pct"), "cpu_temp": STATE.get("cpu_temp"), "fps": STATE.get("fps"),
                "tamper": (STATE.get("tamper") or {}).get("last", ""), "version": APP_VERSION, "name": CFG["device_name"] or "MoveEye"}

    def push_state(self, c):
        st = self.state(); now = time.time()
        cmp = {k: v for k, v in st.items() if k not in ("fps", "cpu_temp")}
        if cmp != self.last or now - self.last_t > 60:
            c.publish(self.base() + "/state", json.dumps(st), retain=True)
            if self.last and st["person"] == "ON" and self.last.get("person") != "ON":
                c.publish(self.base() + "/event", json.dumps({"event": "person", "time": datetime.now().isoformat(timespec="seconds")}))
                self.picture(c)
            self.last = cmp; self.last_t = now

    def picture(self, c):
        w = WATCH_REF["w"]
        if w is None or w.frame_out is None:
            return
        f = w.frame_out; h, wd = f.shape[:2]
        if wd > 960:
            f = cv2.resize(f, (960, int(h * 960 / wd)), interpolation=cv2.INTER_AREA)
        ok, buf = cv2.imencode(".jpg", f, [cv2.IMWRITE_JPEG_QUALITY, 75])
        if ok:
            c.publish(self.base() + "/snapshot", buf.tobytes(), retain=True)

    def command(self, topic, payload):
        if topic.startswith("zigbee2mqtt/"):
            zb_message(topic[12:], payload); return
        cmd = topic.rsplit("/cmd/", 1)[-1]; val = payload.decode(errors="replace").strip()
        log_event("web", f"MQTT command: {cmd} = {val[:40]}")
        if cmd in ("arm", "alarm"):
            v = val.upper()
            if v in ("ARM", "ARM_AWAY", "ARM_HOME", "ARM_NIGHT", "ON"):
                arm()
            elif v in ("ARM_NOW",):
                arm(0)
            elif v in ("DISARM", "OFF"):
                was = is_armed() or bool(CFG["armed"])
                disarm()
                if was:                                  # 2.95.33: the owner learns when MQTT switched the camera off
                    try:
                        WATCH_REF["w"].notifier.info(tr("Disarmed via MQTT / Home Assistant"))
                    except Exception:
                        pass
        elif cmd in ("light_white", "light_ir") and val.lower() in LIGHT_MODES:
            light_set(cmd[6:], val.lower())
        elif cmd == "snapshot" and MQTT["client"] is not None:
            self.picture(MQTT["client"])

    def discovery(self, c):
        """Home Assistant MQTT discovery: the device and its entities appear by themselves."""
        b = self.base(); uid = device_uid(); name = CFG["device_name"] or "MoveEye"
        dev = {"identifiers": ["motionwatch_" + uid], "name": name, "manufacturer": "MoveEye", "model": "Raspberry Pi camera", "sw_version": APP_VERSION}
        avail = {"availability_topic": b + "/availability"}
        ents = [
            ("alarm_control_panel", "alarm", {"name": "Alarm", "state_topic": b + "/state", "value_template": "{{ value_json.alarm_panel }}",
                                              "command_topic": b + "/cmd/arm", "payload_arm_away": "ARM_AWAY", "payload_disarm": "DISARM",
                                              "supported_features": ["arm_away"], "code_arm_required": False, "code_disarm_required": False}),
            ("binary_sensor", "person", {"name": "Person", "state_topic": b + "/state", "value_template": "{{ value_json.person }}", "device_class": "occupancy"}),
            ("binary_sensor", "motion", {"name": "Motion", "state_topic": b + "/state", "value_template": "{{ value_json.motion }}", "device_class": "motion"}),
            ("binary_sensor", "animal", {"name": "Animal", "state_topic": b + "/state", "value_template": "{{ value_json.animal }}", "icon": "mdi:paw"}),
            ("binary_sensor", "recording", {"name": "Recording", "state_topic": b + "/state", "value_template": "{{ value_json.recording }}", "icon": "mdi:record-rec"}),
            ("sensor", "battery", {"name": "Battery", "state_topic": b + "/state", "value_template": "{{ value_json.battery }}", "device_class": "battery", "unit_of_measurement": "%"}),
            ("sensor", "cpu_temp", {"name": "CPU temperature", "state_topic": b + "/state", "value_template": "{{ value_json.cpu_temp }}", "device_class": "temperature", "unit_of_measurement": "°C"}),
            ("camera", "snapshot", {"name": "Last alarm picture", "topic": b + "/snapshot"}),
        ]
        for comp, key, cfg in ents:
            cfg = dict(cfg, unique_id=f"motionwatch_{uid}_{key}", object_id=f"motionwatch_{key}", device=dev, **avail)
            c.publish(f"homeassistant/{comp}/motionwatch_{uid}/{key}/config", json.dumps(cfg), retain=True)


MQTT_BRIDGE = None

# ----------------------------------------------------------------------------
# SMS over an LTE / UMTS stick: alarm as a text message - also where there is no internet (only mobile network).
#   Ways: ModemManager (mmcli, most sticks), AT commands on the serial port, or Huawei HiLink sticks (web API, 192.168.8.1).
#   Only alarms (person, sabotage, warm body, noise), at most one SMS every few minutes and 20 a day (costs!).
# ----------------------------------------------------------------------------
SMS_MODES = ("auto", "mmcli", "at", "hilink")
SMS = {"status": "", "sent": [], "last": 0.0}
_PHONE_RE = re.compile(r"^\+?[0-9]{6,16}$")


# ----------------------------------------------------------------------------
# Extra sensors: motion detector (PIR), door / lid contact (reed switch to GND) and gas / smoke module (digital output) on a
#   GPIO; 433 MHz radio sensors (RTL-SDR USB stick + rtl_433), Zigbee sensors (Zigbee2MQTT -> MQTT broker) and Bluetooth tags
#   (RuuviTag: its movement counter, or "out of range"). An alarm when armed (or always: gas); a PIR also wakes power saving.
# ----------------------------------------------------------------------------
SENS_KINDS = ("pir", "door", "gas", "tag", "other")
SENS_ALARMS = ("armed", "always", "off")
SENS_NAMES = {"pir": "Motion detector", "door": "Door", "gas": "Gas / smoke", "tag": "Tag", "other": "Sensor"}
MAX_SENSORS = 16
SENS = {"st": {}, "seen": {}, "pir_t": 0.0, "rf": "off", "ble": "off", "zb": "off", "ruuvi": {}, "lock": threading.Lock()}
_SENS_SRC = re.compile(r"^(sim:[\w .:+\-]{1,60}|gpio:\d{1,2}|rf:[\w .:+\-]{1,60}|zb:[\w .:+\-/]{1,60}|ble:[0-9A-F]{2}(:[0-9A-F]{2}){5})$")


def sens_used_gpios(skip=None):
    """GPIOs taken by servos, 1-Wire, I2C, relays, lights, the thermal camera and the other sensors."""
    used = set(GPIO_RESERVED) | {r["gpio"] for r in RELAYS} | set(thermal_gpios()) | {2, 3}
    for k in ("light_white_out", "light_ir_out"):
        v = str(CFG.get(k, ""))
        if v.startswith("gpio:") and v[5:].isdigit():
            used.add(int(v[5:]))
    for x in CFG.get("sensors", []):
        if x.get("id") != skip and str(x.get("src", "")).startswith("gpio:"):
            used.add(int(x["src"][5:]))
    if str(CFG.get("wind_gpio") or "").isdigit() and skip != "wind":
        used.add(int(CFG["wind_gpio"]))
    return used


def sens_free_gpios(skip=None):
    """Free GPIOs, the usual free pins first (GPIO 4 = 1-Wire temperature sensor comes last)."""
    used = sens_used_gpios(skip)
    order = [g for g in FREE_GPIOS if g != 4] + [g for g in range(5, 28) if g not in FREE_GPIOS] + [4]
    return [g for g in order if g not in used]


def sens_clean(lst):
    out, ids, gp = [], set(), set()
    for x in (lst if isinstance(lst, list) else [])[:MAX_SENSORS]:
        if not isinstance(x, dict):
            continue
        kind = x.get("kind") if x.get("kind") in SENS_KINDS else "other"
        src = str(x.get("src", "")).strip()
        if src[:4].lower() == "ble:":
            src = "ble:" + src[4:].upper()
        if src and not _SENS_SRC.match(src):
            src = ""
        if src.startswith("gpio:"):
            g = int(src[5:])
            if not 2 <= g <= 27 or g in gp:
                src = ""
            else:
                gp.add(g)
        sid = str(x.get("id", ""))
        if not re.fullmatch(r"[a-f0-9]{8}", sid) or sid in ids:
            sid = secrets.token_hex(4)
        ids.add(sid)
        name = re.sub(r"[\x00-\x1f]", "", str(x.get("name", ""))).strip()[:24] or SENS_NAMES[kind]
        alarm = x.get("alarm") if x.get("alarm") in SENS_ALARMS else ("always" if kind == "gas" else "armed")
        out.append({"id": sid, "name": name, "kind": kind, "src": src, "alarm": alarm, "inv": bool(x.get("inv", kind == "gas"))})
    return out


def sens_find(sid):
    return next((x for x in CFG["sensors"] if x["id"] == sid), None)


def sens_action(d, lang=None):
    """Web page / window: add, change, remove or test a sensor."""
    a = d.get("action")
    if a == "add":
        if len(CFG["sensors"]) >= MAX_SENSORS:
            return False, "at most 16 sensors"
        kind = d.get("kind") if d.get("kind") in SENS_KINDS else "other"
        src = str(d.get("src") or "")
        if not src and kind in ("pir", "door", "gas"):
            free = sens_free_gpios()
            src = f"gpio:{free[0]}" if free else ""
        n = sum(1 for x in CFG["sensors"] if x["kind"] == kind) + 1
        name = str(d.get("name") or "")[:24] or (tr(SENS_NAMES[kind], lang) + (f" {n}" if n > 1 else ""))
        CFG["sensors"] = sens_clean(CFG["sensors"] + [{"name": name, "kind": kind, "src": src}])
        CFG["sens_on"] = True
        if src.startswith("rf:"):
            CFG["rf433_on"] = True
        elif src.startswith("zb:"):
            CFG["zigbee_on"] = True
        elif src.startswith("ble:") or kind == "tag":
            CFG["ble_on"] = True
        save_settings(); return True, ""
    x = sens_find(str(d.get("id", "")))
    if x is None:
        return False, "unknown sensor"
    if a == "remove":
        CFG["sensors"] = [y for y in CFG["sensors"] if y["id"] != x["id"]]
        SENS["st"].pop(x["id"], None); save_settings(); return True, ""
    if a == "test":
        sens_fire(x, "test"); return True, ""
    if a != "set":
        return False, "unknown action"
    f, v = d.get("field"), d.get("value")
    if f == "name":
        v = re.sub(r"[\x00-\x1f]", "", str(v or "")).strip()[:24]
        if not v:
            return False, "invalid value"
    elif f == "kind":
        if v not in SENS_KINDS:
            return False, "invalid value"
    elif f == "alarm":
        if v not in SENS_ALARMS:
            return False, "invalid value"
    elif f == "inv":
        v = bool(v)
    elif f == "src":
        v = str(v or "").strip()
        if v[:4].lower() == "ble:":
            v = "ble:" + v[4:].upper()
        if v and not _SENS_SRC.match(v):
            return False, "invalid value"
        if v.startswith("gpio:") and int(v[5:]) not in sens_free_gpios(x["id"]):
            return False, "this GPIO is already in use"
    else:
        return False, "unknown setting"
    x[f] = v
    if f == "src":
        SENS["st"].pop(x["id"], None)
    CFG["sensors"] = sens_clean(CFG["sensors"]); save_settings()
    return True, ""


def sens_text(x, what, lang=None):
    if what == "test":
        return tr("test - it works", lang)
    if what == "missing":
        return tr("out of range (not seen any more)", lang)
    return tr({"pir": "motion detected", "door": "opened", "gas": "gas / smoke detected!", "tag": "moved"}.get(x["kind"], "triggered"), lang)


def sens_fire(x, what):
    """A sensor reported something: diary line, and (armed or 'always') push with the current picture, siren, recording."""
    now = time.time()
    st = SENS["st"].setdefault(x["id"], {"state": "ok", "last": 0.0, "cool": 0.0})
    st["last"] = now; st["what"] = what
    if x["kind"] == "pir" and what != "missing":
        SENS["pir_t"] = now                               # wakes power saving at once
    test = what == "test"
    alarm = test or x["alarm"] == "always" or (x["alarm"] == "armed" and is_armed())
    log_event("sys", f"Sensor «{x['name']}»: {sens_text(x, what, 'en')}" + ("" if alarm else " (no alarm)"))
    if not alarm or (not test and now - st.get("cool", 0.0) < 60):
        return
    st["cool"] = now
    w = WATCH_REF["w"]
    title = "{name}: " + (tr("GAS ALARM") if x["kind"] == "gas" else tr("SENSOR ALARM"))
    if test:
        title = "[Test] " + title
    if w is not None:
        w.notifier.alert(title, f"{x['name']}: {sens_text(x, what)}", w.frame_out)
    if test:
        return
    if not CFG.get("sim_on"):
        QUICK["rec_until"] = max(QUICK["rec_until"], now + 60)    # one minute of video of what happens now
    if x["kind"] == "gas" and not is_armed():
        if out_selected() and not SOUND["playing"] and TALK["proc"] is None:
            sound_play(None, None, None, reason="gas alarm")
    else:
        siren_alarm("sensor")


def sens_event(src, active, info=""):
    """A radio sensor (433 MHz, Zigbee, Bluetooth) sent something. active: True / False (contact closed again) / None = a pulse."""
    for x in CFG["sensors"] if CFG["sens_on"] else []:
        if x["src"] != src:
            continue
        st = SENS["st"].setdefault(x["id"], {"state": "unknown", "last": 0.0, "cool": 0.0})
        st["seen"] = time.time()
        if active is False:
            st["state"] = "ok"; continue
        if st.get("state") == "missing":
            log_event("sys", f"Sensor «{x['name']}»: back in range")
        if active is None:
            st["state"] = "pulse"; sens_fire(x, info or "active")
        elif st.get("state") != "active":                 # radio sensors report changes: every "open" counts
            st["state"] = "active"; sens_fire(x, "active")


def sens_seen(src, label, data=None):
    with SENS["lock"]:
        SENS["seen"][src] = {"label": str(label)[:80], "t": time.time(), "data": data or {}}
        if len(SENS["seen"]) > 60:
            for k in sorted(SENS["seen"], key=lambda k: SENS["seen"][k]["t"])[:len(SENS["seen"]) - 60]:
                SENS["seen"].pop(k, None)


def rf_message(d):
    """One line of rtl_433 (JSON). Contact sensors: closed / state / contact_open; motion detectors: motion / event."""
    model = re.sub(r"[^\w.+\-]", "_", str(d.get("model", "?")))[:30]
    dev = re.sub(r"[^\w.+\-]", "_", str(d.get("id", d.get("channel", d.get("code", "")))))[:20]
    src = f"rf:{model}:{dev}" if dev else f"rf:{model}"
    vals = {k: d[k] for k in ("closed", "state", "contact_open", "motion", "alarm", "tamper", "event", "temperature_C", "battery_ok") if k in d}
    sens_seen(src, f"{model} {dev}".strip(), vals)
    act = None
    if "contact_open" in d:
        act = bool(d["contact_open"])
    elif "closed" in d:
        act = not bool(d["closed"])
    elif str(d.get("state", "")).lower() in ("open", "opened", "closed", "close"):
        act = str(d["state"]).lower().startswith("open")
    elif "motion" in d:
        act = None if d["motion"] else False
    elif "temperature_C" in d and "alarm" not in d and "event" not in d:
        return                                            # a thermometer: only listed, no trigger
    sens_event(src, act)


def zb_message(name, payload):
    """A Zigbee2MQTT message (topic zigbee2mqtt/<name>). contact false = open, occupancy, smoke, gas, water_leak, vibration ..."""
    if name.startswith("bridge") or "/" in name:
        return
    try:
        d = json.loads(payload.decode(errors="replace"))
    except ValueError:
        return
    if not isinstance(d, dict):
        return
    src = "zb:" + name[:60]
    if not _SENS_SRC.match(src):
        return
    keys = ("contact", "occupancy", "smoke", "carbon_monoxide", "gas", "water_leak", "vibration", "tamper", "action")
    sens_seen(src, name, {k: d[k] for k in keys + ("battery", "temperature") if k in d})
    if "contact" in d:
        sens_event(src, not bool(d["contact"]))
    elif any(d.get(k) for k in ("smoke", "carbon_monoxide", "gas", "water_leak", "occupancy")):
        sens_event(src, True)
    elif any(k in d for k in ("smoke", "carbon_monoxide", "gas", "water_leak", "occupancy")):
        sens_event(src, False)
    elif d.get("vibration") or d.get("action"):
        sens_event(src, None)


def ruuvi_parse(b):
    """RuuviTag data format 5 (RAWv2): temperature, humidity, pressure, acceleration, battery, movement counter."""
    import struct
    if not b or len(b) < 18 or b[0] != 5:
        return None
    t, h, p, ax, ay, az, pw, mv, seq = struct.unpack(">hHHhhhHBH", bytes(b[1:18]))
    return {"t": round(t * 0.005, 1), "h": round(h * 0.0025), "p": round((p + 50000) / 100.0, 1), "acc": (ax, ay, az),
            "bat": round(((pw >> 5) + 1600) / 1000.0, 2), "moves": mv, "seq": seq}


def ble_message(mac, name, ruuvi_raw, rssi=None):
    src = "ble:" + str(mac).upper()
    if not _SENS_SRC.match(src):
        return
    r = ruuvi_parse(ruuvi_raw) if ruuvi_raw else None
    known = any(x["src"] == src for x in CFG["sensors"])
    if r is None and not name and not known:
        return                                            # anonymous phones etc. (changing addresses): not listed
    sens_seen(src, ("RuuviTag " + src[-5:].replace(":", "")) if r else (name or src[4:]), dict(r or {}, rssi=rssi))
    if r is not None:
        old = SENS["ruuvi"].get(src); SENS["ruuvi"][src] = r["moves"]
        if old is not None and r["moves"] != old:
            sens_event(src, None); return
    sens_event(src, False)                                # seen = in range (and not moved)


class SensorHub:
    def __init__(self):
        self.gp = {}                  # gpio -> [device or None, pull_up, time of the last try]
        self.rf_proc = None
        threading.Thread(target=self.loop, daemon=True, name="sensors").start()
        threading.Thread(target=self.rf_loop, daemon=True, name="rtl433").start()
        threading.Thread(target=self.ble_loop, daemon=True, name="ble").start()

    def _gpio_sync(self, want):
        for g in list(self.gp):
            if g not in want or self.gp[g][1] != want[g]:
                try:
                    if self.gp[g][0] is not None:
                        self.gp[g][0].close()
                except Exception:
                    pass
                del self.gp[g]
        for g, pu in want.items():
            ent = self.gp.get(g)
            if ent and (ent[0] is not None or time.time() - ent[2] < 30):
                continue
            try:
                from gpiozero import DigitalInputDevice
                self.gp[g] = [DigitalInputDevice(g, pull_up=pu), pu, time.time()]
            except Exception as e:
                if not ent:
                    log_event("sys", f"Sensor GPIO {g}: {e}"[:160])
                self.gp[g] = [None, pu, time.time()]

    def loop(self):
        n = 0
        while True:
            try:
                self.tick(); n += 1
                if n % 10 == 0:
                    self.publish()
            except Exception as e:
                log_event("sys", f"Sensors: {e}"[:160]); time.sleep(5)
            time.sleep(0.1)

    def tick(self):
        now = time.time()
        lst = CFG["sensors"] if CFG["sens_on"] else []
        self._gpio_sync({int(x["src"][5:]): x["kind"] == "door" for x in lst if x["src"].startswith("gpio:")})
        for x in lst:
            st = SENS["st"].setdefault(x["id"], {"state": "unknown", "last": 0.0, "cool": 0.0})
            if x["src"].startswith("gpio:"):
                ent = self.gp.get(int(x["src"][5:]))
                if not ent or ent[0] is None:
                    st["state"] = "error"; continue
                raw = int(ent[0].value) ^ int(ent[1])          # gpiozero inverts with a pull-up: back to the pin level
                act = bool(raw) ^ bool(x["inv"])
                if act and st["state"] != "active":
                    first = st["state"] in ("unknown", "error")
                    st["state"] = "active"
                    if not (first and x["kind"] == "door"):
                        sens_fire(x, "active")
                elif not act and st["state"] != "ok":
                    st["state"] = "ok"
            elif x["src"].startswith("ble:"):
                seen = SENS["seen"].get(x["src"])
                lim = float(CFG["tag_missing"]) * 60.0
                if not CFG["ble_on"]:
                    continue
                if seen and now - seen["t"] > lim and st["state"] not in ("missing", "unknown"):
                    st["state"] = "missing"; sens_fire(x, "missing")
                elif st["state"] == "pulse" and now - st["last"] > 10:
                    st["state"] = "ok"
            elif st.get("state") == "pulse" and now - st["last"] > 10:
                st["state"] = "ok"

    def publish(self):
        lang = None
        sts = {}
        for x in CFG["sensors"]:
            st = SENS["st"].get(x["id"]) or {}
            sts[x["id"]] = {"state": st.get("state", "unknown") if CFG["sens_on"] else "off",
                            "last": datetime.fromtimestamp(st["last"]).strftime("%d.%m. %H:%M") if st.get("last") else "",
                            "what": st.get("what", "")}
        with SENS["lock"]:
            seen = sorted(({"src": k, "label": v["label"], "ago": int(time.time() - v["t"]), "data": v["data"]} for k, v in SENS["seen"].items()),
                          key=lambda e: e["ago"])[:40]
        zb = "off"
        if CFG["sens_on"] and CFG["zigbee_on"]:
            zb = "needs MQTT" if not (CFG["mqtt_on"] and CFG["mqtt_host"].strip()) else ("listening" if MQTT["status"] == "connected" else MQTT["status"])
        STATE["sens"] = {"st": sts, "seen": seen, "rf": SENS["rf"] if CFG["sens_on"] else "off", "ble": SENS["ble"] if CFG["sens_on"] else "off",
                         "zb": zb, "free": sens_free_gpios(), "pir": time.time() - SENS["pir_t"] < 10}

    def rf_loop(self):
        while True:
            if not (CFG["sens_on"] and CFG["rf433_on"]):
                SENS["rf"] = "off"; time.sleep(3); continue
            exe = shutil.which("rtl_433")
            if not exe:
                SENS["rf"] = "rtl_433 missing (sudo apt install rtl-433)"; time.sleep(30); continue
            t0 = time.time()
            try:
                p = subprocess.Popen([exe, "-F", "json", "-M", "level"], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True, bufsize=1)
                self.rf_proc = p; SENS["rf"] = "listening"
                for line in p.stdout:
                    if not (CFG["sens_on"] and CFG["rf433_on"]):
                        break
                    try:
                        d = json.loads(line)
                    except ValueError:
                        continue
                    if isinstance(d, dict):
                        rf_message(d)
                try:
                    p.terminate(); p.wait(5)
                except Exception:
                    pass
            except Exception as e:
                SENS["rf"] = f"error: {e}"[:100]
            self.rf_proc = None
            if CFG["sens_on"] and CFG["rf433_on"]:
                if time.time() - t0 < 10:
                    SENS["rf"] = "no RTL-SDR stick found"
                time.sleep(20)

    def ble_loop(self):
        while True:
            if not (CFG["sens_on"] and CFG["ble_on"]):
                SENS["ble"] = "off"; time.sleep(3); continue
            try:
                import asyncio
                from bleak import BleakScanner
            except ImportError:
                SENS["ble"] = "python3-bleak missing (sudo apt install python3-bleak)"; time.sleep(30); continue
            try:
                asyncio.run(self._ble(BleakScanner))
            except Exception as e:
                SENS["ble"] = f"error: {e}"[:100]; time.sleep(20)

    async def _ble(self, BleakScanner):
        import asyncio

        def cb(dev, adv):
            try:
                md = adv.manufacturer_data or {}
                ble_message(dev.address, adv.local_name or getattr(dev, "name", "") or "", md.get(0x0499), getattr(adv, "rssi", None))
            except Exception:
                pass
        sc = BleakScanner(detection_callback=cb)
        await sc.start(); SENS["ble"] = "listening"
        try:
            while CFG["sens_on"] and CFG["ble_on"]:
                await asyncio.sleep(1)
        finally:
            await sc.stop()


SENSHUB = None


# ----------------------------------------------------------------------------
# Storm warning: the air pressure of the BME280 falls fast (rule of thumb: 3 hPa in 3 hours = strong wind coming), a wind meter
#   (cup anemometer: a reed contact closes once per turn, between a GPIO and GND) measures strong wind, or the forecast
#   (Open-Meteo, optional) expects gusts in the next 12 hours. Push message, at most every 3 hours per reason.
# ----------------------------------------------------------------------------
STORM = {"p": deque(maxlen=480), "pulses": 0, "win": deque(maxlen=200), "cool": {}, "last": "", "dev": None, "pin": None}


def storm_forecast_gust():
    """The strongest gust (km/h) expected in the next 12 hours, from the stored forecast (None = unknown).
    While the simulator is connected: the gusts of the simulated weather (285), no internet forecast."""
    sf = sim_forecast()
    if sf is not None:
        try:
            return float(sf.get("gust_kmh"))
        except (TypeError, ValueError):
            return None
    now = datetime.now(); best = None
    for k in range(13):
        t = now + timedelta(hours=k)
        d = weather_day(t.strftime("%Y-%m-%d")) or {}
        row = (d.get("hourly") or {}).get(t.strftime("%H"))
        if row and len(row) > 4 and isinstance(row[4], (int, float)):
            best = row[4] if best is None else max(best, row[4])
    return best


def storm_trend():
    """Change of the air pressure in hPa per 3 hours (negative = falling), from at least 1 hour of values."""
    P = list(STORM["p"])
    if len(P) < 2:
        return None
    t1, p1 = P[-1]
    old = [x for x in P if t1 - x[0] >= 3600]
    if not old:
        return None
    t0, p0 = min(old, key=lambda x: abs((t1 - x[0]) - 3 * 3600))
    return round((p1 - p0) * (3 * 3600.0) / (t1 - t0), 1)


def storm_warn(kind, text, test=False):
    now = time.time()
    if not test and now - STORM["cool"].get(kind, 0.0) < 3 * 3600:
        return False
    STORM["cool"][kind] = now
    STORM["last"] = datetime.now().strftime("%d.%m. %H:%M") + " " + text
    log_event("sys", f"STORM WARNING: {text}")
    w = WATCH_REF["w"]
    if w is not None:
        w.notifier.info(text, title="{name}: " + ("[Test] " if test else "") + tr("STORM WARNING"))
    return True


class StormWatch:
    def __init__(self):
        threading.Thread(target=self.loop, daemon=True, name="storm").start()

    def _pin(self):
        g = str(CFG["wind_gpio"] or "")
        want = int(g) if g.isdigit() else None
        if CFG["sim_on"]:
            return                                          # the simulation gives the wind
        if want == STORM["pin"] and (want is None or STORM["dev"] is not None or time.time() - STORM.get("tried", 0) < 30):
            return
        if STORM["dev"] is not None:
            try:
                STORM["dev"].close()
            except Exception:
                pass
        STORM["dev"] = None; STORM["pin"] = want; STORM["tried"] = time.time()
        if want is None:
            return
        try:
            from gpiozero import Button
            b = Button(want, pull_up=True, bounce_time=0.005)
            b.when_pressed = lambda: STORM.__setitem__("pulses", STORM["pulses"] + 1)
            STORM["dev"] = b
        except Exception as e:
            log_event("sys", f"Wind meter GPIO {want}: {e}"[:160])

    def loop(self):
        tp = 0.0
        while True:
            try:
                self.tick(tp); tp = time.time() if time.time() - tp >= 60 else tp
            except Exception as e:
                log_event("sys", f"Storm warning: {e}"[:160]); time.sleep(10)
            time.sleep(3)

    def tick(self, tp):
        now = time.time()
        if GPSMOD["anchor"] is not None and not (CFG["gpsmod_on"] and CFG["gps_theft"] and is_armed()):
            GPSMOD.update(anchor=None, away=0, alarm_t=0.0, dist=None)      # disarmed: theft tracking ends
        self._pin()
        n, STORM["pulses"] = STORM["pulses"], 0
        kmh = n / 3.0 * float(CFG["wind_factor"]) if STORM["pin"] is not None else None
        if CFG["sim_on"] and now - SIM["t"] < 10:
            kmh = float(SIM["wind"]); STORM["pin"] = STORM["pin"] if STORM["pin"] is not None else -1
        if kmh is not None:
            STORM["win"].append((now, kmh))
        env = STATE.get("env") or {}
        if env.get("p") and now - tp >= 60:
            STORM["p"].append((now, float(env["p"])))
        trend = storm_trend()
        win = [v for t, v in STORM["win"] if now - t <= 600]
        avg = round(sum(v for t, v in STORM["win"] if now - t <= 60) / max(1, len([1 for t, v in STORM["win"] if now - t <= 60])), 1) if win else None
        gust = round(max(win), 1) if win else None
        fc = storm_forecast_gust() if CFG["storm_forecast"] else None
        STATE["storm"] = {"p": env.get("p"), "trend": trend, "wind": avg, "gust": gust, "fc": fc, "last": STORM["last"],
                          "meter": STORM["pin"] is not None, "meter_ok": STORM["dev"] is not None or bool(CFG["sim_on"])}
        if not CFG["storm_on"]:
            return
        lim = float(CFG["storm_wind"])
        if trend is not None and trend <= -float(CFG["storm_drop"]):
            storm_warn("pressure", tr("the air pressure falls fast") + f" ({trend:+.1f} hPa / 3 h) - " + tr("strong wind or a thunderstorm may come. Secure the awning and the tent."))
        if gust is not None and gust >= lim:
            storm_warn("wind", tr("strong wind measured") + f": {gust:.0f} km/h - " + tr("secure the awning and the tent."))
        if fc is not None and fc >= lim:
            storm_warn("forecast", tr("gusts expected in the next 12 hours") + f": {fc:.0f} km/h - " + tr("secure the awning and the tent in time."))


STORMWATCH = None


# ----------------------------------------------------------------------------
# Own GPS module: gpsd (if it runs) or the NMEA sentences of a USB / serial receiver (u-blox, VK-162 ...). The position goes
#   into photos / videos and sets the place. Theft tracking: armed + carried away more than gps_theft_m -> alarm, then the
#   position with a map link every 5 minutes (push, and SMS if set up) until disarmed.
# ----------------------------------------------------------------------------
def nmea_ok(line):
    if not line.startswith("$") or "*" not in line:
        return False
    body, _, cs = line[1:].partition("*")
    x = 0
    for ch in body:
        x ^= ord(ch)
    try:
        return x == int(cs[:2], 16)
    except ValueError:
        return False


def _nmea_deg(v, hemi):
    if not v:
        return None
    d = float(v); deg = int(d // 100); val = deg + (d - deg * 100) / 60.0
    return -val if hemi in ("S", "W") else val


def nmea_parse(line):
    """{lat, lon} from RMC (status A), {sats, fix} from GGA - or None."""
    line = line.strip()
    if not nmea_ok(line):
        return None
    f = line.split("*")[0].split(",")
    typ = f[0][3:]
    try:
        if typ == "RMC" and len(f) > 6:
            if f[2] != "A":
                return {"fix": False}
            return {"lat": _nmea_deg(f[3], f[4]), "lon": _nmea_deg(f[5], f[6]), "fix": True}
        if typ == "GGA" and len(f) > 7:
            out = {"sats": int(f[7] or 0), "fix": (f[6] or "0") != "0"}
            if out["fix"]:
                out.update(lat=_nmea_deg(f[2], f[3]), lon=_nmea_deg(f[4], f[5]))
            return out
    except (ValueError, IndexError):
        return None
    return None


def gpsmod_fix(lat, lon, sats=None, via=""):
    if lat is None or lon is None or not (-90 <= lat <= 90 and -180 <= lon <= 180) or (lat == 0 and lon == 0):
        return
    first = GPSMOD["lat"] is None
    GPSMOD.update(lat=round(lat, 6), lon=round(lon, 6), t=time.time(), status="fix", via=via or GPSMOD["via"])
    if sats is not None:
        GPSMOD["sats"] = sats
    if first:
        log_event("sys", f"GPS module: position {lat:.4f}, {lon:.4f}")
    if via != "simulator" and (abs(lat - float(CFG["latitude"])) > 0.01 or abs(lon - float(CFG["longitude"])) > 0.01):   # ~1 km: a new place (never from the simulator)
        CFG["latitude"], CFG["longitude"] = round(lat, 4), round(lon, 4); save_settings()
    gps_theft_check()


def osm_link(lat, lon):
    return f"https://www.openstreetmap.org/?mlat={lat:.5f}&mlon={lon:.5f}#map=17/{lat:.5f}/{lon:.5f}"


def gps_map_link():
    """the map link of the device's own position (GPS module or the simulator's GPS, a fix of the last 5 minutes) for the
    sabotage alarms «device moved / knocked over / power cut» (060) - '' without a fresh fix (Paket «Diebstahl-Kartenlink»)"""
    g = GPSMOD
    if not CFG.get("gpsmod_on") or g.get("lat") is None or time.time() - float(g.get("t") or 0) > 300:
        return ""
    return osm_link(g["lat"], g["lon"])


def gps_theft_check():
    """Armed: the first position is the anchor. Further away than gps_theft_m twice in a row = carried away."""
    g = GPSMOD; now = time.time()
    if not (CFG["gpsmod_on"] and CFG["gps_theft"] and is_armed()) or g["lat"] is None:
        g["anchor"] = None; g["away"] = 0; g["alarm_t"] = 0.0; return
    if g["anchor"] is None:
        g["anchor"] = (g["lat"], g["lon"]); return
    dist = geo_km(g["anchor"], (g["lat"], g["lon"])) * 1000.0
    g["dist"] = round(dist)
    if dist < float(CFG["gps_theft_m"]):
        g["away"] = 0; return
    g["away"] += 1
    if g["away"] < 2:
        return
    w = WATCH_REF["w"]
    link = osm_link(g["lat"], g["lon"])
    if not g["alarm_t"]:
        g["alarm_t"] = now; g["upd_t"] = now
        txt = tr("the device was carried away") + f" ({dist / 1000.0:.2f} km). " + tr("Position") + ": " + link
        log_event("sys", f"THEFT: device carried away {dist:.0f} m - {g['lat']:.5f}, {g['lon']:.5f}")
        if w is not None:
            w.notifier.alert("{name}: " + tr("THEFT ALARM"), txt, w.frame_out)
        siren_alarm("tamper")
    elif now - g["upd_t"] >= 300:
        g["upd_t"] = now
        log_event("sys", f"THEFT tracking: {g['lat']:.5f}, {g['lon']:.5f}")
        if w is not None:
            w.notifier.alert("{name}: " + tr("THEFT ALARM") + " – " + tr("position"), tr("Position now") + f" ({dist / 1000.0:.2f} km): " + link, None)


def sim_sensor(key):
    """2.98.11: a sensor of the 3D simulator (solar panel, GPS module) while it is connected - instead of the real part"""
    if not CFG.get("sim_on") or time.time() - SIM.get("t", 0.0) > 10:
        return None
    v = SIM.get(key)
    return v if isinstance(v, dict) else None


class GpsModule:
    def __init__(self):
        threading.Thread(target=self.loop, daemon=True, name="gps").start()

    def loop(self):
        while True:
            if not CFG["gpsmod_on"]:
                GPSMOD["status"] = "off"; time.sleep(3); continue
            sg = sim_sensor("gps")
            if sg is not None:
                try:
                    GPSMOD["status"] = "fix"
                    gpsmod_fix(float(sg["lat"]), float(sg["lon"]), int(sg.get("sats") or 0), via="simulator")
                except (KeyError, TypeError, ValueError):
                    pass
                time.sleep(5); continue
            port = str(CFG["gpsmod_port"] or "auto")
            try:
                if port in ("auto", "gpsd") and self.gpsd():
                    pass
                elif port == "gpsd":
                    GPSMOD["status"] = "gpsd not running"; time.sleep(15)
                else:
                    busy = {str(CFG.get("sms_port") or "")}             # the AT port of an LTE stick stays for the SMS
                    ports = [port] if port != "auto" else [p for p in sorted(glob.glob("/dev/ttyACM*")) + sorted(glob.glob("/dev/ttyUSB*")) + ["/dev/serial0"]
                                                           if os.path.exists(p) and p not in busy]
                    if not ports:
                        GPSMOD["status"] = "no GPS module found"; time.sleep(15); continue
                    for p in ports:
                        if self.serial(p):
                            break
                    else:
                        GPSMOD["status"] = "no GPS module found"; time.sleep(15)
            except Exception as e:
                GPSMOD["status"] = f"error: {e}"[:100]; time.sleep(15)

    def gpsd(self):
        import socket
        try:
            sk = socket.create_connection(("127.0.0.1", 2947), timeout=2)
        except OSError:
            return False
        GPSMOD["via"] = "gpsd"; GPSMOD["status"] = "searching satellites"
        try:
            sk.sendall(b'?WATCH={"enable":true,"json":true};\n'); sk.settimeout(10)
            buf = b""
            while CFG["gpsmod_on"] and str(CFG["gpsmod_port"]) in ("auto", "gpsd"):
                try:
                    chunk = sk.recv(4096)
                except socket.timeout:
                    continue
                if not chunk:
                    break
                buf += chunk
                while b"\n" in buf:
                    line, buf = buf.split(b"\n", 1)
                    try:
                        d = json.loads(line)
                    except ValueError:
                        continue
                    if d.get("class") == "SKY":
                        GPSMOD["sats"] = sum(1 for x in d.get("satellites") or [] if x.get("used"))
                    elif d.get("class") == "TPV":
                        if (d.get("mode") or 0) >= 2 and "lat" in d and "lon" in d:
                            gpsmod_fix(float(d["lat"]), float(d["lon"]), via="gpsd")
                        elif time.time() - GPSMOD["t"] > 60:
                            GPSMOD["status"] = "searching satellites"
        finally:
            sk.close()
        return True

    def serial(self, port):
        import termios
        try:
            fd = os.open(port, os.O_RDONLY | os.O_NOCTTY | os.O_NONBLOCK)
        except OSError:
            return False
        try:
            try:
                at = termios.tcgetattr(fd)
                at[0] = 0; at[1] = 0; at[2] = termios.CS8 | termios.CREAD | termios.CLOCAL; at[3] = 0
                at[4] = at[5] = termios.B9600
                termios.tcsetattr(fd, termios.TCSANOW, at)
            except termios.error:
                pass                                          # USB modules (ttyACM) ignore the speed
            buf, t0, good = b"", time.time(), False
            GPSMOD["via"] = port
            while CFG["gpsmod_on"] and str(CFG["gpsmod_port"]) in ("auto", port):
                try:
                    chunk = os.read(fd, 1024)
                except BlockingIOError:
                    chunk = b""
                except OSError:
                    break
                if not chunk:
                    if not good and time.time() - t0 > 6:
                        return False                          # nothing that looks like GPS: not this port
                    time.sleep(0.2); continue
                buf += chunk
                while b"\n" in buf:
                    line, buf = buf.split(b"\n", 1)
                    r = nmea_parse(line.decode(errors="replace"))
                    if r is None:
                        continue
                    if not good:
                        good = True; GPSMOD["status"] = "searching satellites"; log_event("sys", f"GPS module found at {port}")
                    if "sats" in r:
                        GPSMOD["sats"] = r["sats"]
                    if r.get("fix") and r.get("lat") is not None:
                        gpsmod_fix(r["lat"], r["lon"], via=port)
                    elif time.time() - GPSMOD["t"] > 60:
                        GPSMOD["status"] = "searching satellites"
                if len(buf) > 4096:
                    buf = b""
            return good
        finally:
            os.close(fd)


GPSMODULE = None


# ----------------------------------------------------------------------------
# Solar panel: an INA219 module (the cheap blue board, shunt 0.1 Ohm, up to 26 V / 3.2 A) between the panel and the charger.
#   Watts, volts and the yield of the day. Night forecast: does the battery last until sunrise at the present consumption?
# ----------------------------------------------------------------------------
SOLAR = {"day": "", "wh": 0.0, "max": 0.0, "t": 0.0, "warned": ""}


def ina219_read(addr, shunt, bus=1):
    """(volts on the panel side, amps) or None."""
    import fcntl
    try:
        fd = os.open(f"/dev/i2c-{bus}", os.O_RDWR)
    except OSError:
        return None
    try:
        fcntl.ioctl(fd, I2C_SLAVE, addr)
        def reg(r):
            os.write(fd, bytes([r])); b = os.read(fd, 2)
            return (b[0] << 8) | b[1]
        bus_raw, sh = reg(0x02), reg(0x01)
        if sh & 0x8000:
            sh -= 0x10000
        return (bus_raw >> 3) * 0.004, sh * 0.00001 / max(0.001, float(shunt))
    except OSError:
        return None
    finally:
        os.close(fd)


def next_sunrise(now=None):
    now = now or sim_now()                                 # the simulated clock and place while connected (285)
    for k in (0, 1):
        d = (now + timedelta(days=k)).date()
        st = sun_times_here(d)
        if isinstance(st, str):
            return None
        t = datetime(d.year, d.month, d.day) + timedelta(minutes=st[0])
        if t > now:
            return t
    return None


def night_forecast():
    """Does the battery last until the next sunrise? {sunrise, need_h, have_h, enough} or None (no battery / unknown)."""
    b = STATE.get("battery") or {}
    if not b.get("on") or b.get("pct") is None or not b.get("cap_wh") or not b.get("use_w"):
        return None
    sr = next_sunrise()
    if sr is None:
        return None
    now = sim_now(); dark = is_dark()
    if dark:
        need = (sr - now).total_seconds() / 3600.0
    else:                                                  # daytime: the coming night (sunset .. sunrise), the sun still charges until then
        st = sun_times_here(now.date())
        ss = datetime(now.year, now.month, now.day) + timedelta(minutes=st[1]) if not isinstance(st, str) else now
        need = max(0.0, (sr - max(ss, now)).total_seconds() / 3600.0)
    have = b["pct"] / 100.0 * float(b["cap_wh"]) / max(0.5, float(b["use_w"]))
    return {"sunrise": sr.strftime("%H:%M"), "need_h": round(need, 1), "have_h": round(have, 1), "enough": have >= need * 1.1, "night": dark}


class SolarMonitor:
    def __init__(self):
        threading.Thread(target=self.loop, daemon=True, name="solar").start()

    def loop(self):
        while True:
            try:
                self.tick()
            except Exception as e:
                log_event("sys", f"Solar: {e}"[:160])
            time.sleep(10)

    def tick(self):
        now = time.time(); day = sim_now().strftime("%Y-%m-%d")      # the day of the simulated scene while connected (285)
        if SOLAR["day"] != day:
            SOLAR.update(day=day, wh=0.0, max=0.0)
        if CFG["solar_on"]:
            try:
                addr = int(str(CFG["solar_addr"]), 16)
            except ValueError:
                addr = 0x41
            try:
                pca_ = int(str(CFG["pca_address"]), 16)
            except ValueError:
                pca_ = -1
            clash = addr == pca_ and str(STATE.get("servo_backend", "")).startswith("pca9685")
            ss = sim_sensor("solar")
            if ss is not None:
                try:
                    r = (float(ss["v"]), float(ss["a"])); clash = False
                except (KeyError, TypeError, ValueError):
                    r = None
            else:
                r = None if clash else ina219_read(addr, CFG["solar_shunt"])
            if r is not None and not (0.0 <= r[0] <= 40.0 and abs(r[1]) <= 20.0):
                r = None                                  # not a plausible solar reading (another chip on that address?)
            if r is None:
                STATE["solar"] = {"on": True, "ok": False, "msg": "same I2C address as the servo board" if clash else ""}
            else:
                v, a = r; w = max(0.0, v * abs(a))
                dt = min(60.0, now - SOLAR["t"]) if SOLAR["t"] else 0.0; SOLAR["t"] = now
                SOLAR["wh"] += w * dt / 3600.0; SOLAR["max"] = max(SOLAR["max"], w)
                STATE["solar"] = {"on": True, "ok": True, "v": round(v, 2), "a": round(abs(a), 2), "w": round(w, 1),
                                  "wh": round(SOLAR["wh"], 1), "max": round(SOLAR["max"], 1)}
        else:
            STATE["solar"] = {"on": False}
        nf = night_forecast(); STATE["night"] = nf
        if nf and CFG["night_warn"] and not nf["enough"] and is_dark() and SOLAR["warned"] != day:
            hh = sim_now().hour
            if hh >= 15:                                       # once in the evening (not again after midnight)
                SOLAR["warned"] = day
                log_event("sys", f"Battery will probably not last until sunrise ({nf['have_h']} h left, {nf['need_h']} h needed)")
                w_ = WATCH_REF["w"]
                if w_ is not None:
                    w_.notifier.info(trf("The battery will probably not last until sunrise ({sr}): about {have} h left, {need} h needed. Charge it or switch on power saving.",
                                         sr=nf["sunrise"], have=nf["have_h"], need=nf["need_h"]), title="{name}: " + tr("Battery"))


SOLARMON = None


# ----------------------------------------------------------------------------
# Wish of Daniel (30.10.2026): while MoveEye is connected to the 3D simulator, the «hardware» readings come from the
# simulated world, not from the Pi. Before (kept): solar panel, GPS (+ theft), outside temperature / pressure / wind (storm),
# sound, thermal camera, head position, door / PIR / gas / bike sensors, darkness. New here (the simulator sends them in its
# answer to /state, simulator3d/scripts/power.gd -> SIM, taken in 350 SimLink.tick -> simvals_take):
#   battery   the simulated UPS HAT -> 100 BatteryMonitor (charge, time left, power cut / back, «almost empty», battery
#             saver 105, shutdown limit). «Empty» never shuts this computer down: MoveEye says what the device would do.
#   clock     the time of the scene -> sim_now(): schedules (030), night report (090), night time / «Heute Nacht bewachen»
#             and «Lagerfeuer bis» (130), night forecast + sunrise (280), battery forecast (066), the quiet night of the
#             sneeze answer (250), the timeline night (425), the solar day (280).
#             NOT for: log lines, file names, signatures, update checks, user time windows (041), backups - real time.
#             Sightings keep their real time stamps; sim_to_real() turns a simulated night into the real time span in which
#             the simulator ran through it (night report, timeline).
#   place     sun times (sun_times_here: schedules «dark» / «light», night forecast, diary day) use the place of the scene.
#   forecast  gusts and weather of the scene instead of Open-Meteo (060 weather_loop makes no internet call while connected,
#             280 storm_forecast_gust, the diary day 060 day_summary).
#   pi_temp   the CPU temperature of the simulated Pi -> STATE["cpu_temp"] (100 SysMonitor): heat warning, AI slower (180),
#             servo diagnosis (072), turbo (130), MQTT / devices. STATE["cpu_temp_real"] keeps the real value (run guard 390).
#   net       «WLAN weg» / «Internet weg» test of the simulator -> 110 online check (offline), 060 Notifier: alarms go to
#             the outbox and are sent later («nachgeschickt»), other messages fail like for real; nothing on the real network.
# After 10 s without an answer (simulator off / gone) everything is real again by itself (sim_live). STATE["simvals"] says
# which values come from the simulator - the web page and the window show «🧪 Simulator» there (part 598).
# ----------------------------------------------------------------------------
SIMVAL = {"live": False, "map": [], "net": "", "off": False, "off_t": 0.0, "temp_warned": False}


def simval_live():
    """the simulator is on and answered in the last 10 s"""
    return bool(CFG.get("sim_on")) and time.time() - float(SIM.get("t", 0.0)) <= 10      # a short hiccup (one failed request) does not count


def simvals_take(rep):
    """350 SimLink.tick: the new values of one answer of the simulator"""
    for k in ("battery", "clock", "place", "forecast", "net"):
        SIM[k] = rep.get(k) if isinstance(rep.get(k), dict) else None
    try:
        SIM["pi_temp"] = float(rep["pi_temp"]) if rep.get("pi_temp") is not None else None
    except (TypeError, ValueError):
        SIM["pi_temp"] = None
    try:
        st = sim_now().timestamp()
        M = SIMVAL["map"]; now = time.time()
        if not M or now - M[-1][0] >= 20 or abs((st - M[-1][1]) - (now - M[-1][0]) * float((SIM.get("clock") or {}).get("speed") or 1.0)) > 300:
            M.append((now, st))
            del M[:-3000]                                  # about 16 hours at one point per 20 s
    except Exception:
        pass


def sim_now():
    """The time of the simulated world while connected (the simulator sends date + hour; between two answers it runs on
    with the speed of the time-lapse) - otherwise the real local time. Only for decisions about day and night (see top)."""
    c = sim_sensor("clock")
    if c is None:
        return datetime.now()
    try:
        d = datetime.strptime(str(c["date"])[:10], "%Y-%m-%d")
        h = float(c["hour"]) % 24.0 + max(0.0, time.time() - float(SIM.get("t", 0.0))) * float(c.get("speed") or 1.0) / 3600.0
        return d + timedelta(hours=h)
    except (KeyError, TypeError, ValueError):
        return datetime.now()


def sim_to_real(dt):
    """A moment of the simulated clock -> the real time at which the simulator showed it (from the points of this
    connection). Not connected / unknown: unchanged. Before the first point: the first point."""
    if not simval_live() or not SIMVAL["map"]:
        return dt
    M = SIMVAL["map"]; s = dt.timestamp()
    if float((SIM.get("clock") or {}).get("speed") or 1.0) <= 1.0 and abs(sim_now().timestamp() - time.time()) < 120:
        return dt                                           # the simulator runs on the real clock: nothing to turn
    if s >= M[-1][1]:
        return datetime.fromtimestamp(min(time.time(), M[-1][0] + (s - M[-1][1]) / max(1.0, float((SIM.get("clock") or {}).get("speed") or 1.0))))
    for i in range(len(M) - 1, 0, -1):
        (r0, s0), (r1, s1) = M[i - 1], M[i]
        if s0 <= s <= s1 and s1 > s0:
            return datetime.fromtimestamp(r0 + (r1 - r0) * (s - s0) / (s1 - s0))
        if s1 < s0:                                         # the clock was set back here: older points are another night
            return datetime.fromtimestamp(r1)
    return datetime.fromtimestamp(M[0][0])


def sim_place():
    """(lat, lon, name) of the scene while connected, else None"""
    p = sim_sensor("place")
    try:
        return (float(p["lat"]), float(p["lon"]), str(p.get("name") or "")) if p else None
    except (KeyError, TypeError, ValueError):
        return None


def here_latlon():
    p = sim_place()
    return (p[0], p[1]) if p else (float(CFG["latitude"]), float(CFG["longitude"]))


def sun_times_here(d):
    """sun_times (030) for the place of MoveEye - or of the simulated scene, in the time zone of the scene"""
    lat, lon = here_latlon()
    st = sun_times(d, lat, lon)
    c = sim_sensor("clock") if sim_place() else None
    if c is not None and isinstance(st, tuple):
        try:
            loc = datetime(d.year, d.month, d.day, 12).astimezone().utcoffset().total_seconds() / 60.0
            off = float(c.get("tz_h", 1.0)) * 60.0 - loc
            st = (st[0] + off, st[1] + off)
        except (OverflowError, OSError, ValueError, TypeError):
            pass
    return st


def sim_forecast():
    return sim_sensor("forecast")


SIM_WX = {"clear": ("☀️", "clear"), "cloudy": ("☁️", "cloudy"), "fog": ("🌫", "fog"), "rain": ("🌧", "rain"), "snow": ("🌨", "snow")}


def sim_weather_day(lang=None):
    """the weather of the scene for the diary day (instead of Open-Meteo)"""
    f = sim_forecast()
    if not f:
        return None
    icon, key = SIM_WX.get(str(f.get("weather")), ("🌤", "partly cloudy"))
    return {"icon": icon, "text": tr(key, lang), "tmax": f.get("tmax"), "tmin": f.get("tmin"), "rain": None,
            "wind": round(float(SIM.get("wind") or 0.0)), "gust": f.get("gust_kmh"), "hourly": {}, "sim": True}


def sim_pi_temp():
    if not simval_live():
        return None
    return SIM.get("pi_temp")


def sim_net_down():
    """'wifi' / 'internet' while the simulator plays «WLAN weg» / «Internet weg», else ''"""
    n = sim_sensor("net")
    if not n:
        return ""
    return "wifi" if n.get("wifi") is False else ("internet" if n.get("internet") is False else "")


def simnet_hold(nf, p, jpg, fname):
    """060 Notifier._dispatch while the simulator plays a network outage: like a failed send - an alarm waits in the
    outbox (sent later, also into the test inbox), other messages are lost (as for real). Nothing goes out."""
    ev = nf._event(p)
    alarm = ev in ("person", "tamper", "warm", "noise")
    why = sim_net_down()
    STATE["notify_status"] = "error: " + ("no Wi-Fi" if why == "wifi" else "no internet") + " (simulator)"
    log_event("web", f"Notification not sent - {'Wi-Fi' if why == 'wifi' else 'internet'} gone (simulator test)")
    msglog_add(nf._title(p), push_with_map(nf._text(p), p, " · "), ev, jpg, "failed", "🧪 " + ("no Wi-Fi" if why == "wifi" else "no internet"))
    if alarm and not p.get("late"):
        outbox_add(dict(p, sandbox=bool(sandbox_active() or p.get("_test"))), jpg, fname)


def simvals_tick():
    """once a second (100 SysMonitor): what comes from the simulator (STATE["simvals"]) and the change back to real"""
    live = simval_live()
    if live != SIMVAL["live"]:
        SIMVAL["live"] = live
        if live:
            log_event("sys", "Simulator values: battery, clock, place, weather and Pi temperature come from the simulator")
        else:
            log_event("sys", "Simulator values ended - the real sensors and the real clock apply again")
            SIMVAL["map"] = []
            if SIMVAL["off"]:
                SIMVAL["off"] = False
    nd = sim_net_down() if live else ""
    if nd != SIMVAL["net"]:
        SIMVAL["net"] = nd
        log_event("sys", ("Simulator test: Wi-Fi gone" if nd == "wifi" else "Simulator test: internet gone") if nd else "Simulator test: network back")
        w = WATCH_REF.get("w")
        try:
            w.netmon.recheck = True                          # the online check (110) at once
        except Exception:
            pass
        if not nd:
            OUTBOX["kick"] = True                            # waiting alarms out at once
            if "(simulator)" in str(STATE.get("notify_status") or ""):
                STATE["notify_status"] = ""                  # no «push problem» afterwards: the outage was only the test
    if not live:
        STATE["simvals"] = {"on": False}
        return
    now = sim_now(); pl = sim_place(); b = sim_sensor("battery")
    keys = [k for k, ok in (("battery", b is not None), ("clock", sim_sensor("clock") is not None), ("place", pl is not None),
                            ("weather", sim_forecast() is not None), ("pi_temp", SIM.get("pi_temp") is not None),
                            ("solar", bool(CFG.get("solar_on")) and sim_sensor("solar") is not None),
                            ("gps", bool(CFG.get("gpsmod_on")) and sim_sensor("gps") is not None), ("net", sim_sensor("net") is not None)) if ok]
    STATE["simvals"] = {"on": True, "keys": keys, "time": now.strftime("%H:%M"), "date": now.strftime("%Y-%m-%d"),
                        "speed": float((SIM.get("clock") or {}).get("speed") or 1.0), "dark": bool(SIM.get("dark")),
                        "place": pl[2] if pl else "", "lat": pl[0] if pl else None, "lon": pl[1] if pl else None,
                        "weather": (sim_forecast() or {}).get("weather"), "net": nd, "pi_temp": SIM.get("pi_temp"),
                        "off": bool(SIMVAL["off"]), "sched": [s["name"] for s in SCHEDULES if schedule_active(s, now)] if SCHEDULES else []}


def sim_battery_tick(bm, sb):
    """100 BatteryMonitor.tick with the simulated UPS HAT: the same display and the same reactions as the real HAT (E)"""
    try:
        v, a, pct = float(sb["v"]), float(sb["a"]), int(sb["pct"])
    except (KeyError, TypeError, ValueError):
        return False
    on_batt = bool(sb.get("on_battery", True)) and not bool(sb.get("charging") and sb.get("mains"))
    charging = bool(sb.get("charging"))
    cap_wh = float(sb.get("cap_wh") or 0.0)
    use_w = float(sb.get("load_w") or 0.0)
    ml = sb.get("min_left")
    hours = round(float(ml) / 60.0, 1) if on_batt and ml else (round(pct / 100.0 * cap_wh / max(0.8, use_w), 1) if on_batt and cap_wh else None)
    STATE["battery"] = {"on": True, "src": "ups", "model": "sim", "sim": True, "pct": pct, "hours": hours, "cap_wh": round(cap_wh, 1),
                        "use_w": round(use_w, 1), "watts": round(use_w, 1), "volt": round(v, 2), "amps": round(a, 2), "on_battery": on_batt,
                        "charging": charging, "full": bool(sb.get("full")), "temp": sb.get("temp"), "solar_w": sb.get("solar_w"),
                        "full_min": None}
    if not getattr(bm, "_sim_seen", False):
        bm._sim_seen = True
        log_event("sys", f"Simulated UPS HAT (simulator): battery {v:.2f} V, {pct} %")
    bm.ups_events(v, pct, hours, on_batt, False)          # volt_ok False: never the real shutdown of this computer
    lim = int(CFG["ups_shutdown_pct"])
    drill_ = drill_active("battery") if "drill_active" in globals() else False   # 565: the drill «battery empty» never «shuts down»
    if not SIMVAL["off"] and on_batt and lim > 0 and (pct <= lim or sb.get("empty")) and not drill_:
        SIMVAL["off"] = True; SIMVAL["off_t"] = time.time()
        log_event("sys", f"Battery empty ({pct} %, {v:.2f} V) - the Pi would shut down now (simulator: this computer stays on)")
        w = WATCH_REF.get("w")
        if w is not None and CFG["ups_push"]:
            w.notifier.info(tr("Battery empty – the Pi shuts down cleanly") + " (🧪 " + tr("simulator") + ")", title="{name}: " + tr("power"))
    elif SIMVAL["off"] and (pct >= lim + 10 or not on_batt):
        SIMVAL["off"] = False
        log_event("sys", f"Battery charged again ({pct} %) - the Pi would start again (simulator)")
    STATE["battery"]["sim_off"] = bool(SIMVAL["off"])
    return True
# ----------------------------------------------------------------------------
# Simulator connection: a separate program (motionwatch_simulator.py, protocol in motionwatch_sim_interface.py) simulates two
#   cameras, a thermal camera, day / night, weather and sensors. One switch: the sources change to the simulator, MoveEye
#   sends what it does (servos, lights, relays, sound, armed) about 10 x per second and takes the world from the answer.
# ----------------------------------------------------------------------------
SIM = {"mover": False, "t": 0.0, "ok": False, "msg": "off", "dark": False, "ambient": 15.0, "pressure": 1013.0, "wind": 0.0, "last_event": 0,
       "seen_event": 0, "info": None, "sent": 0, "since": 0.0, "errs": 0, "rtt": 0.0, "events_n": 0, "th_times": deque(maxlen=30)}


def sim_base():
    u = str(CFG.get("sim_url") or "http://127.0.0.1:8765").strip().rstrip("/")
    return u if re.match(r"^https?://[A-Za-z0-9.\-\[\]:]{1,120}$", u) else "http://127.0.0.1:8765"


_SIM_OPENER = urllib.request.build_opener(urllib.request.ProxyHandler({}))   # the simulator is in the own network: never via a proxy


def _sim_get(path, timeout=2.0):
    with _SIM_OPENER.open(urllib.request.Request(sim_base() + path, headers={"User-Agent": "MotionWatch"}), timeout=timeout) as r:
        return r.read(), r.headers


class SimThermalSource:
    """The thermal camera of the simulator: temperatures in °C (like the Waveshare Thermal-90)."""
    def __init__(self):
        self.size = None; self.t = 0.0

    def ok(self):
        r = self.read()
        return r[0]

    def read(self):
        try:                                             # 557: the model of the simulator (Thermal-90: 15 fps like the driver, 080)
            fps_ = max(2.0, min(25.0, float(((SIM.get("info") or {}).get("thermal") or {}).get("fps") or 8.0)))
        except (TypeError, ValueError):
            fps_ = 8.0
        wait = (1.0 / sim_cam_fps(1) if sim_eco_now() else 1.0 / fps_ - 0.005) - (time.time() - self.t)
        if wait > 0:
            time.sleep(wait)
        self.t = time.time()
        try:
            data, hd = _sim_get("/thermal.bin", 2.0)
            a = np.frombuffer(data, dtype="<f4").reshape(int(hd["X-Height"]), int(hd["X-Width"])).copy()
            self.size = (a.shape[1], a.shape[0]); SIM["th_times"].append(time.time())
            return True, a
        except Exception:
            return False, None

    def set_fps(self, fps):
        pass

    def release(self):
        pass


def cam_fov():
    """2.98.1: field of view (horizontal, vertical in degrees) of the main camera - known in the simulation (/info),
    otherwise the Camera Module 3 (66° x 41°) or what is set"""
    try:
        if CFG.get("sim_on") and str(CFG["source"]).startswith("sim:"):
            info = SIM.get("info") or {}
            cam = next((c for c in info.get("cameras") or [] if str(c.get("id")) == str(CFG["source"])[4:]), None)
            if cam and cam.get("fov_h"):
                hf = float(cam["fov_h"])
                vf = math.degrees(2 * math.atan(math.tan(math.radians(hf) / 2) * float(cam.get("h") or 9) / float(cam.get("w") or 16)))
                return hf, vf
    except (TypeError, ValueError, KeyError):
        pass
    try:
        return cam_fov_hv(None)[:2]                      # 2.98.30: the field of view per camera (318: model, own value, picamera2)
    except NameError:
        return float(CFG.get("cam_hfov") or 66.0), float(CFG.get("cam_vfov") or 41.0)


def servo_half(axis):
    """half the turning range of a servo in degrees: 0 … 100 % = -half … +half (the pan servo may turn 270° or 360°)"""
    try:
        r = float(CFG.get("pan_servo_range") or CFG["servo_range"]) if axis == "pan" else float(CFG["servo_range"])
    except (TypeError, ValueError):
        r = 180.0
    return max(10.0, min(360.0, r)) / 2.0


def _sim_refscan_info():
    try:
        st = refscan_state()
        r = st["reports"][0] if st["reports"] else None
        return {"busy": st["busy"], "step": st["step"], "n": st["n"], "ref": bool(st["ref"]), "ref_n": (st["ref"] or {}).get("n", 0),
                "last": {"missing": r["missing"], "new": r["new"], "changed": r["changed"], "t": r["t"], "gone": r.get("gone") or []} if r else None,
                "night_ref": bool((st.get("refs") or {}).get("night")),
                "cmd_seen": int(SIM.get("cmd_seen") or 0)}
    except Exception:
        return None


def _simtask_now():
    try:
        return simtask_local()
    except NameError:
        return ""


def sim_state():
    hp, ht = servo_half("pan"), servo_half("tilt")
    pl, tl = min(float(CFG["pan_limit"]), hp), min(float(CFG["tilt_limit"]), ht)
    L = STATE.get("lights") or {}
    rs = STATE.get("relay_states") or []
    return {"v": 1, "t": time.time(), "device": CFG["device_name"] or "MoveEye", "armed": is_armed(),
            "uid": f"{device_uid()}:{CFG.get('web_port')}", "helper": bool(STATE.get("helper_arg")),   # 2.98.29: uid/helper - one MoveEye leads the simulator (3D-4.9)
            # Aufräumen 2 (one field list: simulator3d/schnittstelle.json, self-test 558): «picture_mode» and «simtask» are no
            # longer sent (nobody read them: MoveEye makes the picture grey itself, the simulator shows «simtask_de»)
            "mw_version": APP_VERSION, "ai_status": str(STATE.get("ai_status") or ""),     # 2.95.67: for the test bench in the simulator
            "refscan": _sim_refscan_info(),                                                  # 2.95.97: the reference scan, for the button there
            # 2.98.35: the REAL position of the motion planner (072, ramps) + its speed (the simulator goes on with it between
            # two packets) and the goal (it never goes past it)
            "servo": {"pan": round((sp_ := servo_pos())[0], 2), "tilt": round(sp_[1], 2), "pan_deg": round((sp_[0] - 50) / 50 * hp, 2),
                      "tilt_deg": round((sp_[1] - 50) / 50 * ht, 2), "pan_limit": pl, "tilt_limit": tl,
                      "pan_dps": round((sv_ := servo_speed_deg())[0], 1), "tilt_dps": round(sv_[1], 1),
                      "pan_goal": round((CFG["pan"] - 50) / 50 * hp, 2), "tilt_goal": round((CFG["tilt"] - 50) / 50 * ht, 2),
                      "estop": bool(servo_blocked()),
                      "pan_range": round(2 * hp, 1),             # the whole turning range of the pan servo (2.95.24, for the Python simulator)
                      "moving": bool(SRV["moving"]) or time.time() - SERVO_MOVE["t"] < 0.5,
                      # 2.98.1: «Folgen» on, and following something right now - the simulator lets the head follow then (not the patrol)
                      "track": bool(CFG["track_person"] or CFG["track_motion"]), "tracking": bool(STATE.get("tracking")),
                      "track_what": str(STATE.get("track_what") or "")},
            "ups_mah": int(CFG.get("ups_mah") or 3450),   # Aufräumen 2: the battery size - the simulator shows it «von MoveEye» (power.gd)
            "lights": {"white": bool(L.get("white")), "ir": bool(L.get("ir")), "white_level": 1.0, "ir_level": 1.0},
            "wake": {"state": WAKE["state"], "snoozes": WAKE["snoozes"], "t0": round(WAKE["t0"], 2)},       # 2.98.9: the sleeper in the bedroom scene reacts
            "relays": [{"name": r["name"], "on": bool(rs[i]) if i < len(rs) else False} for i, r in enumerate(RELAYS)],
            "sound": (CFG["siren_sound"] or "siren") if SOUND["playing"] else ("talk" if TALK["proc"] is not None else ""),
            "simtask_de": tr(stk_, "de") if (stk_ := _simtask_now()) else "",   # 2.98.13: one lock (147)
            "eco": STATE.get("eco") or "off",     # power saving of MoveEye: «saving» = quiet - the simulator may calculate slower (3D-3.30)
            # automatic update: the simulator compares these checksums with its own files and fetches /sim/simulator.zip
            # (only the Python simulator updates itself with them - the 3D simulator (/info «view») gets an empty list)
            "sim_files": {} if (SIM.get("info") or {}).get("view") else sim_files(), "mw_scheme": "https" if WEB_OPTS.get("https") else "http", "mw_port": int(CFG["web_port"]),
            # CPU in % of the whole computer: total, MoveEye, simulator (None = not on this computer / unknown)
            "cpu": {"total": STATE.get("cpu"), "mw": STATE.get("cpu_mw"), "sim": STATE.get("cpu_sim")},
            # what MoveEye detects right now: the simulator compares it with the truth (test run, game «MoveEye decides»)
            "real_look": real_look(),               # 2.98.6: the look of the real pictures (146_echt_abgleich.py, realism.gd 3D-3.94)
            "det": {"persons": int(STATE.get("persons") or 0), "present": list(STATE.get("present") or []), "armed": is_armed(),
                    "boxes": list(STATE.get("person_boxes") or []) if STATE.get("persons") else [],   # 2.95.75: 0..1 of the head camera
                    "sure": list(STATE.get("person_sure") or []) if STATE.get("persons") else [],     # KI-Hilfe: confirmed by the AI (542)
                    "noise": bool(AUDIO is not None and AUDIO.noisy()),
                    "pushes": msglog_recent(4)},             # after 2.98.17: the test bench counts real pushes (068)
            # the tracks of the mover: -1 … 1 each (from 2.94.0)
            "drive": {"l": MOVER["l"], "r": MOVER["r"]},
            # 2.96.5 (makeover 9 / 10): the twin - zones (0..1 of the picture), patrol points (degrees), the place
            "zones": [{"name": z.get("name", ""), "mode": z.get("mode", "ignore"), "points": z.get("points", [])} for z in ZONES[:12]],
            "waypoints": [[round((float(w[0]) - 50) / 50 * hp, 1), round((float(w[1]) - 50) / 50 * ht, 1)] for w in WAYPOINTS[:12]
                          if isinstance(w, (list, tuple)) and len(w) >= 2]}


_SIMFILES = {}


VIEWERS = {}                       # web page / guest page -> time of its last poll; the Pi screen counts as one more


def viewers_now():
    """How many watch right now: every browser (main page or guest link) that asked in the last 8 s, plus the open
    window on the Pi screen."""
    now = time.time()
    for k in [k for k, t in VIEWERS.items() if now - t > 30]:
        VIEWERS.pop(k, None)
    web = sum(1 for t in VIEWERS.values() if now - t <= 8)
    local = 1 if now - STATE.get("local_view_t", 0.0) <= 5 else 0
    return {"n": web + local, "web": web, "local": local}


