# ----------------------------------------------------------------------------
# 2.98.16 (Fehlalarme durch Tiere, Prüfstand): auf ebenem Boden steht eine Person weiter unten im Bild (näher) grösser da
# als weiter oben (weiter weg) – die Höhe im Bild wächst fast linear mit dem Abstand der Füsse vom Horizont. MoveEye lernt
# diese Gerade aus den Personen, die die KI sicher bestätigt hat (pro Neigung des Kopfes). Ein Ding, das nur durch seine
# Bewegung als «Person» gälte, aber viel kleiner ist, als eine Person an dieser Stelle wäre (Dachs, Katze, Fuchs), wird
# keine Person. Ohne genug gelernte Personen (die ersten Abende) prüft es nichts.
# ----------------------------------------------------------------------------
SIZEFIT = {"b": {}, "fit": {}, "t": 0.0, "rejects": 0}
SIZE_MIN_SAMPLES = 12


def _size_bucket():
    try:
        return int(round(float(CFG.get("tilt", 50)) / 3.0))     # the tilt of the head: another tilt = another line
    except (TypeError, ValueError):
        return 0


def size_learn(tracks, ai_boxes, pw, ph):
    """the AI-confirmed, upright persons of this picture: (feet row, height) both 0..1"""
    if not ai_boxes or ph <= 0:
        return
    b = SIZEFIT["b"].setdefault(_size_bucket(), deque(maxlen=120))
    for (x, y, w, h, *_r) in ai_boxes:
        if h < 0.04 * ph or w > 0.9 * h or y + h > 0.985 * ph or y < 0.01 * ph:
            continue                                     # not upright, or cut off at the edge: the size is not reliable
        b.append(((y + h) / ph, h / ph))
    now = time.time()
    if now - SIZEFIT["t"] > 5.0:
        SIZEFIT["t"] = now
        for k, d in SIZEFIT["b"].items():
            if len(d) >= SIZE_MIN_SAMPLES:
                a = np.array(d, dtype=np.float32)
                if float(a[:, 0].max() - a[:, 0].min()) < 0.12:
                    continue                             # all at the same distance: no line yet
                m, c = np.polyfit(a[:, 0], a[:, 1], 1)
                res = a[:, 1] - (m * a[:, 0] + c)
                ok = np.abs(res) < 2.5 * (np.std(res) + 1e-3)
                if ok.sum() >= SIZE_MIN_SAMPLES * 0.7:
                    m, c = np.polyfit(a[ok, 0], a[ok, 1], 1)
                if m > 0.05:                             # lower in the picture = bigger: a sensible line
                    SIZEFIT["fit"][k] = (float(m), float(c), len(d))


def size_expected(box, ph):
    f = SIZEFIT["fit"].get(_size_bucket())
    if not f or ph <= 0:
        return None
    yb = (box[1] + box[3]) / ph
    e = f[0] * yb + f[1]
    return e if e > 0.02 else None


def size_ok(t, ph):
    """False when the thing is much smaller than a person standing at that place would be (crouching persons are about half
    as high, crawling ones a third - so only clearly smaller things are refused, and never one the AI calls a person)"""
    if not CFG.get("size_check", True) or getattr(t, "ai_confirmed", False):
        return True
    e = size_expected(t.box, ph)
    if e is None:
        return True
    h = t.box[3] / ph
    small = h < 0.28 * e
    if small and not getattr(t, "_size_rej", False):
        t._size_rej = True; SIZEFIT["rejects"] += 1
    return not small


def size_state():
    f = SIZEFIT["fit"].get(_size_bucket())
    return {"learned": bool(f), "persons": int(f[2]) if f else len(SIZEFIT["b"].get(_size_bucket(), [])), "rejects": SIZEFIT["rejects"]}


def foot_selftest():
    """real-reh-fusspunkt (232, third round): at night a roe deer / fox from the SIDE (flat) is an animal; a child 1.0 m, a
    crouching person (also one that never stands up), a roe deer straight from the front and a standing person stay persons;
    a crawling person is an animal without an AI hint and «Person?» with AI >= 0.15 + movement / warmth; by day no animal.
    Camera 1.6 m high, 6° down - boxes from the flat-ground geometry with the field of view of this camera."""
    vf, cam_h, pitch = erk_vfov(), 1.6, -6.0
    hf = cam_fov()[0]
    k = math.tan(math.radians(vf) / 2.0)
    ThermalCam.main_aspect = 9 / 16.0

    def box(dist, height, width=0.4, cx=0.5, ch=None):
        ch = cam_h if ch is None else ch                     # ch = the real camera height (the estimate below uses cam_h)

        def row(z):                                          # picture row 0..1 of a point z m above the ground at dist m
            return 0.5 + math.tan(math.atan((ch - z) / dist) + math.radians(pitch)) / (2.0 * k)
        y0, y1 = row(height), row(0.0)
        w = width / (2.0 * dist * math.tan(math.radians(hf) / 2.0))
        return (cx - w / 2.0, y0, w, y1 - y0)

    def run(seq, night=True, maybe=False, ch=None):
        """seq = [(dist, height, width)] one picture each 0.5 s -> the last decision (like thermal_classify); ch = real
        camera height (the foot point always assumes cam_h = 1.6 m)"""
        hist = deque(maxlen=50); c = None
        for n, (dist, height, width) in enumerate(seq):
            b = box(dist, height, width, ch=ch)
            d = thermal_person_check(b)
            c = foot_decide(b, d, foot_estimate(b, cam_h, pitch, vf) if d is None else None, night, 100.0 + 0.5 * n, hist, maybe, vf)
        return c[0] if c else None
    for dist, height in ((6.0, 1.75), (12.0, 1.6), (9.0, 0.85), (5.0, 0.45)):
        fe = foot_estimate(box(dist, height), cam_h, pitch, vf)
        assert fe is not None and abs(fe[0] - dist) < 0.05 * dist and abs(fe[1] - height) < 0.05, (dist, height, fe)
    assert foot_estimate(box(40.0, 1.7), cam_h, 6.0, vf) is None          # feet near the horizon: no estimate
    assert foot_estimate((0.5, 0.3, 0.05, 0.7), cam_h, pitch, vf) is None  # cut off at the lower edge
    deer_side = [(10.0 - 0.6 * i, 0.9, 1.3) for i in range(5)]            # h/w 0.69
    fox_side = [(9.0 - 0.8 * i, 0.45, 0.8) for i in range(5)]             # h/w 0.56
    crawl = [(7.0 - 0.2 * i, 0.45, 1.5) for i in range(5)]
    assert run(deer_side) == "animal" and run(fox_side) == "animal", (run(deer_side), run(fox_side))
    assert run(fox_side[:2]) == "wait"                                    # 2 pictures in 0.5 s: not decided yet
    assert run(fox_side, night=False) is None                             # by day: no animal (only warm, as before)
    assert run([(9.0, 1.05, 1.2)] * 5) is None                            # deer with the head high (0.88): only warm
    assert run([(9.0, 1.0, 0.35)] * 5) == "person"                        # roe deer straight from the front: person («im Zweifel»)
    assert run([(7.0, 1.0, 0.3)] * 5) == "person"                         # child 1.0 m
    assert run([(6.0, 1.0, 0.55)] * 8) == "person"                        # crouching, never stands up
    assert run([(6.0, 1.75, 0.5)] * 5) == "person"
    assert run([(6.0, 1.75, 0.5)] * 2 + crawl) is None                    # stood, then lies down: never an animal
    assert run(crawl) == "animal" and run(crawl, maybe=True) is None      # crawling: animal without AI, «Person?» wins
    tr_ = [(0.40, 0.70, 0.22, 0.10)]                                      # a movement track at the same place
    assert weak_person_check((0.41, 0.71, 0.20, 0.08, 0.17), tr_, [], None)
    assert not weak_person_check((0.41, 0.71, 0.20, 0.08, 0.10), tr_, [], None)     # AI below 0.15
    assert not weak_person_check((0.41, 0.71, 0.20, 0.08, 0.17), [], [], None)      # nothing confirms it
    assert not weak_person_check((0.45, 0.50, 0.05, 0.30, 0.20), [(0.45, 0.5, 0.05, 0.3)], [], None)   # upright: not flat
    # camera 30 % higher than thought (really 2.1 m, the foot point assumes 1.6 m): the boxes are made with 2.1 m, judged with
    # 1.6 m (Code-Prüfung K8: before, the test gave fe=None with an upright box - the foot point was never used)
    fe_hi = foot_estimate(box(8.0, 0.5, 0.9, ch=2.1), cam_h, pitch, vf)
    assert fe_hi is not None and fe_hi[0] < 8.0 * 0.85, ("the wrong height must change the foot distance", fe_hi)
    assert run([(8.0, 1.65, 0.5)] * 5, ch=2.1) == "person"                # standing
    assert run([(7.0, 1.0, 0.3)] * 5, ch=2.1) == "person"                 # child 1.0 m
    assert run([(6.0, 1.0, 0.55)] * 8, ch=2.1) == "person"                # crouching, never stands up
    assert run([(9.0, 1.0, 0.35)] * 5, ch=2.1) == "person"                # roe deer straight from the front
    wide = box(6.0, 1.0, 0.8, ch=2.1)                                    # crouching wide (h/w 1.25): not upright -> foot point
    assert thermal_person_check(wide) is None and foot_estimate(wide, cam_h, pitch, vf) is not None
    assert run([(6.0, 1.0, 0.8)] * 8, ch=2.1) is None                     # ... and still no animal (only warm)
    crawl_hi = [(7.0 - 0.2 * i, 0.45, 1.5) for i in range(5)]
    assert run(crawl_hi, maybe=True, ch=2.1) is None                      # crawling + AI hint («Person?»): never an animal
    assert run(crawl_hi, ch=2.1) == "animal"                              # without AI hint: thermal_person_feed decides (M3)
    return True


def thermal_maybe_selftest():
    """Code-Prüfung M3: a flat warm body that the foot point calls «animal» is only an animal when the AI really looked for
    weak persons (own run or PC helper with the standard model) - AI off / helper without weak boxes: «Person?» (alarm)"""
    class _AI:
        weak_ok_t = 0.0
    keep = (globals()["thermal_classify"], CFG.get("ai_enabled"), DEMO.get("on"), dict(TPERS), STATE.get("person_maybe"))
    _le = globals()["log_event"]
    try:
        globals()["thermal_classify"] = lambda b, t0=None, maybe=False: ("animal", 6.0, 0.45, 14.0)
        globals()["log_event"] = lambda *a, **k: None
        CFG["ai_enabled"] = True; DEMO["on"] = False
        fr = np.zeros((90, 160, 3), np.uint8)
        wb = [(0.40, 0.70, 0.22, 0.08)]

        def feed(ai, t0=100.0):
            pb, pres = [], set()
            rest = thermal_person_feed(list(wb), pb, pres, fr, 160, 90, 160, 90, t0, (), ai=ai)
            return pres, pb, rest
        ai = _AI(); ai.weak_ok_t = 99.0                     # the AI looked 1 s ago: an animal, no person
        pres, pb, rest = feed(ai)
        assert "animal" in pres and "person" not in pres and not pb and rest == wb, (pres, pb)
        ai.weak_ok_t = 0.0                                   # helper without weak boxes / AI not running: «Person?»
        pres, pb, rest = feed(ai)
        assert "person" in pres and "animal" not in pres and len(pb) == 1 and not rest, ("no «Person?» without the AI", pres)
        ai.weak_ok_t = 99.0; CFG["ai_enabled"] = False       # AI switched off: «Person?»
        pres, pb, rest = feed(ai)
        assert "person" in pres and "animal" not in pres, ("AI off: animal", pres)
        CFG["ai_enabled"] = True
        assert not thermal_ai_checked(100.0, None) or WATCH_REF.get("w") is not None
        assert thermal_ai_checked(100.0, ai) and not thermal_ai_checked(100.0 + WEAK_OK_S + 1, ai)
    finally:
        globals()["thermal_classify"] = keep[0]; globals()["log_event"] = _le
        CFG["ai_enabled"] = keep[1]; DEMO["on"] = keep[2]; TPERS.clear(); TPERS.update(keep[3]); STATE["person_maybe"] = keep[4]
    return "flat warm body: animal only after an AI check, else «Person?» (AI off, PC helper without weak boxes)"

SELFTEST_EXTRA.append(("Thermal picture: animal or person from the foot point (232)", foot_selftest))
SELFTEST_EXTRA.append(("Thermal picture: no «animal» without an AI check, «Person?» instead (232, M3)", thermal_maybe_selftest))
# ----------------------------------------------------------------------------
# real-erk-e1 (Erkennungstest 31.10.2026, Schwachstellen 2, 6, 7):
# 1) «Feste Fehl-Person»: the AI calls a small spruce on a stone base, a tree trunk in the infrared light ... a person, all the
#    time. The head turned after it (−30° → −71°) and a push «Person, ca. 2 m» came for a trunk. Now a person box of the AI that
#    does not move for minutes is remembered as a THING («spot», in degrees: it stays on its place when the head turns):
#    - it never walked there: no moving track (a person walking in) was at that place shortly before or when it appeared,
#    - it stands still: middle within FIX_STILL of its height, height within FIX_SIZE (a few jumps of the AI box are allowed),
#    - for FIX_LEARN_S (3 min) - or only FIX_LEARN_START_S when it was there already at the start (camera / scene new),
#    - Entscheid Daniel (31.10.2026): only a THERMAL CAMERA that sees it NOT warm (FIX_COLD_N looks, never warm) makes it a
#      thing by itself. Without a thermal camera (or no clear reading) it only gets the card below and STAYS A PERSON (push,
#      the head follows) until «Ignorieren» is tapped; warm like a body: nothing (a person).
#    A learned spot: its AI box and a person track standing on it are no person (no push, the head does not follow, drawn
#    grey «OBJECT?»). It is a person again at once when the box moves clearly or another person comes onto it. A card on
#    the Live / Schutz page shows the picture: «Hier steht etwas, das wie eine Person aussieht – ignorieren?» → a mask
#    (anchored ignore zone for persons, like «Platz einrichten») / «Ist eine Person» (never learnt there again) / «Später».
# 2) «Tier vor Person»: once the AI saw an animal (dog, cat, sheep, bird, cow, horse, bear …) on a track, the track keeps that
#    class: no person from the movement (also not «sticky» from before), no «Person?» and no thermal person on it. A new track
#    where an animal was a moment ago inherits it. Only the AI itself saying «person» over FIX_ANIMAL_AI_S (and no animal in
#    that time) makes it a person again («im Zweifel Person» when the AI is sure).
# Gegenprobe (Daniel): a person who walked in and then stands still for a long time is NEVER learnt (walked = for good).
# ----------------------------------------------------------------------------
FIX_LEARN_S = 180.0         # «über Minuten»: 3 min without moving. A visitor standing that long in front of a camera without
                            # having walked there (the case «walked» is never learnt) is very rare; a tree stands for ever.
FIX_LEARN_START_S = 45.0    # there already when the camera / scene started (MoveEye put up, «Einrichten»): the false persons of
                            # the test were there from the first picture; 45 s ≈ 20 AI runs at the 2 fps of the simulator.
FIX_START_WIN_S = 90.0      # «at the start»: a spot first seen in the first 90 s after the camera / scene started
FIX_HEAD_STILL_S = 2.0      # learn only while the head stood still 2 s (the planned servo position is ahead of the picture)
FIX_MATCH = 0.35            # the same spot: middle within 0.35 × its size (degrees) and height ratio 0.6 … 1.67 (the AI box
FIX_MATCH_H = 1.67          # of a tree jumps 10 … 25 % from run to run; a person 2 steps away is outside)
FIX_STILL = 0.25            # «stands still»: middle within 0.25 × its height of where it was first seen, height within FIX_SIZE
FIX_SIZE = 1.33             # (3 pictures in a row outside = it moved: the learning starts again)
FIX_CONF_SURE = 0.75        # the AI is sure it is a person (score >= 0.75 in half of the looks): never learnt («im Zweifel Person»).
                            # Offline with the test model (test-coco640) on the pictures of the test: the spruce 0.30 / 0.56, the
                            # trunk 0.27, the stump in the dusk 0.25 - real persons near the camera are mostly far above.
FIX_COLD_N = 3              # «not warm» in at least 3 looks of the thermal camera (and in at least half of its looks, never warm)
FIX_GAP_S = 25.0            # not seen for 25 s while learning: forgotten (the AI misses a thing now and then, not for that long)
FIX_KEEP_S = 1800.0         # a learnt spot not seen for 30 min is forgotten (light changed, head somewhere else)
FIX_WALK_LOOK_S = 60.0      # «walked in»: a moving track at that place in the last 60 s before the spot appeared (or 5 s after) -
                            # the AI may find a person only after it stopped; a minute covers a slow AI and a short pause
FIX_WALK_AFTER_S = 5.0
FIX_ANIMAL_MEM_S = 4.0      # an animal of the AI is remembered 4 s on its place (the AI runs only now and then; a new track there inherits it)
FIX_ANIMAL_AI_S = 1.0       # an animal track becomes a person only when the AI says «person» on it for 1 s (≥ 2 runs of the AI on
                            # the Pi, 0.3 … 0.6 s apart) and no animal in that time: one wrong «person» of a dog is not enough
FIXP = {"spots": [], "moving": deque(maxlen=1000), "animals": deque(maxlen=60), "start_t": 0.0, "head": None, "head_t": 0.0,
        "offers": [], "next": 1, "learned_n": 0, "suppressed": 0}


def fixp_reset(t0=None):
    """new camera / scene (410 reset_scene): the spots are forgotten (another picture), the start window begins again"""
    FIXP["spots"] = []; FIXP["moving"].clear(); FIXP["animals"].clear()
    FIXP["start_t"] = time.time() if t0 is None else t0


def _fixp_ang(b, pw, ph, head=None):
    """box in working pixels -> (azimuth, elevation, width, height) in degrees (the head position + the field of view)"""
    hf, vf = cam_fov()
    pa, ta = servo_pos_deg() if head is None else head
    x, y, w, h = [float(v) for v in b[:4]]
    return (pa + ((x + w / 2.0) / pw - 0.5) * hf, ta - ((y + h / 2.0) / ph - 0.5) * vf, max(0.05, w / pw * hf), max(0.05, h / ph * vf))


def _fixp_match(s, a):
    """a (angle box) is the same thing as the spot s"""
    sz = max(s["a"][2], s["a"][3])
    if math.hypot(a[0] - s["a"][0], a[1] - s["a"][1]) > FIX_MATCH * sz:
        return False
    r = a[3] / max(1e-6, s["a"][3])
    return 1.0 / FIX_MATCH_H <= r <= FIX_MATCH_H


def _fixp_ov(a, b):
    """overlap of two angle boxes (middle, size): intersection / smaller area"""
    ix = max(0.0, min(a[0] + a[2] / 2, b[0] + b[2] / 2) - max(a[0] - a[2] / 2, b[0] - b[2] / 2))
    iy = max(0.0, min(a[1] + a[3] / 2, b[1] + b[3] / 2) - max(a[1] - a[3] / 2, b[1] - b[3] / 2))
    return ix * iy / max(1e-9, min(a[2] * a[3], b[2] * b[3]))


def _fixp_walked(a, t_from, t_to):
    """a moving track (a person walking in) was at this place in the time window"""
    area = a[2] * a[3]
    for m in reversed(FIXP["moving"]):
        if m[0] < t_from:
            return False
        if m[0] <= t_to and _fixp_ov(a, m[1]) > 0.2 and m[1][2] * m[1][3] >= 0.2 * area:
            return True
    return False


def _fixp_came(s, t0, why):
    """a person walked onto the spot: a person (not learnt) as long as it stays - learnt again only after it left (fixp_track)"""
    if s["learned"]:
        log_event("person", f"Still object #{s['id']}: a person {why} - a person again")
    s.update(learned=False, suggest=False, came=True, first=t0, a0=s["a"], out=0, at_start=False)


def fixp_thermal_judge(region, scene, celsius, delta_pct=None):
    """True = warm like a body, False = clearly not warm, None = not clear. region / scene: arrays of the thermal picture.
    °C: warm = 3 °C over the scene and 25 … 42 °C (a body through clothes); cold = less than 1.5 °C over the scene.
    8-bit picture (the simulator): the step of ThermalCam.detect (thermal_delta of the warm side of the scale); cold = below half
    of that step."""
    if region is None or region.size < 2 or scene is None or scene.size < 4:
        return None
    body, med = float(np.percentile(region, 80)), float(np.median(scene))
    if celsius:
        if body - med >= 3.0 and 25.0 <= body <= 42.0:
            return True
        return False if body - med < 1.5 else None
    lo, hi = float(np.percentile(scene, 2)), float(np.percentile(scene, 99.5))
    sc = 255.0 / max(1e-3, hi - lo)
    b_, m_ = (body - lo) * sc, (med - lo) * sc
    step = (float(CFG.get("thermal_delta", 30)) if delta_pct is None else delta_pct) / 100.0 * max(min(255.0, 2.0 * (255.0 - m_)), 64.0)
    if b_ > m_ + step:
        return True
    return False if b_ < m_ + 0.5 * step else None


def _fixp_thermal(b, pw, ph):
    """what the thermal camera says about the box (x, y, w, h working pixels): True warm / False not warm / None no camera or unclear"""
    th = THERMAL
    if th is None or not CFG.get("thermal_source") or getattr(th, "frame", None) is None or time.time() - float(getattr(th, "t", 0.0) or 0.0) > 3.0:
        return None
    try:
        f = th.crop(th.frame)
        celsius = f.dtype != np.uint8
        f = f.astype(np.float32)
        if f.ndim == 3:
            f = f.mean(axis=2)
        H, W = f.shape[:2]
        x0, y0 = max(0, int(b[0] / pw * W)), max(0, int(b[1] / ph * H))
        x1, y1 = min(W, int(math.ceil((b[0] + b[2]) / pw * W))), min(H, int(math.ceil((b[1] + b[3]) / ph * H)))
        return fixp_thermal_judge(f[y0:y1, x0:x1], f, celsius)
    except Exception:
        return None


def fixp_spot_step(s, a, t0, start_t, walked, warm=None, conf=0.0):
    """one observation a (angle box) of the spot s at t0 - the decision without the camera (self-test). warm = the thermal
    camera: True warm / False not warm / None none or unclear. Returns "learned" when the spot just became a thing (thermal:
    not warm), "suggest" when only the card comes (no thermal camera: stays a person), "moved" when a learned spot moved."""
    if walked:
        s["walked"] = True                                   # walked in: for good never a thing
    if warm:
        s["warm"] = True
    elif warm is False:
        s["cold"] = s.get("cold", 0) + 1
    if warm is not None:
        s["th_n"] = s.get("th_n", 0) + 1
    s["last"] = t0; s["n"] += 1
    s["sure"] = s.get("sure", 0) + (1 if conf >= FIX_CONF_SURE else 0)
    still = (math.hypot(a[0] - s["a0"][0], a[1] - s["a0"][1]) <= FIX_STILL * s["a0"][3]
             and 1.0 / FIX_SIZE <= a[3] / max(1e-6, s["a0"][3]) <= FIX_SIZE)
    s["out"] = 0 if still else s["out"] + 1
    s["a"] = tuple(0.8 * p + 0.2 * q for p, q in zip(s["a"], a))      # the AI box jitters: a slow average
    if s["out"] >= 3:                                        # it moved (not one jump of the AI box)
        was = s["learned"]
        s.update(a0=tuple(a), first=t0, out=0, learned=False, suggest=False, at_start=False)
        return "moved" if was else None
    need = FIX_LEARN_START_S if s["at_start"] else FIX_LEARN_S
    if (not s["learned"] and not s["walked"] and not s.get("came") and not s["warm"] and not s["never"] and t0 - s["first"] >= need
            and s["sure"] * 2 < s["n"]):
        if s.get("cold", 0) >= FIX_COLD_N and s["cold"] * 2 >= s.get("th_n", 0):
            s["learned"] = True                              # the thermal camera says: not warm -> a thing by itself
            return "learned"
        if not s.get("suggest"):
            s["suggest"] = True                              # no thermal camera: only the card, it stays a person
            return "suggest"
    return None


def fixp_new_spot(a, t0, start_t):
    s = {"id": FIXP["next"], "a": tuple(a), "a0": tuple(a), "first": t0, "last": t0, "n": 0, "out": 0, "learned": False,
         "walked": False, "came": False, "warm": False, "never": False, "suggest": False, "cold": 0, "th_n": 0, "at_start": t0 - start_t <= FIX_START_WIN_S, "offered": False}
    FIXP["next"] += 1
    return s


def fixp_filter_ai(ai_boxes, pw, ph, t0, small=None):
    """410, before the AI persons become tracks: learn the spots from the AI person boxes and drop the boxes on learnt spots.
    Returns the AI person boxes that stay persons."""
    if not FIXP["start_t"]:
        FIXP["start_t"] = t0
    head = servo_pos_deg()
    if FIXP["head"] is None or abs(head[0] - FIXP["head"][0]) > 0.3 or abs(head[1] - FIXP["head"][1]) > 0.3:
        FIXP["head"] = head; FIXP["head_t"] = t0
    still = t0 - FIXP["head_t"] >= FIX_HEAD_STILL_S and not manual_active()
    spots = FIXP["spots"]
    out = []
    for b in ai_boxes:
        a = _fixp_ang(b, pw, ph, head)
        s = next((s for s in spots if _fixp_match(s, a)), None)
        if s is None:
            for o in spots:                                  # a person box on a spot that is not the thing itself, walking:
                if _fixp_ov(a, o["a"]) > 0.3 and _fixp_walked(a, t0 - 2.0, t0):     # another person comes onto it
                    _fixp_came(o, t0, "comes onto it")
            if still and len(spots) < 12:
                s = fixp_new_spot(a, t0, FIXP["start_t"])
                s["walked"] = _fixp_walked(a, t0 - FIX_WALK_LOOK_S, t0)
                spots.append(s)
            out.append(b); continue
        if _fixp_walked(a, t0 - 2.0, t0) and (s["learned"] or t0 - s["first"] > FIX_WALK_AFTER_S):
            _fixp_came(s, t0, "walks there")                 # the box of a walking person (the AI box sits on the thing)
        if still or s["learned"]:
            walked = t0 - s["first"] <= FIX_WALK_AFTER_S and _fixp_walked(a, s["first"], t0)
            r = fixp_spot_step(s, a, t0, FIXP["start_t"], walked, _fixp_thermal(b, pw, ph) if not s["learned"] else None,
                               float(b[4]) if len(b) > 4 else 0.0) if still else None
            if r == "learned":
                FIXP["learned_n"] += 1
                log_event("person", f"Still object #{s['id']}: a «person» that has not moved for {int(t0 - s['first'])} s and did not walk "
                                    f"there - from now on a thing (no alarm, the head does not follow)")
                _fixp_offer(s, b, small, pw, ph, t0)
            elif r == "suggest":
                log_event("person", f"Still object #{s['id']}: a «person» that has not moved for {int(t0 - s['first'])} s - no thermal camera "
                                    f"confirms it is not warm: it stays a person, the card «ignore it?» is shown")
                _fixp_offer(s, b, small, pw, ph, t0)
            elif r == "moved":
                log_event("person", f"Still object #{s['id']} moved - a person again")
        if s["learned"]:
            FIXP["suppressed"] += 1; continue
        out.append(b)
    FIXP["spots"] = [s for s in spots if t0 - s["last"] <= (FIX_KEEP_S if s["learned"] else FIX_GAP_S)]
    while FIXP["animals"] and t0 - FIXP["animals"][0][0] > FIX_ANIMAL_MEM_S:
        FIXP["animals"].popleft()
    while FIXP["moving"] and t0 - FIXP["moving"][0][0] > FIX_WALK_LOOK_S + FIX_WALK_AFTER_S:
        FIXP["moving"].popleft()
    return out


def fixp_head_still(t0):
    """seconds the head has stood still (set by fixp_filter_ai every picture; 232 uses it: no speed of warm bodies while it turns)"""
    return t0 - FIXP["head_t"] if FIXP["head"] is not None else 0.0


def fixp_track(t, pw, ph, t0):
    """410, after classify, for every track: remember moving tracks (a person walking in) and take the person away from a
    track that stands on a learnt spot (the AI box is gone, «sticky» kept it a person)"""
    head = FIXP["head"] or servo_pos_deg()
    still = t0 - FIXP["head_t"] >= FIX_HEAD_STILL_S
    learned = [s for s in FIXP["spots"] if s["learned"]]
    if t.lost:
        return
    x, y, w, h = t.box
    net = math.hypot(t.center()[0] - t.start[0], t.center()[1] - t.start[1])
    a = None
    if (still and len(t.hist) >= 3 and t0 - getattr(t, "_fx_t", 0.0) >= 0.4 and net >= max(10.0, 0.5 * max(w, h))
            and (t.is_person or t.steadiness() >= CFG["speed_consistency"])):
        a = _fixp_ang(t.box, pw, ph, head); t._fx_t = t0
        FIXP["moving"].append((t0, a))                   # goes somewhere (no branch swinging to and fro), 2-3 times a second
        for s in FIXP["spots"]:                          # the person that came onto a spot walks away again: the thing may be
            if s.get("came") and not _fixp_match(s, a) and _fixp_ov(a, s["a"]) < 0.1 and any(   # learnt again (from 0)
                    _fixp_match(s, _fixp_ang((px - w / 2.0, py - h / 2.0, w, h), pw, ph, head)) for px, py in list(t.hist)[-12:-3]):
                s.update(came=False, first=t0, a0=s["a"], out=0, at_start=False)
    sup = False
    if (t.is_person or getattr(t, "fixp", False)) and learned and net < max(10.0, 0.5 * max(w, h)):
        a = a or _fixp_ang(t.box, pw, ph, head)
        sup = any(_fixp_match(s, a) for s in learned)
    if sup:
        t.is_person = False                              # 410 classify: no person from the movement while fixp is set
    t.fixp = sup


def fixp_animal_note(boxes, pw, ph, t0):
    """the animals of the AI in this picture (x, y, w, h, conf, cls) -> remembered FIX_ANIMAL_MEM_S on their place"""
    for o in boxes:
        FIXP["animals"].append((t0, tuple(o[:4]), COCO_LABELS.get(o[5], "animal") if len(o) > 5 else "animal"))


def fixp_animal_of(box, t0, same=False):
    """an animal of the AI (now or a moment ago) lies on this box -> its class, else None. same = it must be the same thing
    (IoU > 0.5: for a track the AI calls a person - a dog walking next to its owner does not make the owner an animal)"""
    for tt, b, cls in reversed(FIXP["animals"]):
        if t0 - tt <= FIX_ANIMAL_MEM_S and (iou(box, b) > 0.5 if same else (iou(box, b) > 0.15 or _ov(box, b) > 0.5)):
            return cls
    return None


VEHICLE_LABELS = ("car", "truck", "bus", "motorcycle", "train")


def fixp_veto(tracks, ai_objs, pw, ph, t0):
    """for «Person?» and the thermal person (232): where the camera / AI sees an animal or a vehicle - boxes 0..1 with the kind
    [(x, y, w, h, "animal" | "vehicle")]"""
    out = [(b[0] / pw, b[1] / ph, b[2] / pw, b[3] / ph, "animal") for tt, b, _c in FIXP["animals"] if t0 - tt <= FIX_ANIMAL_MEM_S]
    for t in tracks:
        if t.lost or t.is_person:
            continue
        k = "animal" if getattr(t, "animal_like", False) else ("vehicle" if t.is_vehicle else None)
        if k:
            out.append((t.box[0] / pw, t.box[1] / ph, t.box[2] / pw, t.box[3] / ph, k))
    for o in ai_objs:
        if COCO_LABELS.get(o[5]) in VEHICLE_LABELS:
            out.append((o[0] / pw, o[1] / ph, o[2] / pw, o[3] / ph, "vehicle"))
    return out


def animal_track_decide(t, ai_person, animal_cls, t0):
    """Tier vor Person for one track (410 classify): -> True when the track is an animal (no person from movement / sticky).
    ai_person = the AI calls it a person now; animal_cls = an animal of the AI lies on it now (or a moment ago)."""
    if animal_cls:
        t.animal_like = True; t.animal_cls = animal_cls; t.animal_t = t0; t.ai_p_since = 0.0
    if not getattr(t, "animal_like", False):
        return False
    if ai_person and not animal_cls:
        if not getattr(t, "ai_p_since", 0.0):
            t.ai_p_since = t0
        if t0 - t.ai_p_since >= FIX_ANIMAL_AI_S:             # the AI says «person» on it again and again: a person after all
            t.animal_like = False; t.animal_cls = None
            return False
    elif not ai_person:
        t.ai_p_since = 0.0
    return True


def _fixp_offer(s, b, small, pw, ph, t0):
    """the card «Hier steht etwas, das wie eine Person aussieht – ignorieren?» with the picture of the spot"""
    if s["offered"] or any(o["sid"] == s["id"] for o in FIXP["offers"]):
        return
    s["offered"] = True
    jpg = None
    if small is not None:
        try:
            x, y, w, h = [int(v) for v in b[:4]]
            m = int(max(w, h) * 0.6) + 10
            x0, y0 = max(0, x - m), max(0, y - m); x1, y1 = min(small.shape[1], x + w + m), min(small.shape[0], y + h + m)
            crop = small[y0:y1, x0:x1].copy()
            cv2.rectangle(crop, (x - x0, y - y0), (x - x0 + w, y - y0 + h), (0, 200, 255), 2)
            if crop.shape[0] < 160:
                f_ = 160.0 / crop.shape[0]; crop = cv2.resize(crop, (int(crop.shape[1] * f_), 160))
            ok, buf = cv2.imencode(".jpg", crop, [cv2.IMWRITE_JPEG_QUALITY, 80])
            jpg = buf.tobytes() if ok else None
        except (cv2.error, ValueError):
            jpg = None
    FIXP["offers"].append({"id": uuid.uuid4().hex[:10], "sid": s["id"], "t": t0, "jpg": jpg, "state": ""})
    FIXP["offers"] = FIXP["offers"][-5:]


def fixp_state():
    now = time.time()
    return {"ok": True, "learned": sum(1 for s in FIXP["spots"] if s["learned"]), "learning": sum(1 for s in FIXP["spots"] if not s["learned"]),
            "offers": [{"id": o["id"], "age": int(now - o["t"]), "pic": bool(o["jpg"]), "auto": bool(sp["learned"])}
                       for o in FIXP["offers"] if not o["state"] for sp in FIXP["spots"] if sp["id"] == o["sid"] and (sp["learned"] or sp.get("suggest"))]}


def fixp_answer(oid, op):
    """«mask» = an anchored ignore zone for persons over the spot (stays when the head turns, editable in the zone editor),
    «person» = it is a person: never learnt there again, «later» = the card goes away (the spot stays as it is: a thing only
    when the thermal camera said «not warm», else a person)"""
    o = next((o for o in FIXP["offers"] if o["id"] == oid), None)
    if o is None:
        return False, "gone"
    s = next((s for s in FIXP["spots"] if s["id"] == o["sid"]), None)
    o["state"] = op
    if op == "person":
        if s:
            s.update(learned=False, suggest=False, never=True)
        log_event("person", "Still object: «it is a person» - not learnt there again")
        return True, ""
    if op != "mask" or s is None:
        return True, ""
    if len(ZONES) >= MAX_ZONES:
        return False, "at most 12 zones"
    a, e, w, h = s["a"]
    mg = 1.0                                                 # 1° more on every side (the servo and the field of view are not exact)
    ang = [[a - w / 2 - mg, e + h / 2 + mg], [a + w / 2 + mg, e + h / 2 + mg], [a + w / 2 + mg, e - h / 2 - mg], [a - w / 2 - mg, e - h / 2 - mg]]
    pts = [[round(min(1.0, max(0.0, x)), 4), round(min(1.0, max(0.0, y)), 4)] for x, y in sleep_project(ang)[::8]]
    z = {"mode": "ignore", "kinds": "person", "name": "🌲 " + tr("Looks like a person"), "points": pts, "ang": ang,
         "anchor": True, "id": uuid.uuid4().hex[:8]}
    ok, err = zones_set([dict(z_) for z_ in ZONES] + [z])
    if ok:
        s.update(learned=True, suggest=False)                # at once (the zone does it from now on too)
        log_event("person", "Still object: taken as a mask (ignore zone for persons)")
    return ok, err


def fixp_draw(frame, sx, sy, pw, ph):
    """the learnt spots in the live picture: thin grey box «OBJECT?» (only those in the picture now)"""
    if not FIXP["spots"]:
        return
    hf, vf = cam_fov(); pa, ta = servo_pos_deg(); now = time.time()
    for s in FIXP["spots"]:
        if not s["learned"] or now - s["last"] > 3.0:
            continue
        a, e, w, h = s["a"]
        cx = ((a - pa) / hf + 0.5) * pw; cy = (0.5 - (e - ta) / vf) * ph; bw = w / hf * pw; bh = h / vf * ph
        x0, y0 = int((cx - bw / 2) * sx), int((cy - bh / 2) * sy); x1, y1 = int((cx + bw / 2) * sx), int((cy + bh / 2) * sy)
        cv2.rectangle(frame, (x0, y0), (x1, y1), (160, 160, 160), 1)
        cv2.putText(frame, "OBJECT? (ignored)", (x0, max(14, y0 - 5)), cv2.FONT_HERSHEY_SIMPLEX, 0.45, (160, 160, 160), 1, cv2.LINE_AA)


def fixp_routes(app, reply, body):
    """/api/fixp (state, answer) and /api/fixp/pic/<id> (the picture of the card) - called once by the web server (550)"""
    from flask import Response, g, request

    @app.route("/api/fixp", methods=["GET", "POST"])
    def api_fixp():
        if request.method == "GET":
            return reply(fixp_state())
        if getattr(g, "role", "admin") != "admin":
            return reply({"ok": False, "error": "not allowed"}, 403)
        d = body()
        op = str(d.get("op") or "")
        if op not in ("mask", "person", "later"):
            return reply({"ok": False, "error": "op"}, 400)
        ok, err = fixp_answer(str(d.get("id") or ""), op)
        return reply({"ok": ok, "error": tr(err) if err else None}, 200 if ok else 400)

    @app.route("/api/fixp/pic/<oid>")
    def api_fixp_pic(oid):
        o = next((o for o in FIXP["offers"] if o["id"] == oid and o["jpg"]), None)
        if o is None:
            return Response(b"", status=404)
        return Response(o["jpg"], mimetype="image/jpeg", headers={"Cache-Control": "no-store"})


# the card on the Live / Schutz page (main page 530); German texts by 639l
