def app_icon_id():
    ic = str(CFG.get("app_icon") or "moveeye")
    return ic if ic in dict(APP_ICON_LIST) else "moveeye"


def host_variant():
    """'ext' when the page was opened over Tailscale (100.x address or *.ts.net name), else 'int'. '' outside a request."""
    try:
        from flask import has_request_context, request
        if not has_request_context():
            return ""
        host = (request.host or "").rsplit(":", 1)[0].strip("[]") if not (request.host or "").startswith("[") else request.host[1:].split("]")[0]
    except Exception:
        return ""
    return "ext" if (is_remote_ip(host) or host.lower().endswith(".ts.net")) else "int"


def app_title(variant):
    return "MoveEye"          # 2.96.0: MoveEye (before: Motion Watch); one name and one icon for every address (since 2.3.0)


def app_icon_png(size, variant="", icon=None):
    """App icon (home screen, tab). From 2.95.23 one of several (setting «App icon»): the radar eye and its relatives are
    stored as 512 px PNG and scaled; «classic» is the old orange tile with the camera head, drawn here."""
    ic = icon if icon in dict(APP_ICON_LIST) else app_icon_id()
    key = (ic, size)
    if key in _ICONS:
        return _ICONS[key]
    if ic != "classic" and ic in APP_ICONS_PNG:
        import base64
        src = cv2.imdecode(np.frombuffer(base64.b64decode("".join(APP_ICONS_PNG[ic])), np.uint8), cv2.IMREAD_COLOR)
        if src is not None:
            im = cv2.resize(src, (size, size), interpolation=cv2.INTER_AREA)
            ok, buf = cv2.imencode(".png", im)
            _ICONS[key] = buf.tobytes() if ok else b""
            return _ICONS[key]
    n = 4 * size; k = n / 100.0
    top, bot = np.array((67, 159, 255), np.float32), np.array((12, 89, 232), np.float32)        # #ff9f43 -> #e8590c (BGR)
    g = np.linspace(0, 1, n, dtype=np.float32)[:, None, None]
    img = np.ascontiguousarray(np.repeat((top * (1 - g) + bot * g), n, axis=1).astype(np.uint8))
    W, B, L = (255, 255, 255), (20, 14, 10), (12, 89, 232)
    P = lambda x, y: (int(round((50 + x) * k)), int(round((46 + y) * k)))
    th = max(1, int(round(6 * k)))

    def line(pts):
        cv2.polylines(img, [np.array([P(*q) for q in pts], np.int32)], False, W, th, cv2.LINE_AA)
        for q in (pts[0], pts[-1]):
            cv2.circle(img, P(*q), th // 2, W, -1, cv2.LINE_AA)

    def quad(a, c, e, steps=12):
        return [((1 - t) ** 2 * a[0] + 2 * (1 - t) * t * c[0] + t * t * e[0], (1 - t) ** 2 * a[1] + 2 * (1 - t) * t * c[1] + t * t * e[1])
                for t in [i / steps for i in range(steps + 1)]]
    line([(-26, -6), (-26, 10)] + quad((-26, 10), (-26, 20), (-16, 20)) + [(16, 20)] + quad((16, 20), (26, 20), (26, 10)) + [(26, -6)])   # fork
    line([(0, 20), (0, 30)]); line([(-14, 32), (14, 32)])                                                                                  # stand
    for r, col in ((19, W), (11, B), (6, L)):
        cv2.circle(img, P(0, 0), int(round(r * k)), col, -1, cv2.LINE_AA)
    cv2.circle(img, P(-3.5, -3.5), int(round(2.6 * k)), W, -1, cv2.LINE_AA)
    img = cv2.resize(img, (size, size), interpolation=cv2.INTER_AREA)
    ok, buf = cv2.imencode(".png", img)
    _ICONS[key] = buf.tobytes() if ok else b""
    return _ICONS[key]


def app_manifest():
    v = host_variant(); name = app_title(v)
    return json.dumps({"name": name, "short_name": name, "start_url": "/", "scope": "/", "display": "standalone",
                       "background_color": "#e8590c" if app_icon_id() in ("classic", "moveeye") else "#0e1621", "theme_color": "#0b0f14", "lang": CFG["lang"],
                       # the name of the icon in the address: a new icon is a new address, so Android fetches it again
                       "icons": [{"src": "/icon-192.png?i=" + app_icon_id(), "sizes": "192x192", "type": "image/png", "purpose": "any maskable"},
                                 {"src": "/icon-512.png?i=" + app_icon_id(), "sizes": "512x512", "type": "image/png", "purpose": "any maskable"}]})


SW_JS = r"""// MoveEye service worker: shows web push messages (alarm) and opens the page on a tap
self.addEventListener("install", e => self.skipWaiting());
self.addEventListener("activate", e => e.waitUntil(self.clients.claim()));
self.addEventListener("push", e => {
  let d = {};
  try { d = e.data ? e.data.json() : {}; } catch (x) { d = {body: e.data ? e.data.text() : ""}; }
  e.waitUntil(self.registration.showNotification(d.title || "MoveEye", {
    body: d.body || "", icon: "/icon-192.png", badge: "/icon-192.png", tag: d.tag || "mw", renotify: true,
    requireInteraction: !!d.urgent, vibrate: d.urgent ? [300, 120, 300, 120, 300] : [120], data: {url: d.url || "/"}}));
});
self.addEventListener("notificationclick", e => {
  e.notification.close();
  const url = (e.notification.data && e.notification.data.url) || "/";
  let ext = false; try { ext = new URL(url, self.location.href).origin !== self.location.origin; } catch (x) {}
  if (ext) { e.waitUntil(self.clients.openWindow(url)); return; }   // a message with a position: the map in a new window
  e.waitUntil(self.clients.matchAll({type: "window", includeUncontrolled: true}).then(cs => {
    for (const c of cs) { if ("focus" in c) { try { c.navigate(url); } catch (x) {} return c.focus(); } }
    return self.clients.openWindow(url);
  }));
});
"""


def i18n_loader(help_=False):
    """Runs first: for French, Italian and Romansh the page gets its translation file (cached by the browser per version)."""
    return ("<script>" + LANG_JS.replace("</", "<\\/") + "\n(function(){var l='';try{l=localStorage.getItem('mw-lang')||'';}catch(e){}if(!l)l=" + json.dumps(CFG["lang"]) + ";"
            "window.LX=function(s){var d=window.I18NX;return (d&&d[s])||'';};"
            "if(['fr','it','rm'].indexOf(l)>=0)document.write('<script src=\"/i18n/'+l+'.js?v=" + APP_VERSION + ("&h=1" if help_ else "")
            + "\"><\\/script>');})();</script>")


def i18n_js(lang, help_=False):
    """/i18n/<lang>.js: the translations of one language for the pages (Romansh: German where nothing is translated yet)."""
    L = norm_lang(lang)
    d = dict(TRX.get(L, {}))
    out = "window.I18NX=" + json.dumps(d, ensure_ascii=False, separators=(",", ":")) + ";"
    if help_:
        out += "window.HELPX=" + json.dumps(HELP_X.get(L, ""), ensure_ascii=False) + ";"
    out += "window.MSGX=" + json.dumps(MSG_DEFAULTS.get(L, {}), ensure_ascii=False) + ";"
    return out.replace("</", "<\\/")


def render_page(page, active):
    """Fill the shared pieces into a page template."""
    page = page.replace("<head>", "<head>" + ui_seed_script() + i18n_loader(active == "help") + PWA_HEAD.replace(
        'content="MoveEye">', 'content="' + app_title(host_variant()) + '">').replace(".png\"", ".png?i=" + app_icon_id() + "\"")
        + "<script>window.MW_ICON=" + json.dumps(app_icon_id()) + ";</script>" + makeover_head()
        + ("<style>:root{--mw-icon:url(/app-icon/anim.svg?i=" + app_icon_id() + ")}</style>"
           if CFG.get("app_icon_anim", True) and app_icon_id() in APP_ICONS_ANIM else ""), 1)
    if CFG.get("header_wordmark", True):                # 2.96.11: the wordmark W6 / W1 instead of icon + name (144)
        page = re.sub(r"(<h1[^>]*>)MoveEye</h1>", lambda m_: wordmark_h1(m_) + "</h1>", page, count=1)
        page = page.replace("</svg></h1>", '</svg><span class="ver">' + APP_VERSION + "</span>"
                            + ('<span class="badge yel" style="font-size:10px;padding:1px 7px;min-height:0">DEMO</span>' if DEMO["on"] else "") + "</h1>", 1)
    page = re.sub(r"(<h1[^>]*>)MoveEye</h1>", r'\1MoveEye <span class="ver">' + APP_VERSION + "</span>"
                  + ('<span class="badge yel" style="font-size:10px;padding:1px 7px;min-height:0">DEMO</span>' if DEMO["on"] else "") + "</h1>", page, count=1)
    return (page.replace("/*BASECSS*/", BASE_CSS).replace("/*COMMON*/", COMMON_JS).replace("<!--NAV-->", nav_html(active))
            .replace("/*ALERTS*/", HEADER_JS.replace("__APPVER__", APP_VERSION).replace("__BELLY__", _BELLY) + guide_js(active) + ALERT_JS).replace("/*BTJS*/", BT_JS))


