def web_specs():
    """key -> spec for every setting that may be changed remotely (reuses the GUI definitions)."""
    specs = {}
    for sec, key, label in TOGGLES:
        if key != "web_stream":                  # the stream must not be switched off from the stream itself
            specs[key] = {"type": "bool"}
    for sec, key, label, lo, hi, step in SLIDERS:
        specs[key] = {"type": "num", "min": lo, "max": hi, "step": step}
    return specs


SECTIONS_ON_SIM_PAGE = ("Simulator",)       # 2.98.14 (Konzept): these settings are on the page Simulator, not under Einstellungen


def web_schema(lang=None, only=None):
    """the settings sections for the page; only = one section with its values (the page Simulator), «Simple» does not apply"""
    out = []
    for sec in SECTIONS:
        if only is not None:
            if sec != only:
                continue
            hid = lambda k, s_=None: False
        else:
            if sec in SECTIONS_ON_SIM_PAGE:
                continue
            hid = simple_hidden
        if hid(None, sec):
            continue
        toggles = [{"key": k, "label": tr(l, lang), "value": bool(CFG.get(k))} for s, k, l in TOGGLES if s == sec and k != "web_stream" and not hid(k)]
        sliders = [{"key": k, "label": tr(l, lang), "min": lo, "max": hi, "step": st, "value": CFG.get(k)} for s, k, l, lo, hi, st in SLIDERS if s == sec and not hid(k)]
        texts = [x for x in web_texts(lang) if x["section"] == sec and not hid(x["key"])]
        if toggles or sliders or texts:
            out.append({"id": sec, "name": tr(sec, lang), "toggles": toggles, "sliders": sliders, "texts": texts})
    return out


def set_cfg(key, value):
    """Validated setter for the web API. Returns (ok, error_message)."""
    spec = web_specs().get(key)
    if spec is None:
        return False, "unknown setting"
    if spec["type"] == "bool":
        CFG[key] = bool(value)
        sched_user_changed(key)
        save_settings()
        if key == "patrol":
            log_event("patrol", "Patrol switched ON (web)" if CFG[key] else "Patrol switched OFF (web)")
        _set_cfg_sim(key)
        return True, ""
    try:
        v = float(value)
    except (TypeError, ValueError):
        return False, "not a number"
    if not math.isfinite(v):
        return False, "not a number"
    v = max(spec["min"], min(spec["max"], v))
    v = round(round(v / spec["step"]) * spec["step"], 2)
    CFG[key] = int(round(v)) if isinstance(CFG[key], int) else float(v)
    save_settings()
    _set_cfg_sim(key)
    return True, ""


def _set_cfg_sim(key):
    """«Automatic updates» changed here: the connected simulator gets the same setting (545)"""
    if key == "sim_autoupd" and CFG.get("sim_on") and sim_ready():
        threading.Thread(target=simupd_push, args=(bool(CFG["sim_autoupd"]),), daemon=True, name="simupd").start()


