            if len(NETTEST["res"]) >= 60 and _nt_ip() not in NETTEST["res"]:
                return reply({"error": "full"}, 409)
            r = nettest_report(_nt_ip(), body())
            return reply({k: r[k] for k in ("grade", "why", "rtt", "jitter", "loss", "down", "up", "dbm") if k in r})

