        @app.route("/api/webpush", methods=["GET", "POST"])
        def api_webpush():
            if request.method == "GET":
                sup = webpush_supported()
                mine_ = [x for x in webpush_subs() if getattr(g, "role", "admin") == "admin" or str(x.get("user", "")).lower() == str(getattr(g, "user", "")).lower()]
