                ttk.Button(bf, text=tr("Create link (no limit)"), command=lambda: self._guest("create", 0)).pack(side="left", expand=True, fill="x")
                bf2 = ttk.Frame(sbody); bf2.pack(fill="x", pady=(4, 0))
