            sc.pack(fill="x")
            sc.bind("<ButtonPress-1>", lambda e, k=key: setattr(self, "dragging", k))
            sc.bind("<ButtonRelease-1>", lambda e: (setattr(self, "dragging", None), self.root.focus_set()))
