# 2.98.29 (Wunsch Daniel «Fenster nachziehen»): the window gets the same «Ansicht» as the live page of the web (536):
#   presets Nur schauen / Bedienen / Einrichten, layout automatic / portrait / landscape, picture size, «Grösse» (UI scale,
#   Tk scaling: all fonts + joystick + tiles), favourites (max. 8) + «… mehr», order and hidden quick switches, cards
#   (Bedienung, Einrichten), joystick only with a pan / tilt head (option always / never). Stored in the settings of the
#   window (CFG tk_live_view = this device). «Für alle Geräte übernehmen» = the same default on MoveEye as the web
#   (CFG qs_layout, 290). The window had its own «✎ Anpassen» before - it is gone (one way to arrange).
# ----------------------------------------------------------------------------
TKV_DEF = {"layout": "auto", "size": 60, "ui": "auto", "joy": "auto", "favs": None, "qorder": None, "qhide": None,
           "more": False, "preset": "", "hide": None}
TKV_FAV = ["rec", "photo", "track", "patrol", "white", "ir", "therm", "sim"]       # like the web (listening is only in the browser)
CFG.setdefault("tk_live_view", dict(TKV_DEF))


def tkv():
    """the «Ansicht» of the window, checked (old or broken values = the standard)"""
    d = CFG.get("tk_live_view") if isinstance(CFG.get("tk_live_view"), dict) else {}
    v = dict(TKV_DEF)
    ids = lambda x: [str(i) for i in x if isinstance(i, str) and re.fullmatch(r"[a-z0-9_]{1,20}", i)][:60] if isinstance(x, list) else None
    v["layout"] = d.get("layout") if d.get("layout") in ("auto", "port", "land") else "auto"
    try:
        v["size"] = max(0, min(100, int(d.get("size", 60))))
    except (TypeError, ValueError):
        pass
    try:
        v["ui"] = "auto" if d.get("ui", "auto") == "auto" else max(60, min(160, int(d.get("ui"))))
    except (TypeError, ValueError):
        v["ui"] = "auto"
    v["joy"] = d.get("joy") if d.get("joy") in ("auto", "on", "off") else "auto"
    for k in ("favs", "qorder", "qhide", "hide"):
        v[k] = ids(d.get(k))
    v["more"] = bool(d.get("more")); v["preset"] = d.get("preset") if d.get("preset") in ("look", "operate", "setup") else ""
    return v


def tkv_set(**kw):
    v = tkv(); v.update(kw); CFG["tk_live_view"] = v; save_settings()
    return v


def _tkv_shared():
    return qs_layout_clean(CFG.get("qs_layout"))


def tkv_qs_state(items):
    """(order of the ids, hidden ids, favourites) - own of the window, else the default for all devices, else the standard"""
    v, sh = tkv(), _tkv_shared()
    ids = [q["id"] for q in items]
    hid = v["qhide"] if v["qhide"] is not None else list(sh.get("hidden") or [])
    favs = v["favs"] if v["favs"] is not None else (list(sh["favs"]) if sh.get("favs") else list(TKV_FAV))
    favs = [f for f in favs if f not in hid and f in ids][:8]
    order = v["qorder"] if v["qorder"] is not None else (list(sh.get("order") or []) or list(favs))
    pos = {k: i for i, k in enumerate(order)}
    ids = [x for _i, x in sorted(enumerate(ids), key=lambda p: pos.get(p[1], len(order) + p[0]))]
    return ids, hid, favs


def tkv_hidden_cards():
    v = tkv()
    if v["hide"] is not None:
        return v["hide"]
    ch = _tkv_shared().get("chide")
    return [k for k in ch if k in ("controls", "lvsetup")] if isinstance(ch, list) else ["lvsetup"]


def _tkv_qs_list(self):
    """the quick switches of the window + «Kalibrieren» when there is no pan / tilt head (it needs none; with a head it is
    in the controls beside the joystick)"""
    q = App._tkv_qs_list_orig(self)
    if not self._tk_head():
        q.append(dict(id="recal", ic="↻", lb=tr("Calibrate"), tip=tr("Learn the picture again (after moving the camera)"),
                      on=lambda: False, go=self._recal, flash=True))
    return q


def _tkv_tiles(self, head):
    """the tiles in the controls: favourites (in the order of the list), «… mehr» opens the others"""
    items = {q["id"]: q for q in self._qs_list() if head or q["id"] not in ("track", "patrol")}
    ids, hid, favs = tkv_qs_state(list(items.values()))
    more = tkv()["more"]
    out = [items[i] for i in ids if i in items and i not in hid and (more or i in favs)]
    rest = [i for i in ids if i in items and i not in hid and i not in favs]
    if rest or more:
        out.append(dict(id="more", ic="…", lb=tr("less" if more else "more"), tip=tr("Show only the favourites" if more else "Show all quick switches"),
                        on=lambda: False, go=self._tkv_more))
    return out


def _tkv_more(self):
    tkv_set(more=not tkv()["more"]); self._tkv_redraw()


def _tk_head(self):
    j = tkv()["joy"]
    return True if j == "on" else False if j == "off" else live_has_head()


def _tk_ui(self):
    u = tkv()["ui"]
    if u != "auto":
        return u / 100.0
    try:
        w, h = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
    except Exception:
        return 1.0
    return 1.15 if w >= 2400 and h >= 1300 else 1.0      # a big screen (4K, 1440p) a bit bigger


def _tkv_card(self, key):
    if key == "controls" and "controls" in (CFG.get("ui_hidden") or []):
        # aufr: «Panels → Camera control» of the old right-click menu is gone (one place: ◫ Ansicht, card «Controls») - a
        # camera control hidden there before is taken over once as hidden in the Ansicht of the window
        CFG["ui_hidden"] = [x for x in CFG["ui_hidden"] if x != "controls"]
        tkv_set(hide=[x for x in tkv_hidden_cards() if x != "controls"] + ["controls"])
    return key not in tkv_hidden_cards()


def _tkv_pic_weight(self):
    """portrait: how much of the spare height the picture gets (Bildgrösse 0 … 100 → 30 … 100 %)"""
    return int(30 + tkv()["size"] * 0.7)


def _tkv_side_w(self):
    """landscape: width of the controls column (Bildgrösse: larger picture = narrower column; «Grösse» makes it wider)"""
    W = self._win_w() - 40
    share = 0.5 + tkv()["size"] / 100 * 0.35
    return int(max(300, min(W * 0.6, (1 - share) * W * self._tk_ui())))


def _tkv_live_land(self, w=None, h=None):
    lay = tkv()["layout"]
    if lay == "port":
        return False
    if lay == "land":
        try:
            ww = w or self.root.winfo_width()
            ww = ww if ww > 50 else self.root.winfo_screenwidth()
        except Exception:
            return True
        return ww >= 700
    return App._tkv_land_orig(self, w, h)


def _tkv_setup_card(self, parent):
    """«Einrichten» (preset «Einrichten»): only links, no second copy of a control - like the web card"""
    c = tk.Frame(parent, bg=C["panel"], highlightthickness=1, highlightbackground=C["line"], padx=12, pady=8)
    tk.Label(c, text="🛠 " + tr("Set up"), bg=C["panel"], fg=C["txt"], font=("DejaVu Sans", 10, "bold"), anchor="w").pack(fill="x")
    tk.Label(c, text=tr("Draw where MoveEye should watch, then check the range with the walk test."), bg=C["panel"], fg=C["mut"],
             font=("DejaVu Sans", 8), wraplength=340, justify="left", anchor="w").pack(fill="x", pady=(2, 6))
    r = tk.Frame(c, bg=C["panel"]); r.pack(fill="x")
    self._fbtn(r, "✏️ " + tr("Draw the zones"), lambda: self._open_page("/zones")).pack(side="left", fill="x", expand=True)
    self._fbtn(r, "🚶 " + tr("Walk test"), self._walktest).pack(side="left", fill="x", expand=True, padx=(6, 0))
    return c


def _tkv_redraw(self, full=False):
    if full:
        self._schedule_rebuild(); return
    if self.tab == "live" and self.left_f is not None and self.left_f.winfo_exists():
        tid, self.tab = self.tab, None
        self._tab(tid)


def _tkv_build(self):
    """«Grösse»: tk scaling = all fonts (in points) bigger or smaller; the joystick and the tiles follow (570)"""
    try:
        if not hasattr(self, "_tk_base_scaling"):
            self._tk_base_scaling = float(self.root.tk.call("tk", "scaling"))
        self.root.tk.call("tk", "scaling", self._tk_base_scaling * self._tk_ui())
    except Exception:
        pass
    return App._tkv_build_orig(self)


TKV_PRESETS = {"look": ("👁", "Just watching", "big picture"), "operate": ("🕹", "Operating", "everything"), "setup": ("🛠", "Setting up", "walk test, zones")}


def _tkv_preset(self, k):
    if k == "look":
        v = dict(size=100, more=False, hide=["lvsetup"]); fold = True
    elif k == "operate":
        v = dict(size=60, hide=["lvsetup"]); fold = False
    else:
        v = dict(size=40, hide=[]); fold = False
    v["preset"] = k; tkv_set(**v)
    self.open_secs.discard("ctl:folded"); self.open_secs.discard("ctl:open"); self.open_secs.add("ctl:folded" if fold else "ctl:open")
    if "controls" in CFG["ui_hidden"]:
        CFG["ui_hidden"] = [x for x in CFG["ui_hidden"] if x != "controls"]
    CFG["ui_open"] = sorted(self.open_secs); save_settings()
    self._status_line(("✓ " + TKV_PRESETS[k][0] + " " + tr(TKV_PRESETS[k][1])))
    self._tkv_redraw()


def _tkv_status_line(self, txt):
    try:
        if getattr(self, "_tkv_msg", None) is not None and self._tkv_msg.winfo_exists():
            self._tkv_msg.config(text=txt)
    except Exception:
        pass


def _tkv_share(self):
    if not messagebox.askyesno("MoveEye", tr("Use this arrangement (favourites, order, hidden switches and cards) for all devices that have no own arrangement?")):
        return
    items = self._qs_list()
    ids, hid, favs = tkv_qs_state(items)
    sh = _tkv_shared()
    order = ids + [x for x in (sh.get("order") or []) if x not in ids]          # switches only the web has (listen, talk …) keep their place
    hidden = hid + [x for x in (sh.get("hidden") or []) if x not in ids and x not in hid]
    chide = [x for x in (sh.get("chide") or ["lvsetup"]) if x not in ("controls", "lvsetup")] + tkv_hidden_cards()
    qs_layout_set(order, hidden, favs, sh.get("cards"), chide)
    tkv_set(favs=None, qorder=None, qhide=None, hide=None)              # the window follows the default from now on
    self._status_line("✓ " + tr("Saved on MoveEye for all devices")); self._tkv_redraw()


def _tkv_reset(self):
    if not messagebox.askyesno("MoveEye", tr("Back to the standard view of the live page?")):
        return
    ui = tkv()["ui"]; CFG["tk_live_view"] = dict(TKV_DEF, ui=ui); save_settings()
    self._tkv_redraw()


def _tkv_dialog(self):
    """the «Ansicht» window: everything at once, each change is shown right away"""
    old = getattr(self, "_tkv_top", None)
    try:
        if old is not None and old.winfo_exists():
            old.lift(); return
    except Exception:
        pass
    top = tk.Toplevel(self.root); self._tkv_top = top
    top.title(tr("View of the live page")); top.configure(bg=C["panel"]); top.transient(self.root)
    P = dict(bg=C["panel"])
    cv = tk.Canvas(top, bg=C["panel"], highlightthickness=0, bd=0, width=440, height=min(760, max(420, self.root.winfo_screenheight() - 140)))
    sb = ttk.Scrollbar(top, orient="vertical", command=cv.yview); cv.configure(yscrollcommand=sb.set)
    sb.pack(side="right", fill="y"); cv.pack(side="left", fill="both", expand=True)
    body = tk.Frame(cv, **P); cv.create_window((0, 0), window=body, anchor="nw")
    body.bind("<Configure>", lambda e: cv.configure(scrollregion=cv.bbox("all")))

    def h(txt):
        tk.Label(body, text=txt.upper(), bg=C["panel"], fg=C["mut"], font=("DejaVu Sans", 8, "bold"), anchor="w").pack(fill="x", padx=12, pady=(10, 3))

    def note(txt):
        tk.Label(body, text=txt, bg=C["panel"], fg=C["mut"], font=("DejaVu Sans", 8), anchor="w", justify="left", wraplength=410).pack(fill="x", padx=12)

    def seg(opts, cur, fn):
        f = tk.Frame(body, **P); f.pack(fill="x", padx=12)
        for i, (val, lb) in enumerate(opts):
            on = cur == val
            b = self._fbtn(f, tr(lb), lambda val=val: (fn(val), redraw()), primary=on)
            b.grid(row=0, column=i, sticky="ew", padx=(0, 6)); f.columnconfigure(i, weight=1)
        return f

    def redraw(full=False):
        try:
            top.destroy()
        except Exception:
            pass
        self._tkv_redraw(full)
        self.root.after(300 if full else 60, self._tkv_dialog)

    v = tkv()
    h(tr("Ready-made views"))
    pf = tk.Frame(body, **P); pf.pack(fill="x", padx=12)
    for i, (k, (ic, lb, d)) in enumerate(TKV_PRESETS.items()):
        b = self._fbtn(pf, f"{ic} {tr(lb)}\n{tr(d)}", lambda k=k: (self._tkv_preset(k), redraw()), primary=v["preset"] == k)
        b.grid(row=0, column=i, sticky="ew", padx=(0, 6)); pf.columnconfigure(i, weight=1)
    h(tr("Layout"))
    seg([("auto", "Automatic"), ("port", "Portrait"), ("land", "Landscape")], v["layout"], lambda x: tkv_set(layout=x, preset=""))
    note(tr("Now") + ": " + tr("picture left, cards right" if self._tk_live_land() else "picture on top, cards below"))
    h(tr("Picture size"))
    sz = tk.Scale(body, from_=0, to=100, resolution=5, orient="horizontal", showvalue=False, bg=C["panel"], fg=C["txt"], troughcolor=C["line"],
                  highlightthickness=0, bd=0)
    sz.set(v["size"]); sz.pack(fill="x", padx=12)
    sz.bind("<ButtonRelease-1>", lambda e: (tkv_set(size=int(sz.get()), preset=""), self._tkv_redraw()))
    note(tr("Landscape: how wide the picture is next to the cards (it never gets higher than the window)." if self._tk_live_land() else "Portrait: how high the picture may be."))
    h(tr("Size of text and buttons"))
    uis = [("auto", "Automatic")] + [(n, f"{n} %") for n in (60, 70, 80, 90, 100, 110, 120, 130, 140, 150, 160)]
    cb = ttk.Combobox(body, values=[tr(lb) if val == "auto" else lb for val, lb in uis], state="readonly", width=14)
    cb.current(next((i for i, (val, _l) in enumerate(uis) if val == v["ui"]), 0)); cb.pack(anchor="w", padx=12)
    cb.bind("<<ComboboxSelected>>", lambda e: (tkv_set(ui=uis[cb.current()][0]), redraw(True)))
    note(tr("Like a resolution: everything except the picture gets smaller or bigger (only on this device)."))
    h(tr("Joystick"))
    seg([("auto", "Automatic"), ("on", "Always"), ("off", "Never")], v["joy"], lambda x: tkv_set(joy=x))
    if v["joy"] == "auto":
        note(tr("Automatic") + ": " + tr("pan / tilt head found" if live_has_head() else "no pan / tilt head found"))
    h(tr("Quick switches") + " · " + tr("Favourite buttons (4–8)"))
    items = [q for q in self._qs_list()]
    names = {q["id"]: f"{q['ic']}  {q['lb']}" for q in items}
    ids, hid, favs = tkv_qs_state(items)
    qf = tk.Frame(body, **P); qf.pack(fill="x", padx=12)

    def fav(i):
        F = list(favs)
        if i in F:
            F.remove(i)
        elif len(F) >= 8:
            messagebox.showinfo("MoveEye", "★ " + tr("At most 8 favourites")); return
        else:
            F.append(i)
        tkv_set(favs=F, qhide=[x for x in hid if x != i], preset=""); redraw()

    def hide(i):
        H = [x for x in hid if x != i] + ([] if i in hid else [i])
        tkv_set(qhide=H, favs=[x for x in favs if x not in H], preset=""); redraw()

    def mv(i, d):
        L = list(ids); a = L.index(i); b = a + d
        if 0 <= b < len(L):
            L[a], L[b] = L[b], L[a]; tkv_set(qorder=L, preset=""); redraw()
    for n, i in enumerate(ids):
        row = tk.Frame(qf, **P); row.pack(fill="x", pady=1)
        self._fbtn(row, "★" if i in favs else "☆", lambda i=i: fav(i), tr("Favourite (shown without «… more»)"),
                   font=("DejaVu Sans", 11)).pack(side="left")
        tk.Label(row, text=names[i], bg=C["panel"], fg=C["mut"] if i in hid else C["txt"], font=("DejaVu Sans", 9, "overstrike" if i in hid else "normal"),
                 anchor="w").pack(side="left", fill="x", expand=True, padx=6)
        self._fbtn(row, "✕" if i not in hid else "👁", lambda i=i: hide(i), tr("Hide / show")).pack(side="right")
        self._fbtn(row, "▼", lambda i=i: mv(i, 1), tr("Down")).pack(side="right", padx=(0, 4))
        self._fbtn(row, "▲", lambda i=i: mv(i, -1), tr("Up")).pack(side="right", padx=(0, 4))
    note(tr("★ = always visible, the others behind «… more». ✕ hides a switch on this device."))
    h(tr("Cards"))
    ch = tkv_hidden_cards()
    for key, lb in (("controls", "Controls"), ("lvsetup", "Set up")):
        bv = tk.BooleanVar(value=key not in ch and (key != "controls" or self.is_shown("controls")))

        def tog(key=key, bv=bv):
            H = [x for x in tkv_hidden_cards() if x != key] + ([] if bv.get() else [key])
            if key == "controls" and bv.get() and "controls" in CFG["ui_hidden"]:
                CFG["ui_hidden"] = [x for x in CFG["ui_hidden"] if x != "controls"]
            tkv_set(hide=H, preset=""); redraw()
        tk.Checkbutton(body, text=tr(lb), variable=bv, command=tog, bg=C["panel"], fg=C["txt"], selectcolor=C["field"], activebackground=C["panel"],
                       anchor="w").pack(fill="x", padx=12)
    bf = tk.Frame(body, **P); bf.pack(fill="x", padx=12, pady=(14, 4))
    self._fbtn(bf, "📲 " + tr("Use for all devices"), lambda: (self._tkv_share(), redraw()), tr("Store this arrangement on MoveEye as the default for devices without an own arrangement")).pack(side="left", fill="x", expand=True)
    self._fbtn(bf, tr("Reset"), lambda: (self._tkv_reset(), redraw())).pack(side="left", padx=(6, 0))
    self._fbtn(bf, tr("Close"), top.destroy, primary=True).pack(side="left", padx=(6, 0))
    own = any(v[k] is not None for k in ("favs", "qorder", "qhide", "hide"))
    sh = _tkv_shared(); shon = bool(sh.get("order") or sh.get("hidden") or sh.get("favs"))
    note(tr("This window has its own arrangement. «Reset» = back to the arrangement for all devices." if own else
            "This window uses the arrangement for all devices (stored on MoveEye). A change makes it its own." if shon else
            "Stored in the settings of this window."))
    self._tkv_msg = tk.Label(body, text="", bg=C["panel"], fg=C["grn"], font=("DejaVu Sans", 9), anchor="w"); self._tkv_msg.pack(fill="x", padx=12, pady=(4, 10))


App._tkv_qs_list_orig = App._qs_list
# wraps: App._qs_list
App._qs_list = _tkv_qs_list
App._tkv_land_orig = App._tk_live_land
# wraps: App._tk_live_land
App._tk_live_land = _tkv_live_land
App._tkv_build_orig = App._build
# wraps: App._build
App._build = _tkv_build
for _n, _f in (("_tkv_tiles", _tkv_tiles), ("_tkv_more", _tkv_more), ("_tk_head", _tk_head), ("_tk_ui", _tk_ui), ("_tkv_card", _tkv_card),
               ("_tkv_pic_weight", _tkv_pic_weight), ("_tkv_side_w", _tkv_side_w), ("_tkv_setup_card", _tkv_setup_card),
               ("_tkv_redraw", _tkv_redraw), ("_tkv_preset", _tkv_preset), ("_status_line", _tkv_status_line), ("_tkv_share", _tkv_share),
               ("_tkv_reset", _tkv_reset), ("_tkv_dialog", _tkv_dialog)):
    setattr(App, _n, _f)
# ----------------------------------------------------------------------------
# 2.98.30: the same three steps as the web page: look around (start, progress, cancel), mark on the panorama (tap a
# suggestion or draw a box with the mouse, kind buttons), apply + walk test. Button in Schutz → «Camping / protection».
# ----------------------------------------------------------------------------
PLACE_TK_KINDS = (("tent", "⛺", "My tent / camper", "#ff5a5a"), ("access", "🚶", "Access / path", "#ffb020"),
                  ("valuable", "🚲", "Valuables", "#3cc8ff"), ("ignore", "🌿", "Ignore", "#8fd18f"))
PLACE_TK_COL = {k: c for k, _i, _n, c in PLACE_TK_KINDS}
PLACE_TK_COL["public_path"] = "#c9a0ff"
PLACE_TK_ICON = {k: i for k, i, _n, _c in PLACE_TK_KINDS}
PLACE_TK_ICON["public_path"] = "🛣"


def _app_place(self):
    win = getattr(self, "_pl_win", None)
    try:
        if win is not None and win.winfo_exists():
            win.lift(); return
    except Exception:
        pass
    win = tk.Toplevel(self.root); self._pl_win = win
    win.title("MoveEye – " + tr("Set up the place")); win.geometry("820x860")
    S = {"items": [], "taken": set(), "tool": tk.StringVar(win, ""), "sel": -1, "scale": 1.0, "geo": None, "img": None, "drag": None,
         "scan_v": None, "busy": False}
    top = ttk.Frame(win); top.pack(fill="x", padx=12, pady=(10, 4))
    intro = ttk.Label(top, text="", wraplength=780, justify="left"); intro.pack(anchor="w")
    of = ttk.Frame(top); of.pack(fill="x", pady=(4, 0))
    v_wide, v_rows, v_ir, v_th = tk.BooleanVar(win, True), tk.BooleanVar(win, False), tk.BooleanVar(win, True), tk.BooleanVar(win, True)
    cb_wide = ttk.Checkbutton(of, variable=v_wide, text="")
    ttk.Checkbutton(of, variable=v_rows, text=tr("Thorough: 3 rows instead of 2 (takes longer)")).pack(anchor="w")
    hfr = ttk.Frame(of); hfr.pack(anchor="w", pady=(4, 0))          # real-reh-fusspunkt: «Höhe der Kamera (m)» (232 cam_height)
    v_camh = tk.StringVar(win, "%.2f" % cam_height_cfg())

    def camh_set(*_a):
        try:
            v_ = round(float(v_camh.get().replace(",", ".")), 2)
        except ValueError:
            return
        if 0.2 <= v_ <= 10.0 and v_ != CFG.get("cam_height"):
            CFG["cam_height"] = v_; save_settings()
            self._status("Camping / protection", "📏 " + tr("Camera height (m)") + f": {v_:.2f}")
    sp = ttk.Spinbox(hfr, from_=0.2, to=10.0, increment=0.05, textvariable=v_camh, width=6, command=camh_set)
    sp.pack(side="left"); sp.bind("<FocusOut>", camh_set); sp.bind("<Return>", camh_set)
    ttk.Label(hfr, text=" " + tr("Camera height (m)")).pack(side="left")
    _ci = cam_height_info()
    ttk.Label(of, style="Mut.TLabel", wraplength=760, justify="left",
              text=tr("Height of the lens above the ground - helps to tell animals from persons at night.")
              + ((" " + trf("Simulator: camera height {m} m - counts while connected", m="%.2f" % _ci["sim"])) if _ci["sim"] else "")).pack(anchor="w")
    cb_ir = ttk.Checkbutton(of, variable=v_ir, text=tr("with the infrared light"))
    cb_th = ttk.Checkbutton(of, variable=v_th, text=tr("with the thermal camera too"))
    bf = ttk.Frame(top); bf.pack(fill="x", pady=(6, 0))
    prog = ttk.Progressbar(top, maximum=100); prog.pack(fill="x", pady=(6, 0))
    st = ttk.Label(top, text="", font=("TkDefaultFont", 11, "bold")); st.pack(anchor="w", pady=(4, 0))

    def start():
        ok, err = place_start(v_ir.get(), v_th.get(), v_wide.get() and bool(cam_wide_spec()), 3 if v_rows.get() else 2, "window")
        self._status("Camping / protection", ("📍 " + tr("Set up the place")) if ok else "⚠ " + tr(err))
        if not ok:
            st.config(text="⚠ " + tr(err))
    ttk.Button(bf, text="▶ " + tr("Start looking around"), command=start).pack(side="left", expand=True, fill="x", padx=(0, 4))
    ttk.Button(bf, text="✕ " + tr("Cancel"), command=place_stop).pack(side="left", expand=True, fill="x")
    # ---- the panorama ----
    tf = ttk.Frame(win); tf.pack(fill="x", padx=12, pady=(8, 2))
    for k, ic, nm, _c in PLACE_TK_KINDS + (("", "✋", "Move / select", ""),):
        ttk.Radiobutton(tf, text=ic + " " + tr(nm), value=k, variable=S["tool"]).pack(side="left", padx=(0, 8))
    cf = ttk.Frame(win); cf.pack(fill="x", padx=12)
    cv = tk.Canvas(cf, height=270, background="#111", highlightthickness=0)
    sx = ttk.Scrollbar(cf, orient="horizontal", command=cv.xview); cv.configure(xscrollcommand=sx.set)
    cv.pack(fill="x"); sx.pack(fill="x")
    lf = ttk.Frame(win); lf.pack(fill="both", expand=True, padx=12, pady=(6, 0))
    lb = tk.Listbox(lf, height=7); lb.pack(side="left", fill="both", expand=True)
    ef = ttk.Frame(lf); ef.pack(side="left", fill="y", padx=(8, 0))
    v_name = tk.StringVar(win, ""); v_pub = tk.BooleanVar(win, False)
    ttk.Label(ef, text=tr("Name")).pack(anchor="w")
    en = ttk.Entry(ef, textvariable=v_name, width=24); en.pack(anchor="w")
    cb_pub = ttk.Checkbutton(ef, variable=v_pub, text=tr("public path = only report"))
    cb_pub.pack(anchor="w", pady=(4, 0))
    note = ttk.Label(ef, text="", style="Mut.TLabel", wraplength=230, justify="left"); note.pack(anchor="w", pady=(4, 0))
    v_pat = tk.BooleanVar(win, bool(CFG.get("place_patrol")))
    af = ttk.Frame(win); af.pack(fill="x", padx=12, pady=(6, 10))
    res = ttk.Label(win, text="", wraplength=780, justify="left"); res.pack(anchor="w", padx=12, pady=(0, 8))
    notes = {"tent": "protection zone, lights / siren aim here, a person close by counts more", "access": "line: a person crossing it is reported + patrol point",
             "public_path": "persons there: only a note, no alarm", "valuable": "guarded: in the morning «Bike missing»", "ignore": "mask: movement there is ignored"}

    def px(a, e):
        g = S["geo"]; x = (a - g["a0"]) * g["k"]
        if g.get("wrap") and x < 0:
            x += 360 * g["k"]
        return x * S["scale"], ((g["e_top"] - e) * g["k"] + g.get("head", 0)) * S["scale"]

    def ang(x, y):
        g = S["geo"]; x, y = cv.canvasx(x) / S["scale"], cv.canvasy(y) / S["scale"]
        return g["a0"] + x / g["k"], g["e_top"] - (y - g.get("head", 0)) / g["k"]

    def redraw():
        cv.delete("box")
        scan = place_scan() or {}
        if not S["geo"]:
            return
        for s_ in scan.get("suggest") or []:
            if s_["id"] in S["taken"]:
                continue
            x0, y0 = px(s_["a0"], s_["e1"]); x1, y1 = px(s_["a1"], s_["e0"])
            cv.create_rectangle(x0, y0, x1, y1, outline=PLACE_TK_COL.get(s_["kind"], "#fff"), dash=(6, 4), width=2, tags="box")
            cv.create_text(x0 + 4, y0 + 4, anchor="nw", text="+ " + tr(s_["name"]), fill="#fff", tags="box")
        for i, it in enumerate(S["items"]):
            x0, y0 = px(it["a0"], it["e1"]); x1, y1 = px(it["a1"], it["e0"])
            cv.create_rectangle(x0, y0, x1, y1, outline=PLACE_TK_COL.get(it["kind"], "#fff"), width=4 if i == S["sel"] else 2, tags="box")
            cv.create_text(x0 + 4, y0 + 4, anchor="nw", text=PLACE_TK_ICON.get(it["kind"], "") + " " + it["name"], fill="#fff", tags="box")
        if S["drag"] and S["drag"].get("b"):
            b = S["drag"]["b"]; x0, y0 = px(b["a0"], b["e1"]); x1, y1 = px(b["a1"], b["e0"])
            cv.create_rectangle(x0, y0, x1, y1, outline="#fff", width=2, tags="box")
        lb.delete(0, "end")
        for it in S["items"]:
            lb.insert("end", PLACE_TK_ICON.get(it["kind"], "") + " " + it["name"])
        if 0 <= S["sel"] < len(S["items"]):
            lb.selection_clear(0, "end"); lb.selection_set(S["sel"])

    def select(i):
        S["sel"] = i
        if 0 <= i < len(S["items"]):
            it = S["items"][i]
            v_name.set(it["name"]); v_pub.set(it["kind"] == "public_path")
            note.config(text=tr(notes.get(it["kind"], "")))
        redraw()

    def take(s_, kind=None):
        if s_["id"] in S["taken"]:
            return
        S["taken"].add(s_["id"])
        S["items"].append({"kind": kind or s_["kind"], "name": tr(s_["name"]), "a0": s_["a0"], "a1": s_["a1"], "e0": s_["e0"], "e1": s_["e1"]})

    def hit(lst, a, e):
        for i in range(len(lst) - 1, -1, -1):
            if _place_in(lst[i], a, e):
                return i
        return -1

    def down(ev):
        if S["geo"]:
            S["drag"] = {"x": ev.x, "y": ev.y, "b": None}
            if not S["tool"].get():
                cv.scan_mark(ev.x, 0)

    def move(ev):
        D = S["drag"]
        if not D:
            return
        if not S["tool"].get():
            cv.scan_dragto(ev.x, 0, gain=1); return
        a0, e1 = ang(min(D["x"], ev.x), min(D["y"], ev.y)); a1, e0 = ang(max(D["x"], ev.x), max(D["y"], ev.y))
        D["b"] = {"a0": a0, "a1": a1, "e0": e0, "e1": e1}; redraw()

    def up(ev):
        D, S["drag"] = S["drag"], None
        if not D:
            return
        tool = S["tool"].get()
        if tool and D.get("b") and abs(ev.x - D["x"]) + abs(ev.y - D["y"]) > 12:
            S["items"].append(dict(D["b"], kind=tool, name=tr(dict((k, n) for k, _i, n, _c in PLACE_TK_KINDS)[tool])))
            select(len(S["items"]) - 1); return
        if abs(ev.x - D["x"]) + abs(ev.y - D["y"]) > 12:
            redraw(); return
        a, e = ang(ev.x, ev.y)
        i = hit(S["items"], a, e)
        if i >= 0:
            if tool:
                S["items"][i]["kind"] = tool
            select(i); return
        sg = [s_ for s_ in (place_scan() or {}).get("suggest") or [] if s_["id"] not in S["taken"]]
        j = hit(sg, a, e)
        if j >= 0:
            take(sg[j], tool or None); select(len(S["items"]) - 1)
    cv.bind("<ButtonPress-1>", down); cv.bind("<B1-Motion>", move); cv.bind("<ButtonRelease-1>", up)
    lb.bind("<<ListboxSelect>>", lambda _e: select(lb.curselection()[0]) if lb.curselection() else None)

    def name_changed(*_a):
        if 0 <= S["sel"] < len(S["items"]):
            S["items"][S["sel"]]["name"] = v_name.get()[:40]; redraw()
    v_name.trace_add("write", name_changed)

    def pub_changed(*_a):
        if 0 <= S["sel"] < len(S["items"]) and S["items"][S["sel"]]["kind"] in ("access", "public_path"):
            S["items"][S["sel"]]["kind"] = "public_path" if v_pub.get() else "access"; select(S["sel"])
    v_pub.trace_add("write", pub_changed)

    def remove():
        if 0 <= S["sel"] < len(S["items"]):
            S["items"].pop(S["sel"]); S["sel"] = -1; redraw()

    def take_all():
        for s_ in (place_scan() or {}).get("suggest") or []:
            take(s_)
        redraw()

    def apply_():
        ok, err, r = place_apply(S["items"], True, v_pat.get(), "window")
        if not ok:
            res.config(text="⚠ " + tr(err)); return
        res.config(text="✓ " + tr("The place is set up") + " · " + " · ".join(x for x in (
            trf("{n} protection zone(s) at the tent", n=r["tent"]) if r["tent"] else "", trf("{n} line(s) at the accesses", n=r["lines"]) if r["lines"] else "",
            trf("{n} public path(s): only reported", n=r["public"]) if r["public"] else "", trf("{n} mask(s): ignored", n=r["masks"]) if r["masks"] else "",
            trf("{n} patrol point(s)", n=r["waypoints"]) if r["waypoints"] else "",
            trf("{n} guarded thing(s) - reported in the morning when missing", n=r["watched"]) if r["watched"] else "") if x)
            + "\n" + tr("Now test it: walk past like a visitor would. MoveEye beeps at every detection."))

    def forget():
        if messagebox.askyesno("MoveEye", tr("Forget the place? Its zones, waypoints and guarded things are removed."), parent=win):
            place_clear("window"); S["items"] = []; S["taken"] = set(); redraw()
    ttk.Button(ef, text="✕ " + tr("Remove"), command=remove).pack(anchor="w", pady=(6, 0))
    ttk.Button(ef, text="✚ " + tr("Take all suggestions"), command=take_all).pack(anchor="w", pady=(4, 0))
    ttk.Checkbutton(af, variable=v_pat, text="🔁 " + tr("Patrol: the head looks at the accesses now and then")).pack(anchor="w")
    ttk.Button(af, text="✓ " + tr("Apply"), command=apply_).pack(side="left", expand=True, fill="x", padx=(0, 4), pady=(4, 0))
    ttk.Button(af, text="🚶 " + tr("Start the walk test"), command=self._walktest).pack(side="left", expand=True, fill="x", padx=(0, 4), pady=(4, 0))
    ttk.Button(af, text="🗑 " + tr("Forget the place"), command=forget).pack(side="left", expand=True, fill="x", pady=(4, 0))

    def load_pano(scan):
        S["geo"] = scan.get("geo"); S["scan_v"] = scan.get("t")
        rec = _place_load() or {}
        S["items"] = [{k: it[k] for k in ("kind", "name", "a0", "a1", "e0", "e1")} for it in rec.get("items") or [] if "a0" in it] \
            if (rec.get("t") or 0) >= (scan.get("t") or 0) - 1 else []
        S["taken"] = set(); S["sel"] = -1
        try:
            im = cv2.imread(place_dir("scan", "pano.jpg"))
            if im is None:
                return
            S["scale"] = 260.0 / im.shape[0]
            im = cv2.resize(im, (int(im.shape[1] * S["scale"]), 260))
            ok, buf = cv2.imencode(".png", im)
            if ok:
                S["img"] = tk.PhotoImage(data=base64.b64encode(buf.tobytes()).decode())
                cv.delete("all"); cv.create_image(0, 0, anchor="nw", image=S["img"]); cv.configure(scrollregion=(0, 0, im.shape[1], 260))
        except Exception:
            pass
        redraw()

    def tick():
        try:
            if not win.winfo_exists():
                return
        except Exception:
            return
        P_ = place_state()
        pl = P_["plan"]
        cov = tr("the whole circle (360°)") if pl["wrap"] else tr("about") + f" {pl['cover']}°"
        intro.config(text=tr("Put MoveEye where it will guard. The head looks around once: it takes a photo in every direction and watches for about 10 seconds what moves and what the AI recognises. Then you only mark your tent, the access, your valuables and what to ignore.")
                     + "\n" + tr("Pan range of the servo {servo}°, with the lens it sees {cover} (camera {hf}°).").replace("{servo}", str(pl["servo"])).replace("{cover}", cov).replace("{hf}", str(round(pl["hf"])))
                     + ("" if pl["wrap"] else " " + tr("No full turn: the head turns only as far as its servo goes."))
                     + "\n" + tr("{n} directions in {rows} rows - about {min} minutes.").replace("{n}", str(pl["n"])).replace("{rows}", str(pl["rows"])).replace("{min}", str(max(1, round(pl["eta"] / 60)))))
        W_ = P_.get("wide")
        if W_:
            cb_wide.config(text=tr("Use the wide-angle camera ({cam}, {deg}°): {n} directions, about {min} min").replace("{cam}", W_["label"]).replace("{deg}", str(round(W_["hf"])))
                           .replace("{n}", str(W_["n"])).replace("{min}", str(max(1, round(W_["eta"] / 60)))))
            if not cb_wide.winfo_ismapped():
                cb_wide.pack(anchor="w")
        for cb, okk in ((cb_ir, P_["dark"] and P_["ir_ok"]), (cb_th, P_["dark"] and P_["thermal_ok"])):
            if okk and not cb.winfo_ismapped():
                cb.pack(anchor="w")
            elif not okk and cb.winfo_ismapped():
                cb.pack_forget()
        if P_["busy"]:
            S["busy"] = True
            prog["value"] = 100.0 * max(0, P_["step"] - 0.5) / max(1, P_["n"])
            st.config(text="🔄 " + tr("Direction {i} of {n}").replace("{i}", str(P_["step"])).replace("{n}", str(P_["n"]))
                      + f" · {tr('about')} {P_['left'] // 60}:{P_['left'] % 60:02d} {tr('left')}")
        else:
            if S["busy"]:
                S["busy"] = False; prog["value"] = 100 if P_["done_msg"] else 0
            st.config(text=P_["msg"] or (P_["why_not"] and "⚠ " + P_["why_not"]) or "")
            scan = place_scan()
            if scan and scan.get("t") != S["scan_v"]:
                load_pano(scan)
        win.after(1000, tick)
    tick()


def _app_fov_box(self, parent):
    """Camera / Servos: the field of view of every camera (list, own value, «sits on the head»)"""
    box = ttk.Frame(parent); box.pack(fill="x", pady=(8, 0))
    ttk.Label(box, text="📐 " + tr("Field of view of the camera")).pack(anchor="w")
    F = cam_fov_list()
    names = [n for _k, n in F["choices"]]; keys = [k for k, _n in F["choices"]]
    for c in F["cams"]:
        r = ttk.Frame(box); r.pack(fill="x", pady=(4, 0))
        ttk.Label(r, text=(tr("Main camera") if c["main"] else tr("Extra camera")) + ": " + str(c["label"]), style="Mut.TLabel").pack(anchor="w")
        rr = ttk.Frame(r); rr.pack(fill="x")
        cb = ttk.Combobox(rr, values=names, state="readonly", width=34)
        cb.current(keys.index(c["model"]) if c["model"] in keys else 0); cb.pack(side="left")
        v_deg = tk.StringVar(rr, str(c["deg"] or round(c["h"])))
        ent = ttk.Entry(rr, textvariable=v_deg, width=6); ent.pack(side="left", padx=(6, 0))
        info = ttk.Label(r, text=f"{round(c['h'])}° × {round(c['v'])}°", style="Mut.TLabel"); info.pack(anchor="w")
        v_head = tk.BooleanVar(r, bool(c["head"]))

        def send(*_a, c=c, cb=cb, v_deg=v_deg, info=info, v_head=v_head):
            ok, err = cam_fov_set(c["spec"], keys[cb.current()], v_deg.get(), None if c["main"] else v_head.get())
            h, v, _s = cam_fov_hv(c["spec"])
            info.config(text=(f"{round(h)}° × {round(v)}°") if ok else "⚠ " + tr(err))
        cb.bind("<<ComboboxSelected>>", send); ent.bind("<Return>", send); ent.bind("<FocusOut>", send)
        if not c["main"]:
            ttk.Checkbutton(r, variable=v_head, text=tr("sits on the head (turns with it) - for the panorama"), command=send).pack(anchor="w")


