def _help_sicher3(doc, lang):
    if '<section id="appkeys"' in doc:
        return doc
    i = doc.find('<section id="tips"')
    if i < 0:
        i = doc.find('<section id="privacy"')
    return doc[:i] + _HELP_SICHER3[lang] + doc[i:] if i >= 0 else doc


